      if (/FROM\s+DSEDAC\.CVC\s+CVC/i.test(sql)) {
        return [{
          CLIENTE: 'C003',
          SERIE_DOCUMENTO: 'M',
          NUMERO_DOCUMENTO: 3,
          TOTAL_PENDIENTE: '100.00',
          TOTAL_VENCIDO: '0.00',
