function paramsByInsertColumn(insertCall) {
  const [sql, params] = insertCall;
  const match = sql.match(/\(([^)]+)\)\s+VALUES/i);
  if (!match) return {};
  return Object.fromEntries(
    match[1]
      .split(',')
      .map((column) => column.trim())
      .map((column, index) => [column, params[index]]),
  );
}

