            NAME: 'Cliente Dos',
            ADDRESS: 'Calle 2',
            CITY: 'Madrid',
            PHONE: '600222222',
            PHONE2: '',
          },
        ];
      }

      if (sql.includes('FROM JAVIER.RUTERO_CONFIG')) {
        return [];
      }

      if (sql.includes('FROM DSEDAC.CPC')) {
        return [
          {
            CODE: '4300000001',
            TOTAL_COUNT: 2,
            LAST_ORDER_NUMBER: 1001,
          },
        ];
      }

      return [];
    });
  });

