    expect(missingTable.calls.some((call) => call.sql === 'BEGIN_TRANSACTION')).toBe(false);
    expect(missingTable.isClosed()).toBe(true);

    const missingColumn = fakeConnection({ missingColumn: 'TEST_REPARTO_CONFIRMACIONES.STATUS' });
