      content: item.content,
    });
    const directBlobSelect = fake.calls.find((call) =>
      call.sql.startsWith('SELECT EVIDENCE_ID, DOCUMENT_ID') && call.sql.includes('CONTENT_BLOB'));
    expect(directBlobSelect).toBeUndefined();
    expect(fake.calls.some((call) => call.sql.includes('HEX(SUBSTR(E.CONTENT_BLOB'))).toBe(true);
    expect(fake.isClosed()).toBe(true);
  });

  test('retrieves linked evidence via HEX when ODBC returns a null BLOB', async () => {
    const item = record();
    const fake = fakeConnection({
      linkedRow: {
        EVIDENCE_ID: item.evidenceId,
        DOCUMENT_ID: item.documentId,
        REPARTIDOR_ID: item.repartidorId,
        EVIDENCE_KIND: item.kind,
        MIME_TYPE: item.mimeType,
        CONTENT_SHA256: item.contentSha256,
        CONTENT_BYTES: item.contentBytes,
        CONTENT_BLOB: null,
        STATUS: 'ENLAZADA',
      },
      hexRow: { CONTENT_HEX: item.content.toString('hex') },
    });

    await expect(repository(fake).repo.getLinked(item.evidenceId)).resolves.toMatchObject({
      evidenceId: item.evidenceId,
      content: item.content,
    });
    expect(fake.calls.some((call) => call.sql.includes('HEX(SUBSTR(E.CONTENT_BLOB'))).toBe(true);
  });

  test('reads a maximum-size signature in one ordered set-based BLOB query', async () => {
    const signature = Buffer.alloc(1024 * 1024, 0);
    for (let index = 0; index < signature.length; index += 4096) signature[index] = index / 4096;
    const item = record({ content: signature, contentBytes: signature.length });
    const fake = fakeConnection({ linkedRow: {
      EVIDENCE_ID: item.evidenceId,
      DOCUMENT_ID: item.documentId,
      REPARTIDOR_ID: item.repartidorId,
      EVIDENCE_KIND: item.kind,
      MIME_TYPE: item.mimeType,
      CONTENT_SHA256: item.contentSha256,
      CONTENT_BYTES: item.contentBytes,
      CONTENT_BLOB: signature,
      STATUS: 'ENLAZADA',
    } });

    await expect(repository(fake).repo.getLinked(item.evidenceId)).resolves.toMatchObject({ content: signature });
    const blobReads = fake.calls.filter((call) => call.sql.includes('HEX(SUBSTR(E.CONTENT_BLOB'));
    expect(blobReads).toHaveLength(1);
    expect(blobReads[0].sql).toContain('WITH CHUNKS (ORDINAL, BYTE_OFFSET, BYTE_LENGTH) AS (VALUES');
    expect(blobReads[0].sql).toContain('ORDER BY C.ORDINAL');
    expect(blobReads[0].sql).not.toMatch(/VALUES[^S]*\?/);
    expect(blobReads[0].params).toEqual([item.evidenceId]);
  });

  test('rejects incomplete or malformed set-based BLOB fragments', async () => {
    const item = record({ content: Buffer.alloc(16001, 7), contentBytes: 16001 });
    const fake = fakeConnection({
      linkedRow: {
        EVIDENCE_ID: item.evidenceId, DOCUMENT_ID: item.documentId, REPARTIDOR_ID: item.repartidorId,
        EVIDENCE_KIND: item.kind, MIME_TYPE: item.mimeType, CONTENT_SHA256: item.contentSha256,
        CONTENT_BYTES: item.contentBytes, CONTENT_BLOB: item.content, STATUS: 'ENLAZADA',
      },
      hexRow: { CONTENT_HEX: item.content.subarray(0, 16000).toString('hex') },
    });

    await expect(repository(fake).repo.getLinked(item.evidenceId)).rejects.toMatchObject({
      code: 'REPARTO_EVIDENCE_STORE_UNAVAILABLE',
    });
    expect(MAX_EVIDENCE_BLOB_BYTES).toBe(4 * 1024 * 1024);
  });

  test('cancels and closes a hung linked-evidence query without continuing or leaking a rejection', async () => {
    const item = record();
    const calls = [];
    let releaseQuery;
    let closed = false;
    const cancel = jest.fn();
    const connection = {
      cancel,
      async execute(sql, params = []) {
        calls.push({ sql, params });
        if (sql.includes('QSYS2.SYSTABLES')) return [{ TABLE_NAME: EVIDENCE_TABLE }];
        if (sql.includes('QSYS2.SYSCOLUMNS')) {
          return REQUIRED_EVIDENCE_COLUMNS.map((COLUMN_NAME) => ({ COLUMN_NAME }));
        }
        return new Promise((resolve) => { releaseQuery = resolve; });
      },
      async close() { closed = true; },
    };
    const { repo } = repository({ connection });
    const controller = new AbortController();
    const unhandled = [];
    const onUnhandled = (reason) => unhandled.push(reason);
    process.on('unhandledRejection', onUnhandled);
    try {
      const pending = repo.getLinked(item.evidenceId, { signal: controller.signal });
      await new Promise((resolve) => setImmediate(resolve));
      controller.abort();
      await expect(pending).rejects.toMatchObject({ code: 'EVIDENCE_TIMEOUT', statusCode: 504 });
      expect(cancel).toHaveBeenCalledTimes(1);
      expect(closed).toBe(true);
      expect(calls.filter(({ sql }) => sql.includes('CONTENT_BLOB'))).toHaveLength(0);

      releaseQuery([{
        EVIDENCE_ID: item.evidenceId, REPARTIDOR_ID: item.repartidorId,
        EVIDENCE_KIND: item.kind, MIME_TYPE: item.mimeType,
        CONTENT_SHA256: item.contentSha256, CONTENT_BYTES: item.contentBytes,
        CONTENT_BLOB: item.content, STATUS: 'ENLAZADA',
      }]);
      await new Promise((resolve) => setImmediate(resolve));
      expect(unhandled).toEqual([]);
      expect(calls.filter(({ sql }) => sql.includes('CONTENT_BLOB'))).toHaveLength(0);
    } finally {
      process.removeListener('unhandledRejection', onUnhandled);
    }
  });

  test('purges at most one locked batch and never targets linked evidence', async () => {
    const firstId = `ev_${'c'.repeat(64)}`;
    const secondId = `ev_${'d'.repeat(64)}`;
    const fake = fakeConnection({
      expiredRows: [{ EVIDENCE_ID: firstId }, { EVIDENCE_ID: secondId }],
    });

    await expect(repository(fake).repo.purgeExpired()).resolves.toEqual({ purged: 2 });
    const select = fake.calls.find((call) => call.sql.startsWith('SELECT E.EVIDENCE_ID FROM'));
    const deletion = fake.calls.find((call) => call.sql.startsWith('DELETE FROM'));
    expect(select.sql).toContain("STATUS = 'PENDIENTE'");
    expect(select.sql).toContain('NOT EXISTS');
    expect(select.sql).toContain(QUALIFIED_CONFIRMATION_EVIDENCE_TABLE);
    expect(select.sql).toContain('EXPIRES_AT <= CURRENT TIMESTAMP');
    expect(select.sql).toContain('FETCH FIRST 100 ROWS ONLY');
    expect(select.sql).toContain('USE AND KEEP EXCLUSIVE LOCKS');
    expect(deletion.sql).toContain("STATUS = 'PENDIENTE'");
    expect(deletion.sql).toContain('NOT EXISTS');
    expect(deletion.sql).toContain(QUALIFIED_CONFIRMATION_EVIDENCE_TABLE);
    expect(deletion.sql).toContain('EXPIRES_AT <= CURRENT TIMESTAMP');
    expect(deletion.sql).not.toContain('ENLAZADA');
    expect(deletion.params).toEqual([firstId, secondId]);
    expect(fake.calls.map((call) => call.sql)).toEqual(expect.arrayContaining([
      'BEGIN_TRANSACTION', 'COMMIT_TRANSACTION',
    ]));
    expect(fake.calls.map((call) => call.sql)).not.toContain('ROLLBACK_TRANSACTION');
  });

  test('rejects a non-canonical confirmation-evidence mapping', () => {
    const fake = fakeConnection();
    expect(() => createRepartoEvidenceDb2Repository({
      tables: {
        evidences: QUALIFIED_EVIDENCE_TABLE,
        confirmationEvidences: 'JAVIER.OTHER_LINKS',
      },
      connectionFactory: async () => fake.connection,
      plannedDeliveryPort: { forConnection: jest.fn() },
      pendingTtlHours: 24,
    })).toThrow(expect.objectContaining({
      code: 'REPARTO_EVIDENCE_STORE_UNAVAILABLE',
      details: { key: 'confirmationEvidences' },
    }));
  });

  test('fails capability checks when EXPIRES_AT is absent', async () => {
    const fake = fakeConnection({
      columns: REQUIRED_EVIDENCE_COLUMNS.filter((column) => column !== 'EXPIRES_AT'),
    });

    await expect(repository(fake).repo.stage(record())).rejects.toMatchObject({
      code: 'REPARTO_EVIDENCE_STORE_UNAVAILABLE',
      details: { missingColumns: ['EXPIRES_AT'] },
    });
    expect(fake.calls.map((call) => call.sql)).not.toContain('BEGIN_TRANSACTION');
    expect(fake.calls.some((call) => call.sql.startsWith('INSERT'))).toBe(false);
  });

  test('rolls back staged BLOB data when insertion fails', async () => {
    const fake = fakeConnection({ insertError: new Error('insert failed') });

    await expect(repository(fake).repo.stage(record())).rejects.toMatchObject({
      code: 'REPARTO_EVIDENCE_PERSISTENCE_FAILED', statusCode: 503,
    });
    expect(fake.calls.map((call) => call.sql)).toContain('ROLLBACK_TRANSACTION');
    expect(fake.persistedWrites()).toBe(0);
    expect(fake.isClosed()).toBe(true);
  });

  test('rolls back and persists no BLOB when commit fails', async () => {
    const fake = fakeConnection({ commitError: new Error('commit failed') });

    await expect(repository(fake).repo.stage(record())).rejects.toMatchObject({
      code: 'REPARTO_EVIDENCE_PERSISTENCE_FAILED', statusCode: 503,
    });
    expect(fake.calls.map((call) => call.sql)).toEqual(expect.arrayContaining([
      'BEGIN_TRANSACTION', 'COMMIT_TRANSACTION', 'ROLLBACK_TRANSACTION',
    ]));
    expect(fake.persistedWrites()).toBe(0);
  });

  test('fails closed before staging when explicit transaction methods are absent', async () => {
    const fake = fakeConnection({ transactionMethods: false });

    await expect(repository(fake).repo.stage(record())).rejects.toMatchObject({
      code: 'REPARTO_EVIDENCE_TRANSACTION_UNAVAILABLE', statusCode: 503,
    });
    expect(fake.calls.some((call) => call.sql.startsWith('INSERT'))).toBe(false);
    expect(fake.persistedWrites()).toBe(0);
  });

  test('rolls back and closes when planned ownership validation fails', async () => {
    const fake = fakeConnection();
    const plannedDelivery = jest.fn().mockRejectedValue(new Error('planned unavailable'));

    await expect(repository(fake, plannedDelivery).repo.stage(record())).rejects.toMatchObject({
      code: 'REPARTO_EVIDENCE_PERSISTENCE_FAILED', statusCode: 503,
    });
    expect(fake.calls.map((call) => call.sql)).toContain('ROLLBACK_TRANSACTION');
    expect(fake.calls.map((call) => call.sql)).not.toContain('COMMIT_TRANSACTION');
    expect(fake.isClosed()).toBe(true);
  });
});

'use strict';

const express = require('express');
const request = require('supertest');
const {
  EvidenceError,
  PHOTO_MAX_BYTES,
} = require('../services/delivery-evidence-service');

let mockUser = { id: 'V94', code: '94', role: 'REPARTIDOR', repartidorCodes: ['94'] };
jest.mock('../middleware/logger', () => ({ info: jest.fn(), warn: jest.fn(), error: jest.fn(), debug: jest.fn() }));
jest.mock('../middleware/auth', () => ({
  verifyToken: (req, _res, next) => { req.user = mockUser && { ...mockUser }; next(); },
  requireRoles: () => (_req, _res, next) => next(),
}));
jest.mock('../services/repartidor-finance-service', () => ({}));
jest.mock('../services/redis-cache', () => ({ deleteCachePattern: jest.fn().mockResolvedValue(undefined) }));

const routes = require('../routes/repartidor-finanzas');
const EVIDENCE_ID = `ev_${'a'.repeat(64)}`;
const PNG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

function app() {
  const value = express();
  value.use(express.json({ limit: '2mb' }));
  value.use('/finanzas', routes);
  return value;
}

function injectEvidence(evidenceService) {
  routes.setCanonicalConfirmationRuntime({
    catalogService: { validateConfirmation: jest.fn() },
    confirmationService: { confirm: jest.fn() },
    evidenceService,
  });
}

describe('canonical reparto evidence routes', () => {
  afterEach(() => {
    mockUser = { id: 'V94', code: '94', role: 'REPARTIDOR', repartidorCodes: ['94'] };
    routes.resetCanonicalConfirmationRuntime();
  });

  test('is always mounted but fails closed with 503 when runtime is unavailable', async () => {
    const response = await request(app()).post('/finanzas/rutero/evidence/signature').send({
      documentId: '2026-S-10-404-4300009479',
      signature: `data:image/png;base64,${PNG.toString('base64')}`,
    });

    expect(response.status).toBe(503);
    expect(response.body).toMatchObject({
      success: false,
      code: 'REPARTO_EVIDENCE_RUNTIME_UNAVAILABLE',
    });
    expect(response.headers['cache-control']).toBe('private, no-store');
  });

  test.each([
    [null, 401, 'AUTHENTICATED_ACTOR_REQUIRED'],
    [{ id: 'C1', code: 'C1', role: 'COMERCIAL' }, 403, 'REPARTO_CONFIRMATION_ROLE_REQUIRED'],
  ])('requires authenticated reparto role before staging', async (user, status, code) => {
    const stageSignature = jest.fn();
    injectEvidence({ stageSignature, stagePhoto: jest.fn(), retrieve: jest.fn() });
    mockUser = user;

    const response = await request(app()).post('/finanzas/rutero/evidence/signature').send({
      documentId: '2026-S-10-404-4300009479',
      signature: `data:image/png;base64,${PNG.toString('base64')}`,
    });

    expect(response.status).toBe(status);
    expect(response.headers['cache-control']).toBe('private, no-store');
    expect(response.body).toMatchObject({ success: false, code });
    expect(stageSignature).not.toHaveBeenCalled();
  });

  test.each([
    ['signature', undefined], ['signature', 'ALL'], ['signature', '94,95'],
    ['photo', undefined], ['photo', 'ALL'], ['photo', '94,95'],
  ])('JEFE evidence %s rejects non-concrete selector %s before storage', async (kind, repartidorId) => {
    const stageSignature = jest.fn();
    const stagePhoto = jest.fn();
    injectEvidence({ stageSignature, stagePhoto, retrieve: jest.fn() });
    mockUser = {
      id: '98', code: '98', role: 'JEFE_VENTAS', activeMode: 'REPARTIDOR',
      repartidorCodes: ['94', '95'],
    };
    const base = { documentId: '2026-S-10-404-4300009479' };
    const response = kind === 'signature'
      ? await request(app()).post('/finanzas/rutero/evidence/signature').send({
        ...base, ...(repartidorId ? { repartidorId } : {}),
        signature: 'data:image/png;base64,' + PNG.toString('base64'),
      })
      : await request(app()).post('/finanzas/rutero/evidence/photo')
        .field('documentId', base.documentId)
        .field('repartidorId', repartidorId || '')
        .attach('photo', PNG, { filename: 'proof.png', contentType: 'image/png' });
    expect(response.status).toBe(422);
    expect(stageSignature).not.toHaveBeenCalled();
    expect(stagePhoto).not.toHaveBeenCalled();
  });

  test.each(['signature', 'photo'])('JEFE evidence %s rejects foreign and wrong mode before storage', async (kind) => {
    const stageSignature = jest.fn();
    const stagePhoto = jest.fn();
    injectEvidence({ stageSignature, stagePhoto, retrieve: jest.fn() });
    const send = async (repartidorId) => kind === 'signature'
      ? request(app()).post('/finanzas/rutero/evidence/signature').send({
        documentId: '2026-S-10-404-4300009479', repartidorId,
        signature: 'data:image/png;base64,' + PNG.toString('base64'),
      })
      : request(app()).post('/finanzas/rutero/evidence/photo')
        .field('documentId', '2026-S-10-404-4300009479')
        .field('repartidorId', repartidorId)
        .attach('photo', PNG, { filename: 'proof.png', contentType: 'image/png' });

    mockUser = { id: '98', code: '98', role: 'JEFE_VENTAS', activeMode: 'REPARTIDOR', repartidorCodes: ['94'] };
    expect((await send('95')).status).toBe(403);
    mockUser = { ...mockUser, activeMode: 'COMERCIAL' };
    expect((await send('94')).status).toBe(403);
    expect(stageSignature).not.toHaveBeenCalled();
    expect(stagePhoto).not.toHaveBeenCalled();
  });

  test('stages signature as an opaque ID and returns 201/200 for create/retry', async () => {
    const stageSignature = jest.fn()
      .mockResolvedValueOnce({ evidenceId: EVIDENCE_ID, created: true, idempotent: false })
      .mockResolvedValueOnce({ evidenceId: EVIDENCE_ID, created: false, idempotent: true });
    injectEvidence({ stageSignature, stagePhoto: jest.fn(), retrieve: jest.fn() });
    const body = {
      documentId: '2026-S-10-404-4300009479',
      signature: `data:image/png;base64,${PNG.toString('base64')}`,
    };

    const created = await request(app()).post('/finanzas/rutero/evidence/signature').send(body);
    const replay = await request(app()).post('/finanzas/rutero/evidence/signature').send(body);

    expect(created.status).toBe(201);
    expect(replay.status).toBe(200);
    expect(created.body).toMatchObject({ evidenceId: EVIDENCE_ID, created: true });
    expect(JSON.stringify(created.body)).not.toContain('base64');
    expect(stageSignature).toHaveBeenCalledWith(expect.objectContaining({ repartidorId: '94' }));
  });

  test('accepts one bounded multipart photo and delegates bytes in memory', async () => {
    const stagePhoto = jest.fn().mockResolvedValue({ evidenceId: EVIDENCE_ID, created: true, idempotent: false });
    injectEvidence({ stageSignature: jest.fn(), stagePhoto, retrieve: jest.fn() });

    const response = await request(app())
      .post('/finanzas/rutero/evidence/photo')
      .field('documentId', '2026-S-10-404-4300009479')
      .attach('photo', PNG, { filename: 'proof.png', contentType: 'image/png' });

    expect(response.status).toBe(201);
    expect(stagePhoto).toHaveBeenCalledWith(expect.objectContaining({
      repartidorId: '94', mimeType: 'image/png', buffer: PNG,
    }));
  });

  test('rejects multipart photos above 4 MiB with the public size contract', async () => {
    const stagePhoto = jest.fn();
    injectEvidence({ stageSignature: jest.fn(), stagePhoto, retrieve: jest.fn() });
    const oversizedPhoto = Buffer.alloc(PHOTO_MAX_BYTES + 1);
    PNG.copy(oversizedPhoto);

    const response = await request(app())
      .post('/finanzas/rutero/evidence/photo')
      .field('documentId', '2026-S-10-404-4300009479')
      .attach('photo', oversizedPhoto, { filename: 'proof.png', contentType: 'image/png' });

    expect(response.status).toBe(413);
    expect(response.body).toMatchObject({
      success: false,
      code: 'EVIDENCE_TOO_LARGE',
      error: 'La evidencia supera el límite de 4 MiB',
    });
    expect(stagePhoto).not.toHaveBeenCalled();
  });

  test('maps foreign ownership to 403 and returns linked MIME/base64 to owner', async () => {
    const retrieve = jest.fn()
      .mockRejectedValueOnce(new EvidenceError('EVIDENCE_OWNERSHIP_REQUIRED', 'Sin permisos', 403))
      .mockResolvedValueOnce({ evidenceId: EVIDENCE_ID, kind: 'FOTO', mimeType: 'image/png', contentBase64: PNG.toString('base64') });
    injectEvidence({ stageSignature: jest.fn(), stagePhoto: jest.fn(), retrieve });

    const forbidden = await request(app()).get(`/finanzas/rutero/evidence/${EVIDENCE_ID}`);
    const linked = await request(app()).get(`/finanzas/rutero/evidence/${EVIDENCE_ID}`);

    expect(forbidden.status).toBe(403);
    expect(forbidden.body).toMatchObject({ code: 'EVIDENCE_OWNERSHIP_REQUIRED' });
    expect(linked.status).toBe(200);
    expect(linked.body).toMatchObject({
      evidenceId: EVIDENCE_ID,
      mimeType: 'image/png',
      contentBase64: PNG.toString('base64'),
    });
    expect(linked.headers['cache-control']).toBe('private, no-store');
    expect(linked.headers.pragma).toBe('no-cache');
    expect(linked.headers['x-content-type-options']).toBe('nosniff');
    expect(linked.headers['content-disposition']).toBe('inline; filename="evidence.json"');
    expect(linked.headers['content-type']).toMatch(/^application\/json/);
  });

  test('maps service and DB2 timeouts to a safe 504 without diagnostics', async () => {
    const stageSignature = jest.fn().mockRejectedValue(Object.assign(new Error('network details'), {
      code: 'ETIMEDOUT',
    }));
    const retrieve = jest.fn().mockRejectedValue(Object.assign(new Error('DB2 private details'), {
      odbcErrors: [{ state: 'HYT00', code: 0, message: 'private SQL details' }],
    }));
    injectEvidence({ stageSignature, stagePhoto: jest.fn(), retrieve });

    const signature = await request(app()).post('/finanzas/rutero/evidence/signature').send({
      documentId: '2026-S-10-404-4300009479',
      signature: `data:image/png;base64,${PNG.toString('base64')}`,
    });
    const linked = await request(app()).get(`/finanzas/rutero/evidence/${EVIDENCE_ID}`);

    for (const response of [signature, linked]) {
      expect(response.status).toBe(504);
      expect(response.body).toEqual({
        success: false,
        code: 'EVIDENCE_TIMEOUT',
        error: 'Servicio temporalmente no disponible',
      });
      expect(JSON.stringify(response.body)).not.toMatch(/DB2|SQL|network|private|odbc/i);
    }
  });
});

