            let linesToRender = lines;
            let albaranGroups = null;

            if (!isAlbaran && lines.length > 0 && lines[0].albaranNum) {
                const groups = {};
                lines.forEach(line => {
                    const key = `${line.albaranSerie || ''}-${line.albaranTerminal || ''}-${line.albaranNum}-${line.albaranEjercicio || ''}`;
                    if (!groups[key]) {
                        groups[key] = {
                            albaranNum: line.albaranNum,
                            albaranSerie: line.albaranSerie,
                            albaranTerminal: line.albaranTerminal,
                            albaranEjercicio: line.albaranEjercicio,
                            albaranFecha: line.albaranFecha || '',
                            lines: [],
                            subtotal: 0
                        };
                    }
                    groups[key].lines.push(line);
                    groups[key].subtotal += parseFloat(line.importeNeto || line.importe || 0);
                });
                albaranGroups = Object.values(groups);
                logger.info(`[PDF] Factura grouped into ${albaranGroups.length} albaranes`);
            }

            const renderLine = (line, index, isGroupHeader = false, groupSubtotal = null) => {
                const descripcion = isAlbaran
                    ? (line.DESCRIPCIONARTICULO || '').trim()
                    : (line.DESCRIPCIONARTICULO || '').substring(0, 50);
                const descWidth = isAlbaran ? 275 : 170;
                const descHeight = doc.heightOfString(descripcion, { width: descWidth });
                const rowHeight = isAlbaran
                    ? Math.max(28, descHeight + 18)
                    : Math.max(20, descHeight + 12);

                // Comprobar si necesitamos una nueva página con la nueva altura
                if (y + rowHeight > 700) {
                    doc.addPage();
                    y = drawHeader(doc, 10, headerOptions) + 10;

                    // Repetir cabecera de tabla
                    doc.rect(40, y, 515, 16)
                        .fillAndStroke(COLORS.secondary, COLORS.secondary);

                    doc.fontSize(7)
                        .font('Helvetica-Bold')
                        .fillColor(COLORS.white);

                    if (isAlbaran) {
                        doc.text('Ptda', 42, y + 5, { width: 28 });
                        doc.text('Artículo / Descripción', 72, y + 5, { width: 275 });
                        doc.text('Bultos', 350, y + 5, { width: 55, align: 'right' });
                        doc.text('Imp.Neto', 500, y + 5, { width: 55, align: 'right' });
                    } else {
                        doc.text('CÓDIGO', 42, y + 5, { width: 50 });
                        doc.text('DESCRIPCIÓN', 95, y + 5, { width: 170 });
                        doc.text('LOTE', 270, y + 5, { width: 45 });
                        doc.text('CAJAS', 320, y + 5, { width: 35, align: 'right' });
                        doc.text('CANT.', 360, y + 5, { width: 38, align: 'right' });
                        doc.text('PRECIO', 403, y + 5, { width: 42, align: 'right' });
                        doc.text('% DTO', 450, y + 5, { width: 30, align: 'center' });
                        doc.text('% IVA', 485, y + 5, { width: 25, align: 'center' });
                        doc.text('IMPORTE', 515, y + 5, { width: 40, align: 'right' });
                    }

                    y += 18;
                    alternateRow = true;
                }

                // Datos del producto
                doc.fontSize(7)
                    .font('Helvetica')
                    .fillColor(COLORS.darkGray);

                if (isAlbaran) {
                    // Albaran layout: Ptda | Code+Desc | Bultos | Imp.Neto
                    doc.font('Helvetica-Bold');
                    doc.text(String(index + 1), 44, y + 8, { width: 25 });

                    const codigo = (line.CODIGOARTICULO || '').trim();
                    doc.fontSize(7).font('Helvetica-Bold');
                    doc.text(codigo, 72, y + 3, { width: 275 });
                    doc.fontSize(7).font('Helvetica');
                    doc.text(descripcion, 72, y + 13, { width: 275 });

                    const bultos = parseFloat(line.CAJASARTICULO || line.CANTIDADARTICULO || 0);
                    doc.text(bultos > 0 ? formatNumber(bultos, 2) : '-', 350, y + 8, { width: 55, align: 'right' });

                    const importe = parseFloat(line.IMPORTENETOARTICULO || 0);
                    doc.font('Helvetica-Bold');
                    doc.text(formatNumber(importe, 2) + ' €', 500, y + 8, { width: 55, align: 'right' });
                    doc.font('Helvetica');
                } else {
                    const codigo = (line.codigo || line.CODIGOARTICULO || '').substring(0, 12);
                    doc.text(codigo, 42, y + 3, { width: 50 });

                    doc.text(descripcion, 95, y + 3, { width: 170 });

                    // COLUMNA LOTE
                    const lote = (line.lote || line.LOTEARTICULO || line.LOTE || '').substring(0, 10);
                    doc.text(lote || '-', 270, y + 3, { width: 45 });

                    // COLUMNA CAJAS
                    const cajas = line.cajas ?? line.CAJASARTICULO ?? line.NUMEROCAJAS ?? 0;
                    const cajasDisplay = Number(cajas) === 0 ? '-' : formatNumber(cajas, 0);
                    doc.text(cajasDisplay, 320, y + 3, { width: 35, align: 'right' });

                    const cantidad = (line.cantidad ?? line.CANTIDADARTICULO) || 0;
                    doc.text(formatNumber(cantidad, 3), 360, y + 3, { width: 38, align: 'right' });

                    const precio = (line.precio ?? line.PRECIOARTICULO) || 0;
                    doc.text(formatNumber(precio, 3) + ' €', 403, y + 3, { width: 42, align: 'right' });

                    const dto = (line.descuento ?? line.PORCENTAJEDESCUENTOARTICULO) || 0;
                    doc.text(dto > 0 ? formatNumber(dto, 2) : '-', 450, y + 3, { width: 30, align: 'center' });

                    const iva = (line.codigoIva || line.CODIGOIVA) ? (IVA_MAP[(line.codigoIva || line.CODIGOIVA || '').trim()] || 0) : (parseFloat(line.PORCENTAJEIVAARTICULO) || 0);
                    doc.text(formatNumber(iva, 2), 485, y + 3, { width: 25, align: 'center' });

                    const importe = line.importeNeto || line.IMPORTENETOARTICULO || 0;
                    doc.font('Helvetica-Bold');
                    doc.text(formatNumber(parseFloat(importe), 2) + ' €', 515, y + 3, { width: 40, align: 'right' });
                    doc.font('Helvetica');
                }

                // Incrementar Y dinámicamente
                y += rowHeight;
                alternateRow = !alternateRow;
            };

            // Render lines - either grouped by albaran or flat
            if (albaranGroups && albaranGroups.length > 0) {
                // Render each albaran group with header
                albaranGroups.forEach((group, groupIdx) => {
                    // Draw albaran header with subtotal
                    if (y + 25 > 700) {
                        doc.addPage();
                        y = drawHeader(doc, 10, headerOptions) + 10;
                    }

                    // Albaran header box
                    doc.rect(40, y, 515, 20)
                        .fillAndStroke('#E3F2FD', '#1a5490');

                    doc.fontSize(8)
                        .font('Helvetica-Bold')
                        .fillColor('#003d7a');

                    const albaranLabel = `Albarán: ${group.albaranSerie || ''}-${group.albaranTerminal || ''}-${group.albaranNum}`;
                    const fechaLabel = group.albaranFecha ? `Fecha: ${group.albaranFecha}` : '';
                    doc.text(albaranLabel, 45, y + 5, { width: 250 });

                    if (fechaLabel) {
                        doc.text(fechaLabel, 250, y + 5, { width: 150 });
                    }

                    const subtotalLabel = `SUBTOTAL ALBARÁN ${formatNumber(group.subtotal, 2)} €`;
                    doc.text(subtotalLabel, 400, y + 5, { width: 150, align: 'right' });

                    y += 24;
                    alternateRow = true;

                    // Render lines for this albaran
                    group.lines.forEach((line, idx) => {
                        renderLine(line, idx);
                    });
                });
            } else {
                // Regular flat rendering for albaran or invoices without albaran grouping
                lines.forEach((line, index) => {
                    renderLine(line, index);
                });
            }

            // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
            // TABLA DE TOTALES POR TIPO DE IVA
            // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

            // Build IVA groups from header-level data. CAC/CFC are the source of
            // truth for rounded tax totals; line recomputation can drift by 0.01.
            const grupos = [];
            if (ivaBreakdown) {
                for (let i = 1; i <= 5; i++) {
                    const bi = parseFloat(ivaBreakdown[`BI${i}`]) || 0;
                    const pct = parseFloat(ivaBreakdown[`IVA${i}_PCT`]) || 0;
                    const imp = parseFloat(ivaBreakdown[`IVA${i}_IMP`]) || 0;
                    if (bi !== 0 || imp !== 0) {
                        grupos.push({
                            porcIVA: pct,
                            porcRec: 0,
                            baseImponible: bi,
                            iva: imp,
                            recargo: 0
                        });
                    }
                }
            }

            // Fallback: if no IVA breakdown from CPC, compute from lines
            if (grupos.length === 0) {
                const gruposIVA = {};
                lines.forEach(line => {
                    const porcIVA = line.CODIGOIVA ? (IVA_MAP[(line.CODIGOIVA || '').trim()] || 0) : 0;
                    const key = `${porcIVA.toFixed(2)}`;
                    if (!gruposIVA[key]) {
                        gruposIVA[key] = { porcIVA, porcRec: 0, baseImponible: 0, iva: 0, recargo: 0 };
                    }
                    const importe = parseFloat(line.IMPORTENETOARTICULO) || 0;
                    gruposIVA[key].baseImponible += importe;
                    gruposIVA[key].iva += importe * (porcIVA / 100);
                });
                grupos.push(...Object.values(gruposIVA));
            }

            const taxRows = grupos.length > 0 ? Math.max(grupos.length, 1) : 0;
            const taxTableHeight = taxRows > 0 ? 16 + (taxRows * 14) : 0;
            const totalsBlockHeight = 12 + (taxTableHeight > 0 ? taxTableHeight + 18 : 0) + 22 + 24 + 28;
            // Totales, receptor y firma forman una sola unidad: si no caben
            // juntos se trasladan enteros a la última página, lejos del pie.
            const closingBlockHeight = totalsBlockHeight + 45 + 110;

            y = ensureContentSpace(doc, y, closingBlockHeight, headerOptions);

            // Línea final de productos
            doc.moveTo(40, y)
                .lineTo(555, y)
                .strokeColor(COLORS.lightGray)
                .lineWidth(1)
                .stroke();

            y += 12;

            if (grupos.length > 0) {
                const alturaTabla = taxTableHeight;

                doc.rect(40, y, 515, alturaTabla)
                    .strokeColor(COLORS.border)
                    .lineWidth(1)
                    .stroke();

                [110, 200, 290, 360, 430, 490].forEach(x => {
                    doc.moveTo(x, y).lineTo(x, y + alturaTabla).stroke();
                });

                doc.moveTo(40, y + 16).lineTo(555, y + 16).stroke();

                doc.rect(40, y, 515, 16)
                    .fillAndStroke(COLORS.lightGray, COLORS.border);

                doc.fontSize(7)
                    .font('Helvetica-Bold')
                    .fillColor(COLORS.darkGray);

                doc.text('Base Imponible', 42, y + 5, { width: 65, align: 'center' });
                doc.text('% I.V.A.', 112, y + 5, { width: 85, align: 'center' });
                doc.text('Importe I.V.A.', 202, y + 5, { width: 85, align: 'center' });
                doc.text('% Recargo', 292, y + 5, { width: 65, align: 'center' });
                doc.text('Importe Rec.', 362, y + 5, { width: 65, align: 'center' });
                doc.text('Total', 432, y + 5, { width: 55, align: 'center' });

                let yValor = y + 20;

                doc.fontSize(8)
                    .font('Helvetica');

                grupos.forEach(grupo => {
                    const totalGrupo = grupo.baseImponible + grupo.iva + grupo.recargo;

                    doc.text(formatNumber(grupo.baseImponible, 2) + ' €', 42, yValor, { width: 65, align: 'right' });
                    doc.text(formatNumber(grupo.porcIVA, 2) + ' %', 112, yValor, { width: 85, align: 'center' });
                    doc.text(formatNumber(grupo.iva, 2) + ' €', 202, yValor, { width: 85, align: 'right' });

                    doc.text(grupo.porcRec > 0.001 ? formatNumber(grupo.porcRec, 2) + ' %' : '0,00 %', 292, yValor, { width: 65, align: 'center' });
                    doc.text(grupo.recargo > 0.001 ? formatNumber(grupo.recargo, 2) + ' €' : '0,00 €', 362, yValor, { width: 65, align: 'right' });

                    doc.font('Helvetica-Bold');
                    doc.text(formatNumber(totalGrupo, 2) + ' €', 432, yValor, { width: 115, align: 'right' });
                    doc.font('Helvetica');

                    yValor += 14;
                });

                y += alturaTabla + 18;
            }

            // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
            // TOTALES FINALES - DISEÑO ELEGANTE
            // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

            const totalBase = grupos.reduce((sum, g) => sum + g.baseImponible, 0);
            const totalIVA = grupos.reduce((sum, g) => sum + g.iva, 0);
            const totalRecargo = grupos.reduce((sum, g) => sum + g.recargo, 0);
            const totalConIVA = totalBase + totalIVA + totalRecargo;

            // TOTAL SIN IVA
            doc.rect(350, y, 205, 22)
                .strokeColor(COLORS.border)
                .lineWidth(1)
                .stroke();

            doc.fontSize(10)
                .font('Helvetica')
                .fillColor(COLORS.darkGray)
                .text('TOTAL SIN IVA', 360, y + 7);

            doc.fontSize(12)
                .font('Helvetica-Bold')
                .fillColor(COLORS.darkGray)
                .text(formatNumber(totalBase, 2) + ' €', 450, y + 6, {
                    width: 100,
                    align: 'right'
                });

            y += 24;

            // TOTAL CON IVA - DESTACADO EN VERDE
            doc.rect(350, y, 205, 28)
                .fillAndStroke(COLORS.success, COLORS.success)
                .lineWidth(2);

            doc.fontSize(12)
                .font('Helvetica-Bold')
                .fillColor(COLORS.white)
                .text('TOTAL CON IVA', 360, y + 9);

            doc.fontSize(18)
                .font('Helvetica-Bold')
                .fillColor(COLORS.white)
                .text(formatNumber(totalConIVA, 2) + ' €', 450, y + 6, {
                    width: 100,
                    align: 'right'
                });

            // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
            // FIRMA DEL CLIENTE + COPIA LABEL
            // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

            y += 45;

            if (facturaData.signatureBase64) {
                // Use dark background for ALL signatures to ensure visibility
                // (legacy CACFIRMAS have white strokes, older app captures may also have white strokes)

                // Signature box (right side, like the physical paper)
                doc.rect(300, y, 255, 100)
                    .fillAndStroke('#2A2D35', COLORS.border)
                    .lineWidth(1);

                doc.fontSize(9)
                    .font('Helvetica-Bold')
                    .fillColor('#FFFFFF')
                    .text('Recibí Conforme', 305, y + 5);

                // Embed signature image
                try {
                    const sigBuffer = Buffer.from(facturaData.signatureBase64, 'base64');
                    doc.image(sigBuffer, 310, y + 18, {
                        width: 235,
                        height: 65,
                        fit: [235, 65],
                        align: 'center',
                        valign: 'center'
                    });
                } catch (sigErr) {
                    doc.fontSize(8)
                        .font('Helvetica')
                        .fillColor(COLORS.mediumGray)
                        .text('Firma digital registrada', 310, y + 45);
                }

                // Date label under signature
                doc.fontSize(7)
                    .font('Helvetica')
                    .fillColor('#AAAAAA')
                    .text('Fecha: ' + new Date().toLocaleDateString('es-ES'), 305, y + 88);
            }

            const receptorNombre = String(facturaData.receptorNombre || '').trim();
            const receptorApellidos = String(facturaData.receptorApellidos || '').trim();
            const receptorDni = String(facturaData.receptorDni || '').trim();
            const receptorFull = [receptorNombre, receptorApellidos].filter(Boolean).join(' ');
            if (receptorFull || receptorDni) {
                doc.fontSize(9)
                    .font('Helvetica-Bold')
                    .fillColor(COLORS.secondary)
                    .text('Receptor', 50, y + 8);
                if (receptorFull) {
                    doc.fontSize(10)
                        .font('Helvetica')
                        .fillColor(COLORS.darkGray)
                        .text(receptorFull, 50, y + 24, { width: 230 });
                }
                if (receptorDni) {
                    doc.fontSize(10)
                        .font('Helvetica-Bold')
                        .fillColor(COLORS.darkGray)
                        .text('DNI: ' + receptorDni, 50, y + 48);
                }
            } else {
                // "COPIA" watermark label (left side, like the physical paper)
                doc.fontSize(36)
                    .font('Helvetica-Bold')
                    .fillColor('#E0E0E0')
                    .text('COPIA', 50, y + 25);
            }

            y += 110;

            // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
            // FOOTER - PIE DE PÁGINA ELEGANTE
            // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
            const range = doc.bufferedPageRange();
            for (let i = 0; i < range.count; i++) {
                doc.switchToPage(i);
                drawFooter(doc, i + 1, range.count);
            }

            doc.end();
        });

    } catch (error) {
        logger.error('❌ Error generando PDF factura', error);
        throw error;
    }
}

module.exports = {
    generateInvoicePDF
};

#!/usr/bin/env node
/**
 * ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
 * AUDIT: fix_anomalies.js
 * ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
 *
 * Applies CODE-LEVEL fixes to backend services to handle
 * anomalous data gracefully. Does NOT modify DB data directly
 * (CAC/CPC are ERP-managed).
 *
 * This script patches the backend code to:
 *  1. Filter sentinel NUMEROFACTURA values (>=900000)
 *  2. Sanitize IMPORTETOTAL values (clamp unreasonable)
 *  3. Add transaction wrapper to delivery confirmation
 *  4. Remove "Pendiente"/"Entregado" from PDF output
 *  5. Add PDF generation guards for empty/corrupted data
 *
 * Usage:
 *   node fix_anomalies.js --dry-run    (show what would change)
 *   node fix_anomalies.js --apply      (apply patches)
 *
 * Environment:
 *   BACKUP_DIR (default: ./backups)
 */

const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const DRY_RUN = args.includes('--dry-run') || !args.includes('--apply');
const BACKUP_DIR = process.env.BACKUP_DIR || path.join(__dirname, '..', 'backups');

const BACKEND_ROOT = path.join(__dirname, '..', '..');

const patches = [];

function addPatch(file, description, severity, find, replace) {
    patches.push({ file, description, severity, find, replace });
}

// ─────────────────────────────────────────────────────────
// PATCH 1: Filter sentinel NUMEROFACTURA in facturas.service.js
// Root cause: CAC rows with NUMEROFACTURA = 999999 pass the
// WHERE NUMEROFACTURA > 0 filter and display as "A-999999"
// ─────────────────────────────────────────────────────────
addPatch(
    'services/facturas.service.js',
    'Filter sentinel NUMEROFACTURA values (999999, 9999999) from invoice queries',
    'critical',
    `WHERE CAC.NUMEROFACTURA > 0`,
    `WHERE CAC.NUMEROFACTURA > 0 AND CAC.NUMEROFACTURA < 900000`
);

addPatch(
    'services/facturas.service.js',
    'Filter sentinel in available years query',
    'critical',
    `WHERE NUMEROFACTURA > 0\n    `;`,
    `WHERE NUMEROFACTURA > 0 AND NUMEROFACTURA < 900000\n    `;`
);

addPatch(
    'services/facturas.service.js',
    'Filter sentinel in summary query',
    'critical',
    `WHERE NUMEROFACTURA > 0\n    `;

        if (!isAll)`,
    `WHERE NUMEROFACTURA > 0 AND NUMEROFACTURA < 900000\n    `;

        if (!isAll)`
);

// ─────────────────────────────────────────────────────────
// PATCH 2: Sanitize amounts in facturas aggregation
// Root cause: parseFloat("-0") returns -0, and sentinel
// amounts like -9999999 or 9999999 corrupt totals
// ─────────────────────────────────────────────────────────
addPatch(
    'services/facturas.service.js',
    'Sanitize invoice totals — clamp unreasonable values and normalize -0',
    'critical',
    `                    invoiceMap.set(key, {
                        id: key,
                        serie: row.SERIE,
                        numero: row.NUMERO,
                        ejercicio: row.EJERCICIO,
                        fecha: \`\${String(row.DIA).padStart(2, '0')}/\${String(row.MES).padStart(2, '0')}/\${row.ANO}\`,
                        clienteId: row.CODIGO_CLIENTE,
                        clienteNombre: row.NOMBRE_CLIENTE || \`Cliente \${row.CODIGO_CLIENTE}\`,
                        total: parseFloat(row.TOTAL) || 0,
                        base: parseFloat(row.BASE) || 0,
                        iva: parseFloat(row.IVA) || 0`,
    `                    // Sanitize: clamp sentinel values, normalize -0
                    const sanitize = (v) => {
                        const n = parseFloat(v) || 0;
                        if (Object.is(n, -0)) return 0;
                        if (Math.abs(n) >= 900000) return 0; // sentinel
                        return n;
                    };
                    invoiceMap.set(key, {
                        id: key,
                        serie: row.SERIE,
                        numero: row.NUMERO,
                        ejercicio: row.EJERCICIO,
                        fecha: \`\${String(row.DIA).padStart(2, '0')}/\${String(row.MES).padStart(2, '0')}/\${row.ANO}\`,
                        clienteId: row.CODIGO_CLIENTE,
                        clienteNombre: row.NOMBRE_CLIENTE || \`Cliente \${row.CODIGO_CLIENTE}\`,
                        total: sanitize(row.TOTAL),
                        base: sanitize(row.BASE),
                        iva: sanitize(row.IVA)`
);

// ─────────────────────────────────────────────────────────
