                    await query(restoreSql, false);
                    logger.warn(\`[ENTREGAS] Restored previous state for \${itemId}\`);
                } catch (restoreErr) {
                    logger.error(\`[ENTREGAS] CRITICAL: Could not restore \${itemId}: \${restoreErr.message}\`);
