            FROM DSEDAC.CAC CAC
            LEFT JOIN DSEDAC.CLI CLI ON CLI.CODIGOCLIENTE = CAC.CODIGOCLIENTEFACTURA
            WHERE (ABS(CAC.IMPORTETOTAL - 9013.64) < 0.01
