// ============================================================
// GET /api/kpi/dashboard?vendorCode=V01
// Panel resumen Glacius para la app Flutter
// JEFE_VENTAS: todos los clientes | COMERCIAL: solo los suyos
// ============================================================
router.get('/dashboard', async (req, res) => {
  try {
    const { vendorCode } = req.query;

    // 1. Fetch ALL active alerts with type (single query, filter in Node)
    const allAlertsResult = await kpiQuery(`
      SELECT CLIENT_CODE, ALERT_TYPE, SEVERITY
      FROM ${SCHEMA}.KPI_ALERTS WHERE IS_ACTIVE = 1
    `);

    let filteredAlerts = allAlertsResult.rows;

    logger.info(`[kpi:dashboard] Active alerts in DB: ${allAlertsResult.rows.length}, vendorCode=${vendorCode || 'ALL'}`);
    if (allAlertsResult.rows.length > 0) {
      const sampleCodes = [...new Set(allAlertsResult.rows.slice(0, 5).map(r => r.CLIENT_CODE))];
      logger.info(`[kpi:dashboard] Sample alert client codes: ${sampleCodes.join(', ')}`);
    }

    // 2. Vendor filter: restrict to this vendor's clients
    if (vendorCode && vendorCode !== 'ALL') {
      const vendorCodes = normalizeVendorCodes(vendorCode);
      if (vendorCodes.length === 0) {
        return res.status(400).json({ success: false, error: 'vendorCode invalido' });
      }

      if (vendorCodes.length > MAX_VENDOR_CLIENT_FILTER_CODES) {
        logger.info(`[kpi:dashboard] Vendor filter skipped for ${vendorCodes.length} codes; treating as manager ALL scope`);
      } else {
        const validCodes = await getVendorClientSet(vendorCodes, 'current');

        logger.info(`[kpi:dashboard] LACLAE clients for vendor ${vendorCodes.join(',')}: ${validCodes.size}, sample: ${[...validCodes].slice(0, 5).join(', ')}`);

        filteredAlerts = filteredAlerts.filter(a => validCodes.has((a.CLIENT_CODE || '').trim()));
        logger.info(`[kpi:dashboard] After vendor filter: ${filteredAlerts.length} alerts`);
      }
    }

    // 3. Compute totals, byType, and clientsMap â€” all from the SAME filtered data
    const calcTotals = { TOTAL_ALERTS: 0, TOTAL_CLIENTS: new Set(), CRITICAL: 0, WARNING: 0, INFO: 0 };
    const byTypeMap = {}; // { DESVIACION_VENTAS: { critical: 3, warning: 5, info: 2 } }
    const clientsMap = {};

    for (const row of filteredAlerts) {
      const code = (row.CLIENT_CODE || '').trim();
      const sev = (row.SEVERITY || '').toLowerCase();
      const type = (row.ALERT_TYPE || '').trim();

      calcTotals.TOTAL_ALERTS++;
      calcTotals.TOTAL_CLIENTS.add(code);
      if (sev === 'critical') calcTotals.CRITICAL++;
      if (sev === 'warning') calcTotals.WARNING++;
      if (sev === 'info') calcTotals.INFO++;

      // byType aggregation
      if (!byTypeMap[type]) byTypeMap[type] = { critical: 0, warning: 0, info: 0 };
      if (sev === 'critical') byTypeMap[type].critical++;
      else if (sev === 'warning') byTypeMap[type].warning++;
      else byTypeMap[type].info++;

      // clients aggregation
      if (!clientsMap[code]) clientsMap[code] = { code, total: 0, critical: 0, warning: 0, info: 0, types: new Set() };
      clientsMap[code].total++;
      if (sev === 'critical') clientsMap[code].critical++;
      else if (sev === 'warning') clientsMap[code].warning++;
      else clientsMap[code].info++;
      clientsMap[code].types.add(type);
    }

    // Sort clients: critical first, then warning, then total
    const sortedClients = Object.values(clientsMap)
      .sort((a, b) => b.critical - a.critical || b.warning - a.warning || b.total - a.total)
      .slice(0, 50);

    // 4. Fetch client info from DSEDAC.CLI (name, address, city)
    const clientCodes = sortedClients.map(c => c.code);
    const clientInfo = {}; // code â†’ { name, address, city }
    if (clientCodes.length > 0) {
      try {
        const db2ClientCodes = [...new Set(clientCodes.map(normalizeClientCodeForDb2).filter(Boolean))];
        if (db2ClientCodes.length > 0) {
          const placeholders = db2ClientCodes.map(() => `CAST(? AS VARCHAR(${DB2_CLIENT_CODE_MAX_LEN}))`).join(',');
          const cliResult = await kpiQuery(
            `SELECT TRIM(C.CODIGOCLIENTE) AS CODE,
                    COALESCE(NULLIF(TRIM(C.NOMBREALTERNATIVO), ''), TRIM(C.NOMBRECLIENTE)) AS NAME,
                    TRIM(C.DIRECCION) AS ADDRESS, TRIM(C.POBLACION) AS CITY
             FROM DSEDAC.CLI C
             WHERE TRIM(C.CODIGOCLIENTE) IN (${placeholders})`,
            db2ClientCodes
          );
          for (const r of cliResult.rows) {
            clientInfo[(r.CODE || '').trim()] = {
              name: r.NAME || '',
              address: r.ADDRESS || '',
              city: r.CITY || '',
            };
          }
          for (const originalCode of clientCodes) {
            const db2Code = normalizeClientCodeForDb2(originalCode);
            if (db2Code && clientInfo[db2Code] && !clientInfo[originalCode]) {
              clientInfo[originalCode] = clientInfo[db2Code];
            }
          }
        }
      } catch (e) {
        logger.warn(`[kpi:api] Error fetching client info: ${e.message}`);
        // Fallback: try to get names from RAW_DATA in alerts
        try {
          const placeholders = clientCodes.map(() => '?').join(',');
          const namesResult = await kpiQuery(
            `SELECT CLIENT_CODE, RAW_DATA FROM ${SCHEMA}.KPI_ALERTS
             WHERE CLIENT_CODE IN (${placeholders}) AND IS_ACTIVE = 1
             FETCH FIRST ${clientCodes.length} ROWS ONLY`, clientCodes);
          for (const row of namesResult.rows) {
            const raw = parseRawData(row.RAW_DATA);
            const code = (row.CLIENT_CODE || '').trim();
            if (raw.nombreComercial && !clientInfo[code]) {
              clientInfo[code] = { name: raw.nombreComercial, address: '', city: '' };
            }
          }
        } catch (_) { /* non-critical */ }
      }
    }

    // 5. Fetch detailed alerts per client (with transformation for compact UI)
    const clientAlerts = {}; // code â†’ [{ type, severity, title, summary, detail, actions, ui_hint }]
    if (clientCodes.length > 0) {
      try {
        const placeholders = clientCodes.map(() => '?').join(',');
        const alertsResult = await kpiQuery(
          `SELECT CLIENT_CODE, ALERT_TYPE, SEVERITY, MESSAGE, RAW_DATA
           FROM ${SCHEMA}.KPI_ALERTS
           WHERE CLIENT_CODE IN (${placeholders}) AND IS_ACTIVE = 1
           ORDER BY CASE SEVERITY WHEN 'critical' THEN 0 WHEN 'warning' THEN 1 ELSE 2 END`,
          clientCodes
        );
        for (const row of alertsResult.rows) {
          const code = (row.CLIENT_CODE || '').trim();
          if (!clientAlerts[code]) clientAlerts[code] = [];
          const rawData = parseRawData(row.RAW_DATA);
          const compact = transformAlert({
            alertType: row.ALERT_TYPE, severity: row.SEVERITY,
            message: row.MESSAGE, rawData,
          });
          clientAlerts[code].push({
            type: row.ALERT_TYPE,
            severity: (row.SEVERITY || '').toLowerCase(),
            title: compact.title || row.ALERT_TYPE,
            summary: compact.summary || (row.MESSAGE || '').substring(0, 120),
            detail: compact.detail || '',
            actions: compact.actions || [],
            ui_hint: compact.ui_hint || {},
          });
        }
      } catch (e) {
        logger.warn(`[kpi:api] Error fetching client alerts detail: ${e.message}`);
      }
    }

    // 6. Last load info
    const lastLoadResult = await kpiQuery(
      `SELECT LOAD_ID, STATUS, TOTAL_ALERTS, COMPLETED_AT
       FROM ${SCHEMA}.KPI_LOADS ORDER BY STARTED_AT DESC FETCH FIRST 1 ROWS ONLY`
    );
    const lastLoad = lastLoadResult.rows[0] || null;

    // Format byType as array with labels
    const typeLabels = {
      DESVIACION_VENTAS: 'Desviacion Ventas',
      CUOTA_SIN_COMPRA: 'Sin Compras',
      DESVIACION_REFERENCIACION: 'Referenciacion',
      PROMOCION: 'Promociones',
      ALTA_CLIENTE: 'Clientes Nuevos',
      AVISO: 'Avisos',
      MEDIOS_CLIENTE: 'Equipamiento',
    };

    // Ordered consistently
    const typeOrder = ['DESVIACION_VENTAS', 'CUOTA_SIN_COMPRA', 'DESVIACION_REFERENCIACION',
      'ALTA_CLIENTE', 'PROMOCION', 'AVISO', 'MEDIOS_CLIENTE'];

    const byType = typeOrder
      .filter(t => byTypeMap[t])
      .map(t => ({
        type: t,
        label: typeLabels[t] || t,
        critical: byTypeMap[t].critical,
        warning: byTypeMap[t].warning,
        info: byTypeMap[t].info,
        total: byTypeMap[t].critical + byTypeMap[t].warning + byTypeMap[t].info,
      }));

    res.json({
      success: true,
      totals: {
        alerts: calcTotals.TOTAL_ALERTS,
        clients: calcTotals.TOTAL_CLIENTS.size,
        critical: calcTotals.CRITICAL,
        warning: calcTotals.WARNING,
        info: calcTotals.INFO,
      },
      byType,
      clients: sortedClients.map(c => {
        const info = clientInfo[c.code] || {};
        return {
          code: c.code,
          name: info.name || '',
          address: info.address || '',
          city: info.city || '',
          total: c.total,
          critical: c.critical,
          warning: c.warning,
          info: c.info,
          types: Array.from(c.types),
          alerts: clientAlerts[c.code] || [],
        };
      }),
      lastLoad: lastLoad ? {
        loadId: lastLoad.LOAD_ID,
        status: lastLoad.STATUS,
        totalAlerts: parseInt(lastLoad.TOTAL_ALERTS || 0),
        completedAt: lastLoad.COMPLETED_AT,
      } : null,
    });
  } catch (err) {
    logger.error(`[kpi:api] Error en GET /dashboard: ${err.message}`);
    res.status(500).json({ success: false, error: 'Error obteniendo dashboard KPI' });
  }
});

module.exports = router;

// alert_transformer.js: Transforma alertas verbosas en formato compacto
// Summary: max 2 lineas, action-oriented
// Detail: colapsable, max 4 lineas
// Sin la palabra "año", fechas DD/MM, formato "3.983,17 €"
'use strict';

/**
 * Formatea numero en formato ES con simbolo €.
 * 3983.17 → "3.983,17 €"  |  -2864 → "−2.864,00 €"
 */
function fmtMoney(n) {
    if (n === null || n === undefined) return '0 €';
    const abs = Math.abs(n);
    const parts = abs.toFixed(2).split('.');
    const intPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    const sign = n < 0 ? '−' : '';
    return `${sign}${intPart},${parts[1]} €`;
}

/**
 * Formatea numero corto para summary (sin decimales si entero, con k si > 1000).
 * 1132.56 → "1.132 €"  |  38533.02 → "38.533 €"
 */
function fmtMoneyShort(n) {
    if (n === null || n === undefined) return '0 €';
    const abs = Math.abs(n);
    const intPart = Math.round(abs).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    const sign = n < 0 ? '−' : '';
    return `${sign}${intPart} €`;
}

/**
 * DD/MM desde una fecha string (quita el año/año).
 * "2026-03-05" → "05/03"  |  "05/03/2026" → "05/03"  |  "20-03-2025" → "20/03"
 */
function fmtDateShort(dateStr) {
    if (!dateStr || !dateStr.trim()) return null;
    const s = dateStr.trim();
    // ISO: YYYY-MM-DD
    const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (iso) return `${iso[3]}/${iso[2]}`;
    // ES invertido: DD-MM-YYYY
    const esDash = s.match(/^(\d{2})-(\d{2})-(\d{4})/);
    if (esDash) return `${esDash[1]}/${esDash[2]}`;
    // ES: DD/MM/YYYY
    const es = s.match(/^(\d{2})\/(\d{2})\/\d{2,4}/);
    if (es) return `${es[1]}/${es[2]}`;
    // DD/MM already
    if (/^\d{2}\/\d{2}$/.test(s)) return s;
    return s.substring(0, 5);
}

/**
 * Transforma una alerta completa en formato compacto.
 * Retorna campos adicionales: title, summary, detail, actions, meta, ui_hint
 * El campo message original se mantiene por retrocompatibilidad.
 *
 * @param {object} alert - alerta con { alertType/type, severity, message, rawData }
 * @returns {object} campos compactos { title, summary, detail, actions, meta, ui_hint }
 */
function transformAlert(alert) {
    const raw = typeof alert.rawData === 'string' ? safeParse(alert.rawData) : (alert.rawData || {});
    const type = alert.alertType || alert.type || '';

    switch (type) {
        case 'DESVIACION_VENTAS':
            return transformDesviacionVentas(alert, raw);
        case 'CUOTA_SIN_COMPRA':
            return transformCuotaSinCompra(alert, raw);
        case 'DESVIACION_REFERENCIACION':
            return transformDesviacionRef(alert, raw);
        case 'PROMOCION':
            return transformPromocion(alert, raw);
        case 'ALTA_CLIENTE':
            return transformAltaCliente(alert, raw);
        case 'AVISO':
            return transformAviso(alert, raw);
        case 'MEDIOS_CLIENTE':
            return transformMedios(alert, raw);
        default:
            return {
                title: type,
                summary: (alert.message || '').substring(0, 120),
                detail: '',
                actions: [],
                meta: {},
                ui_hint: { color: '#888888', icon: 'info' },
            };
    }
}

function safeParse(val) {
    if (!val) return {};
    if (typeof val === 'object') return val;
    try { return JSON.parse(val); } catch (_) { return {}; }
}

// ─── DESVIACION VENTAS ────────────────────────────────────────
function transformDesviacionVentas(alert, raw) {
    const desv = raw.desviacionEur || 0;
    const pct = raw.desviacionPct != null ? Math.round(Math.abs(raw.desviacionPct)) : null;
    const positivo = desv >= 0;
    const pctStr = pct != null ? ` (${positivo ? '+' : '−'}${pct} %)` : '';

    const detailParts = [];
    if (raw.vtaActual != null) detailParts.push(`Comprado: ${fmtMoney(raw.vtaActual)}`);
    if (raw.cuotaAnual != null) detailParts.push(`Obj.: ${fmtMoney(raw.cuotaAnual)}`);
    if (raw.ultCompra) detailParts.push(`Ult. compra: ${fmtDateShort(raw.ultCompra)}`);

    let detail = detailParts.join(' · ');
    if (!positivo) {
        detail += '\nQue hacer: Revisar surtido y ofrecer productos que no esta comprando';
    }

    return {
        title: positivo ? 'Ventas OK' : 'Ventas < objetivo',
        severity: alert.severity,
        summary: positivo
            ? `+${fmtMoney(desv)} sobre objetivo${pctStr}`
            : `${fmtMoney(desv)} vs objetivo${pctStr} → revisar surtido`,
        detail,
        actions: positivo ? [] : ['Revisar surtido', 'Ofrecer helados'],
        meta: {
            lastPurchase: fmtDateShort(raw.ultCompra),
            amount: raw.vtaActual,
            target: raw.cuotaAnual,
            pctDeviation: raw.desviacionPct != null ? -Math.abs(raw.desviacionPct) : null,
        },
        ui_hint: {
            color: positivo ? '#44DD88' : '#FF4444',
            icon: positivo ? 'trending_up' : 'trending_down',
        },
    };
}

// ─── CUOTA SIN COMPRA ────────────────────────────────────────
function transformCuotaSinCompra(alert, raw) {
    const canal = (raw.canal || 'Helados').trim();
    const canalLabel = canal.toUpperCase() === 'HELADO' ? 'Helados'
        : canal.toUpperCase() === 'FROZEN FOOD' ? 'Congelados'
            : canal.charAt(0).toUpperCase() + canal.slice(1).toLowerCase();

    const detailParts = [`Canal: ${canalLabel}`];
    if (raw.difCum != null && raw.difCum > 0) {
        detailParts.push(`Pendiente acum.: ${fmtMoney(raw.difCum)}`);
    } else if (raw.cuotaCum != null) {
        detailParts.push(`Pendiente acum.: ${fmtMoney(raw.cuotaCum)}`);
    }
    if (raw.cuotaMes != null && raw.cuotaMes > 0) {
        detailParts.push(`Obj. mes: ${fmtMoney(raw.cuotaMes)}`);
    }

    return {
        title: `Sin compras ${canalLabel}`,
        severity: alert.severity,
        summary: `Cuota ${fmtMoneyShort(raw.cuotaAnual)} sin pedidos → contactar`,
        detail: detailParts.join(' · ') + `\nQue hacer: Conseguir primer pedido de ${canalLabel}`,
        actions: ['Contactar cliente', 'Conseguir primer pedido'],
        meta: {
            lastPurchase: null,
            amount: 0,
            target: raw.cuotaAnual,
            channel: raw.canal,
        },
        ui_hint: { color: '#FF8800', icon: 'remove_shopping_cart' },
    };
}

// ─── DESVIACION REFERENCIACION ───────────────────────────────
function transformDesviacionRef(alert, raw) {
    const faltantes = raw.desviacion != null ? Math.abs(raw.desviacion) : 0;
    const actuales = raw.refActual || 0;
    const esperados = raw.refAnterior || raw.refTotAnterior || (actuales + faltantes);
    const refs = (raw.refs || []).slice(0, 3);

    const refList = refs.map((r, i) => `${i + 1}. ${r.trim()}`).join(' · ');
    const moreStr = faltantes > refs.length ? ` (+${faltantes - refs.length} mas)` : '';

    return {
        title: `Faltan ${faltantes} producto${faltantes !== 1 ? 's' : ''}`,
        severity: alert.severity,
        summary: `Compra ${actuales}/${esperados} refs. esperadas → llevar muestras`,
        detail: (refList ? refList + moreStr : '') +
            '\nQue hacer: Llevar muestras o argumentario en proxima visita',
        actions: ['Llevar muestras', 'Ofrecer argumentario'],
        meta: { count: faltantes },
        ui_hint: { color: '#FF6B9D', icon: 'inventory_2' },
    };
}

// ─── PROMOCION ───────────────────────────────────────────────
function transformPromocion(alert, raw) {
    const promoText = (raw.promocion || '').trim();
    return {
        title: 'Promo disponible',
        severity: 'info',
        summary: promoText.length > 80
            ? promoText.substring(0, 77) + '...' + ' → ofrecer'
            : (promoText || 'Promocion Nestle') + ' → ofrecer en visita',
        detail: promoText + '\nQue hacer: Ofrecer esta promocion al cliente',
        actions: ['Ofrecer promocion'],
        meta: {},
        ui_hint: { color: '#44DD88', icon: 'local_offer' },
    };
}

// ─── ALTA CLIENTE ────────────────────────────────────────────
function transformAltaCliente(alert, raw) {
    const desv = raw.desviacionEur || 0;
    const pct = raw.pctCumplido;
    const positivo = desv >= 0;
    const pctStr = pct != null ? ` (${pct} %)` : '';

    const detailParts = [];
    if (raw.fechaAlta) detailParts.push(`Alta: ${fmtDateShort(raw.fechaAlta)}`);
    if (raw.vtaActual != null) detailParts.push(`Comprado: ${fmtMoney(raw.vtaActual)}`);
    if (raw.cuotaAnual != null) detailParts.push(`Obj.: ${fmtMoney(raw.cuotaAnual)}`);

    return {
        title: positivo ? 'Nuevo cliente OK' : 'Seguimiento nuevo',
        severity: alert.severity,
        summary: positivo
            ? `+${fmtMoney(desv)} vs obj.${pctStr}`
            : `${fmtMoney(desv)} vs obj.${pctStr} → visita frecuente`,
        detail: detailParts.join(' · ') +
            (positivo ? '' : '\nQue hacer: Programar visitas regulares para fidelizar'),
        actions: positivo ? [] : ['Programar visita', 'Asegurar pedidos'],
        meta: {
            lastPurchase: fmtDateShort(raw.ultCompra),
