const crypto = require('crypto');
const logger = require('./logger');

class CircularBuffer {
    constructor(size) {
        this.size = size;
        this.buffer = new Array(size);
        this.head = 0;
        this.count = 0;
    }

    push(item) {
        this.buffer[this.head] = item;
        this.head = (this.head + 1) % this.size;
        if (this.count < this.size) {
            this.count++;
        }
    }

    toArray() {
        if (this.count === 0) return [];
        if (this.count < this.size) {
            return this.buffer.slice(0, this.count);
        }
        return [...this.buffer.slice(this.head), ...this.buffer.slice(0, this.head)];
    }

    get length() {
        return this.count;
    }

    clear() {
        this.buffer = new Array(this.size);
        this.head = 0;
        this.count = 0;
    }
}

// Metrics storage
const metrics = {
    // HTTP request metrics
    httpRequestsTotal: new Map(),
    httpRequestDuration: new CircularBuffer(1000),
    httpRequestSize: new CircularBuffer(1000),
    httpResponseSize: new CircularBuffer(1000),

    // Cache metrics
    cacheHits: 0,
    cacheMisses: 0,
    cacheSize: 0,

    // Database metrics
    dbQueriesTotal: 0,
    dbQueryDuration: new CircularBuffer(1000),
    dbErrorsTotal: 0,

    // Custom metrics
    activeConnections: 0,
    memoryUsage: new CircularBuffer(1000),

    // Timestamps
    startTime: Date.now(),
};

// Configuration
const CONFIG = {
    durationBuckets: [0.01, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10],
    sizeBuckets: [100, 500, 1000, 5000, 10000, 50000, 100000],
