        process['env'].INTERNAL_METRICS_TOKEN,
        process['env'].METRICS_TOKEN,
        process['env'].INTERNAL_HEALTH_TOKEN,
        process['env'].HEALTHCHECK_TOKEN,
    ].filter(Boolean);
}

function safeEquals(a, b) {
