            if (await skipRequest(req, res)) return next();
            if (rateLimitStore.requireRedis && !rateLimitStore.isAvailable()) {
                return res.status(503).json({ error: 'Servicio temporalmente no disponible', code: 'RATE_LIMIT_UNAVAILABLE' });
