      if (isG4Testmovil()) {
        return Boolean(first(await rows(connection,
          'SELECT NUMERO FROM TESTMOVIL.LIQUIDIARI WHERE TRIM(VENDEDOR) = ? '
            + 'AND FECHADIA = ? AND FECHAMES = ? AND FECHAANO = ? '
            + 'FETCH FIRST 1 ROW ONLY WITH RS',
