              + `WHERE TRIM(CODIGOVENDEDOR) IN (${ownerPlaceholders}) AND DIALIQUIDACION = ? `
              + "AND MESLIQUIDACION = ? AND ANOLIQUIDACION = ? AND STATUS = 'CLOSED' WITH RS",
