                + `FROM ${finance.cobros} `
                + 'WHERE TRIM(CODIGOVENDEDOR) = ? AND DIACOBRO = ? AND MESCOBRO = ? AND ANOCOBRO = ? '
                + "AND COALESCE(LIQUIDADO_SN, 'N') <> 'S' ORDER BY ID WITH RS",
              [String(repartidorId).trim(), day, month, year]);
