                String(rowValue(row, 'SERIEDOCUMENTO') || '').trim(),
                String(rowValue(row, 'TERMINALDOCUMENTO') || '').trim(),
                String(rowValue(row, 'NUMERODOCUMENTO') || '').trim(),
