            bankDeposits, pending, openingBalance, breakdown, balance };
        }
        const balanceRow = first(await rows(connection,
          `SELECT SALDO_PENDIENTE FROM ${finance.balances} WHERE CODIGO_REPARTIDOR = ? FOR UPDATE WITH RS`,
