    async selectSaldoFromPendingCobros({ info, repartidorId }) {
      const codeColumn = cobrosCodeColumn(info);
      const pendingColumn = info.cobrosAligned
        ? 'IMPORTEPENDIENTE'
        : info.has('REPARTIDOR_COBROS', 'IMPORTE_PENDIENTE')
          ? 'IMPORTE_PENDIENTE'
          : cobrosAmountColumn(info);
      const notLiquidated = cobrosNotLiquidatedCondition(info);
      return run(
        `SELECT COALESCE(SUM(${pendingColumn}), 0) AS SALDO
       FROM ${tables.cobros}
       WHERE TRIM(${codeColumn}) = ?
         AND ${notLiquidated}`,
        [repartidorId],
      );
    },

    async selectEvolution({ info, ids }) {
      const codeColumn = cobrosCodeColumn(info);
      const amountColumn = cobrosAmountColumn(info);
      const codeFilter = inClause(`TRIM(${codeColumn})`, ids);
      const yearExpr = info.cobrosHasCollectionDate
        ? 'ANOCOBRO'
        : info.cobrosHasFechaCobro
          ? 'YEAR(FECHA_COBRO)'
          : 'ANOVENCIMIENTO';
      const monthExpr = info.cobrosHasCollectionDate
        ? 'MESCOBRO'
        : info.cobrosHasFechaCobro
          ? 'MONTH(FECHA_COBRO)'
          : 'MESVENCIMIENTO';
      return run(
        `SELECT ${yearExpr} AS ANO,
            ${monthExpr} AS MES,
            COALESCE(SUM(${amountColumn}), 0) AS TOTAL,
            COUNT(*) AS NUM_COBROS
     FROM ${tables.cobros}
     WHERE ${codeFilter.sql}
       AND ${yearExpr} BETWEEN 2000 AND 2100
       AND ${monthExpr} BETWEEN 1 AND 12
     GROUP BY ${yearExpr}, ${monthExpr}
     ORDER BY ${yearExpr} DESC, ${monthExpr} DESC
     FETCH FIRST 6 ROWS ONLY`,
        codeFilter.params,
      );
    },

    async selectTopProducts({ ids, safeLimit }) {
      const repFilter = inClause('TRIM(OPP.CODIGOREPARTIDOR)', ids);
      return run(
        `SELECT TRIM(LAC.CODIGOARTICULO) AS CODIGO,
            TRIM(COALESCE(NULLIF(TRIM(ART.DESCRIPCIONARTICULO), ''), NULLIF(TRIM(LAC.DESCRIPCION), ''), LAC.CODIGOARTICULO)) AS NOMBRE,
            COALESCE(SUM(LAC.CANTIDADENVASES), 0) AS UNIDADES,
            COALESCE(SUM(LAC.IMPORTEVENTA), 0) AS IMPORTE
     FROM ${erpDataSchema}.CPC CPC
     INNER JOIN ${erpDataSchema}.LAC LAC
       ON LAC.SUBEMPRESAALBARAN = CPC.SUBEMPRESAALBARAN
      AND LAC.EJERCICIOALBARAN = CPC.EJERCICIOALBARAN
      AND LAC.SERIEALBARAN = CPC.SERIEALBARAN
      AND LAC.TERMINALALBARAN = CPC.TERMINALALBARAN
      AND LAC.NUMEROALBARAN = CPC.NUMEROALBARAN
     LEFT JOIN ${erpDataSchema}.ART ART
       ON TRIM(ART.CODIGOARTICULO) = TRIM(LAC.CODIGOARTICULO)
     INNER JOIN ${erpDataSchema}.OPP OPP
       ON OPP.NUMEROORDENPREPARACION = CPC.NUMEROORDENPREPARACION
      AND OPP.EJERCICIOORDENPREPARACION = CPC.EJERCICIOORDENPREPARACION
     WHERE ${repFilter.sql}
       AND CPC.ANODOCUMENTO >= YEAR(CURRENT DATE) - 1
       AND TRIM(LAC.CODIGOARTICULO) <> ''
     GROUP BY TRIM(LAC.CODIGOARTICULO),
              TRIM(COALESCE(NULLIF(TRIM(ART.DESCRIPCIONARTICULO), ''), NULLIF(TRIM(LAC.DESCRIPCION), ''), LAC.CODIGOARTICULO))
     ORDER BY IMPORTE DESC, CODIGO
     FETCH FIRST ${safeLimit} ROWS ONLY`,
        repFilter.params,
      );
    },
  };
}

let _defaultRepo = null;

function getRepartoFinanceDb2Repository() {
  if (!_defaultRepo) {
    _defaultRepo = createRepartoFinanceDb2Repository();
  }
  return _defaultRepo;
}

function resetRepartoFinanceDb2RepositoryForTests() {
  _defaultRepo = null;
}

module.exports = {
  createRepartoFinanceDb2Repository,
  getRepartoFinanceDb2Repository,
  resetRepartoFinanceDb2RepositoryForTests,
  resolveFinanceBindings,
  FinanceRepoSchemaError,
  skipIsolatedTestFinanceSeed,
  assertIsolatedTestWriteTable,
};

'use strict';

const { RepartoPersistenceError } = require('../services/reparto-confirmation-service');
const {
  resolveDeliveryAmount,
  allowsEmptyPlannedLines,
} = require('../services/delivery-amount-resolver');

const ERP_SCHEMA = 'DSEDAC';
const CLIENT_CODE_PATTERN = /^[A-Za-z0-9_][A-Za-z0-9_-]{0,39}$/;
const DRIVER_CODE_PATTERN = /^[A-Za-z0-9_][A-Za-z0-9_-]{0,39}$/;

class RepartoPlannedDeliveryError extends RepartoPersistenceError {
  constructor(message, { code = 'REPARTO_PLANNED_DELIVERY_UNAVAILABLE', statusCode = 503, details } = {}) {
    super(message, { code, statusCode, details });
    this.name = 'RepartoPlannedDeliveryError';
  }
}

function text(row, name) {
  const value = row?.[name] ?? row?.[name.toLowerCase()] ?? row?.[name.toUpperCase()];
  return value == null ? '' : String(value).trim();
}

function number(row, name) {
  const value = row?.[name] ?? row?.[name.toLowerCase()] ?? row?.[name.toUpperCase()];
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function parseDeliveryItemId(itemId) {
  if (typeof itemId !== 'string') return null;
  const parts = itemId.trim().split('-');
  if (parts.length < 4) return null;
  const [yearRaw, serieRaw, terminalRaw, numberRaw, ...clientParts] = parts;
  if (!/^\d{4}$/.test(yearRaw) || !/^[A-Za-z0-9]{1,5}$/.test(serieRaw)
    || !/^\d{1,3}$/.test(terminalRaw) || !/^\d{1,9}$/.test(numberRaw)) return null;
  const ejercicio = Number(yearRaw);
  const terminal = Number(terminalRaw);
  const numero = Number(numberRaw);
  if (ejercicio < 2000 || ejercicio > 2100 || terminal < 0 || numero < 1) return null;
  const cliente = clientParts.length ? clientParts.join('-').trim() : null;
  if (cliente !== null && !CLIENT_CODE_PATTERN.test(cliente)) return null;
  return Object.freeze({ ejercicio, serie: serieRaw, terminal, numero, cliente });
}

function assertConnection(connection) {
  if (!connection || (typeof connection.query !== 'function' && typeof connection.execute !== 'function')) {
    throw new TypeError('DB2 connection must expose query(sql, params) or execute(sql, params)');
  }
}

function assertRepartidorId(repartidorId) {
  const value = String(repartidorId || '').trim();
  if (!DRIVER_CODE_PATTERN.test(value)) {
    throw new RepartoPlannedDeliveryError('Identidad de repartidor invalida', {
      code: 'INVALID_DELIVERY_IDENTITY', statusCode: 400,
    });
  }
  return value;
}

function assertItemIdentity(itemId) {
  const parsed = parseDeliveryItemId(itemId);
  if (!parsed) {
    throw new RepartoPlannedDeliveryError('Identificador de entrega invalido', {
      code: 'INVALID_DELIVERY_IDENTITY', statusCode: 400,
    });
  }
  return parsed;
}

function validateSchema(schema) {
  if (schema !== ERP_SCHEMA) {
    throw new RepartoPlannedDeliveryError('El puerto de lectura planificada solo admite DSEDAC', {
      code: 'REPARTO_PLANNED_DELIVERY_UNAVAILABLE', statusCode: 503, details: { schema },
    });
  }
  return schema;
}

async function executeRows(connection, sql, params) {
  try {
    const result = typeof connection.query === 'function'
      ? await connection.query(sql, params)
      : await connection.execute(sql, params);
    return Array.isArray(result) ? result : (result?.rows || []);
  } catch (_) {
    throw new RepartoPlannedDeliveryError('No se pudo consultar la entrega planificada', {
      code: 'REPARTO_PLANNED_DELIVERY_UNAVAILABLE', statusCode: 503,
    });
  }
}

function headerQuery(schema, includeClient) {
  const clientClause = includeClient ? ' AND TRIM(CPC.CODIGOCLIENTEALBARAN) = ?' : '';
  return `
    SELECT
      TRIM(CPC.SUBEMPRESAALBARAN) AS SUBEMPRESA,
      CPC.EJERCICIOALBARAN,
      TRIM(CPC.SERIEALBARAN) AS SERIEALBARAN,
      CPC.TERMINALALBARAN,
      CPC.NUMEROALBARAN,
      TRIM(CPC.CODIGOCLIENTEALBARAN) AS CODIGOCLIENTE,
      TRIM(CPC.CODIGOFORMAPAGO) AS FORMA_PAGO,
      TRIM(PC.CODIGO) AS CATALOGO_FORMA_PAGO,
      TRIM(PC.DEBE_COBRAR) AS DEBE_COBRAR,
      TRIM(CLX.COBRORIGUROSOSN) AS COBRO_RIGUROSO,
      TRIM(COALESCE(NULLIF(TRIM(CLI.NOMBREALTERNATIVO), ''), CLI.NOMBRECLIENTE, CPC.CODIGOCLIENTEALBARAN)) AS NOMBRECLIENTE,
      TRIM(OPP.CODIGOREPARTIDOR) AS CODIGOREPARTIDOR,
      CPC.EJERCICIOPEDIDO,
      CPC.NUMEROPEDIDO,
      CPC.IMPORTETOTAL,
      CAC.IMPORTETOTAL AS CAC_IMPORTETOTAL
    FROM ${schema}.CPC CPC
    INNER JOIN ${schema}.OPP OPP
      ON OPP.NUMEROORDENPREPARACION = CPC.NUMEROORDENPREPARACION
      AND OPP.EJERCICIOORDENPREPARACION = CPC.EJERCICIOORDENPREPARACION
      AND TRIM(OPP.SUBEMPRESA) = TRIM(CPC.SUBEMPRESAPEDIDO)
    LEFT JOIN ${schema}.CLI CLI
      ON TRIM(CLI.CODIGOCLIENTE) = TRIM(CPC.CODIGOCLIENTEALBARAN)
    LEFT JOIN JAVIER.PAYMENT_CONDITIONS PC
      ON TRIM(PC.CODIGO) = TRIM(CPC.CODIGOFORMAPAGO)
      AND PC.ACTIVO = 'S'
    LEFT JOIN ${schema}.CLX CLX
      ON TRIM(CLX.CODIGOCLIENTE) = TRIM(CPC.CODIGOCLIENTEALBARAN)
    LEFT JOIN ${schema}.CAC CAC
      ON CAC.SUBEMPRESAALBARAN = CPC.SUBEMPRESAALBARAN
      AND CAC.EJERCICIOALBARAN = CPC.EJERCICIOALBARAN
      AND TRIM(CAC.SERIEALBARAN) = TRIM(CPC.SERIEALBARAN)
      AND CAC.TERMINALALBARAN = CPC.TERMINALALBARAN
      AND CAC.NUMEROALBARAN = CPC.NUMEROALBARAN
      AND TRIM(CAC.CODIGOCLIENTEALBARAN) = TRIM(CPC.CODIGOCLIENTEALBARAN)
    WHERE CPC.EJERCICIOALBARAN = ?
      AND TRIM(CPC.SERIEALBARAN) = ?
      AND CPC.TERMINALALBARAN = ?
      AND CPC.NUMEROALBARAN = ?
      AND TRIM(OPP.CODIGOREPARTIDOR) = ?${clientClause}
    ORDER BY TRIM(CPC.SUBEMPRESAALBARAN), TRIM(CPC.CODIGOCLIENTEALBARAN), CPC.EJERCICIOALBARAN,
      TRIM(CPC.SERIEALBARAN), CPC.TERMINALALBARAN, CPC.NUMEROALBARAN
  `;
}

function financialDocumentQuery(schema) {
  return `
    SELECT
      TRIM(CVC.TIPODOCUMENTO) AS TIPODOCUMENTO,
      TRIM(CVC.ORIGENDOCUMENTO) AS ORIGENDOCUMENTO,
      TRIM(CVC.SUBEMPRESADOCUMENTO) AS SUBEMPRESADOCUMENTO,
      CVC.EJERCICIODOCUMENTO,
      TRIM(CVC.SERIEDOCUMENTO) AS SERIEDOCUMENTO,
      CVC.TERMINALDOCUMENTO,
      CVC.NUMERODOCUMENTO,
      CVC.XDEDOCUMENTO,
      CVC.DEXDOCUMENTO,
      CVC.IMPORTEPENDIENTE
    FROM ${schema}.CVC CVC
    WHERE TRIM(CVC.SUBEMPRESADOCUMENTO) = ?
      AND CVC.EJERCICIODOCUMENTO = ?
      AND TRIM(CVC.SERIEDOCUMENTO) = ?
      AND CVC.TERMINALDOCUMENTO = ?
      AND CVC.NUMERODOCUMENTO = ?
      AND TRIM(CVC.CODIGOCLIENTEALBARAN) = ?
      AND COALESCE(TRIM(CVC.ANULADOSN), '') <> 'S'
      AND CVC.IMPORTEPENDIENTE > 0
    ORDER BY TRIM(CVC.TIPODOCUMENTO), TRIM(CVC.ORIGENDOCUMENTO),
      TRIM(CVC.SUBEMPRESADOCUMENTO), CVC.EJERCICIODOCUMENTO,
      TRIM(CVC.SERIEDOCUMENTO), CVC.TERMINALDOCUMENTO,
      CVC.NUMERODOCUMENTO, CVC.XDEDOCUMENTO, CVC.DEXDOCUMENTO
    FETCH FIRST 2 ROWS ONLY
  `;
}

function linesQuery(schema) {
  return `
    SELECT
      LAC.SECUENCIA,
      TRIM(LAC.CODIGOARTICULO) AS CODIGOARTICULO,
      TRIM(LAC.DESCRIPCION) AS DESCRIPCION,
      LAC.CANTIDADENVASES,
      LAC.CANTIDADUNIDADES,
      TRIM(LAC.UNIDADMEDIDA) AS UNIDADMEDIDA,
      LAC.PRECIOVENTA,
      LAC.IMPORTEVENTA
    FROM ${schema}.LAC LAC
    WHERE TRIM(LAC.SUBEMPRESAALBARAN) = ?
      AND LAC.EJERCICIOALBARAN = ?
      AND TRIM(LAC.SERIEALBARAN) = ?
      AND LAC.TERMINALALBARAN = ?
      AND LAC.NUMEROALBARAN = ?
      AND TRIM(LAC.CODIGOCLIENTEALBARAN) = ?
      AND (LAC.CANTIDADUNIDADES > 0 OR LAC.CANTIDADENVASES > 0)
    ORDER BY LAC.SECUENCIA, TRIM(LAC.CODIGOARTICULO)
  `;
}

function mapLines(rows, { allowEmpty = false } = {}) {
  if (!rows.length) {
    if (allowEmpty) return [];
    throw new RepartoPlannedDeliveryError('La entrega planificada no contiene lineas', {
      code: 'DELIVERY_SOURCE_INCONSISTENT', statusCode: 409,
    });
  }
  const seen = new Set();
  return rows.map((row) => {
    const sequence = number(row, 'SECUENCIA');
    const cantidadUnidades = number(row, 'CANTIDADUNIDADES');
    const cantidadEnvases = number(row, 'CANTIDADENVASES');
    const cantidadPedida = (cantidadUnidades != null && cantidadUnidades > 0)
      ? cantidadUnidades
      : cantidadEnvases;
    const codigoArticulo = text(row, 'CODIGOARTICULO') || (Number.isInteger(sequence) ? String(sequence) : '');
    const importeLinea = number(row, 'IMPORTEVENTA');
    const precioVenta = number(row, 'PRECIOVENTA');
    if (!Number.isInteger(sequence) || sequence < 0 || !codigoArticulo || cantidadPedida == null
      || cantidadPedida <= 0 || cantidadEnvases == null || cantidadEnvases < 0
      || importeLinea == null || importeLinea < 0 || precioVenta == null || precioVenta < 0) {
      throw new RepartoPlannedDeliveryError('Las lineas planificadas no tienen identidad o cantidades validas', {
        code: 'DELIVERY_SOURCE_INCONSISTENT', statusCode: 409,
      });
    }
    const lineaId = String(sequence);
    if (seen.has(lineaId)) {
      throw new RepartoPlannedDeliveryError('La entrega planificada contiene lineas ambiguas', {
        code: 'DELIVERY_IDENTITY_AMBIGUOUS', statusCode: 409,
      });
    }
    seen.add(lineaId);
    const precioUnitario = importeLinea / cantidadPedida;
    return Object.freeze({
      lineaId,
      codigoArticulo,
      descripcion: text(row, 'DESCRIPCION'),
      cantidadPedida,
      cantidadEnvases,
      unidadMedida: text(row, 'UNIDADMEDIDA'),
      precioUnitario,
      importeLinea,
    });
  });
}

function mapFinancialDocument(rows) {
  if (!rows.length) {
    return Object.freeze({ state: 'MISSING', document: null, importePendiente: 0 });
  }
  if (rows.length !== 1) {
    return Object.freeze({ state: 'AMBIGUOUS', document: null, importePendiente: null });
  }
  const row = rows[0];
  const document = {
    tipo: text(row, 'TIPODOCUMENTO'),
    origen: text(row, 'ORIGENDOCUMENTO'),
    subempresa: text(row, 'SUBEMPRESADOCUMENTO'),
    ejercicio: number(row, 'EJERCICIODOCUMENTO'),
    serie: text(row, 'SERIEDOCUMENTO'),
    terminal: number(row, 'TERMINALDOCUMENTO'),
    numero: number(row, 'NUMERODOCUMENTO'),
    xde: number(row, 'XDEDOCUMENTO'),
    dex: number(row, 'DEXDOCUMENTO'),
  };
  const importePendiente = number(row, 'IMPORTEPENDIENTE');
  if (!document.tipo || !document.origen || !document.subempresa || !document.serie
    || !Number.isInteger(document.ejercicio) || !Number.isInteger(document.terminal)
    || !Number.isInteger(document.numero) || !Number.isInteger(document.xde)
    || !Number.isInteger(document.dex) || importePendiente == null) {
    throw new RepartoPlannedDeliveryError('El documento financiero no tiene identidad o saldo validos', {
      code: 'DELIVERY_SOURCE_INCONSISTENT', statusCode: 409,
    });
  }
  if (importePendiente <= 0) {
    return Object.freeze({ state: 'MISSING', document: null, importePendiente: 0 });
  }
  return Object.freeze({
    state: 'AVAILABLE', document: Object.freeze(document), importePendiente,
  });
}

function mapHeader(row, itemId, lineas, financial, resolvedAmount) {
  const subempresa = text(row, 'SUBEMPRESA');
  const codigoCliente = text(row, 'CODIGOCLIENTE');
  const repartidorId = text(row, 'CODIGOREPARTIDOR');
  const formaPago = text(row, 'FORMA_PAGO');
  const catalogoFormaPago = text(row, 'CATALOGO_FORMA_PAGO');
  const ejercicio = number(row, 'EJERCICIOALBARAN');
  const terminal = number(row, 'TERMINALALBARAN');
  const numero = number(row, 'NUMEROALBARAN');
  const serie = text(row, 'SERIEALBARAN');
  const importeTotal = resolvedAmount.amount;
  if (!subempresa || !codigoCliente || !repartidorId || !serie || !Number.isInteger(ejercicio)
    || !Number.isInteger(terminal) || !Number.isInteger(numero) || importeTotal == null) {
    throw new RepartoPlannedDeliveryError('La cabecera planificada no tiene los datos requeridos', {
      code: 'DELIVERY_SOURCE_INCONSISTENT', statusCode: 409,
    });
  }
  if (formaPago && !catalogoFormaPago) {
    throw new RepartoPlannedDeliveryError('La forma de pago del albaran no figura en el catalogo autorizado', {
      code: 'PAYMENT_CATALOG_UNAVAILABLE', statusCode: 503,
    });
  }
  return Object.freeze({
    documentId: itemId,
    repartidorId,
    cliente: Object.freeze({ codigo: codigoCliente, nombre: text(row, 'NOMBRECLIENTE') || codigoCliente }),
    pedido: Object.freeze({ ejercicio: number(row, 'EJERCICIOPEDIDO'), numero: number(row, 'NUMEROPEDIDO') }),
    document: Object.freeze({
      subempresa, ejercicio, serie, terminal, numero,
    }),
    importeTotal,
    amountSource: resolvedAmount.source,
    pricingState: resolvedAmount.pricingState,
    formaPago,
    cobroObligatorio: text(row, 'DEBE_COBRAR') === 'S' || text(row, 'COBRO_RIGUROSO') === 'S',
    importePendiente: financial.importePendiente,
    financialDocumentState: financial.state,
    financialDocument: financial.document,
    lineas,
  });
}

function createRepartoPlannedDeliveryDb2Port({ schema = ERP_SCHEMA } = {}) {
  const safeSchema = validateSchema(schema);

  async function getPlannedDelivery(connection, itemId, repartidorId) {
    assertConnection(connection);
    const identity = assertItemIdentity(itemId);
    const safeRepartidorId = assertRepartidorId(repartidorId);
    const headerParams = [identity.ejercicio, identity.serie, identity.terminal, identity.numero, safeRepartidorId];
    if (identity.cliente) headerParams.push(identity.cliente);
    const headers = await executeRows(connection, headerQuery(safeSchema, Boolean(identity.cliente)), headerParams);
    if (!headers.length) {
      throw new RepartoPlannedDeliveryError('Entrega no encontrada', {
        code: 'DELIVERY_NOT_FOUND', statusCode: 404,
      });
    }
    if (headers.length !== 1) {
      throw new RepartoPlannedDeliveryError('La identidad de entrega no es inequivoca', {
        code: 'DELIVERY_IDENTITY_AMBIGUOUS', statusCode: 409,
      });
    }
    const header = headers[0];
    const documentParams = [
      text(header, 'SUBEMPRESA'), number(header, 'EJERCICIOALBARAN'), text(header, 'SERIEALBARAN'),
      number(header, 'TERMINALALBARAN'), number(header, 'NUMEROALBARAN'), text(header, 'CODIGOCLIENTE'),
    ];
    const rawLines = await executeRows(connection, linesQuery(safeSchema), documentParams);
    const provisionalLines = mapLines(rawLines, { allowEmpty: true });
    const lineSum = provisionalLines.reduce((sum, line) => sum + Number(line.importeLinea || 0), 0);
    const zeroPriceQtyLines = provisionalLines.filter(
      (line) => Number(line.cantidadPedida) > 0 && Math.abs(Number(line.importeLinea) || 0) < 0.005,
    ).length;
    const resolvedAmount = resolveDeliveryAmount({
      cpcTotal: number(header, 'IMPORTETOTAL') || 0,
      cacTotal: number(header, 'CAC_IMPORTETOTAL') || 0,
      lacLineSum: lineSum,
      qtyLines: provisionalLines.length,
      zeroPriceQtyLines,
    });
    if (!allowsEmptyPlannedLines({
      importeTotal: resolvedAmount.amount,
      qtyLines: provisionalLines.length,
      pricingState: resolvedAmount.pricingState,
    }) && provisionalLines.length === 0) {
      throw new RepartoPlannedDeliveryError('La entrega planificada no contiene lineas', {
        code: 'DELIVERY_SOURCE_INCONSISTENT', statusCode: 409,
      });
    }
    const lineas = provisionalLines;
    const financial = mapFinancialDocument(await executeRows(
      connection,
      financialDocumentQuery(safeSchema),
      documentParams,
    ));
    return mapHeader(header, itemId, lineas, financial, resolvedAmount);
  }

  return Object.freeze({
    getPlannedDelivery,
    forConnection(connection) {
      assertConnection(connection);
      return Object.freeze({
        getPlannedDelivery: (itemId, repartidorId) => getPlannedDelivery(connection, itemId, repartidorId),
      });
    },
  });
}

module.exports = {
  ERP_SCHEMA,
  RepartoPlannedDeliveryError,
  createRepartoPlannedDeliveryDb2Port,
  parseDeliveryItemId,
};

'use strict';

const { RepartoPersistenceError } = require('../services/reparto-confirmation-service');
const { TABLE_MAPPINGS, validateFinanceTableMapping } = require('../config/reparto-runtime');

const IDENTIFIER = /^[A-Z][A-Z0-9_]*\.[A-Z][A-Z0-9_]*$/;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9._:-]{8,128}$/;
const FINANCIAL_DOCUMENT_COLUMNS = Object.freeze([
  'DOCUMENTO_TIPO', 'DOCUMENTO_ORIGEN', 'DOCUMENTO_SUBEMPRESA',
  'DOCUMENTO_EJERCICIO', 'DOCUMENTO_SERIE', 'DOCUMENTO_TERMINAL',
  'DOCUMENTO_NUMERO', 'DOCUMENTO_XDE', 'DOCUMENTO_DEX',
]);
const REQUIRED = Object.freeze({
  confirmation: Object.freeze([
    'ID', 'IDEMPOTENCY_KEY', 'DOCUMENT_ID', 'REPARTIDOR_ID', 'CLIENTE_CODIGO',
    'CLIENTE_NOMBRE', 'PEDIDO_EJERCICIO', 'PEDIDO_NUMERO', ...FINANCIAL_DOCUMENT_COLUMNS,
    'STATUS', 'OCCURRED_AT', 'CONFIRMED_AT', 'RECEPTOR_NOMBRE', 'RECEPTOR_APELLIDOS',
    'RECEPTOR_DNI', 'FIRMA_EVIDENCE_ID', 'INCIDENCIA_CODIGO',
    'INCIDENCIA_DESCRIPCION', 'INCIDENCIA_OBSERVACIONES', 'OBSERVACIONES',
    'LATITUD', 'LONGITUD', 'RESULT_JSON',
  ]),
  lines: Object.freeze([
    'CONFIRMACION_ID', 'LINEA_ID', 'CODIGO_ARTICULO', 'DESCRIPCION',
    'CANTIDAD_PEDIDA', 'CANTIDAD_ENTREGADA', 'CANTIDAD_RECHAZADA',
    'CANTIDAD_PENDIENTE', 'MOTIVO_DIFERENCIA', 'OBSERVACIONES', 'PRECIO_UNITARIO',
  ]),
  evidences: Object.freeze(['EVIDENCE_ID', 'EVIDENCE_KIND', 'MIME_TYPE']),
  confirmationEvidences: Object.freeze(['CONFIRMACION_ID', 'EVIDENCE_ID']),
  cobros: Object.freeze([
    'ID', 'IDEMPOTENCY_TOKEN', 'CODIGOCLIENTEALBARAN', 'CODIGOVENDEDOR',
    'TIPODOCUMENTO', 'ORIGENDOCUMENTO', 'SUBEMPRESADOCUMENTO',
    'EJERCICIODOCUMENTO', 'SERIEDOCUMENTO', 'TERMINALDOCUMENTO',
    'NUMERODOCUMENTO', 'XDEDOCUMENTO', 'DEXDOCUMENTO', 'IMPORTEVENCIMIENTO',
    'CODIGOFORMAPAGO', 'DIACOBRO', 'MESCOBRO', 'ANOCOBRO',
  ]),
});

class RepartoReceiptUnavailableError extends RepartoPersistenceError {
  constructor(message, details) {
    super(message, { code: 'REPARTO_RECEIPT_UNAVAILABLE', statusCode: 503, details });
    this.name = 'RepartoReceiptUnavailableError';
  }
}

function value(item, key) {
  return item?.[key] ?? item?.[key.toLowerCase()] ?? item?.[key.toUpperCase()];
}

function resultRows(result) {
  return Array.isArray(result) ? result : (result?.rows || []);
}

function ref(identifier) {
  const [schema, table] = String(identifier).split('.');
  return { schema, table };
}

function throwIfAborted(signal) {
  if (signal?.aborted) {
    throw new RepartoPersistenceError('La consulta del recibo fue cancelada', {
      code: 'REPARTO_RECEIPT_TIMEOUT', statusCode: 504,
    });
  }
}

function assertRuntime(runtime) {
  const tables = runtime?.tables;
  const confirmationMatches = Object.entries(TABLE_MAPPINGS[runtime?.tableSet]?.confirmation || {})
    .every(([key, identifier]) => tables?.confirmation?.[key] === identifier);
  const references = [
    tables?.confirmation?.confirmations,
    tables?.confirmation?.lines,
    tables?.confirmation?.evidences,
    tables?.confirmation?.confirmationEvidences,
    tables?.finance?.cobros,
  ];
  // GET receipt is read-only: require valid table mappings, never write capabilities.
  // Write capability gates belong on confirmation/mutation routes only (G2/G7).
  if (!runtime?.valid
      || !['isolated_test', 'production'].includes(runtime.tableSet)
      || !confirmationMatches
      || !validateFinanceTableMapping(runtime).valid
      || references.some((identifier) => !IDENTIFIER.test(identifier || ''))) {
    throw new RepartoReceiptUnavailableError('El runtime canonico del recibo no esta disponible');
  }
  return tables;
}

function assertConfirmationId(id) {
  const normalized = String(id ?? '').trim();
  if (!/^[1-9]\d*$/.test(normalized) || !Number.isSafeInteger(Number(normalized))) {
    throw new RepartoPersistenceError('El identificador de confirmacion es invalido', {
      code: 'REPARTO_RECEIPT_INVALID_ID', statusCode: 422,
    });
  }
  return normalized;
}

function assertIdempotencyKey(key) {
  const normalized = String(key ?? '').trim();
  if (!IDEMPOTENCY_KEY.test(normalized)) {
    throw new RepartoPersistenceError('La clave de idempotencia es invalida', {
      code: 'REPARTO_RECEIPT_INVALID_IDEMPOTENCY_KEY', statusCode: 422,
    });
  }
  return normalized;
}

function normalizeLookup(input) {
  if (typeof input !== 'object' || input == null || Array.isArray(input)) {
    return Object.freeze({ confirmationId: assertConfirmationId(input), idempotencyKey: null });
  }
  const hasId = input.confirmationId !== undefined && input.confirmationId !== null
    && String(input.confirmationId).trim() !== '';
  const hasKey = input.idempotencyKey !== undefined && input.idempotencyKey !== null
    && String(input.idempotencyKey).trim() !== '';
  if (hasId === hasKey) {
    throw new RepartoPersistenceError('Debe indicarse una sola identidad de recibo', {
      code: 'REPARTO_RECEIPT_INVALID_LOOKUP', statusCode: 422,
    });
  }
  return Object.freeze({
    confirmationId: hasId ? assertConfirmationId(input.confirmationId) : null,
    idempotencyKey: hasKey ? assertIdempotencyKey(input.idempotencyKey) : null,
  });
}

function hasValue(input) {
  return input != null && String(input).trim() !== '';
}

function normalizeOwnerScope(input) {
  if (input?.allowAnyOwner === true) {
    return Object.freeze({ allowAnyOwner: true, ownerRepartidorId: null });
  }
  const ownerRepartidorId = String(input?.ownerRepartidorId ?? '').trim();
  if (!/^[A-Za-z0-9_-]{1,20}$/.test(ownerRepartidorId)) {
    throw new RepartoPersistenceError('Alcance de propietario requerido para consultar el recibo', {
      code: 'REPARTO_RECEIPT_ACTOR_REQUIRED', statusCode: 403,
    });
  }
  return Object.freeze({ allowAnyOwner: false, ownerRepartidorId });
}

async function query(connection, sql, params, signal) {
  throwIfAborted(signal);
  let abortHandler;
  try {
    if (signal && typeof connection?.cancel === 'function') {
      abortHandler = () => {
        try { connection.cancel(); } catch (_error) { /* cancellation is best effort */ }
      };
      signal.addEventListener('abort', abortHandler, { once: true });
    }
    const result = typeof connection.query === 'function'
      ? await connection.query(sql, params)
      : await connection.execute(sql, params);
    throwIfAborted(signal);
    return resultRows(result);
  } catch (error) {
    if (error instanceof RepartoPersistenceError) throw error;
    throw new RepartoReceiptUnavailableError('No se pudo consultar el recibo de reparto', {
      causeCode: error?.code || null,
    });
  } finally {
    if (abortHandler) signal.removeEventListener('abort', abortHandler);
  }
}

function createRepartoReceiptDb2Repository({ connectionFactory, runtime } = {}) {
  if (typeof connectionFactory !== 'function') throw new TypeError('connectionFactory is required');
  const tables = assertRuntime(runtime);
  const references = Object.freeze({
    confirmation: ref(tables.confirmation.confirmations),
    lines: ref(tables.confirmation.lines),
    evidences: ref(tables.confirmation.evidences),
    confirmationEvidences: ref(tables.confirmation.confirmationEvidences),
    cobros: ref(tables.finance.cobros),
  });

  async function assertCapabilities(connection, { signal } = {}) {
    if (!connection || (typeof connection.query !== 'function' && typeof connection.execute !== 'function')) {
      throw new RepartoReceiptUnavailableError('La conexion DB2 del recibo no esta disponible');
    }
    const list = Object.values(references);
    const where = list.map(() => '(TABLE_SCHEMA = ? AND TABLE_NAME = ?)').join(' OR ');
    const params = list.flatMap(({ schema, table }) => [schema, table]);
    const tableRows = await query(connection,
      `SELECT TABLE_SCHEMA, TABLE_NAME FROM QSYS2.SYSTABLES WHERE ${where}`,
      params, signal);
    const found = new Set(tableRows.map((item) =>
      `${String(value(item, 'TABLE_SCHEMA')).trim().toUpperCase()}.${String(value(item, 'TABLE_NAME')).trim().toUpperCase()}`));
    const missingTables = list
      .filter(({ schema, table }) => !found.has(`${schema}.${table}`))
      .map(({ schema, table }) => `${schema}.${table}`);
    if (missingTables.length) {
      throw new RepartoReceiptUnavailableError('Faltan tablas del recibo de reparto', { missingTables });
    }
    const columns = await query(connection,
      `SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME FROM QSYS2.SYSCOLUMNS WHERE ${where}`,
      params, signal);
    const available = new Map();
    for (const item of columns) {
      const key = `${String(value(item, 'TABLE_SCHEMA')).trim().toUpperCase()}.${String(value(item, 'TABLE_NAME')).trim().toUpperCase()}`;
      if (!available.has(key)) available.set(key, new Set());
      available.get(key).add(String(value(item, 'COLUMN_NAME')).trim().toUpperCase());
    }
    const missingColumns = Object.entries(REQUIRED).flatMap(([key, names]) => {
      const current = references[key];
      const table = `${current.schema}.${current.table}`;
      return names.filter((name) => !available.get(table)?.has(name))
        .map((name) => `${table}.${name}`);
    });
    if (missingColumns.length) {
      throw new RepartoReceiptUnavailableError('Faltan columnas del recibo de reparto', { missingColumns });
    }
  }

  async function getReceipt(input) {
    const lookup = normalizeLookup(input);
    const ownerScope = normalizeOwnerScope(input);
    const signal = typeof input === 'object' && input ? input.signal : undefined;
    let connection;
    try {
      throwIfAborted(signal);
      try {
        connection = await connectionFactory({ signal });
      } catch (error) {
        if (error instanceof RepartoPersistenceError) throw error;
        throw new RepartoReceiptUnavailableError('La conexion DB2 del recibo no esta disponible');
      }
      await assertCapabilities(connection, { signal });
      const lookupColumn = lookup.confirmationId ? 'ID' : 'IDEMPOTENCY_KEY';
      const lookupValue = lookup.confirmationId ? Number(lookup.confirmationId) : lookup.idempotencyKey;
      const confirmations = await query(connection,
        `SELECT ID, REPARTIDOR_ID FROM ${tables.confirmation.confirmations} WHERE ${lookupColumn} = ? FETCH FIRST 2 ROWS ONLY`,
        [lookupValue], signal);
      if (confirmations.length > 1) {
        throw new RepartoReceiptUnavailableError('La confirmacion del recibo es ambigua');
      }
      if (!confirmations.length) return null;
      const confirmationIdentity = confirmations[0];
      const confirmationOwner = String(value(confirmationIdentity, 'REPARTIDOR_ID') ?? '').trim();
      if (!confirmationOwner) {
        throw new RepartoReceiptUnavailableError('La confirmacion no contiene propietario');
      }
      if (!ownerScope.allowAnyOwner && confirmationOwner !== ownerScope.ownerRepartidorId) {
        throw new RepartoPersistenceError('El recibo no pertenece al repartidor autenticado', {
          code: 'REPARTO_RECEIPT_OWNERSHIP_REQUIRED', statusCode: 403,
        });
      }
      const confirmationId = Number(value(confirmationIdentity, 'ID'));
      if (!Number.isSafeInteger(confirmationId) || confirmationId <= 0) {
        throw new RepartoReceiptUnavailableError('La confirmacion no contiene un identificador');
      }
      const confirmationRows = await query(connection,
        `SELECT * FROM ${tables.confirmation.confirmations} WHERE ID = ? FETCH FIRST 2 ROWS ONLY`,
        [confirmationId], signal);
      if (confirmationRows.length !== 1
          || String(value(confirmationRows[0], 'REPARTIDOR_ID') ?? '').trim() !== confirmationOwner) {
        throw new RepartoReceiptUnavailableError('La confirmacion del recibo cambio durante la consulta');
      }
      const confirmation = confirmationRows[0];
      const lines = await query(connection,
        `SELECT * FROM ${tables.confirmation.lines} WHERE CONFIRMACION_ID = ? ORDER BY LINEA_ID`,
        [confirmationId], signal);
      const evidences = await query(connection,
        // Evidence retrieval starts from the persisted confirmation link. DISTINCT
        // keeps a historical duplicate link from making the canonical snapshot
        // ambiguous; content is still fetched by the evidence service through its
        // bounded, set-based HEX reader.
        `SELECT DISTINCT E.EVIDENCE_ID, E.EVIDENCE_KIND, E.MIME_TYPE FROM ${tables.confirmation.confirmationEvidences} CE INNER JOIN ${tables.confirmation.evidences} E ON E.EVIDENCE_ID = CE.EVIDENCE_ID WHERE CE.CONFIRMACION_ID = ? ORDER BY E.EVIDENCE_ID`,
        [confirmationId], signal);

      const financialValues = FINANCIAL_DOCUMENT_COLUMNS.map((name) => value(confirmation, name));
      const presentFinancialValues = financialValues.filter(hasValue).length;
      let payments = [];
      // Unpaid deliveries persist albaran keys (serie/terminal/numero) without a
      // complete cobro identity (tipo/origen/xde/dex). That is not a cobro row:
      // skip the ledger lookup instead of failing the delivery receipt.
      if (presentFinancialValues === financialValues.length) {
        const paymentKey = [
          value(confirmation, 'IDEMPOTENCY_KEY'), value(confirmation, 'CLIENTE_CODIGO'),
          value(confirmation, 'REPARTIDOR_ID'), ...financialValues,
        ];
        if (paymentKey.some((item) => !hasValue(item))) {
          throw new RepartoReceiptUnavailableError('La identidad financiera de la confirmacion no esta disponible');
        }
        payments = await query(connection,
          `SELECT ID, IDEMPOTENCY_TOKEN, CODIGOCLIENTEALBARAN, CODIGOVENDEDOR, TIPODOCUMENTO, ORIGENDOCUMENTO, SUBEMPRESADOCUMENTO, EJERCICIODOCUMENTO, SERIEDOCUMENTO, TERMINALDOCUMENTO, NUMERODOCUMENTO, XDEDOCUMENTO, DEXDOCUMENTO, IMPORTEVENCIMIENTO, CODIGOFORMAPAGO, DIACOBRO, MESCOBRO, ANOCOBRO FROM ${tables.finance.cobros} WHERE IDEMPOTENCY_TOKEN = ? AND TRIM(CODIGOCLIENTEALBARAN) = ? AND TRIM(CODIGOVENDEDOR) = ? AND TRIM(TIPODOCUMENTO) = ? AND TRIM(ORIGENDOCUMENTO) = ? AND TRIM(SUBEMPRESADOCUMENTO) = ? AND EJERCICIODOCUMENTO = ? AND TRIM(SERIEDOCUMENTO) = ? AND TERMINALDOCUMENTO = ? AND NUMERODOCUMENTO = ? AND XDEDOCUMENTO = ? AND DEXDOCUMENTO = ? FETCH FIRST 2 ROWS ONLY`,
          paymentKey, signal);
      }
      return Object.freeze({
        confirmation,
        lines: Object.freeze(lines),
        evidences: Object.freeze(evidences),
        payments: Object.freeze(payments),
      });
    } finally {
      if (connection && typeof connection.close === 'function') {
        try {
          await connection.close();
        } catch (_error) {
          throw new RepartoReceiptUnavailableError('No se pudo cerrar la conexion DB2 del recibo');
        }
      }
    }
  }

  return Object.freeze({ assertCapabilities, getReceipt });
}

module.exports = {
  FINANCIAL_DOCUMENT_COLUMNS,
  REQUIRED,
  RepartoReceiptUnavailableError,
  createRepartoReceiptDb2Repository,
};

