                    COUNT(DISTINCT TRIM(L.LCCDRF)) as product_count
                FROM DSED.LACLAE L
                WHERE ${LACLAE_FILTER}
                  AND L.LCAADC = ${year}
                  ${vendedorFilter}
                  ${clientFilter}
                  ${searchFilter}
            `;
            const cacheKey = `history:summary:laclae:${year}:${vendedorCodes}:${clientCode}:${productSearch}`;
            const result = await cachedQuery(query, queryStr, cacheKey, TTL.SHORT);
            return result[0] || {};
