        `${document.label}: ${document.displaySerie}-${document.displayNumero}\n` +
        `Fecha: ${document.fecha}\n` +
        `Total: ${document.total.toFixed(2)} EUR\n\n` +
        `Cliente: ${clienteNombre || document.clienteNombre}\n\n` +
