         )
       ORDER BY I.TABLE_NAME, I.INDEX_NAME, K.ORDINAL_POSITION
    `);
    console.log('INDEXES', JSON.stringify(idx, (_, v) => (typeof v === 'bigint' ? String(v) : v)));
  } catch (error) {
