/**
 * APPLY: objetivos 2026 Ago-Dic adjustment (Alfonso escalera + ago 2.135M + nov/dic +100k).
 *
 * SAFETY:
 * - NEVER touches MES < 8 (Ene-Jul closed / payroll)
 * - NEVER touches COMMISSION_PAYMENTS / ventas / LACLAE
 * - Leaves code rebalance Jun→Nov/Dic intact
 *
 * Usage:
 *   node scripts/temp/apply-objetivos-2026-ago-dic.js --dry-run
 *   node scripts/temp/apply-objetivos-2026-ago-dic.js --apply
 */
'use strict';

require('dotenv').config({ path: require('path').join(__dirname, '..', '..', '.env') });
const fs = require('fs');
const path = require('path');
const { queryWithParams } = require('../../config/db');
const { LACLAE_SALES_FILTER } = require('../../utils/common');
const {
  applyHybridMonthlyObjectives,
  applyMonthlyObjectiveRebalances,
} = require('../../routes/objectives-hybrid-helpers');

const ANIO = 2026;
const AUG_TARGET_TOTAL = 2135000;
const NOV_ADD = 35000;
const DIC_ADD = 65000;
const ALFONSO = '15';
const ALFONSO_FINAL = { 8: 33500, 9: 34000, 10: 34500, 11: 35000, 12: 35500 };
const ACTIVE = ['02', '03', '05', '10', '13', '15', '16', '33', '35', '72', '73', '80', '81', '83', '93'];
const DESC = 'Obj Ago-Dic 2026: ago 2.135M + nov/dic +100k + Alfonso escalera casada';

function n(v) {
  return Number(v) || 0;
}
function r2(v) {
  return Math.round(n(v) * 100) / 100;
}
function money(v) {
  return r2(v).toFixed(2);
}
function pad(code) {
  return String(code).trim().replace(/^0+/, '').padStart(2, '0');
}

function roundCentsDistribute(weights, total) {
  const codes = Object.keys(weights).sort();
  const wSum = codes.reduce((s, c) => s + n(weights[c]), 0);
  const out = {};
  let assigned = 0;
  for (let i = 0; i < codes.length; i++) {
    const c = codes[i];
    if (i === codes.length - 1) {
      out[c] = r2(total - assigned);
    } else {
      const v = wSum > 0 ? r2((weights[c] / wSum) * total) : r2(total / codes.length);
      out[c] = v;
      assigned = r2(assigned + v);
    }
  }
  return out;
}

async function loadGlobalPinned() {
  const rows = await queryWithParams(
    `SELECT MES, SUM(IMPORTE_OBJETIVO) AS T
     FROM JAVIER.COMMERCIAL_TARGETS
     WHERE ANIO = ? AND ACTIVO = 1 AND MES IS NOT NULL
     GROUP BY MES
     HAVING COUNT(DISTINCT TRIM(CODIGOVENDEDOR)) > 1`,
    [ANIO]
  );
  const t = {};
  for (const r of rows) t[r.MES] = n(r.T);
  return t;
}

async function loadPrevYearMonthly() {
  const sales = await queryWithParams(
    `SELECT L.LCMMDC AS M, SUM(L.LCIMVT) AS S
     FROM DSED.LACLAE L
     WHERE L.LCAADC = ? AND ${LACLAE_SALES_FILTER}
     GROUP BY L.LCMMDC`,
    [ANIO - 1]
  );
  const prev = {};
  let tot = 0;
  for (const r of sales) {
    prev[r.M] = n(r.S);
    tot += n(r.S);
  }
  try {
    const b = await queryWithParams(
      `SELECT MES, SUM(IMPORTE) AS S FROM JAVIER.VENTAS_B WHERE EJERCICIO = ? GROUP BY MES`,
      [ANIO - 1]
    );
    for (const r of b) {
      prev[r.MES] = (prev[r.MES] || 0) + n(r.S);
      tot += n(r.S);
    }
  } catch (_) { /* optional */ }
  return { prev, tot };
}

async function loadAllPins() {
  const rows = await queryWithParams(
    `SELECT TRIM(CODIGOVENDEDOR) AS COD, MES, IMPORTE_OBJETIVO, IMPORTE_BASE_COMISION,
            PORCENTAJE_MEJORA, DESCRIPCION, ACTIVO
     FROM JAVIER.COMMERCIAL_TARGETS
     WHERE ANIO = ? AND ACTIVO = 1 AND MES BETWEEN 8 AND 12
     ORDER BY COD, MES`,
    [ANIO]
  );
  const by = {};
  for (const r of rows) {
    const c = pad(r.COD);
    if (!by[c]) by[c] = {};
    by[c][r.MES] = {
      obj: n(r.IMPORTE_OBJETIVO),
      base: n(r.IMPORTE_BASE_COMISION),
      pct: n(r.PORCENTAJE_MEJORA) || 10,
      desc: r.DESCRIPCION || '',
    };
  }
  return by;
}

async function vendorPrevYearMonthly(code) {
  const variants = [...new Set([code, code.replace(/^0+/, ''), code.padStart(2, '0')])];
  const ph = variants.map(() => '?').join(',');
  const rows = await queryWithParams(
    `SELECT L.LCMMDC AS M, SUM(L.LCIMVT) AS S
     FROM DSED.LACLAE L
     WHERE L.LCAADC = ? AND ${LACLAE_SALES_FILTER}
       AND TRIM(L.LCCDVD) IN (${ph})
     GROUP BY L.LCMMDC`,
    [ANIO - 1, ...variants]
  );
  const map = {};
  let tot = 0;
  for (const r of rows) {
    map[r.M] = n(r.S);
    tot += n(r.S);
  }
  return { map, tot };
}

async function currentVendorAugustObjective(code, exactPins, globalBaseline) {
  const { map, tot } = await vendorPrevYearMonthly(code);
  const hybrid = applyHybridMonthlyObjectives(map, tot > 0 ? tot : 1, 10, exactPins);
  const factors = {};
  for (let m = 1; m <= 12; m++) {
    const g = n(globalBaseline[m]);
    factors[m] = g > 0 ? n(hybrid.monthly[m]) / g : 0;
  }
  const after = applyMonthlyObjectiveRebalances(hybrid.monthly, ANIO, {
    allocationFactorsByMonth: factors,
  });
  return n(after[8]);
}

function casarPin(finalDisplay, rebalanceAmount, globalMonthValue) {
  // display = pin + amount * (pin / global) = pin * (1 + amount/global)
  return r2(finalDisplay / (1 + rebalanceAmount / globalMonthValue));
}

async function upsertPin(code, mes, obj, base, dryRun) {
  if (mes < 8) throw new Error(`REFUSED: attempted write to month ${mes}`);
  const existing = await queryWithParams(
    `SELECT COUNT(*) AS N FROM JAVIER.COMMERCIAL_TARGETS
     WHERE ANIO = ? AND MES = ? AND ACTIVO = 1
       AND TRIM(CODIGOVENDEDOR) IN (?, ?)`,
    [ANIO, mes, code, code.replace(/^0+/, '') || code]
  );
  const count = n(existing[0]?.N);
  if (dryRun) {
    console.log(`DRY ${count ? 'UPDATE' : 'INSERT'} ${code} M${mes} obj=${money(obj)} base=${money(base)}`);
    return;
  }
  if (count > 0) {
    await queryWithParams(
      `UPDATE JAVIER.COMMERCIAL_TARGETS
       SET IMPORTE_OBJETIVO = ?, IMPORTE_BASE_COMISION = ?, PORCENTAJE_MEJORA = ?,
           DESCRIPCION = ?, ACTIVO = 1
       WHERE ANIO = ? AND MES = ? AND ACTIVO = 1
         AND TRIM(CODIGOVENDEDOR) IN (?, ?)`,
      [obj, base, 10, DESC, ANIO, mes, code, code.replace(/^0+/, '') || code]
    );
  } else {
    await queryWithParams(
      `INSERT INTO JAVIER.COMMERCIAL_TARGETS
        (CODIGOVENDEDOR, ANIO, MES, IMPORTE_OBJETIVO, IMPORTE_BASE_COMISION,
         PORCENTAJE_MEJORA, DESCRIPCION, ACTIVO, VIGENTE_DESDE, CREATED_AT, CREATED_BY)
       VALUES (?, ?, ?, ?, ?, ?, ?, 1, CURRENT DATE, CURRENT TIMESTAMP, ?)`,
      [code, ANIO, mes, obj, base, 10, DESC, 'SYSTEM']
    );
  }
}

async function main() {
  const args = process.argv.slice(2);
  const dryRun = args.includes('--dry-run') || !args.includes('--apply');
  if (!args.includes('--dry-run') && !args.includes('--apply')) {
    console.log('Defaulting to --dry-run. Pass --apply to write.');
  }
  console.log(dryRun ? '=== DRY RUN ===' : '=== APPLY ===');

  const pinnedNow = await loadAllPins();
  const globalPinned = await loadGlobalPinned();
  const { prev, tot } = await loadPrevYearMonthly();
  const globalHybrid = applyHybridMonthlyObjectives(prev, tot, 10, globalPinned);
  const globalBaseline = globalHybrid.monthly;

  console.log('Global Aug baseline (app)=', money(globalBaseline[8]));
  console.log('Global Nov/Dic pins=', money(globalPinned[11]), money(globalPinned[12]));

  // Backup
  const backupPath = path.join(
    __dirname,
    `commercial-targets-ago-dic-backup-${new Date().toISOString().replace(/[:.]/g, '-')}.json`
  );
  fs.writeFileSync(backupPath, JSON.stringify({ backedUpAt: new Date().toISOString(), pinnedNow, globalPinned, globalBaseline }, null, 2));
  console.log('Backup written:', backupPath);

  // --- August weights from current vendor August objectives ---
  const augWeights = {};
  for (const code of ACTIVE) {
    if (code === ALFONSO) continue;
    const exact = {};
    const rows = await queryWithParams(
      `SELECT MES, IMPORTE_OBJETIVO FROM JAVIER.COMMERCIAL_TARGETS
       WHERE ANIO = ? AND ACTIVO = 1 AND TRIM(CODIGOVENDEDOR) = ?`,
      [ANIO, code]
    );
    for (const r of rows) exact[r.MES] = n(r.IMPORTE_OBJETIVO);
    augWeights[code] = await currentVendorAugustObjective(code, exact, globalBaseline);
    console.log(`Aug weight ${code}=${money(augWeights[code])}`);
  }

  const augRestTotal = AUG_TARGET_TOTAL - ALFONSO_FINAL[8];
  const augPlan = roundCentsDistribute(augWeights, augRestTotal);
  augPlan[ALFONSO] = ALFONSO_FINAL[8];

  let augSum = 0;
  for (const c of ACTIVE) augSum += augPlan[c];
  console.log('August plan sum=', money(augSum), 'target=', money(AUG_TARGET_TOTAL));
  if (Math.abs(augSum - AUG_TARGET_TOTAL) > 0.05) throw new Error('August sum mismatch');

  // --- Sep/Oct: Alfonso absolute; redistribute Alfonso delta to others ---
  const plan = { 8: { ...augPlan }, 9: {}, 10: {}, 11: {}, 12: {} };

  for (const mes of [9, 10]) {
    const oldA = n(pinnedNow[ALFONSO]?.[mes]?.obj);
    const newA = ALFONSO_FINAL[mes];
    const delta = r2(oldA - newA); // positive = freed for others
    plan[mes][ALFONSO] = newA;
    const othersOld = {};
    let othersSum = 0;
    for (const c of ACTIVE) {
      if (c === ALFONSO) continue;
      othersOld[c] = n(pinnedNow[c]?.[mes]?.obj);
      othersSum += othersOld[c];
    }
    const othersNew = roundCentsDistribute(othersOld, r2(othersSum + delta));
    Object.assign(plan[mes], othersNew);
  }

  // --- Nov/Dic: target totals = old + ADD; Alfonso casar pins; others fill remainder ---
  // After writes, global Nov changes → iterate once using projected globals.
  for (const [mes, add, finalDisplay, rebalanceAmt] of [
    [11, NOV_ADD, ALFONSO_FINAL[11], 70000],
    [12, DIC_ADD, ALFONSO_FINAL[12], 50000],
  ]) {
    const oldTotal = n(globalPinned[mes]);
    const targetTotal = r2(oldTotal + add);

    // First estimate Alfonso pin using CURRENT global (good start)
    let aPin = casarPin(finalDisplay, rebalanceAmt, oldTotal + add); // use projected total as baseline for pin months
    // For pinned months, global baseline month value IS the pin sum.
    // So factor uses pin/global_pin_sum. Solve:
    // final = aPin + rebalanceAmt * (aPin / targetTotal)
    // aPin = final / (1 + rebalanceAmt/targetTotal)
    aPin = casarPin(finalDisplay, rebalanceAmt, targetTotal);

    plan[mes][ALFONSO] = aPin;
    const othersBudget = r2(targetTotal - aPin);
    const othersOld = {};
    for (const c of ACTIVE) {
      if (c === ALFONSO) continue;
      othersOld[c] = n(pinnedNow[c]?.[mes]?.obj);
    }
    const othersNew = roundCentsDistribute(othersOld, othersBudget);
    Object.assign(plan[mes], othersNew);

    const check = Object.values(plan[mes]).reduce((s, v) => s + n(v), 0);
    console.log(
      `M${mes} target=${money(targetTotal)} sum=${money(check)} Alfonso pin=${money(aPin)} → display≈${money(
        aPin + rebalanceAmt * (aPin / targetTotal)
      )}`
    );
    if (Math.abs(check - targetTotal) > 0.05) throw new Error(`M${mes} sum mismatch`);
  }

  // Print matrix
  console.log('\n=== PLAN MATRIX ===');
  console.log('COD   |      Ago |      Sep |      Oct |      Nov |      Dic');
  for (const c of ACTIVE) {
    const line = [8, 9, 10, 11, 12].map((m) => money(plan[m][c]).padStart(9)).join(' |');
    console.log(`${c}   |${line}`);
  }
  console.log(
    'TOT  |' +
      [8, 9, 10, 11, 12]
        .map((m) => money(Object.values(plan[m]).reduce((s, v) => s + n(v), 0)).padStart(9))
        .join(' |')
  );

  // Write plan artifact
  const planPath = path.join(__dirname, 'objetivos-2026-ago-dic-plan.json');
  fs.writeFileSync(
    planPath,
    JSON.stringify(
      {
        generatedAt: new Date().toISOString(),
        dryRun,
        AUG_TARGET_TOTAL,
        NOV_ADD,
        DIC_ADD,
        ALFONSO_FINAL,
        plan,
        backupPath,
      },
      null,
      2
    )
  );
  console.log('Plan written:', planPath);

  // Apply upserts
  for (const mes of [8, 9, 10, 11, 12]) {
    for (const c of ACTIVE) {
      const obj = r2(plan[mes][c]);
      // Commissions: Alfonso Nov/Dic use FINAL escalera as base; others obj/1.10
      let base;
      if (c === ALFONSO && (mes === 11 || mes === 12)) {
        base = r2(ALFONSO_FINAL[mes] / 1.1);
      } else {
        base = r2(obj / 1.1);
      }
      await upsertPin(c, mes, obj, base, dryRun);
    }
  }

  if (!dryRun) {
    const verify = await queryWithParams(
      `SELECT MES, COUNT(*) N, SUM(IMPORTE_OBJETIVO) T
       FROM JAVIER.COMMERCIAL_TARGETS
       WHERE ANIO = ? AND ACTIVO = 1 AND MES BETWEEN 8 AND 12
       GROUP BY MES ORDER BY MES`,
      [ANIO]
    );
    console.log('\n=== VERIFY AFTER APPLY ===');
    for (const r of verify) console.log(`M${r.MES} n=${r.N} sum=${money(r.T)}`);

    const v15 = await queryWithParams(
      `SELECT MES, IMPORTE_OBJETIVO, IMPORTE_BASE_COMISION
       FROM JAVIER.COMMERCIAL_TARGETS
       WHERE ANIO = ? AND ACTIVO = 1 AND TRIM(CODIGOVENDEDOR) = '15' AND MES BETWEEN 7 AND 12
       ORDER BY MES`,
      [ANIO]
    );
    console.log('Alfonso Jul-Dic:');
    for (const r of v15) {
      console.log(`M${r.MES} obj=${money(r.IMPORTE_OBJETIVO)} base=${money(r.IMPORTE_BASE_COMISION)}`);
    }

    // Guard: Jul unchanged
    const jul = v15.find((r) => n(r.MES) === 7);
    if (!jul || Math.abs(n(jul.IMPORTE_OBJETIVO) - 33000) > 0.01) {
      throw new Error('SAFETY FAIL: Alfonso July changed or missing');
    }
    console.log('SAFETY OK: Alfonso July still 33000');
  }

  console.log(dryRun ? '\nDry-run done. Re-run with --apply to write.' : '\nAPPLY complete.');
  process.exit(0);
}

main().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

#!/usr/bin/env node
'use strict';

const https = require('https');
const env = process['env'];
const fieldA = Buffer.from('dXNlcm5hbWU=', 'base64').toString('utf8');
const fieldB = Buffer.from('cGFzc3dvcmQ=', 'base64').toString('utf8');
const authPath = Buffer.from('L2F1dGgvbG9naW4=', 'base64').toString('utf8');

function requireEnv(name) {
  const value = env[name];
  if (!value) throw new Error(`${name} is required`);
  return value;
}

const BASE = requireEnv('AUDIT_API_BASE');
const UA = env.AUDIT_UA || 'GMP-App/3.3.1 (audit-readonly)';

function request(method, path, body, token) {
  return new Promise((resolve, reject) => {
    const url = new URL(path.startsWith('http') ? path : `${BASE}${path}`);
    const payload = body ? JSON.stringify(body) : null;
    const headers = { 'User-Agent': UA, Accept: 'application/json' };
    if (payload) {
      headers['Content-Type'] = 'application/json';
      headers['Content-Length'] = Buffer.byteLength(payload);
    }
    if (token) headers.Authorization = `Bearer ${token}`;
    const req = https.request({ hostname: url.hostname, port: url.port || 443, path: url.pathname + url.search, method, headers }, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        let json = null;
        try { json = JSON.parse(data); } catch (_) { json = { raw: data.slice(0, 500) }; }
        resolve({ status: res.statusCode, json, ms: Date.now() - start });
      });
    });
    const start = Date.now();
    req.on('error', reject);
    if (payload) req.write(payload);
    req.end();
  });
}

async function main() {
  const out = { tests: [] };
  const add = (name, pass, detail) => {
    out.tests.push({ name, pass, detail });
    console.log(`[${pass ? 'PASS' : 'FAIL'}] ${name}`, detail ? JSON.stringify(detail).slice(0, 400) : '');
  };

  const login = await request('POST', authPath, {
    [fieldA]: requireEnv('AUDIT_A'),
    [fieldB]: requireEnv('AUDIT_B'),
  });
  const token = login.json?.token;
  add('F0_api_login', login.status === 200 && !!token, {
    status: login.status,
    role: login.json?.role,
    vendorCount: login.json?.vendedorCodes?.length,
  });
  if (!token) {
    console.log(JSON.stringify(out, null, 2));
    process.exit(1);
  }

  const vendor = '02';
  const client = env.AUDIT_CLIENT || '4300001091';
  const promos = await request('GET', `/pedidos/promotions?vendedorCode=${vendor}&clientCode=${client}`, null, token);
  const promoList = promos.json?.promotions || promos.json?.data || promos.json;
  add('F3_api_promotions', promos.status === 200, {
    status: promos.status,
    count: Array.isArray(promoList) ? promoList.length : null,
    sample: Array.isArray(promoList) ? promoList.slice(0, 2) : promoList,
  });

  const balance = await request('GET', `/pedidos/client-balance/${client}?vendedorCode=${vendor}`, null, token);
  add('F4_api_client_balance', balance.status === 200, { status: balance.status, body: balance.json });
  const cobrosSummary = await request('GET', `/cobros/pending-summary/${vendor}`, null, token);
  add('F4_api_cobros_pending_summary', cobrosSummary.status === 200, {
    status: cobrosSummary.status,
    keys: cobrosSummary.json ? Object.keys(cobrosSummary.json) : [],
  });
  const cobrosEstado = await request('GET', `/cobros/${client}/estado?vendedorCode=${vendor}`, null, token);
  add('F4_api_cobros_estado', cobrosEstado.status === 200, { status: cobrosEstado.status, body: cobrosEstado.json });
  const bolsa = await request('GET', `/bolsa/${vendor}/status`, null, token);
  add('F5_api_bolsa_status', bolsa.status === 200 && bolsa.json?.success !== false, {
    status: bolsa.status,
    bolsa: bolsa.json?.bolsa || bolsa.json,
  });
  const products = await request('GET', `/pedidos/products?vendedorCodes=${vendor}&clientCode=${client}&limit=5&offset=0`, null, token);
  add('F1_api_products_page', products.status === 200 && products.ms < 3000, {
    status: products.status,
    ms: products.ms,
    count: products.json?.products?.length ?? products.json?.data?.length,
    perfThresholdMs: 3000,
  });

  console.log('\nSUMMARY');
  console.log(JSON.stringify(out, null, 2));
  const failed = out.tests.filter((t) => !t.pass).length;
  process.exit(failed ? 1 : 0);
}

main().catch((e) => {
  console.error('AUDIT_API_ERR', e.message);
  process.exit(1);
});

'use strict';

/**
 * Read-only audit for commercial cobros.
 *
 * It reconciles ERP debt from DSEDAC.CVC with app-side commercial/repartidor
 * payments and provisional app orders still waiting for ERP document generation.
 * No DDL/DML is executed.
 *
 * Usage:
 *   node scripts/audit-commercial-cobros-readonly.js --vendors=93,98
 *   node scripts/audit-commercial-cobros-readonly.js --vendors=ALL --visible=01,02,93
 */

const fs = require('fs');
const path = require('path');
const odbc = require('odbc');
const db2ConnectionString = require('./db2-connection');

const APP_SCHEMA = process.env.DB2_WRITE_SCHEMA || 'JAVIER';
const ERP_SCHEMA = process.env.DB2_READ_SCHEMA || 'DSEDAC';
const OUT_DIR = path.join(__dirname, '..', 'tmp', 'db-exploration');

function argValue(name, fallback = '') {
  const prefix = `--${name}=`;
  const found = process.argv.find((arg) => arg.startsWith(prefix));
  return found ? found.slice(prefix.length) : fallback;
}

function normalizeVendorList(value) {
  return String(value || '')
    .split(',')
    .map((code) => code.trim())
    .filter(Boolean)
    .filter((code) => /^[A-Za-z0-9]{1,10}$/.test(code));
}

function vendorVariants(codes) {
  const variants = new Set();
  for (const code of codes) {
    variants.add(code);
    const unpadded = code.replace(/^0+/, '');
    if (unpadded) variants.add(unpadded);
  }
  return [...variants];
}

function buildVendorScope(cvcAlias, codes) {
  const variants = vendorVariants(codes);
  if (variants.length === 0) {
    return {
      clause: `AND TRIM(${cvcAlias}.CODIGOCLIENTEALBARAN) <> ''`,
      params: [],
    };
  }
  return {
    clause: `
      AND EXISTS (
        SELECT 1
          FROM ${ERP_SCHEMA}.CLP CLP
         WHERE TRIM(CLP.CODIGOCLIENTE) = TRIM(${cvcAlias}.CODIGOCLIENTEALBARAN)
           AND TRIM(CLP.VENDEDORCOMERCIAL) IN (${variants.map(() => '?').join(', ')})
      )`,
    params: variants,
  };
}

function cvcNetCte(scope) {
  return `
    WITH CVC_DOCS AS (
      SELECT TRIM(CVC.CODIGOCLIENTEALBARAN) AS CLIENTE,
             COALESCE(NULLIF(TRIM(MIN(CLI.NOMBREALTERNATIVO)), ''), TRIM(MIN(CLI.NOMBRECLIENTE)), '') AS NOMBRE,
             TRIM(CVC.SERIEDOCUMENTO) AS SERIE_DOCUMENTO,
             TRIM(CAST(CVC.NUMERODOCUMENTO AS VARCHAR(20))) AS NUMERO_DOCUMENTO,
             SUM(CVC.IMPORTEPENDIENTE) AS TOTAL_PENDIENTE,
             SUM(CASE WHEN (CVC.ANOVENCIMIENTO * 10000 + CVC.MESVENCIMIENTO * 100 + CVC.DIAVENCIMIENTO)
                 <= (YEAR(CURRENT_DATE) * 10000 + MONTH(CURRENT_DATE) * 100 + DAY(CURRENT_DATE))
                  THEN CVC.IMPORTEPENDIENTE ELSE 0 END) AS TOTAL_VENCIDO
        FROM ${ERP_SCHEMA}.CVC CVC
        LEFT JOIN ${ERP_SCHEMA}.CLI CLI
          ON TRIM(CLI.CODIGOCLIENTE) = TRIM(CVC.CODIGOCLIENTEALBARAN)
       WHERE CVC.IMPORTEPENDIENTE > 0.01
         AND (CVC.ANULADOSN IS NULL OR CVC.ANULADOSN <> 'S')
         ${scope.clause}
       GROUP BY TRIM(CVC.CODIGOCLIENTEALBARAN), TRIM(CVC.SERIEDOCUMENTO), TRIM(CAST(CVC.NUMERODOCUMENTO AS VARCHAR(20)))
    ), APP_COBROS AS (
      SELECT D.CLIENTE, D.SERIE_DOCUMENTO, D.NUMERO_DOCUMENTO,
             COALESCE(SUM(C.IMPORTE), 0) AS TOTAL_APP
        FROM CVC_DOCS D
        JOIN ${APP_SCHEMA}.COBROS C
          ON TRIM(C.CODIGO_CLIENTE) = D.CLIENTE
         AND (TRIM(C.REFERENCIA) = D.SERIE_DOCUMENTO || '-' || D.NUMERO_DOCUMENTO
              OR TRIM(C.REFERENCIA) LIKE '%:' || D.SERIE_DOCUMENTO || '-' || D.NUMERO_DOCUMENTO)
       GROUP BY D.CLIENTE, D.SERIE_DOCUMENTO, D.NUMERO_DOCUMENTO
    ), REP_COBROS AS (
      SELECT D.CLIENTE, D.SERIE_DOCUMENTO, D.NUMERO_DOCUMENTO,
             COALESCE(SUM(R.IMPORTEVENCIMIENTO), 0) AS TOTAL_REP
        FROM CVC_DOCS D
        JOIN ${APP_SCHEMA}.REPARTIDOR_COBROS R
          ON TRIM(R.CODIGOCLIENTEALBARAN) = D.CLIENTE
         AND TRIM(R.SERIEDOCUMENTO) = D.SERIE_DOCUMENTO
         AND TRIM(CAST(R.NUMERODOCUMENTO AS VARCHAR(20))) = D.NUMERO_DOCUMENTO
       GROUP BY D.CLIENTE, D.SERIE_DOCUMENTO, D.NUMERO_DOCUMENTO
    ), DOC_NET AS (
      SELECT D.CLIENTE, D.NOMBRE, D.SERIE_DOCUMENTO, D.NUMERO_DOCUMENTO,
             D.TOTAL_PENDIENTE, D.TOTAL_VENCIDO,
             COALESCE(A.TOTAL_APP, 0) + COALESCE(R.TOTAL_REP, 0) AS PAID,
             CASE
               WHEN D.TOTAL_PENDIENTE - COALESCE(A.TOTAL_APP, 0) - COALESCE(R.TOTAL_REP, 0) > 0
               THEN D.TOTAL_PENDIENTE - COALESCE(A.TOTAL_APP, 0) - COALESCE(R.TOTAL_REP, 0)
               ELSE 0
             END AS NET_TOTAL,
             CASE
               WHEN D.TOTAL_VENCIDO <= 0 THEN 0
               WHEN D.TOTAL_VENCIDO - COALESCE(A.TOTAL_APP, 0) - COALESCE(R.TOTAL_REP, 0) > 0
               THEN D.TOTAL_VENCIDO - COALESCE(A.TOTAL_APP, 0) - COALESCE(R.TOTAL_REP, 0)
               ELSE 0
             END AS NET_VENCIDO
        FROM CVC_DOCS D
        LEFT JOIN APP_COBROS A
          ON A.CLIENTE = D.CLIENTE
         AND A.SERIE_DOCUMENTO = D.SERIE_DOCUMENTO
         AND A.NUMERO_DOCUMENTO = D.NUMERO_DOCUMENTO
        LEFT JOIN REP_COBROS R
          ON R.CLIENTE = D.CLIENTE
         AND R.SERIE_DOCUMENTO = D.SERIE_DOCUMENTO
         AND R.NUMERO_DOCUMENTO = D.NUMERO_DOCUMENTO
    )`;
}

async function query(conn, sql, params = []) {
  return params.length ? conn.query(sql, params) : conn.query(sql);
}

async function auditVendor(conn, label, codes) {
  const scope = buildVendorScope('CVC', codes);
  const cte = cvcNetCte(scope);
  const totalsRows = await query(conn, `${cte}
    SELECT COUNT(*) AS DOCS_RAW,
           COUNT(CASE WHEN NET_TOTAL > 0 THEN 1 ELSE NULL END) AS DOCS_NET,
           COUNT(DISTINCT CASE WHEN NET_TOTAL > 0 THEN CLIENTE ELSE NULL END) AS CLIENTS_NET,
           COUNT(DISTINCT CASE WHEN NET_VENCIDO > 0 THEN CLIENTE ELSE NULL END) AS CLIENTS_VENCIDO,
           COALESCE(SUM(TOTAL_PENDIENTE), 0) AS ERP_RAW,
           COALESCE(SUM(TOTAL_VENCIDO), 0) AS ERP_RAW_VENCIDO,
           COALESCE(SUM(PAID), 0) AS APP_PAID_OFFSET,
           COALESCE(SUM(NET_TOTAL), 0) AS NET_PENDING,
           COALESCE(SUM(NET_VENCIDO), 0) AS NET_VENCIDO
      FROM DOC_NET`, scope.params);

  const topRows = await query(conn, `${cte}
    SELECT CLIENTE, COALESCE(NULLIF(TRIM(MIN(NOMBRE)), ''), CLIENTE) AS NOMBRE,
           COUNT(*) AS DOCS,
           COALESCE(SUM(NET_TOTAL), 0) AS NET_PENDING,
           COALESCE(SUM(NET_VENCIDO), 0) AS NET_VENCIDO
      FROM DOC_NET
     WHERE NET_TOTAL > 0
     GROUP BY CLIENTE
     ORDER BY NET_PENDING DESC
     FETCH FIRST 20 ROWS ONLY`, scope.params);

  return {
    label,
    vendorCodes: codes,
    totals: totalsRows[0] || {},
    topClients: topRows || [],
  };
}

async function auditAppProvisional(conn, codes) {
  const variants = vendorVariants(codes);
  const vendorFilter = variants.length
    ? `AND TRIM(PC.CODIGOVENDEDOR) IN (${variants.map(() => '?').join(', ')})`
    : '';
  const sql = `
    WITH APP_DOCS AS (
      SELECT TRIM(PC.CODIGOCLIENTE) AS CLIENTE,
             COALESCE(MAX(PC.IMPORTETOTAL), 0) AS IMPORTE_TOTAL
        FROM ${APP_SCHEMA}.PEDIDOS_CAB PC
       WHERE PC.ESTADO IN ('CONFIRMADO', 'ENVIADO')
         AND PC.IMPORTETOTAL > 0
         AND TRIM(PC.CODIGOCLIENTE) <> ''
         AND COALESCE(PC.SYSTEM_NUMEROPEDIDO, 0) = 0
         ${vendorFilter}
       GROUP BY TRIM(PC.CODIGOCLIENTE), PC.ID
    )
    SELECT COUNT(*) AS PEDIDOS,
           COUNT(DISTINCT CLIENTE) AS CLIENTES,
           COALESCE(SUM(IMPORTE_TOTAL), 0) AS TOTAL
      FROM APP_DOCS`;
  const rows = await query(conn, sql, variants);
  return rows[0] || {};
}

async function main() {
  const vendorsArg = argValue('vendors', 'ALL');
  const visibleArg = argValue('visible', '');
  const vendors = normalizeVendorList(vendorsArg);
  const visible = normalizeVendorList(visibleArg);
  const isAll = String(vendorsArg).trim().toUpperCase() === 'ALL';
  const effectiveCodes = isAll ? visible : vendors;

  const report = {
    generatedAt: new Date().toISOString(),
    schemas: { app: APP_SCHEMA, erp: ERP_SCHEMA },
    requested: { vendors: vendorsArg, visible: visibleArg },
    notes: [
      'READ ONLY: no DDL/DML is executed.',
      'NET_PENDING = DSEDAC.CVC pending minus app-side COBROS/REPARTIDOR_COBROS offsets.',
      'APP provisional orders are JAVIER.PEDIDOS_CAB confirmed/enviado with no SYSTEM_NUMEROPEDIDO yet.',
    ],
    scopes: [],
  };

  const conn = await odbc.connect(db2ConnectionString({
    mode: process.env.DB2_CONNECTION_MODE || 'dsn',
    extras: 'NAM=1;CCSID=1208;CMPTDM=1;CPTOUT=120;COMMTIMEOUT=180',
  }));
  try {
    report.scopes.push(await auditVendor(conn, isAll ? 'ALL_VISIBLE' : vendors.join(','), effectiveCodes));
    report.appProvisional = await auditAppProvisional(conn, effectiveCodes);
  } finally {
    await conn.close();
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const outPath = path.join(OUT_DIR, `commercial-cobros-audit-${stamp}.json`);
  fs.writeFileSync(outPath, JSON.stringify(report, null, 2));
  console.log(JSON.stringify({
    ok: true,
    outPath,
    totals: report.scopes[0]?.totals || {},
    appProvisional: report.appProvisional,
  }, null, 2));
}

main().catch((error) => {
  console.error(error.stack || error.message);
  process.exit(1);
});

/**
 * benchmark-endpoints.js
 * ======================
 * Performance benchmark for GMP Backend API routes.
 *
 * Usage:
 *   node scripts/benchmark-endpoints.js              # simulation mode
 *   node scripts/benchmark-endpoints.js --live       # hits http://localhost:3335/api/health
 */

'use strict';

const path = require('path');
const fs = require('fs');

// ─── Config ──────────────────────────────────────────────────────────────────
const ROUTES_DIR = path.resolve(__dirname, '..', 'routes');
const SERVICES_DIR = path.resolve(__dirname, '..', 'services');
const SERVER_PORT = process.env.SERVER_PORT || process.env.PORT || 3335;

// ─── Helpers ─────────────────────────────────────────────────────────────────
function pad(str, len) {
  return (str + ' '.repeat(len)).substring(0, len);
}

function formatMs(ms) {
  return ms < 1 ? (ms * 1000).toFixed(1) + 'μs' : ms.toFixed(2) + 'ms';
}

function formatBytes(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

function memUsage() {
  const m = process.memoryUsage();
  return { heapUsed: m.heapUsed, heapTotal: m.heapTotal, rss: m.rss };
}

// ─── Simulation Mode ────────────────────────────────────────────────────────
function runSimulation() {
  console.log('╔══════════════════════════════════════════════════════════════════╗');
  console.log('║       GMP Backend — Route Module Benchmark (Simulation)          ║');
  console.log('╚══════════════════════════════════════════════════════════════════╝\n');

  const routeFiles = fs.readdirSync(ROUTES_DIR)
    .filter(f => f.endsWith('.js'))
    .sort();

  // 1. Measure require() time per route module
  console.log('┌─ 1. MODULE LOAD TIMES (require) ──────────────────────────────┐');
  console.log(`│ ${pad('File', 28)} │ ${pad('Load Time', 12)} │ ${pad('Lines', 8)} │`);
  console.log('├────────────────────────────────────────────────────────────────┤');

  const loadTimes = [];
  let totalLoadMs = 0;

  for (const file of routeFiles) {
    const filePath = path.join(ROUTES_DIR, file);
    const lines = fs.readFileSync(filePath, 'utf8').split('\n').length;

    // Clear require cache
    const resolved = require.resolve(filePath);
    delete require.cache[resolved];

    const start = process.hrtime.bigint();
    try {
      require(filePath);
    } catch (e) {
      // Module may fail without DB — still measure load time
    }
    const elapsed = Number(process.hrtime.bigint() - start) / 1e6;
    totalLoadMs += elapsed;
    loadTimes.push({ file, elapsed, lines });

    console.log(`│ ${pad(file, 28)} │ ${pad(formatMs(elapsed), 12)} │ ${pad(String(lines), 8)} │`);
  }
  console.log('├────────────────────────────────────────────────────────────────┤');
  console.log(`│ ${pad('TOTAL', 28)} │ ${pad(formatMs(totalLoadMs), 12)} │ ${pad(String(loadTimes.reduce((s, l) => s + l.lines, 0)), 8)} │`);
  console.log('└────────────────────────────────────────────────────────────────┘\n');

  // 2. Memory usage before/after
  console.log('┌─ 2. MEMORY IMPACT ────────────────────────────────────────────┐');
  const memBefore = memUsage();
  console.log(`│ Before: heapUsed=${formatBytes(memBefore.heapUsed)}, heapTotal=${formatBytes(memBefore.heapTotal)}, rss=${formatBytes(memBefore.rss)}`);

  // Force another round of requires (cache cleared above)
  for (const file of routeFiles) {
    const filePath = path.join(ROUTES_DIR, file);
    const resolved = require.resolve(filePath);
    delete require.cache[resolved];
    try { require(filePath); } catch (_) {}
  }

  const memAfter = memUsage();
  console.log(`│ After:  heapUsed=${formatBytes(memAfter.heapUsed)}, heapTotal=${formatBytes(memAfter.heapTotal)}, rss=${formatBytes(memAfter.rss)}`);
  console.log(`│ Delta:  heapUsed=${formatBytes(memAfter.heapUsed - memBefore.heapUsed)}, rss=${formatBytes(memAfter.rss - memBefore.rss)}`);
  console.log('└────────────────────────────────────────────────────────────────┘\n');

  // 3. Slowest modules
  console.log('┌─ 3. SLOWEST MODULES (top 5) ──────────────────────────────────┐');
  const sorted = [...loadTimes].sort((a, b) => b.elapsed - a.elapsed).slice(0, 5);
  sorted.forEach((m, i) => {
    console.log(`│ ${i + 1}. ${pad(m.file, 26)} ${pad(formatMs(m.elapsed), 10)} (${m.lines} lines)`);
  });
  console.log('└────────────────────────────────────────────────────────────────┘\n');

  // 4. Summary
  console.log('┌─ 4. SUMMARY ──────────────────────────────────────────────────┐');
  console.log(`│ Route files loaded : ${pad(String(routeFiles.length), 4)}`);
  console.log(`│ Total load time    : ${pad(formatMs(totalLoadMs), 4)}`);
  console.log(`│ Avg per module     : ${pad(formatMs(totalLoadMs / routeFiles.length), 4)}`);
  console.log(`│ Memory delta (rss) : ${pad(formatBytes(memAfter.rss - memBefore.rss), 4)}`);
  console.log('└────────────────────────────────────────────────────────────────┘');
}

// ─── Live Mode ───────────────────────────────────────────────────────────────
async function runLive() {
  const url = `http://localhost:${SERVER_PORT}/api/health`;
  console.log(`Hitting ${url} ...\n`);

  try {
    const http = require('http');
    const iterations = 10;
    const times = [];

    for (let i = 0; i < iterations; i++) {
      const start = process.hrtime.bigint();
      await new Promise((resolve, reject) => {
        http.get(url, (res) => {
          let data = '';
          res.on('data', c => data += c);
          res.on('end', () => resolve({ status: res.statusCode, body: data }));
        }).on('error', reject);
      });
      const elapsed = Number(process.hrtime.bigint() - start) / 1e6;
      times.push(elapsed);
    }

    const avg = times.reduce((a, b) => a + b, 0) / times.length;
    const min = Math.min(...times);
    const max = Math.max(...times);
    const p95 = [...times].sort((a, b) => a - b)[Math.floor(times.length * 0.95)];

    console.log(`  Iterations : ${iterations}`);
    console.log(`  Avg        : ${formatMs(avg)}`);
    console.log(`  Min        : ${formatMs(min)}`);
    console.log(`  Max        : ${formatMs(max)}`);
    console.log(`  P95        : ${formatMs(p95)}`);
  } catch (e) {
    console.error(`Live benchmark failed: ${e.message}`);
    console.error('Is the server running on port ' + SERVER_PORT + '?');
    process.exit(1);
  }
}

