  const day = String(Number(row.DIADOCUMENTO || 0)).padStart(2, '0');
  const month = String(Number(row.MESDOCUMENTO || 0)).padStart(2, '0');
  const year = String(Number(row.ANODOCUMENTO || row.EJERCICIOPEDIDO || 0));
  return `${day}-${month}-${year}`;
