        try { json = JSON.parse(raw); } catch (_) { /* receipt can be binary in future */ }
        resolve({ status: res.statusCode, json, raw });
      });
    });
    req.setTimeout(TIMEOUT_MS, () => req.destroy(new Error(`timeout ${method} ${path}`)));
    req.on('error', reject);
    if (payload) req.write(payload);
