#!/usr/bin/env node
/**
 * discover-dsedac-columns.js
 * Queries QSYS2.SYSCOLUMNS for all DSEDAC source tables to get exact column definitions.
 */

const odbc = require('odbc');
const fs = require('fs');
const path = require('path');

require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });


function requireEnv(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(name + " environment variable is required");
  }
  return value;
}

const DB_DSN = process.env.ODBC_DSN || 'GMP';
const DB_UID = requireEnv('ODBC_UID');
const DB_PWD = requireEnv('ODBC_PWD');

const CONNECTION_STRING = [
  `DSN=${DB_DSN}`,
  `UID=${DB_UID}`,
  `PWD=${DB_PWD}`,
  'NAM=1',
  'CCSID=1208',
  'CMPTDM=1',
].join(';');

// DSEDAC source tables mapped to JAVIER target tables
const TABLE_MAP = [
  { dsedac: 'CVC', javier: 'REPARTIDOR_COBROS', desc: 'Cobros' },
  { dsedac: 'LQD', javier: 'REPARTIDOR_LIQUIDACION_OPS', desc: 'Liquidaciones' },
  { dsedac: 'OPP', javier: 'REPARTIDOR_ENTREGAS', desc: 'Entregas (cabecera)' },
  { dsedac: 'LAC', javier: 'REPARTIDOR_ENTREGA_LINEAS', desc: 'Entrega líneas' },
  { dsedac: 'CACFIRMAS', javier: 'REPARTIDOR_FIRMAS', desc: 'Firmas' },
  { dsedac: 'CMV', javier: 'REPARTIDOR_OBJETIVOS', desc: 'Objetivos' },
  { dsedac: 'CPC', javier: 'DELIVERY_STATUS', desc: 'Delivery status' },
  { dsedac: 'CLI', javier: 'CLIENT_SIGNERS', desc: 'Client signers' },
];

async function main() {
  let pool = null;
  let conn = null;

  try {
    pool = await odbc.pool(CONNECTION_STRING);
    conn = await pool.connect();

    const results = {};

    for (const tbl of TABLE_MAP) {
      console.log(`\n=== DSEDAC.${tbl.dsedac} → JAVIER.${tbl.javier} (${tbl.desc}) ===`);

      const query = `
        SELECT 
          COLUMN_NAME,
          SYSTEM_COLUMN_NAME,
          DATA_TYPE,
          LENGTH,
          NUMERIC_SCALE,
          IS_NULLABLE,
          HAS_DEFAULT,
          COLUMN_DEFAULT,
          COLUMN_TEXT,
          ORDINAL_POSITION
        FROM QSYS2.SYSCOLUMNS
        WHERE TABLE_SCHEMA = 'DSEDAC'
          AND TABLE_NAME = '${tbl.dsedac}'
        ORDER BY ORDINAL_POSITION
      `;

      try {
        const rows = await conn.query(query);
        results[tbl.dsedac] = rows;
        console.log(`  Found ${rows.length} columns:`);
        for (const row of rows) {
          const nullable = row.IS_NULLABLE === 'Y' ? 'NULL' : 'NOT NULL';
          const dtype = row.DATA_TYPE;
          const len = row.LENGTH || '';
          const scale = row.NUMERIC_SCALE !== null && row.NUMERIC_SCALE !== undefined ? `,${row.NUMERIC_SCALE}` : '';
          const def = row.HAS_DEFAULT === 'Y' ? ` DEFAULT ${row.COLUMN_DEFAULT || ''}` : '';
          const text = row.COLUMN_TEXT ? ` -- ${row.COLUMN_TEXT}` : '';
          console.log(`  ${row.ORDINAL_POSITION}. ${row.COLUMN_NAME || row.SYSTEM_COLUMN_NAME} ${dtype}${len}${scale} ${nullable}${def}${text}`);
        }
      } catch (err) {
        console.error(`  ERROR querying DSEDAC.${tbl.dsedac}: ${err.message}`);
        results[tbl.dsedac] = [];
      }
    }

    // Save results to JSON for reference
    const outputPath = path.resolve(__dirname, 'results', 'dsedac-column-discovery.json');
    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
    fs.writeFileSync(outputPath, JSON.stringify(results, null, 2));
    console.log(`\nResults saved to ${outputPath}`);

  } catch (err) {
    console.error(`FATAL: ${err.message}`);
    process.exitCode = 1;
  } finally {
    if (conn) { try { await conn.close(); } catch (_) {} }
    if (pool) { try { await pool.close(); } catch (_) {} }
  }
}

main();

#!/usr/bin/env node
/**
 * discover-vista-unificada.js
 * Descubre TODAS las columnas de las 5 tablas exactas del usuario:
 *   DSEDAC.VDDL1, DSEDAC.CLCL1, DSEDAC.CLIX, DSEDAC.CRUT, DSEDAC.CLIL1
 * 
 * También analiza:
 *   - Claves primarias (desde SYSTABLES/SYSKEYS del catálogo)
 *   - Relaciones entre tablas (columnas comunes)
 *   - Número de filas por tabla
 *   - Valores UNIQUE de las columnas clave de JOIN
 *
 * Salida: backend/scripts/results/vista-unificada-discovery.json
 */

const odbc = require('odbc');
const fs = require('fs');
const path = require('path');

require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });


function requireEnv(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(name + " environment variable is required");
  }
  return value;
}

const DB_DSN = process.env.ODBC_DSN || 'GMP';
const DB_UID = requireEnv('ODBC_UID');
const DB_PWD = requireEnv('ODBC_PWD');

const CONNECTION_STRING = [
  `DSN=${DB_DSN}`,
  `UID=${DB_UID}`,
  `PWD=${DB_PWD}`,
  'NAM=1',
  'CCSID=1208',
  'CMPTDM=1',
].join(';');

// TABLAS EXACTAS QUE PIDIÓ EL USUARIO
const TABLES = ['VDDL1', 'CLCL1', 'CLIX', 'CRUT', 'CLIL1'];

async function main() {
  let pool = null;
  let conn = null;

  try {
    pool = await odbc.pool(CONNECTION_STRING);
    conn = await pool.connect();

    // 1. Columnas por tabla (QSYS2.SYSCOLUMNS)
    console.log('═══════════════════════════════════════════════════════════');
    console.log('  DESCUBRIMIENTO DE COLUMNAS — VISTA UNIFICADA JAVIER');
    console.log('═══════════════════════════════════════════════════════════\n');

    const results = {};

    for (const tbl of TABLES) {
      console.log(`━━━ DSEDAC.${tbl} ━━━`);

      try {
        // Verificar que la tabla existe
        const checkQuery = `
          SELECT TABLE_NAME, TABLE_SCHEMA, TABLE_TYPE, TABLE_TEXT
          FROM QSYS2.SYSTABLES
          WHERE TABLE_SCHEMA = 'DSEDAC'
            AND TABLE_NAME = '${tbl}'
        `;
        const tableInfo = await conn.query(checkQuery);
        if (tableInfo.length === 0) {
          console.log(`  ⚠️  TABLA NO ENCONTRADA en QSYS2.SYSTABLES para schema DSEDAC\n`);
          results[tbl] = { error: 'NOT_FOUND', columns: [], tableInfo: null };
          continue;
        }
        console.log(`  Tipo: ${tableInfo[0].TABLE_TYPE}, Desc: ${(tableInfo[0].TABLE_TEXT || '').trim()}`);

        // Columnas
        const colQuery = `
          SELECT 
            COLUMN_NAME,
            SYSTEM_COLUMN_NAME,
            DATA_TYPE,
            LENGTH,
            NUMERIC_SCALE,
            IS_NULLABLE,
            HAS_DEFAULT,
            COLUMN_DEFAULT,
            COLUMN_TEXT,
            ORDINAL_POSITION,
            IS_IDENTITY
          FROM QSYS2.SYSCOLUMNS
          WHERE TABLE_SCHEMA = 'DSEDAC'
            AND TABLE_NAME = '${tbl}'
          ORDER BY ORDINAL_POSITION
        `;
        const columns = await conn.query(colQuery);
        console.log(`  Columnas encontradas: ${columns.length}`);

        for (const col of columns) {
          const nullable = col.IS_NULLABLE === 'Y' ? 'NULL' : 'NOT NULL';
          const dtype = col.DATA_TYPE;
          const len = col.LENGTH || '';
          const scale = col.NUMERIC_SCALE !== null ? `,${col.NUMERIC_SCALE}` : '';
          const def = col.HAS_DEFAULT === 'Y' ? ` DEFAULT ${col.COLUMN_DEFAULT || ''}` : '';
          const text = col.COLUMN_TEXT ? ` -- ${(col.COLUMN_TEXT || '').trim()}` : '';
          console.log(`    ${String(col.ORDINAL_POSITION).padStart(3)}. ${col.COLUMN_NAME} ${dtype}(${len}${scale}) ${nullable}${def}${text}`);
        }

        // Contar filas
        let rowCount = null;
        try {
          const countResult = await conn.query(`SELECT COUNT(*) AS CNT FROM DSEDAC.${tbl}`);
          rowCount = countResult[0].CNT;
          console.log(`  Filas totales: ${rowCount.toLocaleString()}`);
        } catch (e) {
          console.log(`  Filas: ERROR - ${e.message}`);
        }

        // Claves foráneas detectables (columnas comunes con otras tablas del set)
        const colNames = columns.map(c => c.COLUMN_NAME);
        
        results[tbl] = {
          tableInfo: tableInfo[0],
          columns,
          columnNames: colNames,
          rowCount,
        };

        console.log();
      } catch (err) {
        console.error(`  ERROR: ${err.message}\n`);
        results[tbl] = { error: err.message, columns: [], tableInfo: null };
      }
    }

    // 2. Análisis de intersección de columnas (para JOINs)
    console.log('═══════════════════════════════════════════════════════════');
    console.log('  ANÁLISIS DE RELACIONES ENTRE TABLAS');
    console.log('═══════════════════════════════════════════════════════════\n');

    const intersections = {};
    const validTables = Object.entries(results).filter(([, v]) => !v.error);
    
    for (let i = 0; i < validTables.length; i++) {
      for (let j = i + 1; j < validTables.length; j++) {
        const [nameA, dataA] = validTables[i];
        const [nameB, dataB] = validTables[j];
        const common = (dataA.columnNames || []).filter(c => (dataB.columnNames || []).includes(c));
        if (common.length > 0) {
          const key = `${nameA}↔${nameB}`;
          intersections[key] = common;
          console.log(`  ${nameA} ↔ ${nameB}: ${common.join(', ')}`);
        }
      }
    }

    // 3. Muestrear valores de las columnas de JOIN más probables
    console.log('\n═══════════════════════════════════════════════════════════');
    console.log('  MUESTREO DE VALORES DE COLUMNAS CLAVE');
    console.log('═══════════════════════════════════════════════════════════\n');

    const sampleResults = {};
    const keyCols = ['CODIGOCLIENTE', 'CODIGOVENDEDOR', 'CODIGORUTA', 'SUBEMPRESA'];

    for (const tbl of TABLES) {
      if (!results[tbl] || results[tbl].error) continue;
      const colNames = results[tbl].columnNames || [];
      const relevantCols = keyCols.filter(kc => colNames.includes(kc));

      if (relevantCols.length > 0) {
        for (const kc of relevantCols) {
          try {
            const sampleQuery = `
              SELECT ${kc}, COUNT(*) AS CNT
              FROM DSEDAC.${tbl}
              GROUP BY ${kc}
              ORDER BY CNT DESC
              FETCH FIRST 5 ROWS ONLY
            `;
            const samples = await conn.query(sampleQuery);
            const key = `${tbl}.${kc}`;
            sampleResults[key] = samples;
            console.log(`  ${key} (top 5):`);
            for (const s of samples) {
              console.log(`    "${(s[kc] || '').trim()}" → ${s.CNT} filas`);
            }
          } catch (e) {
            console.log(`  ${tbl}.${kc}: ERROR - ${e.message}`);
          }
        }
      }
    }

    // Guardar resultados
    const outputPath = path.resolve(__dirname, 'results', 'vista-unificada-discovery.json');
    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
    fs.writeFileSync(outputPath, JSON.stringify({
      results,
      intersections,
      sampleResults,
      timestamp: new Date().toISOString(),
    }, null, 2));
    console.log(`\n✅ Resultados guardados en: ${outputPath}`);

  } catch (err) {
    console.error(`\n❌ FATAL: ${err.message}`);
    process.exitCode = 1;
  } finally {
    if (conn) { try { await conn.close(); } catch (_) {} }
    if (pool) { try { await pool.close(); } catch (_) {} }
  }
}

main();

'use strict';

/**
 * ERP <-> JAVIER INVENTORY (PEDIDOS + COBROS + LIQUIDACION + ENTREGAS)
 * ====================================================================
 * Objetivo: que JAVIER sea una copia 1:1 (misma estructura) de las tablas de
 * produccion DSEDAC para que los datos generados por la app fluyan despues
 * al ERP sin transformaciones, EXCEPTO bolsa comercial (JAVIER por diseno).
 *
 * Este script:
 *   1. Introspecciona TODAS las tablas DSEDAC y JAVIER usadas en los flujos
 *      de pedidos, cobros y liquidacion diaria de repartidor.
 *   2. Para cada tabla: columnas (nombre, tipo, longitud, escala, null, texto),
 *      n. de filas y 3 filas ejemplo si hay datos.
 *   3. Para cada PAR conocido JAVIER<->DSEDAC: diff automatico de columnas
 *      (presentes en uno y no en el otro, mismo nombre con tipo distinto).
 *   4. Tambien dumpea definicion (TEXT) de las vistas JAVIER del scope.
 *
 * Salida: backend/tmp/db-exploration/erp_inventory_full.md
 *
 * USO: node backend/scripts/erp_cobros_inventory.js
 */

const fs = require('fs/promises');
const path = require('path');
const odbc = require('odbc');
require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });

const OUTPUT_DIR = path.resolve(__dirname, '..', 'tmp', 'db-exploration');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'erp_inventory_full.md');

// ---------------------------------------------------------------------------
// Scope: cada grupo es una "feature" con tablas DSEDAC (producibles) y
// tablas/vistas JAVIER (mirror local). El objetivo es que sean equivalentes.
// ---------------------------------------------------------------------------
const SCOPE = [
  {
    feature: 'PEDIDOS (comercial - confirmar pedido)',
    dsedac: [
      { name: 'CPC',     desc: 'Cab.pedidos cliente' },
      { name: 'LPC',     desc: 'Lin.pedidos cliente' },
      { name: 'OCPC',    desc: 'Observaciones cab.pedidos cliente' },
      { name: 'CDVI',    desc: 'Dias visita cliente (reparto)' },
      { name: 'CRUT',    desc: 'Configuracion rutero' },
      { name: 'OPP',     desc: 'Operaciones de pedido' },
      { name: 'VEH',     desc: 'Vehiculos' },
      { name: 'VDD',     desc: 'Vendedores' },
      { name: 'ART',     desc: 'Articulos' },
      { name: 'ARTX',    desc: 'Articulos extendido' },
