function requireEnv(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(name + " environment variable is required");
  }
  return value;
}

function connectionString() {
  const dsn = process.env.ODBC_DSN || 'GMP';
  const uid = requireEnv('ODBC_UID');
  const pwd = requireEnv('ODBC_PWD');
  return [
    `DSN=${dsn}`,
    `UID=${uid}`,
    `PWD=${pwd}`,
    'NAM=1',
    'CCSID=1208',
    'CMPTDM=1',
    `CPTOUT=${process.env.ODBC_TIMEOUT || 60}`,
    `COMMTIMEOUT=${process.env.ODBC_COMM_TIMEOUT || 90}`,
    `DBQ=${dsn}`,
  ].join(';');
}

async function safeQuery(conn, sql, params = []) {
  try {
    const rows = await conn.query(sql, params);
    return { ok: true, rows };
  } catch (error) {
    return { ok: false, error: error.message };
  }
}

async function fetchColumns(conn, schema, table) {
  return safeQuery(conn, `
    SELECT COLUMN_NAME, DATA_TYPE, LENGTH, NUMERIC_SCALE, IS_NULLABLE, COLUMN_TEXT
    FROM QSYS2.SYSCOLUMNS
    WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?
    ORDER BY ORDINAL_POSITION
  `, [schema, table]);
}

async function fetchCount(conn, schema, table) {
  return safeQuery(conn, `SELECT COUNT(*) AS N FROM ${schema}.${table} FETCH FIRST 1 ROW ONLY`);
}

async function fetchSample(conn, schema, table) {
  return safeQuery(conn, `SELECT * FROM ${schema}.${table} FETCH FIRST 3 ROWS ONLY`);
}

async function fetchViewText(conn, schema, view) {
  return safeQuery(conn, `
    SELECT VIEW_DEFINITION
    FROM QSYS2.SYSVIEWS
    WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?
  `, [schema, view]);
}

async function describeTable(conn, schema, table, desc) {
  const out = [`#### ${schema}.${table} - ${desc || ''}`, ''];

  const cols = await fetchColumns(conn, schema, table);
  if (!cols.ok) {
    out.push(`> ERROR consultando columnas: ${cols.error}`, '');
    return { md: out.join('\n'), exists: false, columns: null };
  }
  if (!cols.rows.length) {
    out.push(`> Tabla **NO EXISTE** en ${schema} (o sin permisos)`, '');
    return { md: out.join('\n'), exists: false, columns: null };
  }

  out.push('| # | Columna | Tipo | Long | Esc | Null | Texto |');
  out.push('|---|---------|------|------|-----|------|-------|');
  cols.rows.forEach((c, i) => {
    const len = c.LENGTH != null ? c.LENGTH : '';
    const scale = c.NUMERIC_SCALE != null ? c.NUMERIC_SCALE : '';
    const text = (c.COLUMN_TEXT || '').toString().trim().replace(/\|/g, '/');
    out.push(`| ${i + 1} | ${c.COLUMN_NAME} | ${c.DATA_TYPE} | ${len} | ${scale} | ${c.IS_NULLABLE} | ${text} |`);
  });
  out.push('');

  const count = await fetchCount(conn, schema, table);
  if (count.ok && count.rows.length) {
    out.push(`**Filas:** ${count.rows[0].N}`, '');
  }

  const sample = await fetchSample(conn, schema, table);
  if (sample.ok && sample.rows.length) {
    const json = JSON.stringify(sample.rows, null, 2).slice(0, 4000);
    out.push('<details><summary>Sample (3 filas)</summary>', '', '```json', json, '```', '', '</details>', '');
  }

  return { md: out.join('\n'), exists: true, columns: cols.rows };
}

function buildColumnDiff(label, javierCols, dsedacCols) {
  const out = [`#### Diff ${label}`, ''];
  if (!javierCols || !dsedacCols) {
    out.push('> No se puede comparar (alguna tabla no existe)', '');
    return out.join('\n');
  }

  const jvMap = new Map(javierCols.map(c => [c.COLUMN_NAME, c]));
  const dsMap = new Map(dsedacCols.map(c => [c.COLUMN_NAME, c]));

  const onlyJavier = [...jvMap.keys()].filter(k => !dsMap.has(k));
  const onlyDsedac = [...dsMap.keys()].filter(k => !jvMap.has(k));
  const both = [...jvMap.keys()].filter(k => dsMap.has(k));

  out.push(`- Columnas en AMBOS: ${both.length}`);
  out.push(`- Solo en JAVIER: ${onlyJavier.length}`);
  out.push(`- Solo en DSEDAC: ${onlyDsedac.length}`);
  out.push('');

  if (onlyJavier.length) {
    out.push('**Solo JAVIER (sobran o son metadata local: SYNC_STATUS, CREATED_AT, etc.):**');
    onlyJavier.forEach(n => out.push(`  - ${n} (${jvMap.get(n).DATA_TYPE})`));
    out.push('');
  }
  if (onlyDsedac.length) {
    out.push('**Solo DSEDAC (FALTAN en JAVIER - hay que anadirlas para mirror 1:1):**');
    onlyDsedac.forEach(n => out.push(`  - ${n} (${dsMap.get(n).DATA_TYPE} len=${dsMap.get(n).LENGTH})`));
    out.push('');
  }

  const typeMismatches = both.filter(n => {
    const j = jvMap.get(n);
    const d = dsMap.get(n);
    return j.DATA_TYPE !== d.DATA_TYPE
        || (j.LENGTH || 0) !== (d.LENGTH || 0)
        || (j.NUMERIC_SCALE || 0) !== (d.NUMERIC_SCALE || 0);
  });
  if (typeMismatches.length) {
    out.push('**Tipo distinto (revisar - puede romper INSERT):**');
    out.push('| Columna | JAVIER | DSEDAC |');
    out.push('|---------|--------|--------|');
    typeMismatches.forEach(n => {
      const j = jvMap.get(n);
      const d = dsMap.get(n);
      out.push(`| ${n} | ${j.DATA_TYPE}(${j.LENGTH || ''},${j.NUMERIC_SCALE || ''}) | ${d.DATA_TYPE}(${d.LENGTH || ''},${d.NUMERIC_SCALE || ''}) |`);
    });
    out.push('');
  }
  return out.join('\n');
}

(async () => {
  await fs.mkdir(OUTPUT_DIR, { recursive: true });
  const conn = await odbc.connect(connectionString());

  const md = [];
  md.push('# ERP <-> JAVIER - Inventario completo (Pedidos + Cobros + Liquidacion + Entregas)');
  md.push('');
  md.push(`Generado: ${new Date().toISOString()}`);
  md.push('');
  md.push('Objetivo: que JAVIER sea mirror 1:1 de DSEDAC para que los datos generados por la app fluyan al ERP sin transformaciones. **EXCEPTO** Bolsa Comercial (JAVIER por diseno).');
  md.push('');
  md.push('---');
  md.push('');

  for (const group of SCOPE) {
    md.push(`## ${group.feature}`);
    md.push('');

    // Cache de columnas para diff posterior
    const colsCache = new Map();

    if (group.dsedac.length) {
      md.push('### Tablas DSEDAC (produccion - destino final)');
      md.push('');
      for (const t of group.dsedac) {
        process.stdout.write(`  DSEDAC.${t.name}... `);
        const r = await describeTable(conn, 'DSEDAC', t.name, t.desc);
        md.push(r.md);
        colsCache.set(`DSEDAC.${t.name}`, r.columns);
        process.stdout.write(r.exists ? 'OK\n' : 'NO EXISTE\n');
      }
    }

    if (group.javier.length) {
      md.push('### Tablas JAVIER (mirror local)');
      md.push('');
      for (const t of group.javier) {
        process.stdout.write(`  JAVIER.${t.name}... `);
        const r = await describeTable(conn, 'JAVIER', t.name, t.desc);
        md.push(r.md);
        colsCache.set(`JAVIER.${t.name}`, r.columns);
        process.stdout.write(r.exists ? 'OK\n' : 'NO EXISTE\n');
      }
    }

    if (group.pairs.length) {
      md.push('### Diffs JAVIER <-> DSEDAC (alineacion necesaria)');
      md.push('');
      for (const p of group.pairs) {
        const jv = colsCache.get(`JAVIER.${p.javier}`);
        const ds = colsCache.get(`DSEDAC.${p.dsedac}`);
        md.push(buildColumnDiff(`JAVIER.${p.javier} <-> DSEDAC.${p.dsedac}`, jv, ds));
      }
    }

    md.push('---');
    md.push('');
  }

  md.push('## Vistas JAVIER (definicion textual)');
  md.push('');
  for (const v of JAVIER_VIEWS) {
    process.stdout.write(`  VIEW JAVIER.${v}... `);
    const r = await fetchViewText(conn, 'JAVIER', v);
    md.push(`### JAVIER.${v}`, '');
    if (!r.ok) {
      md.push(`> ERROR: ${r.error}`, '');
      process.stdout.write('FAIL\n');
      continue;
    }
    if (!r.rows.length) {
      md.push(`> Vista no existe en JAVIER`, '');
      process.stdout.write('NO EXISTE\n');
      continue;
    }
    const def = (r.rows[0].VIEW_DEFINITION || '').toString().slice(0, 4000);
    md.push('```sql', def, '```', '');
    process.stdout.write('OK\n');
  }

  await conn.close();
  await fs.writeFile(OUTPUT_FILE, md.join('\n'), 'utf8');
  console.log(`\nInforme guardado en: ${OUTPUT_FILE}`);
})().catch((err) => {
  console.error('FATAL:', err.message);
  process.exit(1);
});

'use strict';

/**
 * Execute JAVIER schema alignment to DSEDAC export targets.
 * Adds missing DSEDAC columns to JAVIER tables (insert-compatible mirror).
 *
 * Usage (on server with ODBC):
 *   cd backend && node scripts/execute-javier-dsedac-alignment.js
 *   node scripts/execute-javier-dsedac-alignment.js --dry-run
 *
 * Output: backend/tmp/db-exploration/javier-dsedac-alignment-executed-<ts>.json
 */

require('dotenv').config({ path: require('path').join(__dirname, '../.env') });
const fs = require('fs/promises');
const path = require('path');
const odbc = require('odbc');

const DRY_RUN = process.argv.includes('--dry-run');
const APP_SCHEMA = 'JAVIER';
const ERP_SCHEMA = 'DSEDAC';

const PAIRS = [
  { javier: 'PEDIDOS_CAB', dsedac: 'CPC' },
  { javier: 'PEDIDOS_LIN', dsedac: 'LPC' },
  { javier: 'COBROS', dsedac: 'CRC' },
  { javier: 'REPARTIDOR_COBROS', dsedac: 'CRCA' },
];

const APP_ONLY_TABLES = ['BOLSA_COMERCIAL', 'MOVIMIENTOS_BOLSA', 'PEDIDOS_SEQ', 'PEDIDOS_STOCK_RESERVE'];

/** Columns that share a name but differ by design (app UUID vs ERP integer). */
const SEMANTIC_TYPE_OVERRIDES = new Set([
  'JAVIER.COBROS:ID',
]);

function connectionString() {
  const pwd = process.env.ODBC_PWD || process.env.ODBC_PASSWORD;
  return [
    `DSN=${process.env.ODBC_DSN || 'GMP'}`,
    `UID=${process.env.ODBC_UID || 'JAVIER'}`,
    `PWD=${pwd}`,
    'NAM=1', 'CCSID=1208', 'CMPTDM=1', 'CPTOUT=120', 'COMMTIMEOUT=180',
  ].join(';');
}

function normalizeName(v) {
  return String(v || '').trim().toUpperCase();
}

function sqlType(col) {
  const t = normalizeName(col.DATA_TYPE);
  const len = Number(col.LENGTH || 0);
  const scale = Number(col.NUMERIC_SCALE || col.SCALE || 0);
  if (['DECIMAL', 'NUMERIC', 'PACKED', 'ZONED'].includes(t)) {
    return `${t}(${len || 10},${scale || 0})`;
  }
  if (['CHAR', 'CHARACTER', 'VARCHAR', 'GRAPHIC', 'VARGRAPHIC'].includes(t)) {
    return `${t}(${len || 1})`;
  }
  if (['BIGINT', 'INTEGER', 'SMALLINT', 'DATE', 'TIME', 'TIMESTAMP', 'REAL', 'DOUBLE', 'DECFLOAT'].includes(t)) {
    return t;
  }
  if (len > 0 && scale > 0) return `${t}(${len},${scale})`;
  if (len > 0) return `${t}(${len})`;
  return t;
}

function typesCompatible(jCol, dCol) {
  const jSig = `${normalizeName(jCol.DATA_TYPE)}(${jCol.LENGTH},${jCol.NUMERIC_SCALE || 0})`;
  const dSig = `${normalizeName(dCol.DATA_TYPE)}(${dCol.LENGTH},${dCol.NUMERIC_SCALE || 0})`;
  if (jSig === dSig) return true;
  const numeric = new Set(['BIGINT', 'DECIMAL', 'DECFLOAT', 'DOUBLE', 'FLOAT', 'INTEGER', 'NUMERIC', 'PACKED', 'REAL', 'SMALLINT', 'ZONED']);
  const strings = new Set(['CHAR', 'CHARACTER', 'VARCHAR', 'CLOB']);
  const jt = normalizeName(jCol.DATA_TYPE);
  const dt = normalizeName(dCol.DATA_TYPE);
  if (numeric.has(jt) && numeric.has(dt)) {
    return Number(jCol.LENGTH) >= Number(dCol.LENGTH) && Number(jCol.NUMERIC_SCALE || 0) >= Number(dCol.NUMERIC_SCALE || 0);
  }
  if (strings.has(jt) && strings.has(dt)) {
    return Number(jCol.LENGTH) >= Number(dCol.LENGTH);
  }
  return jt === dt;
}

async function getColumns(conn, schema, table) {
  return conn.query(
    `SELECT COLUMN_NAME, DATA_TYPE, LENGTH, NUMERIC_SCALE, IS_NULLABLE, ORDINAL_POSITION
       FROM QSYS2.SYSCOLUMNS
      WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?
      ORDER BY ORDINAL_POSITION`,
    [schema, table],
  );
}

async function tableExists(conn, schema, table) {
  const rows = await conn.query(
    `SELECT 1 AS OK FROM QSYS2.SYSTABLES WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ? FETCH FIRST 1 ROW ONLY`,
    [schema, table],
  );
  return rows.length > 0;
}

async function runDdl(conn, sql, log) {
  log.ddl.push(sql);
  if (DRY_RUN) {
    log.executed.push({ sql, status: 'dry-run' });
    return;
  }
  try {
    await conn.query(sql);
    log.executed.push({ sql, status: 'ok' });
  } catch (err) {
    log.executed.push({ sql, status: 'error', error: err.message });
    log.errors.push({ sql, error: err.message });
  }
}

async function alignPair(conn, pair, log) {
  const result = { pair: `${pair.javier}->${pair.dsedac}`, missing: [], typeMismatches: [], appOnly: [] };
  const jExists = await tableExists(conn, APP_SCHEMA, pair.javier);
  const dExists = await tableExists(conn, ERP_SCHEMA, pair.dsedac);
  if (!dExists) {
    result.error = `DSEDAC.${pair.dsedac} not found`;
    log.pairs.push(result);
    return;
  }
  if (!jExists) {
    result.error = `JAVIER.${pair.javier} not found — run generate_align_migration.js first`;
    log.pairs.push(result);
    return;
  }

  const [jCols, dCols] = await Promise.all([
    getColumns(conn, APP_SCHEMA, pair.javier),
    getColumns(conn, ERP_SCHEMA, pair.dsedac),
  ]);
  const jMap = new Map(jCols.map((c) => [normalizeName(c.COLUMN_NAME), c]));
  const dMap = new Map(dCols.map((c) => [normalizeName(c.COLUMN_NAME), c]));

  for (const dCol of dCols) {
    const name = normalizeName(dCol.COLUMN_NAME);
    const jCol = jMap.get(name);
    if (!jCol) {
      result.missing.push(name);
      const nullable = normalizeName(dCol.IS_NULLABLE) === 'N' ? ' NOT NULL WITH DEFAULT' : '';
      const ddl = `ALTER TABLE ${APP_SCHEMA}.${pair.javier} ADD COLUMN ${name} ${sqlType(dCol)}${nullable}`;
      await runDdl(conn, ddl, log);
      continue;
    }
    if (!typesCompatible(jCol, dCol)) {
      const overrideKey = `${APP_SCHEMA}.${pair.javier}:${name}`;
      if (SEMANTIC_TYPE_OVERRIDES.has(overrideKey)) {
        result.semanticOverrides = result.semanticOverrides || [];
        result.semanticOverrides.push({ column: name, javier: sqlType(jCol), dsedac: sqlType(dCol) });
        continue;
      }
      result.typeMismatches.push({
        column: name,
        javier: sqlType(jCol),
        dsedac: sqlType(dCol),
      });
      const ddl = `ALTER TABLE ${APP_SCHEMA}.${pair.javier} ALTER COLUMN ${name} SET DATA TYPE ${sqlType(dCol)}`;
      await runDdl(conn, ddl, log);
    }
  }

  for (const jCol of jCols) {
    const name = normalizeName(jCol.COLUMN_NAME);
    if (!dMap.has(name)) result.appOnly.push(name);
  }

  result.javierCols = jCols.length;
  result.dsedacCols = dCols.length;
  result.insertReady = result.missing.length === 0 && result.typeMismatches.length === 0;
  log.pairs.push(result);
}

async function main() {
  const ts = new Date().toISOString().replace(/[:.]/g, '-');
  const outDir = path.resolve(__dirname, '..', 'tmp', 'db-exploration');
  await fs.mkdir(outDir, { recursive: true });
  const outPath = path.join(outDir, `javier-dsedac-alignment-executed-${ts}.json`);

  const log = {
    ts: new Date().toISOString(),
    dryRun: DRY_RUN,
    appSchema: APP_SCHEMA,
    erpSchema: ERP_SCHEMA,
    ddl: [],
    executed: [],
    errors: [],
    pairs: [],
    appOnly: [],
  };

  const conn = await odbc.connect(connectionString());
  try {
    for (const pair of PAIRS) {
      process.stdout.write(`[align] ${pair.javier} <- ${pair.dsedac}... `);
      await alignPair(conn, pair, log);
      console.log('done');
    }

    for (const table of APP_ONLY_TABLES) {
      const exists = await tableExists(conn, APP_SCHEMA, table);
      log.appOnly.push({ table, exists, note: 'ERP-only N/A — app buffer by design' });
    }

    log.summary = {
      ddlCount: log.ddl.length,
      errors: log.errors.length,
      pairsInsertReady: log.pairs.filter((p) => p.insertReady).length,
      pairsTotal: log.pairs.length,
    };
    log.verdict = log.errors.length === 0 && log.pairs.every((p) => p.insertReady || p.error)
      ? 'ALIGNED'
      : 'NEEDS_REVIEW';

    await fs.writeFile(outPath, JSON.stringify(log, null, 2), 'utf8');
    console.log(`[align] verdict=${log.verdict} ddl=${log.ddl.length} wrote ${outPath}`);
    if (log.errors.length) process.exitCode = 1;
  } finally {
    await conn.close();
  }
}

main().catch((e) => {
  console.error('[align] FATAL:', e.message);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * execute-vista-unificada.js
 * Versión robusta: sin comentarios, sin CREATE OR REPLACE
 */

const fs = require('fs');
const path = require('path');
const odbc = require('odbc');

require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });


function requireEnv(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(name + " environment variable is required");
  }
  return value;
}

const DB_DSN = process.env.ODBC_DSN || 'GMP';
const DB_UID = requireEnv('ODBC_UID');
const DB_PWD = requireEnv('ODBC_PWD');

const CONNECTION_STRING = [
  `DSN=${DB_DSN}`,
  `UID=${DB_UID}`,
  `PWD=${DB_PWD}`,
  'NAM=1',
  'CCSID=1208',
  'CMPTDM=1',
].join(';');

async function main() {
  let pool = null;
  let conn = null;

  try {
    pool = await odbc.pool(CONNECTION_STRING);
    conn = await pool.connect();
    console.log('✅ Conectado a DB2\n');

    const sqlPath = path.resolve(__dirname, 'sql', 'vista_clientes_unificada.sql');
    let rawSql = fs.readFileSync(sqlPath, 'utf8');

    // Limpiar comentarios
    const cleanSql = rawSql
      .replace(/--.*$/gm, '')  // quitar comentarios de línea
      .replace(/\/\*[\s\S]*?\*\//g, '') // quitar comentarios de bloque
      .replace(/^\s*[\r\n]+/gm, '\n') // líneas vacías
      .trim();

    // Reemplazar CREATE OR REPLACE por CREATE (DB2 for i)
    const finalSql = cleanSql.replace(/CREATE OR REPLACE VIEW/i, 'CREATE VIEW');

    console.log(`📄 SQL: ${sqlPath} (${finalSql.length} chars limpios)`);

    // Dropear vista si existe
    console.log('\n🔨 Preparando...');
    try {
      await conn.query('DROP VIEW JAVIER.VISTA_CLIENTES_UNIFICADA');
      console.log('   Vista anterior eliminada');
    } catch (e) {
      console.log('   No había vista previa (OK)');
    }

    // Ejecutar CREATE VIEW
    console.log('   Creando vista...');
    await conn.query(finalSql);
    console.log('✅ Vista JAVIER.VISTA_CLIENTES_UNIFICADA CREADA\n');

    // Verificar catálogo
    console.log('🔍 Verificando...');
    const catalogQuery = `
      SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_TYPE
      FROM QSYS2.SYSTABLES
      WHERE TABLE_SCHEMA = 'JAVIER'
        AND TABLE_NAME = 'VISTA_CLIENTES_UNIFICADA'
    `;
    const cat = await conn.query(catalogQuery);
    if (cat.length > 0) {
      console.log(`✅ En catálogo: ${cat[0].TABLE_TYPE}`);

      // Columnas
      const colCount = await conn.query(`
        SELECT COUNT(*) AS CNT FROM QSYS2.SYSCOLUMNS
        WHERE TABLE_SCHEMA = 'JAVIER' AND TABLE_NAME = 'VISTA_CLIENTES_UNIFICADA'
      `);
      console.log(`   Columnas: ${colCount[0].CNT}`);

      // Filas
      const rowCount = await conn.query('SELECT COUNT(*) AS CNT FROM JAVIER.VISTA_CLIENTES_UNIFICADA');
      console.log(`   Filas: ${rowCount[0].CNT.toLocaleString()}\n`);

      // Muestra
      console.log('📋 Muestra (3 filas):');
      const sample = await conn.query(`
        SELECT CODIGOCLIENTE, NOMBRECLIENTE, POBLACION,
               CLCL1_DIASLIMITECREDITO, CLCL1_DIASLIMITECREDITOCONFECHAALB,
               RUT_CODIGOVENDEDOR, VDD_NOMBREVENDEDOR
        FROM JAVIER.VISTA_CLIENTES_UNIFICADA
        FETCH FIRST 3 ROWS ONLY
      `);
      for (const row of sample) {
        console.log(JSON.stringify(row, null, 2));
      }

      // Estadísticas
      console.log('\n📊 Estadísticas:');
      const stats = [
        ['Total clientes', 'SELECT COUNT(*) AS C FROM JAVIER.VISTA_CLIENTES_UNIFICADA'],
        ['Con crédito (CLCL1)', 'SELECT COUNT(*) AS C FROM JAVIER.VISTA_CLIENTES_UNIFICADA WHERE CLCL1_DIASLIMITECREDITO IS NOT NULL'],
        ['Con extensión (CLIX)', 'SELECT COUNT(*) AS C FROM JAVIER.VISTA_CLIENTES_UNIFICADA WHERE CLIX_CODIGOCLIENTE IS NOT NULL'],
        ['Con ruta (CRUT)', 'SELECT COUNT(*) AS C FROM JAVIER.VISTA_CLIENTES_UNIFICADA WHERE SECUENCIA IS NOT NULL'],
        ['Con vendedor (VDDL1)', 'SELECT COUNT(*) AS C FROM JAVIER.VISTA_CLIENTES_UNIFICADA WHERE VDD_NOMBREVENDEDOR IS NOT NULL'],
        ['DIASLIMITECREDITOCONFECHAALB=S', "SELECT COUNT(*) AS C FROM JAVIER.VISTA_CLIENTES_UNIFICADA WHERE TRIM(CLCL1_DIASLIMITECREDITOCONFECHAALB) = 'S'"],
        ['Con CODIGORUTA asignado', 'SELECT COUNT(*) AS C FROM JAVIER.VISTA_CLIENTES_UNIFICADA WHERE TRIM(CODIGORUTA) <> \'\' AND CODIGORUTA <> \'0000\''],
      ];
      for (const [label, sql] of stats) {
        const r = await conn.query(sql);
        console.log(`   ${label}: ${r[0].C.toLocaleString()}`);
      }

      console.log('\n═══════════════════════════════════════');
      console.log('  ✅ VISTA CREADA Y VERIFICADA');
      console.log('═══════════════════════════════════════');
    } else {
      console.log('⚠️ Vista no aparece en catálogo');
    }

  } catch (err) {
    console.error(`\n❌ ERROR: ${err.message}`);
    if (err.odbcErrors) {
      for (const e of err.odbcErrors) {
        console.error(`   STATE=${e.state} CODE=${e.code}: ${e.message}`);
      }
    }
    process.exitCode = 1;
  } finally {
    if (conn) { try { await conn.close(); } catch (_) {} }
    if (pool) { try { await pool.close(); } catch (_) {} }
  }
}

main();

'use strict';

/**
 * Pedido schema alignment SQL generator
 * =====================================
 *
 * Read-only DB2 metadata audit for the commercial order tables. It compares
 * JAVIER pedido tables against the production DSEDAC tables and writes one SQL
 * review file with the commands needed to make JAVIER match production.
 *
 * This script does not execute DDL/DML.
 */

const fs = require('fs/promises');
const path = require('path');
const odbc = require('odbc');
const db2ConnectionString = require('./db2-connection');

const OUTPUT_DIR = path.resolve(__dirname, '..', 'tmp', 'db-exploration');

const APP_SCHEMA = String(process.env.PEDIDOS_CONFIRMATION_SCHEMA || 'JAVIER')
  .trim()
  .toUpperCase();
const ERP_SCHEMA = String(process.env.ERP_SCHEMA || 'DSEDAC')
  .trim()
  .toUpperCase();

const TABLE_PAIRS = [
  {
    label: 'Cabecera de pedidos comerciales',
    test: `${APP_SCHEMA}.PEDIDOS_CAB`,
    production: `${ERP_SCHEMA}.CPC`,
  },
  {
    label: 'Lineas de pedidos comerciales',
    test: `${APP_SCHEMA}.PEDIDOS_LIN`,
    production: `${ERP_SCHEMA}.LPC`,
  },
];

function getArgValue(name) {
  const prefix = `${name}=`;
  const inline = process.argv.find(arg => arg.startsWith(prefix));
  if (inline) return inline.slice(prefix.length);

  const index = process.argv.indexOf(name);
  if (index >= 0 && process.argv[index + 1]) return process.argv[index + 1];
  return null;
}

function splitQualifiedName(qualifiedName) {
  const [schema, table] = String(qualifiedName || '').split('.');
  if (!schema || !table) {
    throw new Error(`Invalid qualified table name: ${qualifiedName}`);
  }
  return { schema, table };
}

function normalizeName(value) {
  return String(value || '').trim().toUpperCase();
}

function normalizeColumn(row) {
  return {
    name: normalizeName(row.COLUMN_NAME),
    type: normalizeName(row.DATA_TYPE),
    length: Number(row.LENGTH || row.CHARACTER_MAXIMUM_LENGTH || 0),
    scale: Number(row.NUMERIC_SCALE || row.SCALE || 0),
    nullable: normalizeName(row.IS_NULLABLE || row.NULLS),
    defaulted: normalizeName(row.HAS_DEFAULT || ''),
    text: String(row.COLUMN_TEXT || row.LONG_COMMENT || '').trim(),
    ordinal: Number(row.ORDINAL_POSITION || 0),
  };
}

function isNullable(column) {
  return ['YES', 'Y'].includes(normalizeName(column.nullable || column.IS_NULLABLE || column.NULLS));
}

function typeSignature(column) {
  return `${column.type}(${column.length},${column.scale})`;
}

function nullabilitySignature(column) {
  return isNullable(column) ? 'NULL' : 'NOT NULL';
}

function sqlTypeFor(column) {
  const type = column.type;
  const length = Number(column.length || 0);
  const scale = Number(column.scale || 0);

  if (['DECIMAL', 'NUMERIC', 'PACKED', 'ZONED'].includes(type)) {
    return `${type}(${length || 10},${scale || 0})`;
  }
  if (['CHAR', 'CHARACTER', 'VARCHAR', 'GRAPHIC', 'VARGRAPHIC'].includes(type)) {
    return `${type}(${length || 1})`;
  }
  if (['BIGINT', 'INTEGER', 'SMALLINT', 'DATE', 'TIME', 'TIMESTAMP'].includes(type)) {
    return type;
  }
  if (length > 0 && scale > 0) return `${type}(${length},${scale})`;
  if (length > 0) return `${type}(${length})`;
  return type;
}

function columnDefinition(column) {
  const nullable = isNullable(column) ? '' : ' NOT NULL WITH DEFAULT';
  return `${column.name} ${sqlTypeFor(column)}${nullable}`;
}

function ddlCommented(sql, reason) {
  return [
    `-- REVIEW: ${reason}`,
    `-- ${sql}`,
  ];
}

async function queryRows(connection, sql, params = []) {
  return connection.query(sql, params);
}

async function getTableInfo(connection, schema, table) {
  const rows = await queryRows(connection, `
    SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_TYPE
    FROM QSYS2.SYSTABLES
    WHERE TABLE_SCHEMA = ?
      AND TABLE_NAME = ?
    FETCH FIRST 1 ROW ONLY
  `, [schema, table]);

  if (!rows.length) {
    return { exists: false, schema, table, type: null };
  }

  return {
    exists: true,
    schema,
    table,
    type: normalizeName(rows[0].TABLE_TYPE),
  };
}

async function getColumns(connection, schema, table) {
  const rows = await queryRows(connection, `
    SELECT COLUMN_NAME,
           DATA_TYPE,
           LENGTH,
           NUMERIC_SCALE,
           IS_NULLABLE,
           HAS_DEFAULT,
           COLUMN_TEXT,
           ORDINAL_POSITION
    FROM QSYS2.SYSCOLUMNS
    WHERE TABLE_SCHEMA = ?
      AND TABLE_NAME = ?
    ORDER BY ORDINAL_POSITION
  `, [schema, table]);

  return rows.map(normalizeColumn);
}

function compareColumns(testColumns, productionColumns) {
  const testByName = new Map(testColumns.map(column => [column.name, column]));
  const productionByName = new Map(productionColumns.map(column => [column.name, column]));

  const missingInJavier = productionColumns.filter(column => !testByName.has(column.name));
  const extraInJavier = testColumns.filter(column => !productionByName.has(column.name));

  const mismatches = [];
  for (const productionColumn of productionColumns) {
    const testColumn = testByName.get(productionColumn.name);
    if (!testColumn) continue;

    const typeMismatch = typeSignature(testColumn) !== typeSignature(productionColumn);
    const nullabilityMismatch = nullabilitySignature(testColumn) !== nullabilitySignature(productionColumn);
    if (typeMismatch || nullabilityMismatch) {
      mismatches.push({
        column: productionColumn.name,
        test: {
          type: typeSignature(testColumn),
          nullable: nullabilitySignature(testColumn),
        },
        production: {
          type: typeSignature(productionColumn),
          nullable: nullabilitySignature(productionColumn),
        },
        targetType: sqlTypeFor(productionColumn),
      });
    }
  }

  return {
    testColumnCount: testColumns.length,
    productionColumnCount: productionColumns.length,
    sharedColumnCount: productionColumns.length - missingInJavier.length,
    missingInJavier,
    extraInJavier,
    mismatches,
  };
}

async function auditPair(connection, pair) {
  const testName = splitQualifiedName(pair.test);
  const productionName = splitQualifiedName(pair.production);

  const [testTable, productionTable] = await Promise.all([
    getTableInfo(connection, testName.schema, testName.table),
    getTableInfo(connection, productionName.schema, productionName.table),
  ]);

  const result = {
    ...pair,
    tableStatus: { test: testTable, production: productionTable },
    diff: null,
    status: 'OK',
  };

  if (!testTable.exists || !productionTable.exists) {
    result.status = 'BLOCK';
    return result;
  }

  const [testColumns, productionColumns] = await Promise.all([
    getColumns(connection, testName.schema, testName.table),
    getColumns(connection, productionName.schema, productionName.table),
  ]);

  result.diff = compareColumns(testColumns, productionColumns);
  result.status = result.diff.missingInJavier.length || result.diff.mismatches.length
    ? 'BLOCK'
    : result.diff.extraInJavier.length
      ? 'REVIEW'
      : 'OK';

  if (testTable.type !== productionTable.type) {
    result.tableTypeMismatch = {
      test: testTable.type,
      production: productionTable.type,
    };
    result.status = 'BLOCK';
  }

  return result;
}

function renderSql(report) {
  const lines = [
    '-- Pedido schema alignment: JAVIER -> DSEDAC',
    `-- Generated: ${report.timestamp}`,
    `-- App schema: ${report.appSchema}`,
    `-- Production schema: ${report.erpSchema}`,
    '-- Source of truth: production table structure and data types.',
    '-- This file was generated from DB2 catalog metadata and was NOT executed.',
    '-- Execute DDL only after staging verification, QA/AppSec/SRE gates, and explicit production approval.',
    '',
  ];

  if (report.error) {
    lines.push(`-- BLOCK: ${report.error}`, '');
    return `${lines.join('\n')}\n`;
  }

  for (const pair of report.pairs) {
    lines.push(
      `-- ${pair.label}`,
      `-- JAVIER: ${pair.test}`,
      `-- DSEDAC: ${pair.production}`,
      `-- Status: ${pair.status}`,
      `-- Table type: JAVIER=${pair.tableStatus.test.type || 'missing'} DSEDAC=${pair.tableStatus.production.type || 'missing'}`,
      '',
    );

    if (!pair.diff) {
      lines.push('-- No column comparison available because one side is missing.', '');
      continue;
    }

    lines.push(
      `-- Columns: JAVIER=${pair.diff.testColumnCount} DSEDAC=${pair.diff.productionColumnCount} shared=${pair.diff.sharedColumnCount}`,
      `-- Missing in JAVIER: ${pair.diff.missingInJavier.length}`,
      `-- Extra in JAVIER: ${pair.diff.extraInJavier.length}`,
      `-- Type/nullability mismatches: ${pair.diff.mismatches.length}`,
      '',
    );

    if (!pair.diff.missingInJavier.length && !pair.diff.extraInJavier.length && !pair.diff.mismatches.length) {
      lines.push('-- No DDL needed: JAVIER already matches DSEDAC for this pedido table.', '');
      continue;
    }

    for (const column of pair.diff.missingInJavier) {
      lines.push(`ALTER TABLE ${pair.test} ADD COLUMN ${columnDefinition(column)};`);
    }

    for (const mismatch of pair.diff.mismatches) {
      const alterType = `ALTER TABLE ${pair.test} ALTER COLUMN ${mismatch.column} SET DATA TYPE ${mismatch.targetType};`;
      lines.push(...ddlCommented(
        alterType,
        `${mismatch.column} differs: JAVIER=${mismatch.test.type} ${mismatch.test.nullable}, DSEDAC=${mismatch.production.type} ${mismatch.production.nullable}`,
      ));

      if (mismatch.test.nullable !== mismatch.production.nullable) {
        const nullabilityDdl = mismatch.production.nullable === 'NOT NULL'
          ? `ALTER TABLE ${pair.test} ALTER COLUMN ${mismatch.column} SET NOT NULL;`
          : `ALTER TABLE ${pair.test} ALTER COLUMN ${mismatch.column} DROP NOT NULL;`;
        lines.push(...ddlCommented(
          nullabilityDdl,
          `${mismatch.column} nullability must match production before cutover`,
        ));
      }
    }

    if (pair.diff.extraInJavier.length) {
      lines.push(
        '-- Exact alignment requires removing the following JAVIER-only columns.',
        '-- They are commented because DROP COLUMN is destructive and can break app code.',
      );
      for (const column of pair.diff.extraInJavier) {
        lines.push(...ddlCommented(
          `ALTER TABLE ${pair.test} DROP COLUMN ${column.name};`,
          `${column.name} exists only in JAVIER; review application usage before dropping`,
        ));
      }
    }

    lines.push('');
  }

  return `${lines.join('\n')}\n`;
}

function normalizeSourceColumn(column) {
  return {
    name: normalizeName(column.name || column.COLUMN_NAME),
    type: normalizeName(column.type || column.DATA_TYPE),
    length: Number(column.length || column.LENGTH || 0),
    scale: Number(column.scale || column.NUMERIC_SCALE || 0),
    nullable: normalizeName(column.nullable || column.IS_NULLABLE || column.NULLS),
    defaulted: normalizeName(column.defaulted || column.HAS_DEFAULT || ''),
    text: String(column.text || column.COLUMN_TEXT || '').trim(),
    ordinal: Number(column.ordinal || column.ORDINAL_POSITION || 0),
  };
}

function pairFromSource(sourcePair) {
  const matchingDefinition = TABLE_PAIRS.find(pair =>
    normalizeName(pair.test) === normalizeName(sourcePair.test) &&
    normalizeName(pair.production) === normalizeName(sourcePair.production));

  const missingInJavier = (sourcePair.diff?.missingInTest || [])
    .map(normalizeSourceColumn);
  const extraInJavier = (sourcePair.diff?.appOnly || sourcePair.diff?.extraInJavier || [])
    .map(normalizeSourceColumn);
  const mismatches = (sourcePair.diff?.typeMismatches || []).map(mismatch => ({
    column: normalizeName(mismatch.column),
    test: {
      type: String(typeof mismatch.test === 'object' ? mismatch.test?.type || '' : mismatch.test || ''),
      nullable: String(mismatch.test?.nullable || 'UNKNOWN'),
    },
    production: {
      type: String(typeof mismatch.production === 'object' ? mismatch.production?.type || '' : mismatch.production || ''),
      nullable: String(mismatch.production?.nullable || 'UNKNOWN'),
    },
    targetType: String(mismatch.targetType || (typeof mismatch.production === 'string' ? mismatch.production : '') || 'REVIEW_TARGET_TYPE'),
  }));

  return {
    label: matchingDefinition?.label || sourcePair.feature || 'Pedidos',
    test: sourcePair.test,
    production: sourcePair.production,
    tableStatus: sourcePair.tableStatus || { test: {}, production: {} },
    tableTypeMismatch: sourcePair.tableTypeMismatch || null,
    diff: {
      testColumnCount: Number(sourcePair.diff?.testColumnCount || 0),
      productionColumnCount: Number(sourcePair.diff?.productionColumnCount || 0),
      sharedColumnCount: Number(sourcePair.diff?.shared?.length || 0),
      missingInJavier,
      extraInJavier,
      mismatches,
    },
    status: sourcePair.tableTypeMismatch || missingInJavier.length || mismatches.length
      ? 'BLOCK'
      : extraInJavier.length
        ? 'REVIEW'
        : 'OK',
  };
}

async function reportFromSourceFile(sourceReportPath) {
  const absolutePath = path.resolve(sourceReportPath);
  const raw = await fs.readFile(absolutePath, 'utf8');
  const source = JSON.parse(raw);
  const pairs = (source.pairs || [])
    .filter(pair => TABLE_PAIRS.some(definition =>
      normalizeName(definition.test) === normalizeName(pair.test) &&
      normalizeName(definition.production) === normalizeName(pair.production)))
    .map(pairFromSource);

  const summary = {
    ok: pairs.filter(pair => pair.status === 'OK').length,
    review: pairs.filter(pair => pair.status === 'REVIEW').length,
    block: pairs.filter(pair => pair.status === 'BLOCK').length,
    missingInJavier: pairs.reduce((total, pair) => total + (pair.diff?.missingInJavier.length || 0), 0),
    extraInJavier: pairs.reduce((total, pair) => total + (pair.diff?.extraInJavier.length || 0), 0),
    mismatches: pairs.reduce((total, pair) => total + (pair.diff?.mismatches.length || 0), 0),
    sourceReportPath: absolutePath,
  };

  return {
    timestamp: new Date().toISOString(),
    appSchema: normalizeName(source.appSchema || APP_SCHEMA),
    erpSchema: normalizeName(source.erpSchema || ERP_SCHEMA),
    status: summary.block > 0 ? 'BLOCK' : summary.review > 0 ? 'REVIEW' : 'OK',
    sourceReportPath: absolutePath,
    pairs,
    summary,
  };
}

async function writeOutputs(report, stamp) {
  await fs.mkdir(OUTPUT_DIR, { recursive: true });
  const jsonPath = path.join(OUTPUT_DIR, `pedidos-javier-dsedac-align-${stamp}.json`);
  const sqlPath = path.join(OUTPUT_DIR, `pedidos-javier-dsedac-align-${stamp}.sql`);
  await fs.writeFile(jsonPath, JSON.stringify(report, null, 2), 'utf8');
  await fs.writeFile(sqlPath, renderSql(report), 'utf8');
  return { jsonPath, sqlPath };
}

async function writeFailedReport(error) {
  const timestamp = new Date().toISOString();
  const stamp = timestamp.replace(/[:.]/g, '-');
  const report = {
    timestamp,
    appSchema: APP_SCHEMA,
    erpSchema: ERP_SCHEMA,
    status: 'BLOCK',
    error: error.message,
    odbcErrors: error.odbcErrors || [],
    pairs: [],
    summary: {
      ok: 0,
      review: 0,
      block: TABLE_PAIRS.length,
      missingInJavier: 0,
      extraInJavier: 0,
      mismatches: 0,
    },
  };
  const paths = await writeOutputs(report, stamp);
  return { report, ...paths };
}

async function main() {
  const timestamp = new Date().toISOString();
  const stamp = timestamp.replace(/[:.]/g, '-');
  const sourceReportPath = getArgValue('--source-report') || process.env.PEDIDOS_SCHEMA_SOURCE_REPORT;

  if (sourceReportPath) {
    const report = await reportFromSourceFile(sourceReportPath);
    const sourceStamp = report.timestamp.replace(/[:.]/g, '-');
    const { jsonPath, sqlPath } = await writeOutputs(report, sourceStamp);

    console.log(`[pedidos-schema-align] status=${report.status}`);
    console.log(`[pedidos-schema-align] source=${report.sourceReportPath}`);
    console.log(`[pedidos-schema-align] pairs ok/review/block=${report.summary.ok}/${report.summary.review}/${report.summary.block}`);
    console.log(`[pedidos-schema-align] missing/extra/mismatch=${report.summary.missingInJavier}/${report.summary.extraInJavier}/${report.summary.mismatches}`);
    console.log(`[pedidos-schema-align] wrote ${jsonPath}`);
    console.log(`[pedidos-schema-align] wrote ${sqlPath}`);
    return;
  }

  const connection = await odbc.connect(db2ConnectionString());

  try {
    const pairs = [];
    for (const pair of TABLE_PAIRS) {
      pairs.push(await auditPair(connection, pair));
    }

    const summary = {
      ok: pairs.filter(pair => pair.status === 'OK').length,
      review: pairs.filter(pair => pair.status === 'REVIEW').length,
      block: pairs.filter(pair => pair.status === 'BLOCK').length,
      missingInJavier: pairs.reduce((total, pair) => total + (pair.diff?.missingInJavier.length || 0), 0),
      extraInJavier: pairs.reduce((total, pair) => total + (pair.diff?.extraInJavier.length || 0), 0),
      mismatches: pairs.reduce((total, pair) => total + (pair.diff?.mismatches.length || 0), 0),
    };

    const report = {
      timestamp,
      appSchema: APP_SCHEMA,
      erpSchema: ERP_SCHEMA,
      status: summary.block > 0 ? 'BLOCK' : summary.review > 0 ? 'REVIEW' : 'OK',
      pairs,
      summary,
    };

    const { jsonPath, sqlPath } = await writeOutputs(report, stamp);

    console.log(`[pedidos-schema-align] status=${report.status}`);
    console.log(`[pedidos-schema-align] pairs ok/review/block=${summary.ok}/${summary.review}/${summary.block}`);
    console.log(`[pedidos-schema-align] missing/extra/mismatch=${summary.missingInJavier}/${summary.extraInJavier}/${summary.mismatches}`);
    console.log(`[pedidos-schema-align] wrote ${jsonPath}`);
    console.log(`[pedidos-schema-align] wrote ${sqlPath}`);

    if (report.status === 'BLOCK') process.exitCode = 2;
  } finally {
    await connection.close();
  }
}

main().catch(async error => {
  const { jsonPath, sqlPath } = await writeFailedReport(error);
  console.error(`[pedidos-schema-align] BLOCK: ${error.message}`);
  if (error.odbcErrors) console.error(JSON.stringify(error.odbcErrors, null, 2));
  console.error(`[pedidos-schema-align] wrote ${jsonPath}`);
  console.error(`[pedidos-schema-align] wrote ${sqlPath}`);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * generate-vista-deuda-completa.js
 * 
 * Genera CREATE VIEW para JAVIER.VISTA_DEUDA_COMPLETA
 * Ancla: DSEDAC.CVC (deuda/vencimientos)
 * LEFT JOIN: CLIL1, CLCL1, CLIX, CRUT, VDDL1
 */

const fs = require('fs');
const path = require('path');

const discoveryPath = path.resolve(__dirname, 'results', 'dsedac-column-discovery.json');
const vistaDiscoveryPath = path.resolve(__dirname, 'results', 'vista-unificada-discovery.json');

const cvcDiscovery = JSON.parse(fs.readFileSync(discoveryPath, 'utf8'));
const vistaDiscovery = JSON.parse(fs.readFileSync(vistaDiscoveryPath, 'utf8'));

const TABLA_ANCLA = 'CVC';
const ANCLA_ALIAS = 'CVC';

const OMITIR = ['ID', 'MARCAACTUALIZACION'];

// Función helper
function getColumns(tableName, discoveryData, omit = OMITIR) {
  let data = discoveryData.results?.[tableName] || discoveryData[tableName];
  if (!data || data.error) return [];
  // data puede ser {columns: [...]} o directamente un array de columnas
  const cols = Array.isArray(data) ? data : (data.columns || []);
  return cols.filter(c => !omit.includes(c.COLUMN_NAME));
}

// Columnas de CVC
const cvcCols = getColumns('CVC', cvcDiscovery);
// Columnas de las tablas cliente
const cliCols = getColumns('CLIL1', vistaDiscovery);
const clcl1Cols = getColumns('CLCL1', vistaDiscovery);
const clixCols = getColumns('CLIX', vistaDiscovery);
const crutCols = getColumns('CRUT', vistaDiscovery);
const vddl1Cols = getColumns('VDDL1', vistaDiscovery);

// Tracking de columnas ya usadas
const used = new Set();

// Generar SQL
const lines = [];

lines.push('-- ============================================================================');
lines.push('-- VISTA DE DEUDA COMPLETA — Esquema JAVIER');
lines.push('-- Ancla: DSEDAC.CVC (deuda/vencimientos = 1 fila por registro de deuda)');
lines.push('-- LEFT JOIN: DSEDAC.CLIL1, CLCL1, CLIX, CRUT, VDDL1');
lines.push('-- Columnas duplicadas: prefijo de tabla origen');
lines.push('-- CRUT filtrado por SECUENCIA = 1');
lines.push('-- ID y MARCAACTUALIZACION omitidos (técnicos)');
lines.push(`-- Generado: ${new Date().toISOString()}`);
lines.push('-- ============================================================================');
lines.push('');
lines.push('CREATE VIEW JAVIER.VISTA_DEUDA_COMPLETA AS');
lines.push('SELECT');

// 1. CVC (ancla) — todas las columnas sin prefijo
lines.push('');
lines.push('  -- ═══ DSEDAC.CVC (ANCLA: Deuda / Vencimientos) ═══');
for (const col of cvcCols) {
  const name = col.COLUMN_NAME;
  lines.push(`  ${ANCLA_ALIAS}.${name},`);
  used.add(name);
}

// 2. CLIL1 (cliente maestro)
lines.push('');
lines.push('  -- ═══ DSEDAC.CLIL1 (Cliente maestro) ═══');
for (const col of cliCols) {
  const name = col.COLUMN_NAME;
  if (used.has(name)) {
    lines.push(`  CLIL1.${name} AS CLI_${name},`);
    used.add(`CLI_${name}`);
  } else {
    lines.push(`  CLIL1.${name},`);
    used.add(name);
  }
}

// 3. CLCL1 (condiciones crédito)
lines.push('');
lines.push('  -- ═══ DSEDAC.CLCL1 (Condiciones de crédito) ═══');
for (const col of clcl1Cols) {
  const name = col.COLUMN_NAME;
  if (used.has(name)) {
    lines.push(`  CLCL1.${name} AS CLCL1_${name},`);
    used.add(`CLCL1_${name}`);
  } else {
    lines.push(`  CLCL1.${name},`);
    used.add(name);
  }
}

// 4. CLIX (extensión)
lines.push('');
lines.push('  -- ═══ DSEDAC.CLIX (Extensión cliente) ═══');
for (const col of clixCols) {
  const name = col.COLUMN_NAME;
  if (used.has(name)) {
    lines.push(`  CLIX.${name} AS CLIX_${name},`);
    used.add(`CLIX_${name}`);
  } else {
    lines.push(`  CLIX.${name},`);
    used.add(name);
  }
}

// 5. CRUT (ruta, SECUENCIA=1)
lines.push('');
lines.push('  -- ═══ DSEDAC.CRUT (Datos ruta, SECUENCIA=1) ═══');
for (const col of crutCols) {
  const name = col.COLUMN_NAME;
  if (used.has(name)) {
    lines.push(`  CRUT.${name} AS RUT_${name},`);
    used.add(`RUT_${name}`);
  } else {
    lines.push(`  CRUT.${name},`);
    used.add(name);
  }
}

// 6. VDDL1 (vendedor — directo desde CVC.CODIGOVENDEDOR)
lines.push('');
lines.push('  -- ═══ DSEDAC.VDDL1 (Vendedor, vía CVC.CODIGOVENDEDOR) ═══');
for (const col of vddl1Cols) {
  const name = col.COLUMN_NAME;
  if (used.has(name)) {
    lines.push(`  VDDL1.${name} AS VDD_${name},`);
    used.add(`VDD_${name}`);
  } else {
    lines.push(`  VDDL1.${name},`);
    used.add(name);
  }
}

// Quitar última coma
const lastIdx = lines.length - 1;
lines[lastIdx] = lines[lastIdx].replace(/,$/, '');

// FROM y JOINS
lines.push(`FROM DSEDAC.${TABLA_ANCLA} ${ANCLA_ALIAS}`);
lines.push('');
lines.push('-- Cliente maestro: CODIGOCLIENTEALBARAN = CODIGOCLIENTE');
lines.push('LEFT JOIN DSEDAC.CLIL1 CLIL1');
lines.push('  ON TRIM(CLIL1.CODIGOCLIENTE) = TRIM(CVC.CODIGOCLIENTEALBARAN)');
lines.push('');
lines.push('-- Condiciones de crédito');
lines.push('LEFT JOIN DSEDAC.CLCL1 CLCL1');
lines.push('  ON TRIM(CLCL1.CODIGOCLIENTE) = TRIM(CVC.CODIGOCLIENTEALBARAN)');
lines.push('');
lines.push('-- Extensión cliente');
lines.push('LEFT JOIN DSEDAC.CLIX CLIX');
lines.push('  ON TRIM(CLIX.CODIGOCLIENTE) = TRIM(CVC.CODIGOCLIENTEALBARAN)');
lines.push('');
lines.push('-- Datos ruta (secuencia principal)');
lines.push('LEFT JOIN DSEDAC.CRUT CRUT');
lines.push('  ON TRIM(CRUT.CODIGOCLIENTE) = TRIM(CVC.CODIGOCLIENTEALBARAN)');
lines.push('  AND CRUT.SECUENCIA = 1');
lines.push('');
lines.push('-- Vendedor (directo desde CVC.CODIGOVENDEDOR, no vía CRUT)');
lines.push('LEFT JOIN DSEDAC.VDDL1 VDDL1');
lines.push('  ON TRIM(VDDL1.CODIGOVENDEDOR) = TRIM(CVC.CODIGOVENDEDOR);');

const sql = lines.join('\n');

// Guardar
const sqlPath = path.resolve(__dirname, 'sql', 'vista_deuda_completa.sql');
const mdPath = path.resolve(__dirname, '..', '..', 'VISTA_DEUDA_COMPLETA.md');

fs.mkdirSync(path.dirname(sqlPath), { recursive: true });
fs.writeFileSync(sqlPath, sql);
fs.writeFileSync(mdPath, '```sql\n' + sql + '\n```\n');

const totalCols = (sql.match(/,/g) || []).length;
console.log(`✅ Vista generada:`);
console.log(`   SQL:  ${sqlPath}`);
console.log(`   MD:   ${mdPath}`);
console.log(`   Columnas totales: ~${totalCols}`);
console.log(`   Ancla: CVC (1 fila por registro de deuda)`);
console.log(`   JOINs: CVC → CLIL1 → CLCL1 → CLIX → CRUT → VDDL1`);

#!/usr/bin/env node
/**
 * generate-vista-unificada-sql.js
 * 
 * Genera el CREATE VIEW SQL para JAVIER.VISTA_CLIENTES_UNIFICADA
 * combinando las 5 tablas: VDDL1, CLCL1, CLIX, CRUT, CLIL1
 * 
 * Lógica de deduplicación de columnas:
 *   - Columnas presentes en CLIL1 (tabla base) → sin prefijo
 *   - Columnas repetidas en otras tablas → prefijo de la tabla
 *   - Columnas ID y MARCAACTUALIZACION → se omiten
 *   - CRUT filtrado por SECUENCIA = 1
 */

const fs = require('fs');
const path = require('path');

const discoveryPath = path.resolve(__dirname, 'results', 'vista-unificada-discovery.json');
const discovery = JSON.parse(fs.readFileSync(discoveryPath, 'utf8'));

const TABLA_BASE = 'CLIL1';
const TABLAS_JOIN = [
  { table: 'CLCL1', joinOn: 'CODIGOCLIENTE' },
  { table: 'CLIX', joinOn: 'CODIGOCLIENTE' },
  { table: 'CRUT', joinOn: 'CODIGOCLIENTE', extraFilter: 'CRUT.SECUENCIA = 1' },
  { table: 'VDDL1', joinOn: 'CODIGOVENDEDOR', joinVia: 'CRUT', joinViaCol: 'CODIGOVENDEDOR' },
];

// Columnas técnicas a omitir
const OMITIR = ['ID', 'MARCAACTUALIZACION'];

// Obtener columnas de una tabla
function getColumns(tableName) {
  const data = discovery.results[tableName];
  if (!data || data.error) return [];
  return (data.columns || []).map(c => c.COLUMN_NAME);
}

// Columnas de la tabla base (sin omitir)
const baseColumns = getColumns(TABLA_BASE).filter(c => !OMITIR.includes(c));

// Mapa para tracking: qué columnas ya se usaron
const usedColumns = new Set(baseColumns);

// SQL builder
let sql = `-- ============================================================================\n`;
sql += `-- VISTA UNIFICADA DE CLIENTES - Esquema JAVIER\n`;
sql += `-- Combina: DSEDAC.CLIL1 (base) + CLCL1 + CLIX + CRUT + VDDL1\n`;
sql += `-- Columnas duplicadas se prefijan con el alias de la tabla de origen\n`;
sql += `-- CRUT filtrado por SECUENCIA = 1 (ruta principal)\n`;
sql += `-- Columnas ID y MARCAACTUALIZACION omitidas por ser técnicas\n`;
sql += `-- Generado: ${new Date().toISOString()}\n`;
sql += `-- ============================================================================\n\n`;

sql += `CREATE OR REPLACE VIEW JAVIER.VISTA_CLIENTES_UNIFICADA AS\n`;
sql += `SELECT\n`;

// 1. Columnas de CLIL1 (base) - sin prefijo
const baseAlias = TABLA_BASE;
const baseColDefs = discovery.results[TABLA_BASE].columns.filter(c => !OMITIR.includes(c.COLUMN_NAME));

for (let i = 0; i < baseColDefs.length; i++) {
  const col = baseColDefs[i];
  const isLast = false; // placeholder
  sql += `  ${baseAlias}.${col.COLUMN_NAME}`;
  sql += `, -- ${(col.COLUMN_TEXT || '').trim()}`;
  sql += `\n`;
}

sql += `\n  -- ═══ DSEDAC.CLCL1 (Condiciones de crédito) ═══\n`;

// 2. Columnas de CLCL1
const clcl1Cols = discovery.results['CLCL1'].columns.filter(c => !OMITIR.includes(c.COLUMN_NAME));
for (const col of clcl1Cols) {
  if (usedColumns.has(col.COLUMN_NAME)) {
    sql += `  CLCL1.${col.COLUMN_NAME} AS CLCL1_${col.COLUMN_NAME}`;
  } else {
    sql += `  CLCL1.${col.COLUMN_NAME}`;
    usedColumns.add(col.COLUMN_NAME);
  }
  sql += `, -- ${(col.COLUMN_TEXT || '').trim()}`;
  sql += `\n`;
}

sql += `\n  -- ═══ DSEDAC.CLIX (Extensión de clientes) ═══\n`;

// 3. Columnas de CLIX
const clixCols = discovery.results['CLIX'].columns.filter(c => !OMITIR.includes(c.COLUMN_NAME));
for (const col of clixCols) {
  if (usedColumns.has(col.COLUMN_NAME)) {
    sql += `  CLIX.${col.COLUMN_NAME} AS CLIX_${col.COLUMN_NAME}`;
  } else {
    sql += `  CLIX.${col.COLUMN_NAME}`;
    usedColumns.add(col.COLUMN_NAME);
  }
  sql += `, -- ${(col.COLUMN_TEXT || '').trim()}`;
  sql += `\n`;
}

sql += `\n  -- ═══ DSEDAC.CRUT (Datos de ruta, SECUENCIA=1) ═══\n`;

// 4. Columnas de CRUT
const crutCols = discovery.results['CRUT'].columns.filter(c => !OMITIR.includes(c.COLUMN_NAME));
for (const col of crutCols) {
  // CODIGOVENDEDOR se maneja especial: presente en CRUT y VDDL1
  if (col.COLUMN_NAME === 'CODIGOVENDEDOR') {
    sql += `  CRUT.CODIGOVENDEDOR AS RUT_CODIGOVENDEDOR, -- Vendedor asignado en ruta\n`;
    usedColumns.add('RUT_CODIGOVENDEDOR');
    continue;
  }
  if (usedColumns.has(col.COLUMN_NAME)) {
    sql += `  CRUT.${col.COLUMN_NAME} AS RUT_${col.COLUMN_NAME}`;
  } else {
    sql += `  CRUT.${col.COLUMN_NAME}`;
    usedColumns.add(col.COLUMN_NAME);
  }
  sql += `, -- ${(col.COLUMN_TEXT || '').trim()}`;
  sql += `\n`;
}

sql += `\n  -- ═══ DSEDAC.VDDL1 (Vendedores, vía CRUT.CODIGOVENDEDOR) ═══\n`;

// 5. Columnas de VDDL1
const vddl1Cols = discovery.results['VDDL1'].columns.filter(c => !OMITIR.includes(c.COLUMN_NAME));
for (const col of vddl1Cols) {
  // CODIGOVENDEDOR de VDDL1 es igual al de CRUT (por el JOIN), no lo duplicamos
  if (col.COLUMN_NAME === 'CODIGOVENDEDOR') {
    continue; // Ya está como RUT_CODIGOVENDEDOR
  }
  if (usedColumns.has(col.COLUMN_NAME)) {
    sql += `  VDDL1.${col.COLUMN_NAME} AS VDD_${col.COLUMN_NAME}`;
  } else {
    sql += `  VDDL1.${col.COLUMN_NAME}`;
    usedColumns.add(col.COLUMN_NAME);
  }
  sql += `, -- ${(col.COLUMN_TEXT || '').trim()}`;
  sql += `\n`;
}

// Quitar última coma (antes del FROM)
// Find the last comma that appears before a FROM clause preceded only by whitespace/comments
const lines = sql.split('\n');
for (let i = lines.length - 1; i >= 0; i--) {
  const line = lines[i];
  if (line.trim().startsWith('--') || line.trim() === '') continue;
  if (line.trim().endsWith(',')) {
    lines[i] = line.trim().replace(/,\s*$/, '');
    break;
  }
  if (line.trim().startsWith('FROM')) break;
}
sql = lines.join('\n') + '\n';

// FROM y JOINS
sql += `FROM DSEDAC.${TABLA_BASE} ${TABLA_BASE}\n`;

// CLCL1
sql += `LEFT JOIN DSEDAC.CLCL1 CLCL1\n`;
sql += `  ON TRIM(CLCL1.CODIGOCLIENTE) = TRIM(${TABLA_BASE}.CODIGOCLIENTE)\n`;

// CLIX
sql += `LEFT JOIN DSEDAC.CLIX CLIX\n`;
sql += `  ON TRIM(CLIX.CODIGOCLIENTE) = TRIM(${TABLA_BASE}.CODIGOCLIENTE)\n`;

// CRUT
sql += `LEFT JOIN DSEDAC.CRUT CRUT\n`;
sql += `  ON TRIM(CRUT.CODIGOCLIENTE) = TRIM(${TABLA_BASE}.CODIGOCLIENTE)\n`;
sql += `  AND CRUT.SECUENCIA = 1\n`;

// VDDL1 (vía CRUT)
sql += `LEFT JOIN DSEDAC.VDDL1 VDDL1\n`;
sql += `  ON TRIM(VDDL1.CODIGOVENDEDOR) = TRIM(CRUT.CODIGOVENDEDOR);\n`;

// Guardar
const outputPath = path.resolve(__dirname, 'sql', 'vista_clientes_unificada.sql');
fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, sql);

// Contar columnas totales
const totalCols = (sql.match(/, --/g) || []).length + 1;
console.log(`✅ Vista generada: ${outputPath}`);
console.log(`   Tablas: ${['CLIL1', 'CLCL1', 'CLIX', 'CRUT', 'VDDL1'].join(', ')}`);
console.log(`   JOIN: CLIL1 → CLCL1(CODIGOCLIENTE) → CLIX(CODIGOCLIENTE) → CRUT(CODIGOCLIENTE, SECUENCIA=1) → VDDL1(CODIGOVENDEDOR)`);
console.log(`   Columnas totales: ~${totalCols}`);
console.log(`   Colisiones resueltas con prefijos: CLCL1_, CLIX_, RUT_, VDD_`);

// También guardar el análisis de mapeo
const mappingReport = {
  vista: 'JAVIER.VISTA_CLIENTES_UNIFICADA',
  tablas: {
    CLIL1: { alias: 'CLIL1', columnas: baseColumns.length, rol: 'BASE (cliente maestro)' },
    CLCL1: { alias: 'CLCL1', columnas: clcl1Cols.length, join: 'CODIGOCLIENTE', rol: 'Condiciones crédito' },
    CLIX: { alias: 'CLIX', columnas: clixCols.length, join: 'CODIGOCLIENTE', rol: 'Extensión cliente' },
    CRUT: { alias: 'CRUT', columnas: crutCols.length, join: 'CODIGOCLIENTE', filtro: 'SECUENCIA = 1', rol: 'Datos ruta' },
    VDDL1: { alias: 'VDDL1', columnas: vddl1Cols.length, join: 'CODIGOVENDEDOR (vía CRUT)', rol: 'Vendedor' },
  },
  colisiones_resueltas: [],
  columnas_omitidas: OMITIR,
  sql_file: outputPath,
};

fs.writeFileSync(
  path.resolve(__dirname, 'results', 'vista-unificada-mapping.json'),
  JSON.stringify(mappingReport, null, 2)
);

console.log(`\n📋 Mapping report: backend/scripts/results/vista-unificada-mapping.json`);

'use strict';

/**
 * Importador controlado para overlay de precios de bolsa en JAVIER.
 *
 * Por defecto no escribe nada. Para aplicar:
 *   CONFIRM_BOLSA_PRICING_IMPORT=YES node backend/scripts/import-bolsa-pricing-from-erp.js --apply
 *
 * Fuentes:
 * - DSEDAC.ARA tarifa 2: minimo base actual.
 * - DSEDAC.LAC ultimo PRECIOCOSTO: coste de fabricacion/compra observado.
 *
 * Los precios especiales/promociones de cliente NO se importan aqui:
 * se leen en runtime desde tablas ERP DSEDAC.PES/PPU.
 */

const { initDb, queryWithParams, closePool } = require('../config/db');

const APPLY = process.argv.includes('--apply');
const LIMIT_ARG = process.argv.find(arg => arg.startsWith('--limit='));
const LIMIT = Math.max(1, Math.min(10000, Number.parseInt(LIMIT_ARG?.split('=')[1] || '1000', 10) || 1000));
const DEFAULT_MARGIN = Number.parseFloat(process.env.BOLSA_DEFAULT_MARGIN_PCT || '20') || 20;
const CONFIRMED = process.env.CONFIRM_BOLSA_PRICING_IMPORT === 'YES';

function usageGuard() {
  if (APPLY && !CONFIRMED) {
    throw new Error('DML bloqueado: usa CONFIRM_BOLSA_PRICING_IMPORT=YES junto con --apply');
  }
}

function round4(value) {
  const number = Number.parseFloat(value);
  if (!Number.isFinite(number)) return 0;
  return Math.round(number * 10000) / 10000;
}

async function loadProductPricingCandidates() {
  const sql = `
    SELECT
      TRIM(A.CODIGOARTICULO) AS CODIGOARTICULO,
      COALESCE(T2.PRECIOTARIFA, 0) AS PRECIO_MINIMO,
      COALESCE(LC.PRECIOCOSTO, 0) AS COSTE_FABRICACION
    FROM DSEDAC.ART A
    LEFT JOIN DSEDAC.ARA T2
      ON A.CODIGOARTICULO = T2.CODIGOARTICULO
     AND T2.CODIGOTARIFA = 2
    LEFT JOIN (
      SELECT TRIM(CODIGOARTICULO) AS CODIGOARTICULO,
             PRECIOCOSTO,
             ROW_NUMBER() OVER (
               PARTITION BY TRIM(CODIGOARTICULO)
               ORDER BY ANODOCUMENTO DESC, MESDOCUMENTO DESC, DIADOCUMENTO DESC
             ) AS RN
      FROM DSEDAC.LAC
      WHERE PRECIOCOSTO > 0
    ) LC ON TRIM(A.CODIGOARTICULO) = LC.CODIGOARTICULO AND LC.RN = 1
    WHERE COALESCE(A.ANOBAJA, 0) = 0
      AND (COALESCE(T2.PRECIOTARIFA, 0) > 0 OR COALESCE(LC.PRECIOCOSTO, 0) > 0)
    ORDER BY A.CODIGOARTICULO
    FETCH FIRST ${LIMIT} ROWS ONLY`;

  return queryWithParams(sql, [], false);
}

async function countImportedToday() {
  const rows = await queryWithParams(
    `SELECT COUNT(*) AS TOTAL
       FROM JAVIER.BOLSA_PRODUCTO_PRECIO
      WHERE FECHA_DESDE = CURRENT DATE
        AND SOURCE = 'ERP_IMPORT'`,
    [],
    false,
    false
  );
  return Number.parseInt(rows?.[0]?.TOTAL ?? rows?.[0]?.total ?? '0', 10) || 0;
}

async function syncIdentityNextValue() {
  const rows = await queryWithParams(
    `SELECT COALESCE(MAX(ID), 0) + 1 AS NEXT_ID
       FROM JAVIER.BOLSA_PRODUCTO_PRECIO`,
    [],
    false,
    true
  );
  const nextId = Math.max(1, Number.parseInt(rows?.[0]?.NEXT_ID ?? rows?.[0]?.next_id ?? '1', 10) || 1);
  await queryWithParams(
    `ALTER TABLE JAVIER.BOLSA_PRODUCTO_PRECIO ALTER COLUMN ID RESTART WITH ${nextId}`,
    [],
    false,
    true
  );
  return nextId;
}

async function upsertProductPricing() {
  const margin = round4(DEFAULT_MARGIN);
