                        width: tableWidth - 20,
                        align: 'left',
                    });
                doc.font('Helvetica').fontSize(8).fillColor(COLORS.muted)
                    .text('El informe se ha generado correctamente, pero no hay vendedores con datos para ese filtro.', margin + 10, yPos + 30, {
                        width: tableWidth - 20,
                        align: 'left',
                    });
                yPos += 68;
            }

            vendors.forEach(vendor => {
                const monthsInRange = endMonth - startMonth + 1;
                const estimatedHeight = 18 * 3 + 15 * monthsInRange + 18;
                if (!firstVendor && yPos + estimatedHeight > pageHeight - margin - 20) {
                    doc.addPage();
                    yPos = drawPageHeader(margin);
                }
                firstVendor = false;

                const drawn = drawSummaryPdfTable({
                    doc,
                    vendor,
                    condorDataMap,
                    startMonth,
                    endMonth,
                    margin,
                    tableWidth,
                    cols,
                    yPos,
                });
                yPos = drawn.yPos;
                Object.keys(globalTotals).forEach(key => {
