    };

    try {
        const maxRetries = 3;
        for (let attempt = 1; attempt <= maxRetries; attempt++) {
            try {
                if (!transporter) initEmailService();
                const info = await transporter.sendMail(mailOptions);
                logger.info('✅ Planner email enviado', { vendorName, messageId: info.messageId });
