}

function buildAlbaranClientSearchFilter(value) {
    return buildClientSearchFilter(value, 'CAC.CODIGOCLIENTEALBARAN');
}

function buildAlbaranDocSearchFilter(value) {
    return buildDocSearchFilter(value, 'CAC.NUMEROALBARAN', 'CAC.SERIEALBARAN', 'CAC.CODIGOCLIENTEALBARAN');
}

function buildAlbaranSearchFilter(value) {
    return buildSearchFilter(value, 'CAC.NUMEROALBARAN', 'CAC.SERIEALBARAN', 'CAC.CODIGOCLIENTEALBARAN');
}

async function mapWithConcurrency(items, concurrency, mapper) {
    const results = new Array(items.length);
    let next = 0;
    const workers = Array.from({ length: Math.min(concurrency, items.length) }, async () => {
        while (next < items.length) {
            const index = next++;
            results[index] = await mapper(items[index], index);
        }
    });
    await Promise.all(workers);
    return results;
}

function buildTaxBases(header) {
    return TAX_SLOTS.map(slot => ({
        base: parseFloat(header[`IMPORTEBASEIMPONIBLE${slot}`]) || 0,
        pct: parseFloat(header[`PORCENTAJEIVA${slot}`]) || 0,
        iva: parseFloat(header[`IMPORTEIVA${slot}`]) || 0
    })).filter(b => b.base !== 0 || b.iva !== 0);
}

function normalizeSerieForLookup(value) {
    const serie = String(value || '')
        .trim()
        .replace(/[^A-Z0-9]/gi, '')
        .toUpperCase()
        .slice(0, 3);
    return serie;
}

function parseDocumentNumber(value) {
    const parsed = parseInt(value, 10);
    if (!Number.isFinite(parsed) || parsed <= 0 || parsed >= 900000) {
        return null;
    }
    return parsed;
}

function buildDocumentDetailCacheKey(type, serie, numero, ejercicio, terminal = null) {
    const cleanSerie = normalizeSerieForLookup(serie);
    const cleanNumero = parseDocumentNumber(numero);
    const cleanEjercicio = parseInt(ejercicio, 10);
    const cleanTerminal = terminal === null || terminal === undefined || terminal === ''
        ? null
        : parseInt(terminal, 10);
    if (!cleanSerie || !cleanNumero || !Number.isFinite(cleanEjercicio) || cleanEjercicio <= 0
        || (terminal !== null && terminal !== undefined && terminal !== ''
            && (!Number.isFinite(cleanTerminal) || cleanTerminal < 0))) {
        return null;
    }
    const terminalKey = cleanTerminal === null ? 'ALL' : String(cleanTerminal);
    return 'facturas:document:' + DOCUMENT_DETAIL_CACHE_VERSION + ':' + type + ':' + cleanEjercicio + ':' + cleanSerie + ':' + terminalKey + ':' + cleanNumero;
}

function buildIvaBreakdown(header) {
    const breakdown = {};
    for (const slot of TAX_SLOTS) {
        breakdown[`BI${slot}`] = parseFloat(header[`IMPORTEBASEIMPONIBLE${slot}`]) || 0;
        breakdown[`IVA${slot}_PCT`] = parseFloat(header[`PORCENTAJEIVA${slot}`]) || 0;
        breakdown[`IVA${slot}_IMP`] = parseFloat(header[`IMPORTEIVA${slot}`]) || 0;
    }
    breakdown.IMPORTETOTAL = parseFloat(header.IMPORTETOTAL) || 0;
    return breakdown;
}

async function batchedVendorQuery(baseSql, vendorColumn, vendors, queryFn) {
    if (!vendors || vendors.length === 0) {
        return [];
    }

    const batches = [];
    for (let i = 0; i < vendors.length; i += BATCH_SIZE) {
        batches.push(vendors.slice(i, i + BATCH_SIZE));
    }

    const results = [];
    for (const batch of batches) {
        const placeholders = batch.map(() => '?').join(',');
        const sql = baseSql.replace('@VENDOR_IN@', `TRIM(${vendorColumn}) IN (${placeholders})`);
        const rows = await queryFn(sql, batch);
        results.push(...rows);
    }
    return results;
}

class FacturasService {

    async getFacturas(params) {
        const cacheKey = `facturas:list:${FACTURA_CACHE_VERSION}:${JSON.stringify(params)}`;
        
        // Try Redis cache first (30s TTL for list — data changes slightly during day)
        const cached = await redisCache.get('route', cacheKey);
        if (cached !== null) return cached;

        return withInFlight(facturasListInFlight, cacheKey, async () => {
            const secondCache = await redisCache.get('route', cacheKey);
            if (secondCache !== null) return secondCache;

            const result = await facturasBreaker.execute(
                () => this.getFacturasRaw(params),
                async () => {
                    const stale = await redisCache.get('route', cacheKey);
                    if (stale !== null) return stale;
                    throw new Error('Facturas DB no disponible dentro del timeout seguro');
                }
            );

            if (result) {
                await redisCache.set('route', cacheKey, result, TTL.SHORT);
                return result;
            }

            throw new Error('Facturas DB no devolvio datos');
        });
    }
    
    async _getFacturasRawLegacy(params) {
        const { vendedorCodes, year, month, search, clientId, clientSearch, docSearch, dateFrom, dateTo } = params;
        const documentType = normalizeDocumentType(params.documentType || params.tipoDocumento);
        const rowsLimit = clampPositiveInt(params.limit, DEFAULT_LIST_LIMIT, MAX_LIST_LIMIT);
        const rowsOffset = clampOffset(params.offset);

        if (!vendedorCodes) {
            throw new Error('vendedorCodes is required');
        }

        const isAll = vendedorCodes.trim().toUpperCase() === 'ALL';
        const vendors = isAll ? [] : vendedorCodes.split(',').map(v => v.trim()).filter(v => v && v !== 'UNK' && /^[A-Z0-9]+$/.test(v));

        const currentYear = year || new Date().getFullYear();
        const dateFilterApplied = dateFrom && dateTo;
        const dateFromInt = dateFilterApplied ? parseInt(dateFrom.replace(/-/g, '')) : null;
        const dateToInt = dateFilterApplied ? parseInt(dateTo.replace(/-/g, '')) : null;
        const ownershipYear = resolveOwnershipYear({ year: currentYear, dateFromInt, dateFilterApplied });

        function buildSqlForVendors(vendorBatch, offsetValue = rowsOffset, limitValue = rowsLimit) {
            let sql = `
      SELECT
        TRIM(CFC.SERIEFACTURA) as SERIE,
        CFC.NUMEROFACTURA as NUMERO,
        CFC.EJERCICIOFACTURA as EJERCICIO,
        CFC.ANODOCUMENTO as ANO,
        CFC.MESDOCUMENTO as MES,
        CFC.DIADOCUMENTO as DIA,
        TRIM(CFC.CODIGOCLIENTE) as CODIGO_CLIENTE,
        TRIM(COALESCE(CLI.NOMBREALTERNATIVO, CLI.NOMBRECLIENTE, '')) as NOMBRE_CLIENTE,
        TRIM(CLI.NOMBREALTERNATIVO) as NOMBRE_COMERCIAL,
        TRIM(CLI.NOMBRECLIENTE) as NOMBRE_FISCAL,
        CFC.IMPORTETOTAL as TOTAL,
        CFC.IMPORTEBASEIMPONIBLE as BASE,
        CFC.IMPORTEIVA as IVA
      FROM DSEDAC.CFC CFC
      LEFT JOIN DSEDAC.CLI CLI ON CLI.CODIGOCLIENTE = CFC.CODIGOCLIENTE
      WHERE CFC.NUMEROFACTURA > 0 AND CFC.NUMEROFACTURA < 900000
    `;
            const queryParams = [];

            if (vendorBatch.length > 0) {
                sql = appendCfcVendorScopeFilter(sql, queryParams, vendorBatch, ownershipYear);
            }

            if (dateFilterApplied && dateFromInt && dateToInt) {
                sql += ` AND (CFC.ANODOCUMENTO * 10000 + CFC.MESDOCUMENTO * 100 + CFC.DIADOCUMENTO) BETWEEN ? AND ?`;
                queryParams.push(dateFromInt, dateToInt);
            } else {
                sql += ` AND CFC.EJERCICIOFACTURA = ?`;
                queryParams.push(currentYear);
                if (month) {
                    sql += ` AND CFC.MESDOCUMENTO = ?`;
                    queryParams.push(month);
                }
            }

            if (clientId) {
                sql += ` AND TRIM(CFC.CODIGOCLIENTE) = ?`;
                queryParams.push(clientId.trim());
            }

            const clientFilter = buildInvoiceClientSearchFilter(clientSearch);
            sql += ` ${clientFilter.clause}`;
            queryParams.push(...clientFilter.params);

            const docFilter = buildInvoiceDocSearchFilter(docSearch);
            sql += ` ${docFilter.clause}`;
            queryParams.push(...docFilter.params);

            const genericFilter = buildInvoiceSearchFilter(search);
            sql += ` ${genericFilter.clause}`;
            queryParams.push(...genericFilter.params);

            sql += ` ORDER BY CFC.ANODOCUMENTO DESC, CFC.MESDOCUMENTO DESC, CFC.DIADOCUMENTO DESC, CFC.NUMEROFACTURA DESC
                     OFFSET ? ROWS FETCH NEXT ? ROWS ONLY`;
            queryParams.push(offsetValue, limitValue);
            return { sql, queryParams };
        }

        try {
            let rows;
            if (isAll || vendors.length === 0) {
                const { sql, queryParams } = buildSqlForVendors([]);
                rows = await queryWithParams(sql, queryParams);
            } else if (vendors.length <= BATCH_SIZE) {
                const { sql, queryParams } = buildSqlForVendors(vendors);
                rows = await queryWithParams(sql, queryParams);
            } else {
                const batches = [];
                for (let i = 0; i < vendors.length; i += BATCH_SIZE) {
                    batches.push(vendors.slice(i, i + BATCH_SIZE));
                }
                const batchLimit = rowsOffset + rowsLimit;
                const batchResults = await mapWithConcurrency(
                    batches,
                    2,
                    async (batch) => {
                        const { sql, queryParams } = buildSqlForVendors(batch, 0, batchLimit);
                        return queryWithParams(sql, queryParams);
                    }
                );
                rows = batchResults.flat().sort(sortInvoiceRowsDesc).slice(rowsOffset, rowsOffset + rowsLimit);
            }

            const invoiceMap = new Map();
            for (const row of rows) {
                const key = `${row.SERIE}-${row.NUMERO}-${row.EJERCICIO}`;
                const sanitize = (v) => {
                    const n = parseFloat(v) || 0;
                    if (Object.is(n, -0)) return 0;
                    if (Math.abs(n) >= 900000) return 0;
                    return n;
                };

                if (!invoiceMap.has(key)) {
                    invoiceMap.set(key, {
                        id: key,
                        serie: row.SERIE,
                        numero: row.NUMERO,
                        ejercicio: row.EJERCICIO,
                        fecha: `${String(row.DIA).padStart(2, '0')}/${String(row.MES).padStart(2, '0')}/${row.ANO}`,
                        clienteId: row.CODIGO_CLIENTE,
                        clienteNombre: row.NOMBRE_CLIENTE || `Cliente ${row.CODIGO_CLIENTE}`,
                        nombreComercial: row.NOMBRE_COMERCIAL || row.NOMBRE_CLIENTE || `Cliente ${row.CODIGO_CLIENTE}`,
                        nombreFiscal: row.NOMBRE_FISCAL || `Cliente ${row.CODIGO_CLIENTE}`,
                        total: sanitize(row.TOTAL),
                        base: sanitize(row.BASE),
                        iva: sanitize(row.IVA)
                    });
                } else {
                    // Same invoice, different albarán → accumulate amounts
                    const existing = invoiceMap.get(key);
                    existing.total += sanitize(row.TOTAL);
                    existing.base += sanitize(row.BASE);
                    existing.iva += sanitize(row.IVA);
                }
            }

            return Array.from(invoiceMap.values());
        } catch (error) {
            if (error.message.includes('CWB0111') || error.message.includes('22001') || error.message.includes('parameter')) {
                logger.warn(`[facturas] Query failed (expected with many vendors), returning empty: ${error.message.substring(0, 80)}`);
            } else {
                logger.error(`Error fetching facturas: ${error.message}`);
            }
            return [];
        }
    }

    async getFacturasRaw(params) {
        const { vendedorCodes, year, month, search, clientId, clientSearch, docSearch, dateFrom, dateTo } = params;
        const rowsLimit = clampPositiveInt(params.limit, DEFAULT_LIST_LIMIT, MAX_LIST_LIMIT);
        const rowsOffset = clampOffset(params.offset);
        const documentType = normalizeDocumentType(params.documentType || params.tipoDocumento);
        const includeFacturas = documentType !== 'albaran';
        const includeAlbaranes = documentType !== 'factura';

        if (!vendedorCodes) {
            throw new Error('vendedorCodes is required');
        }

        const isAll = vendedorCodes.trim().toUpperCase() === 'ALL';
        const vendors = isAll ? [] : vendedorCodes.split(',').map(v => v.trim()).filter(v => v && v !== 'UNK' && /^[A-Z0-9]+$/.test(v));

        const currentYear = year || new Date().getFullYear();
        const dateFilterApplied = dateFrom && dateTo;
        const dateFromInt = dateFilterApplied ? parseInt(dateFrom.replace(/-/g, '')) : null;
        const dateToInt = dateFilterApplied ? parseInt(dateTo.replace(/-/g, '')) : null;
        const ownershipYear = resolveOwnershipYear({ year: currentYear, dateFromInt, dateFilterApplied });

        function applyCommonFilters(sql, queryParams, {
            vendorBatch,
            vendorColumn,
            dateExpr,
            yearColumn,
            monthColumn,
            clientColumn,
            clientFilterBuilder,
            docFilterBuilder,
            genericFilterBuilder,
            includeOwnedEmptyVendor = false,
        }) {
            if (vendorBatch.length > 0) {
                if (includeOwnedEmptyVendor) {
                    sql = appendCfcVendorScopeFilter(sql, queryParams, vendorBatch, ownershipYear);
                } else {
                    const placeholders = vendorBatch.map(() => '?').join(',');
                    sql += ` AND TRIM(${vendorColumn}) IN (${placeholders})`;
                    queryParams.push(...vendorBatch);
                }
            }

            if (dateFilterApplied && dateFromInt && dateToInt) {
                sql += ` AND ${dateExpr} BETWEEN ? AND ?`;
                queryParams.push(dateFromInt, dateToInt);
            } else {
                sql += ` AND ${yearColumn} = ?`;
                queryParams.push(currentYear);
                if (month) {
                    sql += ` AND ${monthColumn} = ?`;
                    queryParams.push(month);
                }
            }

            if (clientId) {
                sql += ` AND TRIM(${clientColumn}) = ?`;
                queryParams.push(clientId.trim());
            }

            const clientFilter = clientFilterBuilder(clientSearch);
            sql += ` ${clientFilter.clause}`;
            queryParams.push(...clientFilter.params);

            const docFilter = docFilterBuilder(docSearch);
            sql += ` ${docFilter.clause}`;
            queryParams.push(...docFilter.params);

            const genericFilter = genericFilterBuilder(search);
            sql += ` ${genericFilter.clause}`;
            queryParams.push(...genericFilter.params);

            return sql;
        }

        function buildInvoiceSqlForVendors(vendorBatch, offsetValue, limitValue) {
            const queryParams = [];
            let sql = `
      SELECT
        'factura' as DOCUMENT_TYPE,
        TRIM(CFC.SERIEFACTURA) as SERIE,
        CFC.NUMEROFACTURA as NUMERO,
        CFC.EJERCICIOFACTURA as EJERCICIO,
        CAST(NULL AS INTEGER) as TERMINAL,
        CFC.ANODOCUMENTO as ANO,
        CFC.MESDOCUMENTO as MES,
        CFC.DIADOCUMENTO as DIA,
        TRIM(CFC.CODIGOCLIENTE) as CODIGO_CLIENTE,
        TRIM(COALESCE(CLI.NOMBREALTERNATIVO, CLI.NOMBRECLIENTE, '')) as NOMBRE_CLIENTE,
        TRIM(CLI.NOMBREALTERNATIVO) as NOMBRE_COMERCIAL,
        TRIM(CLI.NOMBRECLIENTE) as NOMBRE_FISCAL,
        CFC.IMPORTETOTAL as TOTAL,
        CFC.IMPORTEBASEIMPONIBLE as BASE,
        CFC.IMPORTEIVA as IVA
      FROM DSEDAC.CFC CFC
      LEFT JOIN DSEDAC.CLI CLI ON CLI.CODIGOCLIENTE = CFC.CODIGOCLIENTE
      WHERE CFC.NUMEROFACTURA > 0 AND CFC.NUMEROFACTURA < 900000
    `;
            sql = applyCommonFilters(sql, queryParams, {
                vendorBatch,
                vendorColumn: 'CFC.CODIGOVENDEDOR',
                dateExpr: '(CFC.ANODOCUMENTO * 10000 + CFC.MESDOCUMENTO * 100 + CFC.DIADOCUMENTO)',
                yearColumn: 'CFC.EJERCICIOFACTURA',
                monthColumn: 'CFC.MESDOCUMENTO',
                clientColumn: 'CFC.CODIGOCLIENTE',
                clientFilterBuilder: buildInvoiceClientSearchFilter,
                docFilterBuilder: buildInvoiceDocSearchFilter,
                genericFilterBuilder: buildInvoiceSearchFilter,
                includeOwnedEmptyVendor: true,
            });
            sql += ` ORDER BY CFC.ANODOCUMENTO DESC, CFC.MESDOCUMENTO DESC, CFC.DIADOCUMENTO DESC, CFC.NUMEROFACTURA DESC
                     OFFSET ? ROWS FETCH NEXT ? ROWS ONLY`;
            queryParams.push(offsetValue, limitValue);
            return { sql, queryParams };
        }

        function buildAlbaranSqlForVendors(vendorBatch, offsetValue, limitValue) {
            const queryParams = [];
            let sql = `
      SELECT
        'albaran' as DOCUMENT_TYPE,
        TRIM(CAC.SERIEALBARAN) as SERIE,
        CAC.NUMEROALBARAN as NUMERO,
        CAC.EJERCICIOALBARAN as EJERCICIO,
        CAC.TERMINALALBARAN as TERMINAL,
        CAC.ANODOCUMENTO as ANO,
        CAC.MESDOCUMENTO as MES,
        CAC.DIADOCUMENTO as DIA,
        TRIM(CAC.CODIGOCLIENTEALBARAN) as CODIGO_CLIENTE,
        TRIM(COALESCE(CLI.NOMBREALTERNATIVO, CLI.NOMBRECLIENTE, '')) as NOMBRE_CLIENTE,
        TRIM(CLI.NOMBREALTERNATIVO) as NOMBRE_COMERCIAL,
        TRIM(CLI.NOMBRECLIENTE) as NOMBRE_FISCAL,
        CAC.IMPORTETOTAL as TOTAL,
        COALESCE(CAC.IMPORTEBRUTO, 0) as BASE,
        COALESCE(CAC.IMPORTEIVA1, 0) + COALESCE(CAC.IMPORTEIVA2, 0) + COALESCE(CAC.IMPORTEIVA3, 0) + COALESCE(CAC.IMPORTEIVA4, 0) + COALESCE(CAC.IMPORTEIVA5, 0) as IVA
      FROM DSEDAC.CAC CAC
      LEFT JOIN DSEDAC.CLI CLI ON TRIM(CLI.CODIGOCLIENTE) = TRIM(CAC.CODIGOCLIENTEALBARAN)
      WHERE CAC.NUMEROALBARAN > 0 AND CAC.NUMEROALBARAN < 900000
        AND NOT (CAC.NUMEROFACTURA > 0 AND CAC.NUMEROFACTURA < 900000)
    `;
            sql = applyCommonFilters(sql, queryParams, {
                vendorBatch,
                vendorColumn: 'CAC.CODIGOVENDEDOR',
                dateExpr: '(CAC.ANODOCUMENTO * 10000 + CAC.MESDOCUMENTO * 100 + CAC.DIADOCUMENTO)',
                yearColumn: 'CAC.EJERCICIOALBARAN',
                monthColumn: 'CAC.MESDOCUMENTO',
                clientColumn: 'CAC.CODIGOCLIENTEALBARAN',
                clientFilterBuilder: buildAlbaranClientSearchFilter,
                docFilterBuilder: buildAlbaranDocSearchFilter,
                genericFilterBuilder: buildAlbaranSearchFilter,
            });
            sql += ` ORDER BY CAC.ANODOCUMENTO DESC, CAC.MESDOCUMENTO DESC, CAC.DIADOCUMENTO DESC, CAC.NUMEROALBARAN DESC
                     OFFSET ? ROWS FETCH NEXT ? ROWS ONLY`;
            queryParams.push(offsetValue, limitValue);
            return { sql, queryParams };
        }

        async function queryDocumentsForVendors(vendorBatch, offsetValue, limitValue) {
            const queries = [];
            if (includeFacturas) {
                const { sql, queryParams } = buildInvoiceSqlForVendors(vendorBatch, offsetValue, limitValue);
                queries.push(() => queryWithParams(sql, queryParams));
            }
            if (includeAlbaranes) {
                const { sql, queryParams } = buildAlbaranSqlForVendors(vendorBatch, offsetValue, limitValue);
                queries.push(() => queryWithParams(sql, queryParams));
            }
            const results = [];
            for (const runQuery of queries) {
                results.push(await runQuery());
            }
            return results.flat();
        }

        try {
            const mergePagination = documentType === 'all' || (!isAll && vendors.length > BATCH_SIZE);
            const perQueryOffset = mergePagination ? 0 : rowsOffset;
            const perQueryLimit = mergePagination ? rowsOffset + rowsLimit : rowsLimit;

            let rows;
            if (isAll || vendors.length === 0) {
                rows = await queryDocumentsForVendors([], perQueryOffset, perQueryLimit);
            } else if (vendors.length <= BATCH_SIZE) {
                rows = await queryDocumentsForVendors(vendors, perQueryOffset, perQueryLimit);
            } else {
                const batches = [];
                for (let i = 0; i < vendors.length; i += BATCH_SIZE) {
                    batches.push(vendors.slice(i, i + BATCH_SIZE));
                }
                const batchResults = await mapWithConcurrency(
                    batches,
                    FACTURAS_LIST_BATCH_CONCURRENCY,
                    (batch) => queryDocumentsForVendors(batch, 0, rowsOffset + rowsLimit)
                );
                rows = batchResults.flat();
            }

            rows = rows.sort(sortInvoiceRowsDesc);
            if (mergePagination) {
                rows = rows.slice(rowsOffset, rowsOffset + rowsLimit);
            }

            const documentMap = new Map();
            for (const row of rows) {
                const sanitize = (v) => {
                    const n = parseFloat(v) || 0;
                    if (Object.is(n, -0)) return 0;
                    if (Math.abs(n) >= 900000) return 0;
                    return n;
                };
                const rowType = String(row.DOCUMENT_TYPE || row.document_type || 'factura').trim().toLowerCase() === 'albaran'
                    ? 'albaran'
                    : 'factura';
                const terminal = row.TERMINAL === null || row.TERMINAL === undefined ? null : parseInt(row.TERMINAL, 10);
                const key = rowType === 'albaran'
                    ? `ALB-${row.EJERCICIO}-${row.SERIE}-${terminal || 0}-${row.NUMERO}`
                    : `${row.SERIE}-${row.NUMERO}-${row.EJERCICIO}`;

                if (!documentMap.has(key)) {
                    documentMap.set(key, {
                        id: key,
                        documentType: rowType,
                        tipoDocumento: rowType,
                        serie: row.SERIE,
                        numero: row.NUMERO,
                        ejercicio: row.EJERCICIO,
                        terminal,
                        fecha: `${String(row.DIA).padStart(2, '0')}/${String(row.MES).padStart(2, '0')}/${row.ANO}`,
                        clienteId: row.CODIGO_CLIENTE,
                        clienteNombre: row.NOMBRE_CLIENTE || `Cliente ${row.CODIGO_CLIENTE}`,
                        nombreComercial: row.NOMBRE_COMERCIAL || row.NOMBRE_CLIENTE || `Cliente ${row.CODIGO_CLIENTE}`,
                        nombreFiscal: row.NOMBRE_FISCAL || `Cliente ${row.CODIGO_CLIENTE}`,
                        total: sanitize(row.TOTAL),
                        base: sanitize(row.BASE),
                        iva: sanitize(row.IVA)
                    });
                } else {
                    const existing = documentMap.get(key);
                    existing.total += sanitize(row.TOTAL);
                    existing.base += sanitize(row.BASE);
                    existing.iva += sanitize(row.IVA);
                }
            }

            return Array.from(documentMap.values());
        } catch (error) {
            if (error.message.includes('CWB0111') || error.message.includes('22001') || error.message.includes('parameter')) {
                logger.warn(`[facturas] Query failed (expected with many vendors), returning empty: ${error.message.substring(0, 80)}`);
            } else {
                logger.error(`Error fetching facturas: ${error.message}`);
            }
            return [];
        }
    }

    async _getAvailableYearsLegacy(vendedorCodes) {
        if (!vendedorCodes) {
            throw new Error('vendedorCodes is required');
        }

        const isAll = vendedorCodes.trim().toUpperCase() === 'ALL';
        
        if (isAll) {
            const sql = `
      SELECT DISTINCT EJERCICIOFACTURA as YEAR
      FROM DSEDAC.CFC
      WHERE NUMEROFACTURA > 0 AND NUMEROFACTURA < 900000
      ORDER BY YEAR DESC
    `;
            try {
                const rows = await query(sql);
                return rows.map(r => r.YEAR);
            } catch (error) {
                logger.error(`Error fetching available years: ${error.message}`);
                throw error;
            }
        }

        const vendors = vendedorCodes.split(',').map(v => v.trim()).filter(v => v && v !== 'UNK' && /^[A-Z0-9]+$/.test(v));

        const baseSql = `
      SELECT DISTINCT EJERCICIOFACTURA as YEAR
      FROM DSEDAC.CFC
      WHERE NUMEROFACTURA > 0 AND NUMEROFACTURA < 900000
        AND @VENDOR_IN@
      ORDER BY YEAR DESC
    `;

        try {
            const rows = await batchedVendorQuery(baseSql, 'CODIGOVENDEDOR', vendors, queryWithParams);
            const years = [...new Set(rows.map(r => r.YEAR))].sort((a, b) => b - a);
            return years;
        } catch (error) {
            if (error.message.includes('CWB0111') || error.message.includes('22001') || error.message.includes('parameter')) {
                logger.warn(`[facturas] Vendor batch query failed (expected with many vendors), returning empty: ${error.message.substring(0, 80)}`);
            } else {
                logger.error(`Error fetching available years: ${error.message}`);
            }
            return [];
        }
    }

    async getAvailableYears(vendedorCodes) {
        if (!vendedorCodes) {
            throw new Error('vendedorCodes is required');
        }

        const invoiceYearsSql = `
      SELECT DISTINCT EJERCICIOFACTURA as YEAR
      FROM DSEDAC.CFC
      WHERE NUMEROFACTURA > 0 AND NUMEROFACTURA < 900000
        AND @VENDOR_IN@
    `;
        const albaranYearsSql = `
      SELECT DISTINCT CAC.EJERCICIOALBARAN as YEAR
      FROM DSEDAC.CAC CAC
      WHERE CAC.NUMEROALBARAN > 0 AND CAC.NUMEROALBARAN < 900000
        AND @VENDOR_IN@
        AND NOT (CAC.NUMEROFACTURA > 0 AND CAC.NUMEROFACTURA < 900000)
    `;

        try {
            const isAll = vendedorCodes.trim().toUpperCase() === 'ALL';
            let rows;
            if (isAll) {
                const [invoiceRows, albaranRows] = await Promise.all([
                    query(invoiceYearsSql.replace('AND @VENDOR_IN@', '')),
                    query(albaranYearsSql.replace('AND @VENDOR_IN@', '')),
                ]);
                rows = [...invoiceRows, ...albaranRows];
            } else {
                const vendors = vendedorCodes.split(',').map(v => v.trim()).filter(v => v && v !== 'UNK' && /^[A-Z0-9]+$/.test(v));
                const [invoiceRows, albaranRows] = await Promise.all([
                    batchedVendorQuery(invoiceYearsSql, 'CODIGOVENDEDOR', vendors, queryWithParams),
                    batchedVendorQuery(albaranYearsSql, 'CAC.CODIGOVENDEDOR', vendors, queryWithParams),
                ]);
                rows = [...invoiceRows, ...albaranRows];
            }

            return [...new Set(rows.map(r => r.YEAR).filter(Boolean))].sort((a, b) => b - a);
        } catch (error) {
            if (error.message.includes('CWB0111') || error.message.includes('22001') || error.message.includes('parameter')) {
                logger.warn(`[facturas] Years query failed (expected with many vendors), returning empty: ${error.message.substring(0, 80)}`);
            } else {
                logger.error(`Error fetching available years: ${error.message}`);
            }
            return [];
        }
    }

    async getSummary(params) {
        const { vendedorCodes, year, month, search, clientId, clientSearch, docSearch, dateFrom, dateTo } = params;
        const documentType = normalizeDocumentType(params.documentType || params.tipoDocumento);

        if (!vendedorCodes) {
            throw new Error('vendedorCodes is required');
        }

        const cacheKey = `facturas:summary:${FACTURA_CACHE_VERSION}:${vendedorCodes || 'ALL'}:${year || ''}:${month || ''}:${dateFrom || ''}:${dateTo || ''}:${documentType}:${normalizeSearchValue(search)}:${normalizeSearchValue(clientId)}:${normalizeSearchValue(clientSearch)}:${normalizeSearchValue(docSearch)}`;
        const cached = await redisCache.get('route', cacheKey);
        if (cached !== null) return cached;

        return withInFlight(facturasSummaryInFlight, cacheKey, async () => {
            const secondCache = await redisCache.get('route', cacheKey);
            if (secondCache !== null) return secondCache;

            const result = await this._getSummaryInternal(params);
            await redisCache.set('route', cacheKey, result, TTL.MEDIUM);
            return result;
        });
    }

    async _getSummaryInternalLegacy(params) {
        const { vendedorCodes, year, month, search, clientId, clientSearch, docSearch, dateFrom, dateTo } = params;

        if (!vendedorCodes) {
            throw new Error('vendedorCodes is required');
        }

        const isAll = vendedorCodes.trim().toUpperCase() === 'ALL';
        const vendors = isAll ? [] : vendedorCodes.split(',').map(v => v.trim()).filter(v => v && v !== 'UNK' && /^[A-Z0-9]+$/.test(v));

        const dateFilterApplied = dateFrom && dateTo;
        const dateFromInt = dateFilterApplied ? parseInt(dateFrom.replace(/-/g, '')) : null;
        const dateToInt = dateFilterApplied ? parseInt(dateTo.replace(/-/g, '')) : null;
        const useYearFilter = !dateFilterApplied && (year || month);
        const currentYear = year || new Date().getFullYear();
        const ownershipYear = resolveOwnershipYear({ year: currentYear, dateFromInt, dateFilterApplied });

        async function runSummaryBatch(batchVendors) {
            let sql = `
      SELECT
        COUNT(DISTINCT TRIM(CFC.SERIEFACTURA) || '-' || CFC.NUMEROFACTURA) as NUM_FACTURAS,
        SUM(CFC.IMPORTETOTAL) as TOTAL,
        SUM(CFC.IMPORTEBASEIMPONIBLE) as BASE,
        SUM(CFC.IMPORTEIVA) as IVA
      FROM DSEDAC.CFC CFC
      LEFT JOIN DSEDAC.CLI CLI ON CLI.CODIGOCLIENTE = CFC.CODIGOCLIENTE
      WHERE CFC.NUMEROFACTURA > 0 AND CFC.NUMEROFACTURA < 900000
    `;
            const queryParams = [];

            if (batchVendors.length > 0) {
                sql = appendCfcVendorScopeFilter(sql, queryParams, batchVendors, ownershipYear);
            }

            if (dateFilterApplied && dateFromInt && dateToInt) {
                sql += ` AND (CFC.ANODOCUMENTO * 10000 + CFC.MESDOCUMENTO * 100 + CFC.DIADOCUMENTO) BETWEEN ? AND ?`;
                queryParams.push(dateFromInt, dateToInt);
            } else {
                sql += ` AND CFC.EJERCICIOFACTURA = ?`;
                queryParams.push(currentYear);
                if (month) {
                    sql += ` AND CFC.MESDOCUMENTO = ?`;
                    queryParams.push(month);
                }
            }

            if (clientId) {
                sql += ` AND TRIM(CFC.CODIGOCLIENTE) = ?`;
                queryParams.push(clientId.trim());
            }

            const clientFilter = buildInvoiceClientSearchFilter(clientSearch);
            sql += ` ${clientFilter.clause}`;
            queryParams.push(...clientFilter.params);

            const docFilter = buildInvoiceDocSearchFilter(docSearch);
            sql += ` ${docFilter.clause}`;
            queryParams.push(...docFilter.params);

            const genericFilter = buildInvoiceSearchFilter(search);
            sql += ` ${genericFilter.clause}`;
            queryParams.push(...genericFilter.params);

            return queryWithParams(sql, queryParams);
        }

        try {
            let rows;
            if (isAll || vendors.length === 0) {
                rows = await runSummaryBatch([]);
            } else {
                const batches = [];
                for (let i = 0; i < vendors.length; i += BATCH_SIZE) {
                    batches.push(vendors.slice(i, i + BATCH_SIZE));
                }
                const batchResults = await Promise.all(batches.map(runSummaryBatch));
                rows = batchResults.flat();
            }

            const stats = rows.reduce((acc, r) => ({
                NUM_FACTURAS: (acc.NUM_FACTURAS || 0) + (parseInt(r.NUM_FACTURAS) || 0),
                TOTAL: (acc.TOTAL || 0) + (parseFloat(r.TOTAL) || 0),
                BASE: (acc.BASE || 0) + (parseFloat(r.BASE) || 0),
                IVA: (acc.IVA || 0) + (parseFloat(r.IVA) || 0)
            }), { NUM_FACTURAS: 0, TOTAL: 0, BASE: 0, IVA: 0 });

            return {
                totalFacturas: stats.NUM_FACTURAS,
                totalImporte: stats.TOTAL,
                totalBase: stats.BASE,
                totalIva: stats.IVA
            };
        } catch (error) {
            if (error.message.includes('CWB0111') || error.message.includes('22001') || error.message.includes('parameter')) {
                logger.warn(`[facturas] Summary query failed (expected with many vendors), returning zeros: ${error.message.substring(0, 80)}`);
            } else {
                logger.error(`Error fetching summary: ${error.message}`);
            }
            return { totalFacturas: 0, totalImporte: 0, totalBase: 0, totalIva: 0 };
        }
    }

    async _getSummaryInternal(params) {
        const { vendedorCodes, year, month, search, clientId, clientSearch, docSearch, dateFrom, dateTo } = params;
        const documentType = normalizeDocumentType(params.documentType || params.tipoDocumento);
        const includeFacturas = documentType !== 'albaran';
        const includeAlbaranes = documentType !== 'factura';

        if (!vendedorCodes) {
            throw new Error('vendedorCodes is required');
        }

        const isAll = vendedorCodes.trim().toUpperCase() === 'ALL';
        const vendors = isAll ? [] : vendedorCodes.split(',').map(v => v.trim()).filter(v => v && v !== 'UNK' && /^[A-Z0-9]+$/.test(v));

        const dateFilterApplied = dateFrom && dateTo;
        const dateFromInt = dateFilterApplied ? parseInt(dateFrom.replace(/-/g, '')) : null;
        const dateToInt = dateFilterApplied ? parseInt(dateTo.replace(/-/g, '')) : null;
        const currentYear = year || new Date().getFullYear();
        const ownershipYear = resolveOwnershipYear({ year: currentYear, dateFromInt, dateFilterApplied });

        function applySummaryFilters(sql, queryParams, {
            batchVendors,
            vendorColumn,
            dateExpr,
            yearColumn,
            monthColumn,
            clientColumn,
            clientFilterBuilder,
            docFilterBuilder,
            genericFilterBuilder,
            includeOwnedEmptyVendor = false,
        }) {
            if (batchVendors.length > 0) {
                if (includeOwnedEmptyVendor) {
                    sql = appendCfcVendorScopeFilter(sql, queryParams, batchVendors, ownershipYear);
                } else {
                    const placeholders = batchVendors.map(() => '?').join(',');
                    sql += ` AND TRIM(${vendorColumn}) IN (${placeholders})`;
                    queryParams.push(...batchVendors);
                }
            }

            if (dateFilterApplied && dateFromInt && dateToInt) {
                sql += ` AND ${dateExpr} BETWEEN ? AND ?`;
                queryParams.push(dateFromInt, dateToInt);
            } else {
                sql += ` AND ${yearColumn} = ?`;
                queryParams.push(currentYear);
                if (month) {
                    sql += ` AND ${monthColumn} = ?`;
                    queryParams.push(month);
                }
            }

            if (clientId) {
                sql += ` AND TRIM(${clientColumn}) = ?`;
                queryParams.push(clientId.trim());
            }

            const clientFilter = clientFilterBuilder(clientSearch);
            sql += ` ${clientFilter.clause}`;
            queryParams.push(...clientFilter.params);

            const docFilter = docFilterBuilder(docSearch);
            sql += ` ${docFilter.clause}`;
            queryParams.push(...docFilter.params);

            const genericFilter = genericFilterBuilder(search);
            sql += ` ${genericFilter.clause}`;
            queryParams.push(...genericFilter.params);

            return sql;
        }

        async function runInvoiceSummaryBatch(batchVendors) {
            const queryParams = [];
            let sql = `
      SELECT
        'factura' as DOCUMENT_TYPE,
        COUNT(DISTINCT TRIM(CFC.SERIEFACTURA) || '-' || CFC.NUMEROFACTURA || '-' || CFC.EJERCICIOFACTURA) as NUM_DOCUMENTOS,
        SUM(CFC.IMPORTETOTAL) as TOTAL,
        SUM(CFC.IMPORTEBASEIMPONIBLE) as BASE,
        SUM(CFC.IMPORTEIVA) as IVA
      FROM DSEDAC.CFC CFC
      LEFT JOIN DSEDAC.CLI CLI ON CLI.CODIGOCLIENTE = CFC.CODIGOCLIENTE
      WHERE CFC.NUMEROFACTURA > 0 AND CFC.NUMEROFACTURA < 900000
    `;
            sql = applySummaryFilters(sql, queryParams, {
                batchVendors,
                vendorColumn: 'CFC.CODIGOVENDEDOR',
                dateExpr: '(CFC.ANODOCUMENTO * 10000 + CFC.MESDOCUMENTO * 100 + CFC.DIADOCUMENTO)',
                yearColumn: 'CFC.EJERCICIOFACTURA',
                monthColumn: 'CFC.MESDOCUMENTO',
                clientColumn: 'CFC.CODIGOCLIENTE',
                clientFilterBuilder: buildInvoiceClientSearchFilter,
                docFilterBuilder: buildInvoiceDocSearchFilter,
                genericFilterBuilder: buildInvoiceSearchFilter,
                includeOwnedEmptyVendor: true,
            });
            return queryWithParams(sql, queryParams);
        }

        async function runAlbaranSummaryBatch(batchVendors) {
            const queryParams = [];
            let sql = `
      SELECT
        'albaran' as DOCUMENT_TYPE,
        COUNT(DISTINCT CAC.EJERCICIOALBARAN || '-' || TRIM(CAC.SERIEALBARAN) || '-' || CAC.TERMINALALBARAN || '-' || CAC.NUMEROALBARAN) as NUM_DOCUMENTOS,
        SUM(CAC.IMPORTETOTAL) as TOTAL,
        SUM(COALESCE(CAC.IMPORTEBRUTO, 0)) as BASE,
        SUM(COALESCE(CAC.IMPORTEIVA1, 0) + COALESCE(CAC.IMPORTEIVA2, 0) + COALESCE(CAC.IMPORTEIVA3, 0) + COALESCE(CAC.IMPORTEIVA4, 0) + COALESCE(CAC.IMPORTEIVA5, 0)) as IVA
      FROM DSEDAC.CAC CAC
      LEFT JOIN DSEDAC.CLI CLI ON TRIM(CLI.CODIGOCLIENTE) = TRIM(CAC.CODIGOCLIENTEALBARAN)
      WHERE CAC.NUMEROALBARAN > 0 AND CAC.NUMEROALBARAN < 900000
        AND NOT (CAC.NUMEROFACTURA > 0 AND CAC.NUMEROFACTURA < 900000)
    `;
            sql = applySummaryFilters(sql, queryParams, {
                batchVendors,
                vendorColumn: 'CAC.CODIGOVENDEDOR',
                dateExpr: '(CAC.ANODOCUMENTO * 10000 + CAC.MESDOCUMENTO * 100 + CAC.DIADOCUMENTO)',
                yearColumn: 'CAC.EJERCICIOALBARAN',
                monthColumn: 'CAC.MESDOCUMENTO',
                clientColumn: 'CAC.CODIGOCLIENTEALBARAN',
                clientFilterBuilder: buildAlbaranClientSearchFilter,
                docFilterBuilder: buildAlbaranDocSearchFilter,
                genericFilterBuilder: buildAlbaranSearchFilter,
            });
            return queryWithParams(sql, queryParams);
        }

        async function runSummaryBatch(batchVendors) {
            const queries = [];
            if (includeFacturas) queries.push(() => runInvoiceSummaryBatch(batchVendors));
            if (includeAlbaranes) queries.push(() => runAlbaranSummaryBatch(batchVendors));
            const results = [];
            for (const runQuery of queries) {
                results.push(await runQuery());
            }
            return results.flat();
        }

        try {
            let rows;
            if (isAll || vendors.length === 0) {
                rows = await runSummaryBatch([]);
            } else {
                const batches = [];
                for (let i = 0; i < vendors.length; i += BATCH_SIZE) {
                    batches.push(vendors.slice(i, i + BATCH_SIZE));
                }
                const batchResults = await mapWithConcurrency(
                    batches,
                    FACTURAS_SUMMARY_BATCH_CONCURRENCY,
                    runSummaryBatch
                );
                rows = batchResults.flat();
            }

            const stats = rows.reduce((acc, r) => {
                const count = parseInt(r.NUM_DOCUMENTOS, 10) || 0;
                const rowType = String(r.DOCUMENT_TYPE || r.document_type || '').trim().toLowerCase();
                if (rowType === 'albaran') {
                    acc.NUM_ALBARANES += count;
                } else {
                    acc.NUM_FACTURAS += count;
                }
                acc.TOTAL += parseFloat(r.TOTAL) || 0;
                acc.BASE += parseFloat(r.BASE) || 0;
                acc.IVA += parseFloat(r.IVA) || 0;
                return acc;
            }, { NUM_FACTURAS: 0, NUM_ALBARANES: 0, TOTAL: 0, BASE: 0, IVA: 0 });

            const totalDocumentos = stats.NUM_FACTURAS + stats.NUM_ALBARANES;
            return {
                totalFacturas: totalDocumentos,
                totalDocumentos,
                totalFacturasEmitidas: stats.NUM_FACTURAS,
                totalAlbaranes: stats.NUM_ALBARANES,
                totalImporte: stats.TOTAL,
                totalBase: stats.BASE,
                totalIva: stats.IVA
            };
        } catch (error) {
            if (error.message.includes('CWB0111') || error.message.includes('22001') || error.message.includes('parameter')) {
                logger.warn(`[facturas] Summary query failed (expected with many vendors), returning zeros: ${error.message.substring(0, 80)}`);
            } else {
                logger.error(`Error fetching summary: ${error.message}`);
            }
            return {
                totalFacturas: 0,
                totalDocumentos: 0,
                totalFacturasEmitidas: 0,
                totalAlbaranes: 0,
                totalImporte: 0,
                totalBase: 0,
                totalIva: 0
            };
        }
    }

    async getFacturaDetail(serie, numero, ejercicio) {
        const cacheKey = buildDocumentDetailCacheKey('factura', serie, numero, ejercicio);
        if (!cacheKey) return this._getFacturaDetailUncached(serie, numero, ejercicio);
        const cached = await redisCache.get('document', cacheKey);
        if (cached !== null) return cached;
        return withInFlight(facturaDetailInFlight, cacheKey, async () => {
            const secondCache = await redisCache.get('document', cacheKey);
            if (secondCache !== null) return secondCache;
            const result = await this._getFacturaDetailUncached(serie, numero, ejercicio);
            await redisCache.set('document', cacheKey, result, TTL.REALTIME);
            return result;
        });
    }

    async _getFacturaDetailUncached(serie, numero, ejercicio) {
        // AUDIT FIX: Block sentinel invoice numbers
        if (numero >= 900000 || numero <= 0) {
            throw new Error('Factura no encontrada');
        }

        // Use CFC as the fiscal invoice header. CAC is per-albaran and its
        // rounded totals can drift from the printed invoice header.
        const headerSql = `
      SELECT
        CFC.NUMEROFACTURA,
        CFC.SERIEFACTURA,
        CFC.EJERCICIOFACTURA,
        CFC.DIADOCUMENTO as DIAFACTURA,
        CFC.MESDOCUMENTO as MESFACTURA,
        CFC.ANODOCUMENTO as ANOFACTURA,
        TRIM(CFC.CODIGOCLIENTE) as CODIGOCLIENTE,
        TRIM(COALESCE(CLI.NOMBREALTERNATIVO, CLI.NOMBRECLIENTE, '')) as NOMBRECLIENTEFACTURA,
        TRIM(CLI.NOMBREALTERNATIVO) as NOMBRECOMERCIALFACTURA,
        TRIM(CLI.NOMBRECLIENTE) as NOMBREFISCALFACTURA,
        TRIM(COALESCE(CLI.DIRECCION, '')) as DIRECCIONCLIENTEFACTURA,
        TRIM(COALESCE(CLI.POBLACION, '')) as POBLACIONCLIENTEFACTURA,
        TRIM(COALESCE(CLI.NIF, '')) as CIFCLIENTEFACTURA,
        CFC.IMPORTETOTAL as TOTALFACTURA,
        CFC.IMPORTEBASEIMPONIBLE1,
        CFC.PORCENTAJEIVA1,
        CFC.IMPORTEIVA1,
        CFC.IMPORTEBASEIMPONIBLE2,
        CFC.PORCENTAJEIVA2,
        CFC.IMPORTEIVA2,
        CFC.IMPORTEBASEIMPONIBLE3,
        CFC.PORCENTAJEIVA3,
        CFC.IMPORTEIVA3,
        CFC.IMPORTEBASEIMPONIBLE4,
        CFC.PORCENTAJEIVA4,
        CFC.IMPORTEIVA4,
        CFC.IMPORTEBASEIMPONIBLE5,
        CFC.PORCENTAJEIVA5,
        CFC.IMPORTEIVA5
      FROM DSEDAC.CFC CFC
      LEFT JOIN DSEDAC.CLI CLI ON CLI.CODIGOCLIENTE = CFC.CODIGOCLIENTE
      WHERE TRIM(CFC.SERIEFACTURA) = ?
        AND CFC.NUMEROFACTURA = ?
        AND CFC.EJERCICIOFACTURA = ?
      FETCH FIRST 1 ROWS ONLY
    `;

        try {
            const headers = await queryWithParams(headerSql, [serie, numero, ejercicio]);

            if (!headers || headers.length === 0) {
                throw new Error('Factura no encontrada'); // This string must match the check in routes
            }

            const header = headers[0];

            const linesSql = `
        SELECT 
          LAC.CODIGOARTICULO,
          LAC.DESCRIPCION as DESCRIPCIONARTICULO,
          LAC.CANTIDADUNIDADES as CANTIDAD,
          LAC.PRECIOVENTA as PRECIO,
          LAC.IMPORTEVENTA as IMPORTE,
          LAC.PORCENTAJEDESCUENTO as DESCUENTO,
          LAC.NUMEROALBARAN,
          LAC.SERIEALBARAN,
          LAC.TERMINALALBARAN,
          LAC.EJERCICIOALBARAN,
          LAC.CODIGOIVA,
          COALESCE(LAC.CANTIDADENVASES, 0) as CAJAS,
          LAC.IMPORTEVENTA as IMPORTENETO,
          LAC.DIADOCUMENTO,
          LAC.MESDOCUMENTO,
          LAC.ANODOCUMENTO
        FROM DSEDAC.LAC LAC
        INNER JOIN DSEDAC.CAC CAC 
          ON LAC.EJERCICIOALBARAN = CAC.EJERCICIOALBARAN
          AND LAC.SERIEALBARAN = CAC.SERIEALBARAN
          AND LAC.TERMINALALBARAN = CAC.TERMINALALBARAN
          AND LAC.NUMEROALBARAN = CAC.NUMEROALBARAN
        WHERE TRIM(CAC.SERIEFACTURA) = ?
          AND CAC.NUMEROFACTURA = ?
          AND CAC.EJERCICIOFACTURA = ?
        ORDER BY LAC.NUMEROALBARAN, LAC.SECUENCIA
      `;

            const lines = await queryWithParams(linesSql, [serie, numero, ejercicio]);

            const bases = buildTaxBases(header);

            return {
                header: {
                    serie: header.SERIEFACTURA && header.SERIEFACTURA.trim ? header.SERIEFACTURA.trim() : serie,
                    numero: header.NUMEROFACTURA,
                    ejercicio: header.EJERCICIOFACTURA,
                    fecha: `${String(header.DIAFACTURA).padStart(2, '0')}/${String(header.MESFACTURA).padStart(2, '0')}/${header.ANOFACTURA}`,
                    clienteId: header.CODIGOCLIENTE,
                    clienteNombre: header.NOMBRECLIENTEFACTURA,
                    nombreComercial: header.NOMBRECOMERCIALFACTURA || header.NOMBRECLIENTEFACTURA,
                    nombreFiscal: header.NOMBREFISCALFACTURA || header.NOMBRECLIENTEFACTURA,
                    clienteDireccion: header.DIRECCIONCLIENTEFACTURA,
                    clientePoblacion: header.POBLACIONCLIENTEFACTURA,
                    clienteNif: header.CIFCLIENTEFACTURA,
                    total: parseFloat(header.TOTALFACTURA) || 0,
                    bases
                },
                lines: lines.map(l => ({
                    codigo: l.CODIGOARTICULO && l.CODIGOARTICULO.trim ? l.CODIGOARTICULO.trim() : '',
                    descripcion: l.DESCRIPCIONARTICULO && l.DESCRIPCIONARTICULO.trim ? l.DESCRIPCIONARTICULO.trim() : '',
                    cantidad: parseFloat(l.CANTIDAD) || 0,
                    precio: parseFloat(l.PRECIO) || 0,
                    importe: parseFloat(l.IMPORTE) || 0,
                    descuento: parseFloat(l.DESCUENTO) || 0,
                    albaranNum: l.NUMEROALBARAN,
                    albaranSerie: l.SERIEALBARAN ? l.SERIEALBARAN.trim() : '',
                    albaranTerminal: l.TERMINALALBARAN,
                    albaranEjercicio: l.EJERCICIOALBARAN,
                    albaranFecha: l.DIADOCUMENTO && l.MESDOCUMENTO && l.ANODOCUMENTO
                        ? `${String(l.DIADOCUMENTO).padStart(2, '0')}.${String(l.MESDOCUMENTO).padStart(2, '0')}.${l.ANODOCUMENTO}`
                        : '',
                    codigoIva: l.CODIGOIVA ? l.CODIGOIVA.trim() : '',
                    cajas: l.CAJAS || 0,
                    importeNeto: parseFloat(l.IMPORTENETO) || 0
                }))
            };
        } catch (error) {
            if (error.message === 'Factura no encontrada') {
                logger.warn(`Factura detail not found for ${serie}-${numero}-${ejercicio}`);
            } else {
                logger.error(`Error fetching factura detail: ${error.message}`);
            }
            throw error;
        }
    }

    async getAlbaranDetailForPdf(serie, numero, ejercicio, terminal = null) {
        const cacheKey = buildDocumentDetailCacheKey('albaran', serie, numero, ejercicio, terminal);
        if (!cacheKey) return this._getAlbaranDetailForPdfUncached(serie, numero, ejercicio, terminal);
        const cached = await redisCache.get('document', cacheKey);
        if (cached !== null) return cached;
        return withInFlight(albaranDetailInFlight, cacheKey, async () => {
            const secondCache = await redisCache.get('document', cacheKey);
            if (secondCache !== null) return secondCache;
            const result = await this._getAlbaranDetailForPdfUncached(serie, numero, ejercicio, terminal);
            await redisCache.set('document', cacheKey, result, TTL.REALTIME);
            return result;
        });
    }

    async _getAlbaranDetailForPdfUncached(serie, numero, ejercicio, terminal = null) {
        const cleanSerie = normalizeSerieForLookup(serie);
        const cleanNumero = parseDocumentNumber(numero);
        const cleanEjercicio = parseInt(ejercicio, 10);
        const cleanTerminal = terminal === null || terminal === undefined || terminal === ''
            ? null
            : parseInt(terminal, 10);

        if (!cleanSerie || !cleanNumero || !Number.isFinite(cleanEjercicio) || cleanEjercicio <= 0) {
            throw new Error('Albaran no encontrado');
        }

        if (cleanTerminal !== null && (!Number.isFinite(cleanTerminal) || cleanTerminal < 0)) {
            throw new Error('Albaran no encontrado');
        }

        const terminalClause = cleanTerminal === null ? '' : 'AND CAC.TERMINALALBARAN = ?';
        const headerParams = [cleanNumero, cleanSerie, cleanEjercicio];
        if (cleanTerminal !== null) headerParams.push(cleanTerminal);

        const headerSql = `
      SELECT
        CAC.EJERCICIOALBARAN,
        TRIM(CAC.SERIEALBARAN) as SERIEALBARAN,
        CAC.NUMEROALBARAN,
        CAC.TERMINALALBARAN,
        CAC.NUMEROFACTURA,
        TRIM(CAC.SERIEFACTURA) as SERIEFACTURA,
        CAC.EJERCICIOFACTURA,
        CAC.DIADOCUMENTO as DIAFACTURA,
        CAC.MESDOCUMENTO as MESFACTURA,
        CAC.ANODOCUMENTO as ANOFACTURA,
        TRIM(CAC.CODIGOCLIENTEALBARAN) as CODIGOCLIENTEFACTURA,
        TRIM(COALESCE(CLI.NOMBREALTERNATIVO, CLI.NOMBRECLIENTE, '')) as NOMBRECLIENTEFACTURA,
        TRIM(CLI.NOMBREALTERNATIVO) as NOMBRECOMERCIALFACTURA,
        TRIM(CLI.NOMBRECLIENTE) as NOMBREFISCALFACTURA,
        TRIM(COALESCE(CLI.DIRECCION, '')) as DIRECCIONCLIENTEFACTURA,
        TRIM(COALESCE(CLI.POBLACION, '')) as POBLACIONCLIENTEFACTURA,
        TRIM(COALESCE(CLI.PROVINCIA, '')) as PROVINCIACLIENTEFACTURA,
        TRIM(COALESCE(CLI.CODIGOPOSTAL, '')) as CPCLIENTEFACTURA,
        TRIM(COALESCE(CLI.NIF, '')) as CIFCLIENTEFACTURA,
        CAC.IMPORTETOTAL,
        COALESCE(CAC.IMPORTEBRUTO, 0) as IMPORTEBRUTO,
        CAC.IMPORTEBASEIMPONIBLE1,
        CAC.PORCENTAJEIVA1,
        CAC.IMPORTEIVA1,
        CAC.IMPORTEBASEIMPONIBLE2,
        CAC.PORCENTAJEIVA2,
        CAC.IMPORTEIVA2,
        CAC.IMPORTEBASEIMPONIBLE3,
        CAC.PORCENTAJEIVA3,
        CAC.IMPORTEIVA3,
        CAC.IMPORTEBASEIMPONIBLE4,
        CAC.PORCENTAJEIVA4,
        CAC.IMPORTEIVA4,
        CAC.IMPORTEBASEIMPONIBLE5,
        CAC.PORCENTAJEIVA5,
        CAC.IMPORTEIVA5
      FROM DSEDAC.CAC CAC
      LEFT JOIN DSEDAC.CLI CLI ON TRIM(CLI.CODIGOCLIENTE) = TRIM(CAC.CODIGOCLIENTEALBARAN)
      WHERE CAC.NUMEROALBARAN = ?
        AND TRIM(CAC.SERIEALBARAN) = ?
        AND CAC.EJERCICIOALBARAN = ?
        ${terminalClause}
        AND CAC.NUMEROALBARAN > 0 AND CAC.NUMEROALBARAN < 900000

      ORDER BY CAC.ANODOCUMENTO DESC, CAC.MESDOCUMENTO DESC, CAC.DIADOCUMENTO DESC, CAC.TERMINALALBARAN DESC
      FETCH FIRST 2 ROWS ONLY
    `;

        try {
            const headers = await queryWithParams(headerSql, headerParams);
            if (!headers || headers.length === 0) {
                throw new Error('Albaran no encontrado');
            }

            if (headers.length > 1) {
                logger.warn(`[facturas] Multiple albaran headers for ${cleanSerie}-${cleanNumero}-${cleanEjercicio}; using most recent terminal ${headers[0].TERMINALALBARAN}`);
            }

            const header = headers[0];
            const actualEjercicio = parseInt(header.EJERCICIOALBARAN, 10);
            const actualSerie = (header.SERIEALBARAN || cleanSerie).toString().trim();
            const actualTerminal = parseInt(header.TERMINALALBARAN, 10) || 0;
            const actualNumero = parseInt(header.NUMEROALBARAN, 10);

            const linesSql = `
        SELECT
          LAC.CODIGOARTICULO,
          LAC.DESCRIPCION as DESCRIPCIONARTICULO,
          '' as LOTEARTICULO,
          LAC.CANTIDADUNIDADES as CANTIDADARTICULO,
          LAC.CANTIDADENVASES as CAJASARTICULO,
          LAC.IMPORTEVENTA as IMPORTENETOARTICULO,
          TRIM(LAC.CODIGOIVA) as CODIGOIVA,
          0 as PORCENTAJERECARGOARTICULO,
          LAC.PORCENTAJEDESCUENTO as PORCENTAJEDESCUENTOARTICULO,
          LAC.PRECIOVENTA as PRECIOARTICULO
        FROM DSEDAC.LAC LAC
        WHERE LAC.EJERCICIOALBARAN = ?
          AND TRIM(LAC.SERIEALBARAN) = ?
          AND LAC.TERMINALALBARAN = ?
          AND LAC.NUMEROALBARAN = ?
        ORDER BY LAC.SECUENCIA
      `;

            const lines = await queryWithParams(linesSql, [actualEjercicio, actualSerie, actualTerminal, actualNumero]);
            const fecha = `${String(header.DIAFACTURA).padStart(2, '0')}/${String(header.MESFACTURA).padStart(2, '0')}/${header.ANOFACTURA}`;
            const bases = buildTaxBases(header);
            const total = parseFloat(header.IMPORTETOTAL) || 0;

            return {
                documentType: 'albaran',
                header: {
                    ...header,
                    SERIEALBARAN: actualSerie,
                    NUMEROALBARAN: actualNumero,
                    EJERCICIOALBARAN: actualEjercicio,
                    TERMINALALBARAN: actualTerminal,
                    NUMEROFACTURA: parseInt(header.NUMEROFACTURA, 10) || 0,
                    SERIEFACTURA: header.SERIEFACTURA || '',
                    EJERCICIOFACTURA: parseInt(header.EJERCICIOFACTURA, 10) || 0,
                    IVA_BREAKDOWN: buildIvaBreakdown(header),
                    serie: actualSerie,
                    numero: actualNumero,
                    ejercicio: actualEjercicio,
                    terminal: actualTerminal,
                    fecha,
                    clienteId: header.CODIGOCLIENTEFACTURA,
                    clienteNombre: header.NOMBRECLIENTEFACTURA,
                    nombreComercial: header.NOMBRECOMERCIALFACTURA || header.NOMBRECLIENTEFACTURA,
                    nombreFiscal: header.NOMBREFISCALFACTURA || header.NOMBRECLIENTEFACTURA,
                    clienteDireccion: header.DIRECCIONCLIENTEFACTURA,
                    clientePoblacion: header.POBLACIONCLIENTEFACTURA,
                    clienteNif: header.CIFCLIENTEFACTURA,
                    total,
                    base: parseFloat(header.IMPORTEBRUTO) || bases.reduce((sum, b) => sum + b.base, 0),
                    iva: TAX_SLOTS.reduce((sum, slot) => sum + (parseFloat(header[`IMPORTEIVA${slot}`]) || 0), 0),
                    bases
                },
                lines: (lines || []).map(line => ({
                    ...line,
                    CODIGOARTICULO: line.CODIGOARTICULO && line.CODIGOARTICULO.trim ? line.CODIGOARTICULO.trim() : '',
                    DESCRIPCIONARTICULO: line.DESCRIPCIONARTICULO && line.DESCRIPCIONARTICULO.trim ? line.DESCRIPCIONARTICULO.trim() : '',
                    CODIGOIVA: line.CODIGOIVA && line.CODIGOIVA.trim ? line.CODIGOIVA.trim() : '',
                    CANTIDADARTICULO: parseFloat(line.CANTIDADARTICULO) || 0,
                    CAJASARTICULO: parseFloat(line.CAJASARTICULO) || 0,
                    IMPORTENETOARTICULO: parseFloat(line.IMPORTENETOARTICULO) || 0,
                    PORCENTAJEDESCUENTOARTICULO: parseFloat(line.PORCENTAJEDESCUENTOARTICULO) || 0,
                    PRECIOARTICULO: parseFloat(line.PRECIOARTICULO) || 0
                }))
            };
        } catch (error) {
            if (error.message === 'Albaran no encontrado') {
                logger.warn(`Albaran detail not found for ${cleanSerie}-${cleanNumero}-${cleanEjercicio}`);
            } else {
                logger.error(`Error fetching albaran detail: ${error.message}`);
            }
            throw error;
        }
    }

    generateWhatsAppMessage(serie, numero, fecha, total, clienteNombre) {
        return `Granja Mari Pepa\n\n` +
            `Factura: ${serie}-${numero}\n` +
            `Fecha: ${fecha}\n` +
            `Total: ${total.toFixed(2)} EUR\n\n` +
            `Cliente: ${clienteNombre}\n\n` +
            `Gracias por su confianza.`;
    }
}

module.exports = new FacturasService();
module.exports.facturasBreaker = facturasBreaker;

const logger = require('../middleware/logger');
const { getPool } = require('../config/db');

// LACLAE Cache for fast visit/delivery day lookups
// Structure: { vendedor: { clientCode: { visitDays: [], deliveryDays: [] } } }
// PRODUCTION-READY: LRU eviction with MAX_ENTRIES limit to prevent memory exhaustion
const MAX_CACHE_ENTRIES = 50000; // Max vendor-client pairs (50k entries ~ 50-100MB)
const MAX_CONFIG_ENTRIES = 10000; // Max rutero config entries
let laclaeCache = {};
let laclaeCacheReady = false;
let laclaeCacheLoadAttempted = false;
let laclaeCacheLastLoadTime = null;
let laclaeCacheAccessOrder = []; // LRU tracking: [vendor-client-key, ...]
let ruteroConfigCache = {};
let ruteroConfigAccessOrder = []; // LRU tracking for config
let laclaeCacheLoadPromise = null;

function toDayArray(days) {
    if (Array.isArray(days)) return days;
    if (days instanceof Set) return Array.from(days);
    return [];
}

/** CLI.ANOBAJA: 0 / NULL = active. Non-zero = baja (used on vendor transfers). */
function isAnoBaja(value) {
    const n = Number(value);
    return Number.isFinite(n) && n !== 0;
}

function ensureCacheEntry(cache, accessOrder, vendor, client, extras = {}) {
    if (!cache[vendor]) cache[vendor] = {};
    if (!cache[vendor][client]) {
        cache[vendor][client] = {
            visitDays: new Set(),
            deliveryDays: new Set(),
            isBaja: false,
            ...extras,
        };
        accessOrder.push(`${vendor}::${client}`);
    } else if (extras.naturalOrder && !cache[vendor][client].naturalOrder) {
        cache[vendor][client].naturalOrder = extras.naturalOrder;
    }
    if (extras.isBaja) cache[vendor][client].isBaja = true;
    return cache[vendor][client];
}

function normalizeCodeList(value) {
    if (value === undefined || value === null) return [];
    const values = Array.isArray(value) ? value : [value];
    return values
        .flatMap(v => String(v ?? '').split(','))
        .map(v => v.trim())
        .filter(v => v && !['undefined', 'null', 'N/A', 'ALL'].includes(v.toUpperCase()) && v.length <= 10);
}

function expandVendorCacheCodes(value) {
    return [...new Set(normalizeCodeList(value).flatMap(code => {
        const raw = String(code || '').trim();
        const unpadded = raw.replace(/^0+/, '') || raw;
        const padded = /^\d{1,2}$/.test(unpadded) ? unpadded.padStart(2, '0') : raw;
        return [raw, unpadded, padded].filter(Boolean);
    }))];
}

// Evict oldest entries when cache exceeds limit
function evictLaclaeCache(maxEntries) {
    while (laclaeCacheAccessOrder.length > maxEntries) {
        const oldest = laclaeCacheAccessOrder.shift();
        if (oldest) {
            const [vendor, client] = oldest.split('::');
            if (vendor && client && laclaeCache[vendor]) {
                delete laclaeCache[vendor][client];
                if (Object.keys(laclaeCache[vendor]).length === 0) {
                    delete laclaeCache[vendor];
                }
            }
        }
    }
}

function evictRuteroConfigCache(maxEntries) {
    while (ruteroConfigAccessOrder.length > maxEntries) {
        const oldest = ruteroConfigAccessOrder.shift();
        if (oldest) {
            const [vendor, client] = oldest.split('::');
            if (vendor && client && ruteroConfigCache[vendor]) {
                delete ruteroConfigCache[vendor][client];
                if (Object.keys(ruteroConfigCache[vendor]).length === 0) {
                    delete ruteroConfigCache[vendor];
                }
            }
        }
    }
}

// Track access for LRU
function trackLaclaeAccess(vendor, client) {
    const key = `${vendor}::${client}`;
    const idx = laclaeCacheAccessOrder.indexOf(key);
    if (idx !== -1) laclaeCacheAccessOrder.splice(idx, 1);
    laclaeCacheAccessOrder.push(key);
    evictLaclaeCache(MAX_CACHE_ENTRIES);
}

function trackRuteroConfigAccess(vendor, client) {
    const key = `${vendor}::${client}`;
    const idx = ruteroConfigAccessOrder.indexOf(key);
    if (idx !== -1) ruteroConfigAccessOrder.splice(idx, 1);
    ruteroConfigAccessOrder.push(key);
    evictRuteroConfigCache(MAX_CONFIG_ENTRIES);
}

// P2: Prevent reload - once attempted, stay in same state
function isCacheReady() {
    return laclaeCacheReady;
}

async function loadRuteroConfigCache(conn) {
    try {
        const rows = await conn.query(`
            SELECT TRIM(VENDEDOR) as VENDEDOR, TRIM(CLIENTE) as CLIENTE, TRIM(DIA) as DIA, ORDEN
            FROM JAVIER.RUTERO_CONFIG
        `);

        ruteroConfigCache = {};
        rows.forEach(r => {
            if (!r.VENDEDOR || !r.CLIENTE) return;
            if (!ruteroConfigCache[r.VENDEDOR]) ruteroConfigCache[r.VENDEDOR] = {};

            if (!ruteroConfigCache[r.VENDEDOR][r.CLIENTE]) {
                ruteroConfigCache[r.VENDEDOR][r.CLIENTE] = {};
            }
            // Store by DAY
            ruteroConfigCache[r.VENDEDOR][r.CLIENTE][r.DIA?.toLowerCase()] = {
                order: r.ORDEN
            };
        });
        logger.info(`📅 Rutero Config loaded: ${rows.length} overrides`);
    } catch (e) {
        logger.warn(`⚠️ Failed to load Rutero Config (might not exist yet): ${e.message}`);
    }
}

// Reload function exposed for planner.js
async function reloadRuteroConfig() {
    const dbPool = getPool();
    if (!dbPool) return;
    try {
        const conn = await dbPool.connect();
        await loadRuteroConfigCache(conn);
        await conn.close();
    } catch (e) {
        logger.error(`Reload config failed: ${e.message}`);
    }
}


// Load LACLAE visit/delivery data into memory cache
// NOW ENHANCED: Merges data from DSEDAC.CDVI (Master Route Config) + DSED.LACLAE (Sales/History)
async function loadLaclaeCache() {
    if (laclaeCacheLoadPromise) {
        return laclaeCacheLoadPromise;
    }

    laclaeCacheLoadPromise = loadLaclaeCacheInternal();
    try {
        return await laclaeCacheLoadPromise;
    } finally {
        laclaeCacheLoadPromise = null;
    }
}

async function loadLaclaeCacheInternal() {
    logger.info('📅 Loading LACLAE cache (visit/delivery days)...');
    const start = Date.now();

    const dbPool = getPool();
    if (!dbPool) {
        logger.error('❌ Database pool not initialized - cannot load LACLAE cache');
        return;
    }

    try {
        const conn = await dbPool.connect();
        try {
            const nextLaclaeCache = {};
            const nextLaclaeCacheAccessOrder = [];

            // 1. Load Master Route Config from DSEDAC.CDVI (Cuadro de Visitas)
            // This ensures NEW clients without sales are included
            logger.info('   Loading Master Route Config from DSEDAC.CDVI...');
            // Include clients with ANOBAJA (vendor transfers mark the previous ficha as baja).
            // Sales scope needs them; visit helpers skip isBaja so they do not appear on the day route.
            const cdviRows = await conn.query(`
                SELECT 
                    TRIM(C.CODIGOVENDEDOR) as VENDEDOR,
                    TRIM(C.CODIGOCLIENTE) as CLIENTE,
                    K.ANOBAJA as ANOBAJA,
                    C.DIAVISITALUNESSN as VIS_L, 
                    C.DIAVISITAMARTESSN as VIS_M, 
                    C.DIAVISITAMIERCOLESSN as VIS_X,
                    C.DIAVISITAJUEVESSN as VIS_J, 
                    C.DIAVISITAVIERNESSN as VIS_V, 
                    C.DIAVISITASABADOSN as VIS_S, 
                    C.DIAVISITADOMINGOSN as VIS_D,
                    C.ORDENVISITALUNES as OR_L,
                    C.ORDENVISITAMARTES as OR_M,
                    C.ORDENVISITAMIERCOLES as OR_X,
                    C.ORDENVISITAJUEVES as OR_J,
                    C.ORDENVISITAVIERNES as OR_V,
                    C.ORDENVISITASABADO as OR_S,
                    C.ORDENVISITADOMINGO as OR_D
                FROM DSEDAC.CDVI C
                JOIN DSEDAC.CLI K ON C.CODIGOCLIENTE = K.CODIGOCLIENTE
                WHERE (C.MARCAACTUALIZACION <> 'B' OR C.MARCAACTUALIZACION IS NULL OR TRIM(C.MARCAACTUALIZACION) = '')
                  AND (  -- EXCLUDE zombie entries with NO visit days assigned
                    TRIM(C.DIAVISITALUNESSN) = 'S' OR TRIM(C.DIAVISITAMARTESSN) = 'S' OR
                    TRIM(C.DIAVISITAMIERCOLESSN) = 'S' OR TRIM(C.DIAVISITAJUEVESSN) = 'S' OR
                    TRIM(C.DIAVISITAVIERNESSN) = 'S' OR TRIM(C.DIAVISITASABADOSN) = 'S' OR
                    TRIM(C.DIAVISITADOMINGOSN) = 'S'
                  )
            `);

            const dayNames = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
            // CDVI mapping: Sunday is usually handled, checking sample data

            cdviRows.forEach(row => {
                if (!row.VENDEDOR || !row.CLIENTE) return;

                const entry = ensureCacheEntry(
                    nextLaclaeCache,
                    nextLaclaeCacheAccessOrder,
                    row.VENDEDOR,
                    row.CLIENTE,
                    {
                        isBaja: isAnoBaja(row.ANOBAJA),
                        naturalOrder: {
                            lunes: Number(row.OR_L) || 0,
                            martes: Number(row.OR_M) || 0,
                            miercoles: Number(row.OR_X) || 0,
                            jueves: Number(row.OR_J) || 0,
                            viernes: Number(row.OR_V) || 0,
                            sabado: Number(row.OR_S) || 0,
                            domingo: Number(row.OR_D) || 0
                        }
                    }
                );

                // Map 'S' to days (Handle 'S ' with trim)
                if (String(row.VIS_D).trim() === 'S') entry.visitDays.add('domingo');
                if (String(row.VIS_L).trim() === 'S') entry.visitDays.add('lunes');
                if (String(row.VIS_M).trim() === 'S') entry.visitDays.add('martes');
                if (String(row.VIS_X).trim() === 'S') entry.visitDays.add('miercoles');
                if (String(row.VIS_J).trim() === 'S') entry.visitDays.add('jueves');
                if (String(row.VIS_V).trim() === 'S') entry.visitDays.add('viernes');
                if (String(row.VIS_S).trim() === 'S') entry.visitDays.add('sabado');

                if (String(row.CLIENTE).includes('9046')) {
                    logger.info(`🔍 DEBUG 9046 MATCH: '${row.CLIENTE}' Vend '${row.VENDEDOR}' Flags L:${row.VIS_L} V:${row.VIS_V} (Hex V: ${Buffer.from(String(row.VIS_V)).toString('hex')}) -> Days: ${Array.from(entry.visitDays).join(',')}`);
                }
            });

            logger.info(`   ✅ Loaded ${cdviRows.length} route configs from CDVI`);
            const v15Count = cdviRows.filter(r => r.VENDEDOR === '15').length;
            logger.info(`   🔎 DEBUG: Vendor 15 has ${v15Count} clients in CDVI cache`);


            // 2. Load Sales/History data from DSED.LACLAE (Legacy source + Delivery Info)
            // Load base LACLAE data (Optimized: Current + Previous Year only)
            const currentYear = new Date().getFullYear();
            const startYear = currentYear - 1;

            const rows = await conn.query(`
        SELECT DISTINCT
          L.R1_T8CDVD as VENDEDOR,
          L.LCCDCL as CLIENTE,
          C.ANOBAJA as ANOBAJA,
          L.R1_T8DIVL as VIS_L, L.R1_T8DIVM as VIS_M, L.R1_T8DIVX as VIS_X,
          L.R1_T8DIVJ as VIS_J, L.R1_T8DIVV as VIS_V, L.R1_T8DIVS as VIS_S, L.R1_T8DIVD as VIS_D,
          L.R1_T8DIRL as DEL_L, L.R1_T8DIRM as DEL_M, L.R1_T8DIRX as DEL_X,
          L.R1_T8DIRJ as DEL_J, L.R1_T8DIRV as DEL_V, L.R1_T8DIRS as DEL_S, L.R1_T8DIRD as DEL_D
        FROM DSED.LACLAE L
        JOIN DSEDAC.CLI C ON L.LCCDCL = C.CODIGOCLIENTE
        WHERE L.R1_T8CDVD IS NOT NULL 
          AND L.LCCDCL IS NOT NULL
          AND L.LCAADC >= ?
      `, [startYear]);

            const visitCols = ['VIS_D', 'VIS_L', 'VIS_M', 'VIS_X', 'VIS_J', 'VIS_V', 'VIS_S'];
            const deliveryCols = ['DEL_D', 'DEL_L', 'DEL_M', 'DEL_X', 'DEL_J', 'DEL_V', 'DEL_S'];

            rows.forEach(row => {
                const vendedor = row.VENDEDOR?.trim() || '';
                const cliente = row.CLIENTE?.trim() || '';
                if (!vendedor || !cliente) return;

                const entry = ensureCacheEntry(
                    nextLaclaeCache,
                    nextLaclaeCacheAccessOrder,
                    vendedor,
                    cliente,
                    { isBaja: isAnoBaja(row.ANOBAJA) }
                );

                for (let i = 0; i < 7; i++) {
                    if (row[visitCols[i]] === 'S') entry.visitDays.add(dayNames[i]);
                    if (row[deliveryCols[i]] === 'S') entry.deliveryDays.add(dayNames[i]);
                }
            });

            // Convert Sets to Arrays for compatibility
            Object.values(nextLaclaeCache).forEach(vendorClients => {
                Object.values(vendorClients).forEach(clientData => {
                    clientData.visitDays = Array.from(clientData.visitDays);
                    clientData.deliveryDays = Array.from(clientData.deliveryDays);
                });
            });

            // Load Overrides
            await loadRuteroConfigCache(conn);

            const vendorCount = Object.keys(nextLaclaeCache).length;
            const totalClients = Object.values(nextLaclaeCache).reduce((sum, v) => sum + Object.keys(v).length, 0);
            const duration = Date.now() - start;

            logger.info(`📅 LACLAE/CDVI cache loaded: ${vendorCount} vendors, ${totalClients} clients in ${duration}ms`);
            laclaeCache = nextLaclaeCache;
            laclaeCacheAccessOrder = nextLaclaeCacheAccessOrder;
            evictLaclaeCache(MAX_CACHE_ENTRIES);
            laclaeCacheReady = true;
            laclaeCacheLoadAttempted = true;
            laclaeCacheLastLoadTime = Date.now();

        } finally {
            await conn.close();
        }
    } catch (error) {
        logger.warn(`⚠️ LACLAE cache failed to load: ${error.message} - using hash fallback`);
        if (Object.keys(laclaeCache).length === 0) {
            laclaeCacheReady = false;
        }
        laclaeCacheLoadAttempted = true; // P2: Mark as attempted, never retry
    }
}

// P2: Get clients for a day - NEVER reloads, uses fallback if not ready
function getClientsForDay(vendedorCodes, day, role = 'comercial', ignoreOverrides = false) {
    // P2: If cache not ready and we've attempted load, use fallback (don't retry)
    if (!laclaeCacheReady && laclaeCacheLoadAttempted) {
        logger.warn('[LACLAE] Cache not ready, using fallback (no reload)');
        return null;
    }
    
    if (!laclaeCacheReady) {
        // First request before cache loaded - trigger async load but return null
        logger.warn('[LACLAE] Cache not yet loaded, triggering background load');
        loadLaclaeCache().catch(() => {});
        return null;
    }

    const dayLower = day.toLowerCase();
    const isDelivery = role === 'repartidor';
    let finalClients = new Set();

    const requestedVendors = expandVendorCacheCodes(vendedorCodes);
    const vendedors = requestedVendors.length > 0 ? requestedVendors : Object.keys(laclaeCache);

    vendedors.forEach(vendedor => {
        const vendorClients = laclaeCache[vendedor] || {};
        const configClients = ruteroConfigCache[vendedor] || {};

        Object.entries(vendorClients).forEach(([clientCode, data]) => {
            // Baja fichas stay in sales scope but must not appear on the day route
            if (data.isBaja) return;

            const days = toDayArray(isDelivery ? data.deliveryDays : data.visitDays);

            let shouldInclude = false;

            if (!ignoreOverrides) {
                const clientOverrides = configClients[clientCode] || {};
                const overrideForDay = clientOverrides[dayLower];

                if (overrideForDay) {
                    // Entry exists for this day - check if it's a block (order < 0) or positive
                    shouldInclude = overrideForDay.order >= 0;
                } else {
                    // No override for this specific day - use natural days
                    if (days.includes(dayLower)) shouldInclude = true;
                }
            } else {
                // Ignore overrides - PURE NATURAL ROUTE
                if (days.includes(dayLower)) shouldInclude = true;
            }

            if (shouldInclude) {
                finalClients.add(clientCode);
            }
        });

        logger.debug(`📊 getClientsForDay('${vendedor}', '${day}'): Found ${finalClients.size} so far`);

        // Add clients that exist ONLY in RuteroConfig (orphan overrides)
        if (!ignoreOverrides) {
            Object.entries(configClients).forEach(([clientCode, cfg]) => {
                const overrideForDay = cfg[dayLower];
                // Only add POSITIVE overrides (order >= 0)
                if (overrideForDay && overrideForDay.order >= 0) {
                    finalClients.add(clientCode);
                }
            });
        }
    });

    return Array.from(finalClients);
}

// Get week counts from cache - FIXED: Respects blocking entries (ORDEN = -1) and ignoreOverrides flag
function getWeekCountsFromCache(vendedorCodes, role = 'comercial', ignoreOverrides = false) {
    if (!laclaeCacheReady) return null; // Use fallback

    const isDelivery = role === 'repartidor';
    const counts = { lunes: 0, martes: 0, miercoles: 0, jueves: 0, viernes: 0, sabado: 0, domingo: 0 };
    const clientsSet = { lunes: new Set(), martes: new Set(), miercoles: new Set(), jueves: new Set(), viernes: new Set(), sabado: new Set(), domingo: new Set() };

    const requestedVendors = expandVendorCacheCodes(vendedorCodes);
    const vendedors = requestedVendors.length > 0 ? requestedVendors : Object.keys(laclaeCache);

    vendedors.forEach(vendedor => {
        const vendorClients = laclaeCache[vendedor] || {};
        const configClients = ruteroConfigCache[vendedor] || {};

        Object.entries(vendorClients).forEach(([clientCode, data]) => {
            if (data.isBaja) return;

            const days = toDayArray(isDelivery ? data.deliveryDays : data.visitDays);

            if (!ignoreOverrides) {
                const clientOverrides = configClients[clientCode] || {};

                // 1. Add POSITIVE overrides (order >= 0)
                Object.entries(clientOverrides).forEach(([day, cfg]) => {
                    if (cfg.order >= 0 && counts.hasOwnProperty(day)) {
                        clientsSet[day].add(clientCode);
                    }
                });

                // 2. Add Natural Days (if no override exists for that day)
                days.forEach(day => {
                    if (counts.hasOwnProperty(day) && !clientOverrides[day]) {
                        clientsSet[day].add(clientCode);
                    }
                });
            } else {
                // Ignore overrides - purely natural counts from AS400
                days.forEach(day => {
                    if (counts.hasOwnProperty(day)) {
                        clientsSet[day].add(clientCode);
                    }
                });
            }
        });

        // Also add orphan overrides (clients only in RuteroConfig, not in LACLAE)
        if (!ignoreOverrides) {
            Object.entries(configClients).forEach(([clientCode, overrides]) => {
                Object.entries(overrides).forEach(([day, cfg]) => {
                    if (cfg.order >= 0 && counts.hasOwnProperty(day)) {
                        clientsSet[day].add(clientCode);
                    }
                });
            });
        }
    });

    Object.keys(counts).forEach(day => {
        counts[day] = clientsSet[day].size;
    });

    return counts;
}

// Get total unique clients from cache
function getTotalClientsFromCache(vendedorCodes, role = 'comercial') {
    if (!laclaeCacheReady) return 0;

    const isDelivery = role === 'repartidor';
    const allClients = new Set();

    const requestedVendors = expandVendorCacheCodes(vendedorCodes);
    const vendedors = requestedVendors.length > 0 ? requestedVendors : Object.keys(laclaeCache);

    vendedors.forEach(vendedor => {
        const vendorClients = laclaeCache[vendedor] || {};
        Object.entries(vendorClients).forEach(([clientCode, data]) => {
            if (data.isBaja) return;
            const days = toDayArray(isDelivery ? data.deliveryDays : data.visitDays);
            if (days.length > 0) {
                allClients.add(clientCode);
            }
        });
    });

    return allClients.size;
}

// Get client codes from cache (for sales/commission/objective client-scope).
// Includes clients with ANOBAJA (vendor transfers). Visit helpers filter those out.
// Delivery-only entries (from LACLAE history) are excluded — those clients
// belong to another vendor for sales purposes and only appear in repartidor views.
function getClientCodesFromCache(vendedorCodes) {
    if (!laclaeCacheReady) return null;

    const allClients = new Set();

    // Handle 'ALL' or empty string - use all vendors
    if (!vendedorCodes || vendedorCodes === 'ALL' || vendedorCodes.trim() === '') {
        Object.keys(laclaeCache).forEach(vendedor => {
            const vendorClients = laclaeCache[vendedor] || {};
            Object.entries(vendorClients).forEach(([clientCode, data]) => {
                if (toDayArray(data.visitDays).length > 0) {
                    allClients.add(clientCode);
                }
            });
        });
        return Array.from(allClients);
    }

    const vendedors = expandVendorCacheCodes(vendedorCodes);

    vendedors.forEach(vendedor => {
        const vendorClients = laclaeCache[vendedor] || {};
        Object.entries(vendorClients).forEach(([clientCode, data]) => {
            if (toDayArray(data.visitDays).length > 0) {
                allClients.add(clientCode);
            }
        });
    });

    return Array.from(allClients);
}

// Get list of vendedores from cache
function getVendedoresFromCache() {
    if (!laclaeCacheReady) return null;

    return Object.entries(laclaeCache).map(([code, clients]) => ({
        code,
        clients: Object.keys(clients).length
    })).sort((a, b) => b.clients - a.clients);
}

// P7: Get aggregated active VISIT days for vendor(s) - handles single or comma-separated
function getVendorActiveDaysFromCache(vendedorCode) {
    if (!laclaeCacheReady || !vendedorCode) {
        logger.debug(`getVendorActiveDaysFromCache: cache not ready or no vendedorCode`);
        return [];
    }

    // P7: Split comma-separated codes and process each
    const codes = expandVendorCacheCodes(vendedorCode);
    const daysSet = new Set();
    let totalClients = 0;

    codes.forEach(code => {
        const vendorClients = laclaeCache[code];
        if (vendorClients) {
            totalClients += Object.keys(vendorClients).length;
            Object.values(vendorClients).forEach(clientData => {
                toDayArray(clientData.visitDays).forEach(d => daysSet.add(d));
            });
        }
    });

    if (daysSet.size === 0 && codes.length > 0) {
        logger.debug(`Vendors [${codes.join(',')}] not in LACLAE cache. Available: ${Object.keys(laclaeCache).slice(0, 10).join(', ')}...`);
        return [];
    }

    const result = Array.from(daysSet);
    logger.debug(`Vendors [${codes.join(',')}] visit days: ${result.join(', ')} (${totalClients} clients)`);
    return result; // Returns ['lunes', 'martes'...]
}

// Get aggregated active DELIVERY days for a vendor (for repartidores in rutero)
// P7: Get delivery days for vendor(s) - handles single or comma-separated
function getVendorDeliveryDaysFromCache(vendedorCode) {
    if (!laclaeCacheReady || !vendedorCode) return [];

    // P7: Split comma-separated codes and process each
    const codes = expandVendorCacheCodes(vendedorCode);
    const daysSet = new Set();

    codes.forEach(code => {
        const vendorClients = laclaeCache[code] || {};
        Object.values(vendorClients).forEach(clientData => {
            toDayArray(clientData.deliveryDays).forEach(d => daysSet.add(d));
        });
    });

    return Array.from(daysSet);
}

// Debug: Get list of vendor codes in cache
function getCachedVendorCodes() {
    if (!laclaeCacheReady) return [];
    return Object.keys(laclaeCache);
}

/**
 * Obtiene el día actual de un cliente para un vendedor
 * Primero busca en RUTERO_CONFIG (override), si no existe, usa LACLAE (días naturales)
 * @returns {string|null} El día en minúsculas o null si no está asignado
 */
function getClientCurrentDay(vendedor, clientCode) {
    if (!laclaeCacheReady) return null;

    const vendedorStr = String(vendedor).trim();
    const clientStr = String(clientCode).trim();

    // 1. Buscar override en RUTERO_CONFIG
    // 1. Buscar overrides en RUTERO_CONFIG
    const configClients = ruteroConfigCache[vendedorStr] || {};
    const clientOverrides = configClients[clientStr];

    if (clientOverrides) {
        // Return the first POSITIVE override day (skip blocking entries with order < 0)
        const positiveDays = Object.entries(clientOverrides)
            .filter(([, cfg]) => cfg.order >= 0)
            .map(([day]) => day);
        if (positiveDays.length > 0) return positiveDays[0];
    }

    // 2. Buscar días naturales en LACLAE
    const vendorClients = laclaeCache[vendedorStr] || {};
    const clientData = vendorClients[clientStr];
    const visitDays = clientData ? toDayArray(clientData.visitDays) : [];
    if (visitDays.length > 0) {
        // Devolver el primer día de visita natural
        return visitDays[0];
    }

    return null;
}

/**
 * Get visit and delivery days for a specific client
 * @param {string} vendorCode - Vendor code (optional, will search all if not provided)
 * @param {string} clientCode - Client code
 * @returns { visitDays: string[], deliveryDays: string[] } or null
 */
function getClientDays(vendorCode, clientCode) {
    if (!laclaeCacheReady || !clientCode) return null;

    const dayLabels = {
        'lunes': 'L', 'martes': 'M', 'miercoles': 'X',
        'jueves': 'J', 'viernes': 'V', 'sabado': 'S', 'domingo': 'D'
    };

    const trimmedClient = clientCode.trim();

    // If vendor specified, search only there
    if (vendorCode) {
        const vendorData = laclaeCache[vendorCode.trim()];
        if (vendorData && vendorData[trimmedClient]) {
            const data = vendorData[trimmedClient];
            const visitDays = toDayArray(data.visitDays);
            const deliveryDays = toDayArray(data.deliveryDays);
            return {
                visitDays,
                deliveryDays,
                visitDaysShort: visitDays.map(d => dayLabels[d] || d).join(''),
                deliveryDaysShort: deliveryDays.map(d => dayLabels[d] || d).join('')
            };
        }
    }

    // Search all vendors — prefer entries with actual visit days over empty ones
    let fallbackResult = null;
    for (const [vCode, vendorData] of Object.entries(laclaeCache)) {
        if (vendorData[trimmedClient]) {
            const data = vendorData[trimmedClient];
            const visitDays = toDayArray(data.visitDays);
            const deliveryDays = toDayArray(data.deliveryDays);
            const result = {
                visitDays,
                deliveryDays,
                visitDaysShort: visitDays.map(d => dayLabels[d] || d).join(''),
                deliveryDaysShort: deliveryDays.map(d => dayLabels[d] || d).join(''),
                foundVendor: vCode
            };
            // Return immediately if this vendor has actual visit days
            if (visitDays.length > 0) {
                return result;
            }
            // Otherwise keep as fallback (e.g. delivery-only entries from LACLAE)
            if (!fallbackResult) fallbackResult = result;
        }
    }
    if (fallbackResult) return fallbackResult;

    return null;
}

/**
 * Get natural order for a client on a specific day
 */
function getNaturalOrder(vendorCode, clientCode, day) {
    if (!laclaeCacheReady || !vendorCode || !clientCode || !day) return 9999;

    const vendorData = laclaeCache[vendorCode.trim()];
    if (!vendorData) return 9999;

    const clientData = vendorData[clientCode.trim()];
    if (!clientData || !clientData.naturalOrder) return 9999;

    const order = clientData.naturalOrder[day.toLowerCase()];
    // If order is 0, return 9999 (so it falls back to Code/Name sort logic)
    // Actually, planner will handle fallback logic. Let's return the raw value.
    return order || 0;
}

// Clear all caches (for graceful shutdown)
function clearLaclaeCache() {
    laclaeCache = {};
    laclaeCacheReady = false;
    laclaeCacheLoadAttempted = false;
    laclaeCacheLastLoadTime = null;
    laclaeCacheAccessOrder = [];
    ruteroConfigCache = {};
    ruteroConfigAccessOrder = [];
    logger.info('📴 LACLAE cache fully cleared');
}

/** Test-only: inject laclae cache shape without hitting DB2. */
function __setLaclaeCacheForTests(cache, { ready = true } = {}) {
    laclaeCache = cache || {};
    laclaeCacheAccessOrder = [];
    Object.entries(laclaeCache).forEach(([vendor, clients]) => {
        Object.keys(clients || {}).forEach((client) => {
            laclaeCacheAccessOrder.push(`${vendor}::${client}`);
        });
    });
    laclaeCacheReady = !!ready;
    laclaeCacheLoadAttempted = true;
    laclaeCacheLastLoadTime = Date.now();
}

module.exports = {
    loadLaclaeCache,
    isCacheReady,
    isCacheLoadAttempted: () => laclaeCacheLoadAttempted,
    getClientsForDay,
    getWeekCountsFromCache,
    getTotalClientsFromCache,
    getClientCodesFromCache,
    getVendedoresFromCache,
    getVendorActiveDaysFromCache,
    getVendorDeliveryDaysFromCache,
    getCachedVendorCodes,
    reloadRuteroConfig,
    getClientCurrentDay,
    getClientDays,
    getNaturalOrder,
    ruteroConfigCache,
    laclaeCacheLastLoadTime: () => laclaeCacheLastLoadTime,
    clearLaclaeCache,
    __setLaclaeCacheForTests,
    isAnoBaja,
};

'use strict';

const PDFDocument = require('pdfkit');

const NAVY = '#003d7a';
const NAVY_DEEP = '#00264d';
const GREEN = '#00a878';
const GREEN_DARK = '#067a58';
const AMBER = '#f0b429';
const RED = '#c2410c';
const SLATE = '#334155';
const MUTED = '#64748b';
const LINE = '#c5d4e8';
const CARD_BG = '#eef6ff';
const CARD_GREEN = '#e7f8f1';
const CARD_AMBER = '#fff6e0';
const CARD_MUTED = '#f1f5f9';
const WHITE = '#ffffff';

const CASH_METHOD_RE = /^(EFECTIVO|EF|F0|E|CONTADO|CT)$/i;
const CHEQUE_METHOD_RE = /^(CHEQUE|CH|TALON|TALON BANCARIO)$/i;
const CARD_METHOD_RE = /^(TARJETA|TJ|TPV|TRANSFERENCIA|TR|T0|BIZUM|BI)$/i;
const POSTDATED_METHOD_RE = /^(POSTDATADO|PD|POSTDATADOS)$/i;

function toNumber(raw) {
  const num = Number(raw);
  return Number.isFinite(num) ? num : 0;
}

function roundMoney(raw) {
  return Math.round((toNumber(raw) + Number.EPSILON) * 100) / 100;
}

function pad(raw, size) {
  return String(raw ?? '').trim().padStart(size, '0');
}

function formatEuro(raw) {
  const amount = roundMoney(raw);
  const formatted = new Intl.NumberFormat('es-ES', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);
  return `${formatted} €`;
}

function formatGmpLiquidacionDisplay({
  year,
  vendorCode,
  serie = 'A',
  numero,
} = {}) {
  const y = Number(year);
  const safeYear = Number.isInteger(y) && y >= 2000 ? y : new Date().getFullYear();
  const serieLetter = String(serie || 'A').trim().toUpperCase().slice(0, 1) || 'A';
  const digits = String(vendorCode || '').replace(/\D/g, '');
  const vendor = digits ? digits.slice(-3) : '000';
  const n = Number(numero);
  const safeNumero = Number.isFinite(n) ? Math.trunc(Math.abs(n)) : 0;
  return `GMP ${safeYear} ${serieLetter} ${pad(vendor, 3)} ${pad(safeNumero, 6)}`;
}

function isCashPaymentMethod(raw) {
  return CASH_METHOD_RE.test(String(raw || '').trim());
}

function isChequePaymentMethod(raw) {
  return CHEQUE_METHOD_RE.test(String(raw || '').trim());
}

function isCardPaymentMethod(raw) {
  return CARD_METHOD_RE.test(String(raw || '').trim());
}

function isPostdatedPaymentMethod(raw) {
  return POSTDATED_METHOD_RE.test(String(raw || '').trim());
}

/**
 * Cash treasury deposit target.
 * Cheques / cartera / tarjeta never enter bank cash deposit.
 *
 * totalAIngresar = efectivo + saldoActual − gastos + ajustes
 * Identity: totalEfectivo = totalAIngresar − saldoActual  (when gastos=ajustes=0)
 */
function cashToDeposit({
  totalEfectivo = 0,
  saldoActual = 0,
  gastos = 0,
  ajustes = 0,
} = {}) {
  return roundMoney(
    toNumber(totalEfectivo)
      + toNumber(saldoActual)
      - toNumber(gastos)
      + toNumber(ajustes),
  );
}

/**
 * Carry-forward debt written to REPARTIDOR_FINANCIAL_BALANCES.SALDO_PENDIENTE.
 * Only cash affects treasury debt; tarjeta/cheques/postdatados stay out.
 */
function computeClosingBalance({
  openingBalance = 0,
  cashPayments = 0,
  expenses = 0,
  adjustments = 0,
  bankDeposits = 0,
} = {}) {
  return roundMoney(
    toNumber(openingBalance)
      + toNumber(cashPayments)
      - toNumber(expenses)
      + toNumber(adjustments)
      - toNumber(bankDeposits),
  );
}

function sumCashPayments(payments = []) {
  return roundMoney(
    (Array.isArray(payments) ? payments : []).reduce((sum, payment) => {
      if (!isCashPaymentMethod(payment?.paymentMethod)) return sum;
      return sum + toNumber(payment?.amount);
    }, 0),
  );
}

function paymentTypeLabel(raw) {
  const value = String(raw || '').trim().toUpperCase();
  if (CASH_METHOD_RE.test(value)) return 'EFECTIVO';
  if (CARD_METHOD_RE.test(value)) return 'TARJETA';
  if (['TRANSFERENCIA', 'TR'].includes(value)) return 'TRANSFERENCIA';
  if (['BIZUM', 'BI'].includes(value)) return 'BIZUM';
  if (CHEQUE_METHOD_RE.test(value)) return 'CHEQUE';
  if (POSTDATED_METHOD_RE.test(value)) return 'POSTDATADO';
  return value || '—';
}

function paperDocumentLabel(cobro) {
  const explicit = String(cobro?.documento || '').trim();
  const tipo = String(cobro?.tipoDocumento || cobro?.tipoCobro || '').trim().toUpperCase();
  const letter = tipo.startsWith('F') ? 'F'
    : tipo.startsWith('P') ? 'P'
      : tipo.startsWith('E') || tipo === 'CAC' || tipo === 'ALB' ? 'E'
        : '';
  const terminal = Number(cobro?.terminalDocumento ?? cobro?.terminal);
  const numero = Number(cobro?.numeroDocumento ?? cobro?.numero);
  if (letter && Number.isFinite(numero) && numero > 0) {
    const term = Number.isFinite(terminal) ? terminal : 0;
    return `${letter} ${pad(term, 3)} ${pad(numero, 6)}`;
  }
  return explicit || '—';
}

function normalizeTotals(input = {}) {
  const totalEfectivo = roundMoney(input.totalEfectivo);
  const totalCheques = roundMoney(input.totalCheques);
  const totalTarjeta = roundMoney(input.totalTarjeta);
  const totalPostdatados = roundMoney(input.totalPostdatados);
  const saldoActual = roundMoney(input.saldoActual ?? input.saldoAnterior);
  const gastos = roundMoney(input.gastos);
  const ajustes = roundMoney(input.ajustes);
  const totalCobrosDia = roundMoney(
    input.totalCobrosDia
      ?? (totalEfectivo + totalCheques + totalTarjeta + totalPostdatados),
  );
  const totalAIngresar = roundMoney(
    input.totalAIngresar
      ?? cashToDeposit({
        totalEfectivo, saldoActual, gastos, ajustes,
      }),
  );
  const ingresoBanco = roundMoney(input.ingresoBanco);
  const diff = roundMoney(input.diff ?? (totalAIngresar - ingresoBanco));
  const saldoResultante = roundMoney(
    input.saldoResultante ?? computeClosingBalance({
      openingBalance: saldoActual,
      cashPayments: totalEfectivo,
      expenses: gastos,
      adjustments: ajustes,
      bankDeposits: ingresoBanco,
    }),
  );
  return {
    totalEfectivo,
    totalCheques,
    totalTarjeta,
    totalPostdatados,
    totalCobrosDia,
    saldoActual,
    gastos,
    ajustes,
    totalAIngresar,
    ingresoBanco,
    diff,
    saldoResultante,
  };
}

function drawCard(doc, {
  x, y, width, height, fill, border, label, value, valueColor,
}) {
  doc.roundedRect(x, y, width, height, 8).fillAndStroke(fill, border);
  doc.fillColor(MUTED).font('Helvetica').fontSize(7.5)
    .text(label, x + 10, y + 9, { width: width * 0.55 });
  doc.fillColor(valueColor || NAVY).font('Helvetica-Bold').fontSize(10)
    .text(value, x + width * 0.48, y + 8, {
      width: width * 0.48 - 12,
      align: 'right',
    });
  doc.font('Helvetica');
}

