          tipoCobro: paymentTypeLabel(cobro.tipoCobro),
          documento: paperDocumentLabel(cobro),
          importe: formatEuro(cobro.importe),
        };
        let cx = 40;
        doc.font('Helvetica').fontSize(7.5).fillColor(SLATE);
