            SELECT
                V.CODIGOVEHICULO AS code,
                V.MATRICULA      AS matricula,
                V.DESCRIPCIONVEHICULO AS description,
                V.CODIGOCONDUCTOR AS driverCode,
                V.TONELADAS      AS toneladas,
                V.CARGAMAXIMA    AS cargaMaxima
            FROM DSEDAC.VEH V
            ORDER BY V.CODIGOVEHICULO
