            options: {
                cacheKey: options,
                ttl,
                params: queryArgs.length > 0 ? { args: queryArgs } : {},
            },
            queryArgs,
        };
    }

    if (!options || typeof options !== 'object' || Array.isArray(options)) {
        const queryArgs = options === undefined ? args : [options, ...args];
        return {
            options: {
                params: queryArgs.length > 0 ? { args: queryArgs } : {},
            },
            queryArgs,
        };
    }

    return {
        options,
        queryArgs: args,
    };
