        const runNext = () => {
            const current = nextIndex;
            nextIndex += 1;
            if (current >= items.length) {
                return Promise.resolve();
            }
            return Promise.resolve(worker(items[current])).then(runNext);
        };

        await Promise.allSettled(Array.from({ length: safeLimit }, runNext));
