    _toSqlLiteral(id) {
        if (typeof id === 'number') {
            if (!Number.isFinite(id)) {
                throw new Error('Invalid batch id');
            }
            return String(id);
        }
        if (typeof id === 'string') {
            if (id.includes('\0')) {
                throw new Error('Invalid batch id');
            }
            return `'${id.replace(/'/g, "''")}'`;
        }
        throw new Error('Invalid batch id');
    }

