     * Convert single-value query to IN query
     */
    _createBatchedSQL(sql, ids) {
        const uniqueIds = [...new Set(ids)];
        const inList = uniqueIds.map(id => this._toSqlLiteral(id)).join(',');

        return sql.replace(/=\s*['"]?[^'")\s]+['"]?(\s|$)/i, `IN (${inList})$1`);
    }

