  if (!identity) return { codigo: '', nombre: '' };

  const params = [identity.ejercicio, identity.serie, identity.terminal, identity.numero];
  let sql = `
    SELECT TRIM(CPC.CODIGOCLIENTEALBARAN) AS CLIENTE,
