/**
 * After a newly created cobro: notify the driver and liquidacion recipients.
 * Replays and every directory/policy/SMTP failure are non-blocking.
 */
async function notifyAfterCobro({
  cobro,
  result,
} = {}, {
  query = queryWithParams,
  env = process.env,
  sendEmail = sendEmailWithPdf,
  resolveRecipients = resolveLiquidacionRecipients,
} = {}) {
  if (!result?.created || !cobro) {
    return { skipped: true, reason: 'not_created' };
  }

  try {
    const repartidorId = normalizeText(cobro.codigoRepartidor || cobro.repartidorId);
    const identity = normalizeText(
      result.id || result.cobroId || cobro.idempotencyToken,
    );
    if (!repartidorId || !identity) {
      return { skipped: true, reason: 'invalid_identity' };
    }

    const resolution = await resolveRecipients({ repartidorId }, { query, env });
    if ((resolution?.missingRequired || []).length > 0) {
      logger.warn('[cobro-notify] delivery deferred: unresolved required DB recipient');
      return { skipped: true, reason: 'unresolved_recipients' };
    }

    let delivery;
    try {
      delivery = resolveRepartoEmailDelivery({
        recipients: resolution?.emails || [],
        env,
        mode: 'automatic',
      });
    } catch (error) {
      logger.warn(`[cobro-notify] delivery policy rejected message: ${error.code || 'POLICY_REJECTED'}`);
      return { skipped: true, reason: 'policy_rejected' };
    }

    const amount = Number(cobro.importeCobrado);
    const payload = {
      cobroId: identity,
      documento: cobroDocumentLabel(cobro),
      codigoCliente: normalizeText(cobro.codigoCliente),
      nombreCliente: normalizeText(cobro.nombreCliente),
      repartidorId,
      importe: Number.isFinite(amount) ? amount.toFixed(2) : '0.00',
      pendiente: Number.isFinite(Number(cobro.importePendiente))
        ? Number(cobro.importePendiente).toFixed(2)
        : '0.00',
      formaPago: normalizeText(cobro.formaPago),
      origen: normalizeText(cobro.pantallaOrigen) || 'RUTERO',
      registradoAt: new Date().toISOString(),
      notas: normalizeText(cobro.notas),
    };
    const subject = `Cobro ${payload.documento} - ${payload.importe} EUR`;
    const htmlBody = buildCobroEmailHtml(payload);
    const textBody = [
      'ID de cobro: ' + payload.cobroId,
      'Documento: ' + payload.documento,
      ('Cliente: ' + payload.codigoCliente + ' ' + payload.nombreCliente).trim(),
      'Repartidor: ' + payload.repartidorId,
      'Importe: ' + payload.importe + ' EUR',
      'Pendiente tras el cobro: ' + payload.pendiente + ' EUR',
      'Forma de pago: ' + payload.formaPago,
      'Origen: ' + payload.origen,
    ].join('\n');

    const pdfBuffer = await buildCobroPdfBuffer(payload);
    const pdfFilename = buildCobroPdfFileName(payload);
    const results = [];
    for (const to of delivery.effectiveRecipients) {
      try {
        await sendEmail({
          to,
          subject,
          htmlBody,
          textBody,
          pdfBuffer,
          pdfFilename,
          messageId: buildRepartoMessageId({
            kind: 'cobro',
            identity,
            recipient: to,
            env,
          }),
        });
        results.push({ to, success: true });
      } catch (error) {
        logger.error('[cobro-notify] email failed', {
          code: normalizeText(error?.code) || 'SMTP_FAILURE',
        });
        results.push({ success: false });
      }
    }

    return {
      skipped: false,
      ...redactDeliverySummary(results),
    };
  } catch (error) {
    logger.warn('[cobro-notify] notification failed', {
      code: normalizeText(error?.code) || 'NOTIFICATION_FAILURE',
    });
    return { skipped: true, reason: 'notification_failed' };
  }
}

/**
 * After successful confirm: detect variance, enqueue, send immediate email.
 * Never throws to caller — failures are logged.
 */
async function notifyAfterConfirm({
  command,
  result,
} = {}, {
  query = queryWithParams,
  env = process.env,
  sendEmail = sendEmailWithPdf,
  resolveRecipients = resolveDeliveryVarianceRecipients,
  resolveComercial = resolveDocumentComercialCode,
  resolveClient = resolveDocumentClient,
} = {}) {
  if (!result?.created || !command?.delivery) {
    return { skipped: true, reason: 'not_created' };
  }

  const lineas = detectVarianceLines(command.delivery.lineas);
  const deliveryStatus = normalizeText(result.deliveryStatus || command.delivery.status).toUpperCase();
  const isExceptionStatus = ['PARCIAL', 'RECHAZADO', 'NO_ENTREGADO'].includes(deliveryStatus);
  // Exception states are operationally material even for a prepaid 0€ document.
  if (lineas.length === 0 && !isExceptionStatus) {
    return { skipped: true, reason: 'no_variance' };
  }

  const documentId = normalizeText(command.delivery.itemId);
  const repartidorId = normalizeText(
    command.delivery.repartidorId || command.actor?.repartidorId,
  );
  let comercialCode = '';
  try {
    comercialCode = await resolveComercial(documentId, { query });
  } catch (error) {
    logger.warn(`[variance] comercial resolve error: ${error.message}`);
  }

  const fecha = normalizeText(command.delivery.occurredAt).slice(0, 10)
    || new Date().toISOString().slice(0, 10);

  let clienteCodigo = normalizeText(command.cobro?.codigoCliente);
  let clienteNombre = normalizeText(command.cobro?.nombreCliente);
  if (!clienteCodigo || !clienteNombre) {
    try {
      const resolvedClient = await resolveClient(documentId, { query });
      clienteCodigo = clienteCodigo || normalizeText(resolvedClient?.codigo || resolvedClient?.code);
      clienteNombre = clienteNombre || normalizeText(resolvedClient?.nombre || resolvedClient?.name);
    } catch (error) {
      logger.warn(`[variance] client resolve error: ${error.message}`);
    }
  }
  const payload = {
    confirmationId: String(result.confirmationId),
    documentId,
    documentoTipo: 'ALBARAN',
    fecha,
    clienteCodigo,
    clienteNombre,
    repartidorId,
    comercialCode,
    deliveryStatus: normalizeText(result.deliveryStatus || command.delivery.status),
    confirmedAt: normalizeText(result.confirmedAt),
    observaciones: normalizeText(command.delivery.observaciones),
    lineas,
  };

  let outboxId = null;
  try {
    const tables = notificationTables(env);
    const existing = await query(
      `SELECT ID, STATUS
         FROM ${tables.varianceOutbox}
        WHERE CONFIRMATION_ID = ?
        ORDER BY ID
        FETCH FIRST 1 ROW ONLY`,
      [Number(result.confirmationId)],
    );
    if (existing?.length) {
      return {
        skipped: true,
        reason: 'already_enqueued',
        confirmationId: String(result.confirmationId),
      };
    }
    await enqueueVarianceOutbox({
      confirmationId: result.confirmationId,
      documentId,
      repartidorId,
      comercialCode,
      payload,
    }, { query, env });
    outboxId = Number(result.confirmationId);
  } catch (error) {
    logger.error(`[variance] outbox enqueue failed: ${error.message}`);
    // Never send before durable TEST/production app-state enqueue. Confirmation
    // remains successful; a transient DB failure is observable and cannot create
    // an untracked duplicate email.
    return {
      skipped: true,
      reason: 'outbox_unavailable',
      confirmationId: String(result.confirmationId),
    };
  }

  const { emails, details, missingRequired = [] } = await resolveRecipients({ repartidorId, comercialCode }, { query, env });
  const repartidorDetail = details.find((d) => d.label === 'repartidor');
  const comercialDetail = details.find((d) => d.label === 'comercial');
  payload.repartidorNombre = repartidorDetail?.nombre || '';
  payload.comercialNombre = comercialDetail?.nombre || '';

  let delivery;
  if ((missingRequired || []).length > 0 || details.some((detail) => !detail.email)) {
    logger.warn('[variance] delivery deferred: unresolved required DB recipient');
    delivery = { effectiveRecipients: [] };
  } else try {
    delivery = resolveRepartoEmailDelivery({ recipients: emails, env, mode: 'automatic' });
  } catch (error) {
    logger.warn(`[variance] delivery policy rejected message: ${error.code || error.message}`);
    delivery = { effectiveRecipients: [] };
  }
  const sendResult = await sendVarianceEmail(payload, delivery.effectiveRecipients, { sendEmail });
  payload.delivery = redactDeliverySummary(sendResult.results);

  if (outboxId != null) {
    try {
      const tables = notificationTables(env);
      const ok = payload.delivery.allSucceeded;
      if (ok) {
        await query(
          `UPDATE ${tables.varianceOutbox}
              SET STATUS = 'SENT', SENT_AT = CURRENT TIMESTAMP, ERROR = NULL, PAYLOAD_JSON = ?
            WHERE CONFIRMATION_ID = ? AND STATUS = 'PENDING'`,
          [JSON.stringify(payload), outboxId],
        );
      } else {
        await query(
          `UPDATE ${tables.varianceOutbox}
              SET STATUS = 'FAILED', ERROR = ?, PAYLOAD_JSON = ?
            WHERE CONFIRMATION_ID = ? AND STATUS = 'PENDING'`,
          ['No recipients or incomplete send', JSON.stringify(payload), outboxId],
        );
      }
    } catch (error) {
      logger.warn(`[variance] outbox status update failed: ${error.message}`);
    }
  }

  return { skipped: false, lineCount: lineas.length, ...sendResult, outboxId };
}

function previousMadridIsoDate(now = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Madrid',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now);
  const get = (type) => parts.find((part) => part.type === type)?.value;
  const year = Number(get('year'));
  const month = Number(get('month'));
  const day = Number(get('day'));
  const previous = new Date(Date.UTC(year, month - 1, day) - 24 * 60 * 60 * 1000);
  const y = previous.getUTCFullYear();
  const m = String(previous.getUTCMonth() + 1).padStart(2, '0');
  const d = String(previous.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/**
 * Daily digest: previous Europe/Madrid day, plus any earlier digest still awaiting
 * a fully successful delivery.
 */
async function sendDailyVarianceDigest({
  query = queryWithParams,
  env = process.env,
  sendEmail = sendHtmlEmail,
  resolveRecipients = resolveDeliveryVarianceRecipients,
  digestDate = previousMadridIsoDate(),
} = {}) {
  const tables = notificationTables(env);
  const sql = `
    SELECT ID, CONFIRMATION_ID, DOCUMENT_ID, REPARTIDOR_ID, COMERCIAL_CODE,
           PAYLOAD_JSON, STATUS, CREATED_AT, SENT_AT
      FROM ${tables.varianceOutbox}
     WHERE DIGEST_INCLUDED = 'N'
       AND (
         DATE(CREATED_AT) = ?
         OR (SENT_AT IS NOT NULL AND DATE(SENT_AT) = ?)
         OR STATUS IN ('PENDING', 'FAILED')
       )
       AND STATUS IN ('PENDING', 'SENT', 'FAILED')
     ORDER BY CREATED_AT
  `;
  let rows = [];
  try {
    rows = await query(sql, [digestDate, digestDate]);
  } catch (error) {
    logger.error(`[variance] digest query failed: ${error.message}`);
    throw error;
  }

  if (!rows.length) {
    logger.info(`[variance] digest: nothing to send for ${digestDate}`);
    return { sent: 0, items: 0, digestDate };
  }

  const items = rows.map((row) => ({
    id: rowValue(row, 'ID'),
    documentId: normalizeText(rowValue(row, 'DOCUMENT_ID')),
    repartidorId: normalizeText(rowValue(row, 'REPARTIDOR_ID')),
    comercialCode: normalizeVendorCode(rowValue(row, 'COMERCIAL_CODE')),
    createdAt: normalizeText(rowValue(row, 'CREATED_AT')),
    payload: safeJson(rowValue(row, 'PAYLOAD_JSON')),
  }));

  const emails = new Set();
  const missingRequired = new Set();
  let recipientResolutionFailed = false;
  function addResolution(resolution) {
    for (const email of resolution?.emails || []) emails.add(String(email).toLowerCase());
    for (const label of resolution?.missingRequired || []) missingRequired.add(String(label));
  }
  try {
    const roleRecipients = await resolveRecipients({}, { query, env });
    addResolution(roleRecipients);
    const driverCodes = [...new Set(items.map((item) => normalizeVendorCode(item.repartidorId)).filter(Boolean))];
    const comercialCodes = [...new Set(items.map((item) => normalizeVendorCode(item.comercialCode)).filter(Boolean))];
    // The directory has no batch recipient API. Resolve each unique vendor once,
    // never once per outbox row, retaining its cache and ERP fallback behavior.
    for (const code of driverCodes) {
      const extra = await resolveRecipients({ repartidorId: code }, { query, env });
      addResolution(extra);
    }
    for (const code of comercialCodes) {
      const extra = await resolveRecipients({ comercialCode: code }, { query, env });
      addResolution(extra);
    }
  } catch (error) {
    logger.error(`[variance] digest recipient resolution failed: ${error.message}`);
    recipientResolutionFailed = true;
  }

  const subject = `Resumen diario diferencias entrega ${digestDate} (${items.length})`;
  const htmlBody = buildDigestEmailHtml(items);
  const textBody = items.map((item) => (
    `${item.documentId} rep=${item.repartidorId} com=${item.comercialCode || ''} lines=${(item.payload.lineas || []).length}`
  )).join('\n');

  let delivery;
  const recipientFailureCount = missingRequired.size + (recipientResolutionFailed ? 1 : 0);
  if (recipientFailureCount > 0) {
    logger.warn(`[variance] digest delivery deferred: unresolved required DB recipients=${missingRequired.size}`);
    delivery = { effectiveRecipients: [] };
  } else try {
    delivery = resolveRepartoEmailDelivery({ recipients: [...emails], env, mode: 'automatic' });
  } catch (error) {
    logger.warn(`[variance] digest delivery policy rejected message: ${error.code || error.message}`);
    delivery = { effectiveRecipients: [] };
  }
  const results = [];
  const digestIdentity = `${digestDate}|${items.map((item) => item.id).filter((id) => id != null).sort().join(',')}`;
  for (const to of delivery.effectiveRecipients || []) {
    try {
      const result = await sendEmail({
        to, subject, htmlBody, textBody,
        messageId: buildRepartoMessageId({ kind: 'variance-digest', identity: digestIdentity, recipient: to, env }),
      });
      results.push({ to, success: true, result });
    } catch (error) {
      logger.error(`[variance] digest email failed recipient=${results.length + 1}/${delivery.effectiveRecipients.length}: ${String(error?.code || error?.message || 'smtp failure').replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[redacted-email]')}`);
      results.push({ to, success: false });
    }
  }
  const deliverySummary = redactDeliverySummary(results);

  const ids = items.map((item) => item.id).filter((id) => id != null);
  if (ids.length) {
    const placeholders = ids.map(() => '?').join(', ');
    try {
      if (deliverySummary.allSucceeded) {
        await query(
          `UPDATE ${tables.varianceOutbox} SET DIGEST_INCLUDED = 'S', ERROR = NULL WHERE ID IN (${placeholders})`,
          ids,
        );
      } else {
        const error = recipientFailureCount > 0
          ? `Digest pending: unresolved recipients (${recipientFailureCount})`
          : `Digest pending: ${deliverySummary.sent}/${deliverySummary.attempted} delivered`;
        await query(
          `UPDATE ${tables.varianceOutbox} SET ERROR = ? WHERE ID IN (${placeholders})`,
          [error, ...ids],
        );
      }
    } catch (error) {
      logger.error(`[variance] digest mark failed: ${error.message}`);
    }
  }

  logger.info(`[variance] digest sent=${deliverySummary.sent} items=${items.length} date=${digestDate}`);
  return {
    sent: deliverySummary.sent,
    items: items.length,
    digestDate,
    delivery: deliverySummary,
    unresolvedRecipients: recipientFailureCount,
  };
}

function rowValue(row, key) {
  if (!row) return undefined;
  if (Object.prototype.hasOwnProperty.call(row, key)) return row[key];
  const lower = key.toLowerCase();
  if (Object.prototype.hasOwnProperty.call(row, lower)) return row[lower];
  const upper = key.toUpperCase();
  if (Object.prototype.hasOwnProperty.call(row, upper)) return row[upper];
  return undefined;
}

module.exports = {
  detectVarianceLines,
  buildVarianceEmailHtml,
  buildDigestEmailHtml,
  previousMadridIsoDate,
  resolveDocumentComercialCode,
  resolveDocumentClient,
  notifyAfterCobro,
  notifyAfterConfirm,
  sendDailyVarianceDigest,
  enqueueVarianceOutbox,
  sendVarianceEmail,
};

/**
 * Request Coalescing - P4
 * Prevents duplicate requests: if same request is in-flight, wait for it instead of spawning new query
 */

const logger = require('../middleware/logger');

// In-flight requests map
const inFlightRequests = new Map();

/**
 * Execute or coalesce: if identical request is in-flight, wait for it
 * @param {string} key - Request unique key (e.g., hash of params)
 * @param {Function} fn - Function to execute if not in-flight
 * @param {number} ttl - Time to live for cache (ms), optional
 * @returns {Promise} Result from either current or in-flight request
 */
async function executeOrCoalesce(key, fn, ttl = 30000) {
    // Check if already in-flight
    if (inFlightRequests.has(key)) {
        logger.info(`[Coalescing] Request ${key.substring(0, 20)} already in-flight, waiting...`);
        return inFlightRequests.get(key);
    }

    // Create new request promise
    const promise = fn().finally(() => {
        // Remove from in-flight after completion
        inFlightRequests.delete(key);
    });

    inFlightRequests.set(key, promise);
    logger.info(`[Coalescing] New request ${key.substring(0, 20)} started, ${inFlightRequests.size} in-flight`);

    return promise;
}

/**
 * Generate unique key from request params
 */
function generateRequestKey(base, params) {
    const normalized = typeof params === 'object' 
        ? JSON.stringify(params) 
        : String(params);
    return `${base}:${normalized}`;
}

module.exports = {
    executeOrCoalesce,
    generateRequestKey,
    getInFlightCount: () => inFlightRequests.size
};

'use strict';

/**
 * Team visibility for commercial 80 (Almeria).
 * Members keep their normal individual commission calculation.
 * The leader special payout uses accumulated 80+72+73+81+83 sales,
 * with a fixed LY + 10% threshold and no IPC.
 */

const { queryWithParams } = require('../config/db');
const logger = require('../middleware/logger');

/**
 * Team lead (commercial 80) — flip here or env TEAM_LEAD_80_ENABLED=false.
 * When off: normal comercial view, no team panel/PDF section.
 */
const TEAM_LEAD_80_ENABLED =
    process.env.TEAM_LEAD_80_ENABLED !== 'false' &&
    process.env.TEAM_LEAD_80_ENABLED !== '0';

const TEAM_LEADER_CODES = new Set(['80']);
/** Four Almería commercials under Juan Luis (80) */
const ALMERIA_TEAM_MEMBERS_80 = ['72', '73', '81', '83'];
/** Scoped "Todos los comerciales" for login 80 */
const ALMERIA_TEAM_WITH_LEADER = ['80', ...ALMERIA_TEAM_MEMBERS_80];
const ALMERIA_TEAM_ACCUMULATED_80 = ['80', ...ALMERIA_TEAM_MEMBERS_80];
const TEAM_LEAD_GROWTH_THRESHOLD_PCT = 10;

const TEAM_CONFIG_BY_LEADER = {
    '80': {
        memberCodes: [...ALMERIA_TEAM_MEMBERS_80],
    },
};

function normalizeVendorCode(code) {
    const raw = String(code || '').trim();
    return raw.replace(/^0+/, '') || raw;
}

function normalizeUserCode(code) {
    return normalizeVendorCode(code);
}

/** Commercial 80 (Almería lead) — scoped "Todos" ≠ jefe global ALL */
function isCommercial80User(userCode) {
    return normalizeUserCode(userCode) === '80';
}

/**
 * Historical name kept for external callers/tests. This is the fixed growth
 * threshold for the 80 accumulated special, not IPC and not OBJ_CONFIG.
 */
const TEAM_LEAD_YOY_BONUS_PCT = TEAM_LEAD_GROWTH_THRESHOLD_PCT;

function isScopedTeamAllRequest(userCode, vendorCode) {
    const code = String(vendorCode || '').trim().toUpperCase();
    return code === 'ALL' && isCommercial80User(userCode);
}

/**
 * Resolve vendor list when vendedorCode=ALL.
 * Commercial 80 → sum ONLY 72,73,81,83 (excludes leader 80 personal sales).
 */
async function resolveAllModeVendorCodes(userCode, year, discoverAllFn) {
    if (isCommercial80User(userCode)) {
        return [...ALMERIA_TEAM_MEMBERS_80];
    }
    return discoverAllFn(year);
}

function resolveAllModeVendorCodesString(userCode) {
    if (isCommercial80User(userCode)) {
        return ALMERIA_TEAM_MEMBERS_80.join(',');
    }
    return 'ALL';
}

function allModeCacheScope(userCode, vendorCode) {
    if (isScopedTeamAllRequest(userCode, vendorCode)) return 'TEAM80';
    if (String(vendorCode || '').trim().toUpperCase() === 'ALL') return 'ALL';
    return null;
}

function isTeamLeader(vendorCode) {
    if (!TEAM_LEAD_80_ENABLED) return false;
    return TEAM_LEADER_CODES.has(normalizeVendorCode(vendorCode));
}

function filterTeamMembers(memberRows, leaderCode) {
    const allowed = new Set(ALMERIA_TEAM_MEMBERS_80);
    const leader = normalizeVendorCode(leaderCode);
    const fromDb = (memberRows || [])
        .map((r) => normalizeVendorCode(r.MEMBER_CODE || r.memberCode || r))
        .filter((c) => c && c !== leader && allowed.has(c));
    if (fromDb.length >= 4) {
        return [...new Set(fromDb)].sort();
    }
    return [...ALMERIA_TEAM_MEMBERS_80];
}

async function loadTeamCommissionConfig(leaderCode, year) {
    const leader = normalizeVendorCode(leaderCode);
    const staticCfg = TEAM_CONFIG_BY_LEADER[leader];
    if (!staticCfg) {
        logger.warn(`[TEAM_COMM] No in-code config for leader ${leader}`);
        return { leaderCode: leader, year, memberCodes: [] };
    }

    if (process.env.TEAM_COMMISSION_USE_DB === 'true') {
        try {
            const rules = await queryWithParams(
                `SELECT LEADER_CODE, YEAR
                 FROM JAVIER.TEAM_COMMISSION_RULES
                 WHERE LEADER_CODE = ? AND YEAR = ? AND ACTIVE = 'Y'
                 FETCH FIRST 1 ROWS ONLY`,
                [leader, year],
                false,
                false,
            );
            if (rules?.length) {
                const members = await queryWithParams(
                    `SELECT MEMBER_CODE
                     FROM JAVIER.TEAM_COMMISSION_MEMBERS
                     WHERE RULE_ID = (
                       SELECT ID FROM JAVIER.TEAM_COMMISSION_RULES
                       WHERE LEADER_CODE = ? AND YEAR = ? AND ACTIVE = 'Y'
                     ) AND ACTIVE = 'Y'
                     ORDER BY MEMBER_CODE`,
                    [leader, year],
                    false,
                    false,
                );
                const memberCodes = filterTeamMembers(members, leader);
                if (memberCodes.length >= 4) {
                    return { leaderCode: leader, year, memberCodes };
                }
            }
        } catch (e) {
            logger.warn(`[TEAM_COMM] DB override skipped for ${leader}: ${e.message}`);
        }
    }

    return {
        leaderCode: leader,
        year,
        memberCodes: filterTeamMembers(
            staticCfg.memberCodes.map((c) => ({ MEMBER_CODE: c })),
            leader,
        ),
    };
}

function monthMetricsFromVendorData(vendorData, month) {
    const md = (vendorData.months || []).find((m) => m.month === month) || {};
    const prevSales = md.prevSales ?? 0;
    const currentSales = md.actual ?? 0;
    const threshold = md.target ?? 0;
    const ctx = md.complianceCtx || {};
    const excess = Math.max(0, currentSales - threshold);
    const ownCommission = ctx.commission ?? 0;
    const qualifies = threshold > 0 && currentSales > threshold;

    return {
        prevSales,
        currentSales,
        threshold,
        excess,
        qualifies,
        commission: ownCommission,
        tier: ctx.tier ?? 0,
        rate: ctx.rate ?? 0,
    };
}

function calculateTierCommission(actual, target, config) {
    if (target <= 0) {
        return { commission: 0, tier: 0, rate: 0, increment: 0, compliancePct: 0 };
    }

    const compliancePct = (actual / target) * 100;
    const increment = actual - target;
    let rate = 0;
    let tier = 0;

    if (compliancePct > config.TIER3_MAX) {
        rate = config.TIER4_PCT;
        tier = 4;
    } else if (compliancePct > config.TIER2_MAX) {
        rate = config.TIER3_PCT;
        tier = 3;
    } else if (compliancePct > config.TIER1_MAX) {
        rate = config.TIER2_PCT;
        tier = 2;
    } else if (compliancePct > 100.00) {
        rate = config.TIER1_PCT;
        tier = 1;
    }

    return {
        commission: increment > 0 && rate > 0 ? increment * (rate / 100) : 0,
        tier,
        rate,
        increment,
        compliancePct,
    };
}

function buildAccumulatedTeamMetrics(leaderMetric, memberMetrics, config) {
    const allMetrics = [leaderMetric, ...memberMetrics];
    const prevSales = allMetrics.reduce((sum, metric) => sum + (metric.prevSales || 0), 0);
    const currentSales = allMetrics.reduce((sum, metric) => sum + (metric.currentSales || 0), 0);
    const threshold = prevSales * (1 + (TEAM_LEAD_GROWTH_THRESHOLD_PCT / 100));
    const result = calculateTierCommission(currentSales, threshold, config);

    return {
        prevSales,
        currentSales,
        threshold,
        excess: Math.max(0, currentSales - threshold),
        commission: result.commission,
        tier: result.tier,
        rate: result.rate,
        compliancePct: result.compliancePct,
        qualifies: threshold > 0 && currentSales > threshold,
        growthThresholdPct: TEAM_LEAD_GROWTH_THRESHOLD_PCT,
        memberCodes: [...ALMERIA_TEAM_ACCUMULATED_80],
    };
}

/**
 * @param {Function} calculateVendorData - (code, year, config) => vendor data
 */
async function calculateTeamMonth(leaderCode, year, month, config, calculateVendorData, vendorDataCache, teamConfig) {
    const leader = normalizeVendorCode(leaderCode);
    const members = [];

    if (!vendorDataCache.has(leader)) {
        vendorDataCache.set(leader, await calculateVendorData(leader, year, config));
    }
    const leaderData = vendorDataCache.get(leader);
    const leaderM = monthMetricsFromVendorData(leaderData, month);

    let qualifyingCount = 0;
    let membersIndividualExcess = 0;
    let membersIndividualCommission = 0;

    for (const memberCode of teamConfig.memberCodes) {
        if (!vendorDataCache.has(memberCode)) {
            vendorDataCache.set(memberCode, await calculateVendorData(memberCode, year, config));
        }
        const vendorData = vendorDataCache.get(memberCode);
        const m = monthMetricsFromVendorData(vendorData, month);

        if (m.qualifies) qualifyingCount += 1;
        membersIndividualExcess += m.excess;
        membersIndividualCommission += m.commission;

        members.push({
            vendorCode: memberCode,
            vendorName: vendorData.vendorName || memberCode,
            prevYearSales: m.prevSales,
            currentSales: m.currentSales,
            threshold: m.threshold,
            excess: m.excess,
            qualifies: m.qualifies,
            commission: m.commission,
            tier: m.tier,
        });
    }

    const accumulated = buildAccumulatedTeamMetrics(
        leaderM,
        members.map(member => ({
            prevSales: member.prevYearSales,
            currentSales: member.currentSales,
        })),
        config,
    );

    return {
        year,
        month,
        members,
        leaderPrevSales: leaderM.prevSales,
        leaderCurrentSales: leaderM.currentSales,
        leaderThreshold: leaderM.threshold,
        leaderExcess: leaderM.excess,
        leaderPersonalCommission: leaderM.commission,
        membersIndividualExcess,
        membersIndividualCommission,
        teamAggregatePrevSales: accumulated.prevSales,
        teamAggregateThreshold: accumulated.threshold,
        teamAggregateCurrentSales: accumulated.currentSales,
        teamAggregateExcess: accumulated.excess,
        teamAggregateCommission: accumulated.commission,
        teamAggregateTier: accumulated.tier,
        teamAggregateRate: accumulated.rate,
        teamAggregateCompliancePct: accumulated.compliancePct,
        teamAggregateQualifies: accumulated.qualifies,
        teamAggregateGrowthPct: accumulated.growthThresholdPct,
        teamAggregateCodes: accumulated.memberCodes,
        teamMembersExcess: accumulated.excess,
        teamMembersCommission: accumulated.commission,
        /** @deprecated use leaderExcess — kept for PDF/clients */
        totalExcess: leaderM.excess,
        totalCommission: 0,
        qualifyingMembers: qualifyingCount,
        allMembersQualified: false,
        config: {
            teamMemberCodes: teamConfig.memberCodes,
            accumulatedCodes: accumulated.memberCodes,
            formula: 'leader_accumulated_LY_plus_10_no_ipc',
        },
    };
}

async function getTeamCommission(leaderCode, year, calculateVendorData, config) {
    const leader = normalizeVendorCode(leaderCode);
    const teamConfig = await loadTeamCommissionConfig(leader, year);
    const vendorDataCache = new Map();
    const months = [];
    const currentMonth = new Date().getMonth() + 1;
    let annualTeamAggregateCommission = 0;
    let annualTeamAggregateExcess = 0;
    let annualMembersIndividualCommission = 0;
    let annualMembersIndividualExcess = 0;
    let annualLeaderExcess = 0;

    for (let m = 1; m <= 12; m++) {
        const result = await calculateTeamMonth(
            leader,
            year,
            m,
            config,
            calculateVendorData,
            vendorDataCache,
            teamConfig,
        );
        months.push(result);
        annualTeamAggregateCommission += result.teamAggregateCommission;
        annualTeamAggregateExcess += result.teamAggregateExcess;
        annualMembersIndividualCommission += result.membersIndividualCommission;
        annualMembersIndividualExcess += result.membersIndividualExcess;
        annualLeaderExcess += result.leaderExcess;
    }

    const leaderData = vendorDataCache.get(leader) || (await calculateVendorData(leader, year, config));

    return {
        success: true,
        year,
        leaderCode: leader,
        months,
        annualTotal: 0,
        annualExcess: annualLeaderExcess,
        annualTeamAggregateExcess,
        annualTeamAggregateCommission,
        annualMembersIndividualExcess,
        annualMembersIndividualCommission,
        annualTeamMembersExcess: annualTeamAggregateExcess,
        annualTeamMembersCommission: annualTeamAggregateCommission,
        arrearsTotal: 0,
        leaderPersonalCommission: leaderData.grandTotalCommission ?? 0,
        teamMembers: teamConfig.memberCodes,
        accumulatedCodes: [...ALMERIA_TEAM_ACCUMULATED_80],
        growthThresholdPct: TEAM_LEAD_GROWTH_THRESHOLD_PCT,
        config: {
            formula: 'leader_accumulated_LY_plus_10_no_ipc',
        },
        currentMonth,
    };
}

/**
 * Team-lead API payload: personal months from calculateVendorData + team breakdown.
 */
function buildTeamLeadSummaryPayload(leaderPersonal, teamData, config, payments) {
    return {
        config,
        grandTotalCommission: leaderPersonal.grandTotalCommission ?? 0,
        totals: { commission: leaderPersonal.grandTotalCommission ?? 0 },
        months: leaderPersonal.months ?? [],
        quarters: leaderPersonal.quarters ?? [],
        vendor: teamData.leaderCode,
        breakdown: [],
        isExcluded: leaderPersonal.isExcluded ?? false,
        isTeamLead: true,
        hidePersonalCommissionBadge: leaderPersonal.isExcluded ?? false,
        teamCommission: teamData,
        payments: payments || leaderPersonal.payments || { monthly: {}, quarterly: {}, total: 0 },
    };
}

module.exports = {
    TEAM_LEAD_80_ENABLED,
    TEAM_LEADER_CODES,
    ALMERIA_TEAM_MEMBERS_80,
    ALMERIA_TEAM_WITH_LEADER,
    ALMERIA_TEAM_ACCUMULATED_80,
    TEAM_LEAD_GROWTH_THRESHOLD_PCT,
    TEAM_LEAD_YOY_BONUS_PCT,
    isTeamLeader,
    isCommercial80User,
    isScopedTeamAllRequest,
    resolveAllModeVendorCodes,
    resolveAllModeVendorCodesString,
    allModeCacheScope,
    loadTeamCommissionConfig,
    getTeamCommission,
    buildTeamLeadSummaryPayload,
    monthMetricsFromVendorData,
    calculateTierCommission,
};

/**
 * GMP App - WebSocket Cache Manager
 * ===================================
 * Real-time cache invalidation via WebSockets
 * Enables instant cache sync across all connected clients
 */

const WebSocket = require('ws');
const logger = require('../middleware/logger');
const { redisCache } = require('./redis-cache');

// Configuration
const WS_PORT = parseInt(process.env.WS_PORT, 10) || 3335;
const HEARTBEAT_INTERVAL = 30000; // 30 seconds

class WebSocketCacheManager {
    constructor() {
        this.wss = null;
        this.clients = new Map(); // clientId -> { ws, subscriptions, lastHeartbeat }
        this.heartbeatInterval = null;
        this.messageHandlers = new Map();
        this.stats = {
            totalConnections: 0,
            activeConnections: 0,
            messagesReceived: 0,
            messagesSent: 0,
            invalidationsBroadcast: 0,
        };
    }

    /**
     * Initialize WebSocket server
     */
    init(server = null) {
        try {
            if (server) {
                // Attach to existing HTTP server
                this.wss = new WebSocket.Server({ server, path: '/ws/cache' });
            } else {
                // Create standalone server
                this.wss = new WebSocket.Server({ port: WS_PORT });
            }

            this.wss.on('connection', (ws, req) => this._handleConnection(ws, req));
            this.wss.on('error', (error) => {
                logger.error(`[WSCache] Server error: ${error.message}`);
            });

            // Start heartbeat checker
            this._startHeartbeat();

            // Setup message handlers
            this._setupMessageHandlers();

            logger.info(`[WSCache] ✅ WebSocket server started on port ${WS_PORT}`);
            return true;
        } catch (error) {
            logger.error(`[WSCache] ❌ Failed to start: ${error.message}`);
            return false;
        }
    }

    /**
     * Handle new WebSocket connection
     */
    _handleConnection(ws, req) {
        const clientId = this._generateClientId();
        const clientIp = req.socket.remoteAddress;

        // Store client
        this.clients.set(clientId, {
            ws,
            subscriptions: new Set(['default']),
            lastHeartbeat: Date.now(),
            ip: clientIp,
            connectedAt: new Date(),
        });

        this.stats.totalConnections++;
        this.stats.activeConnections = this.clients.size;

        logger.info(`[WSCache] Client connected: ${clientId} from ${clientIp}`);

        // Send welcome message with client ID
        this._send(ws, {
            type: 'connected',
            clientId,
            timestamp: new Date().toISOString(),
        });

        // Handle messages
        ws.on('message', (data) => {
            this.stats.messagesReceived++;
            this._handleMessage(clientId, data);
        });

        // Handle disconnect
        ws.on('close', () => {
            this.clients.delete(clientId);
            this.stats.activeConnections = this.clients.size;
            logger.info(`[WSCache] Client disconnected: ${clientId}`);
        });

        // Handle errors
        ws.on('error', (error) => {
            logger.warn(`[WSCache] Client ${clientId} error: ${error.message}`);
        });

        // Handle pong (heartbeat response)
        ws.on('pong', () => {
            const client = this.clients.get(clientId);
            if (client) {
                client.lastHeartbeat = Date.now();
            }
        });
    }

    /**
     * Setup message handlers
     */
    _setupMessageHandlers() {
        // Subscribe to cache keys
        this.messageHandlers.set('subscribe', (clientId, data) => {
            const client = this.clients.get(clientId);
            if (client && data.channels) {
                data.channels.forEach(channel => client.subscriptions.add(channel));
                logger.info(`[WSCache] Client ${clientId} subscribed to: ${data.channels.join(', ')}`);
            }
        });

        // Unsubscribe from cache keys
        this.messageHandlers.set('unsubscribe', (clientId, data) => {
            const client = this.clients.get(clientId);
            if (client && data.channels) {
                data.channels.forEach(channel => client.subscriptions.delete(channel));
            }
        });

        // Request cache invalidation
        this.messageHandlers.set('invalidate', (clientId, data) => {
            if (data.pattern) {
                this.broadcastInvalidation(data.pattern, clientId);
            }
        });

        // Heartbeat
        this.messageHandlers.set('ping', (clientId) => {
            const client = this.clients.get(clientId);
            if (client) {
                client.lastHeartbeat = Date.now();
                this._send(client.ws, { type: 'pong', timestamp: Date.now() });
            }
        });
    }

    /**
     * Handle incoming message
     */
    _handleMessage(clientId, rawData) {
        try {
            const data = JSON.parse(rawData.toString());
            const handler = this.messageHandlers.get(data.type);

            if (handler) {
                handler(clientId, data);
            } else {
                logger.warn(`[WSCache] Unknown message type: ${data.type}`);
            }
        } catch (error) {
            logger.warn(`[WSCache] Invalid message from ${clientId}: ${error.message}`);
        }
    }

    /**
     * Broadcast cache invalidation to all subscribed clients
     */
    broadcastInvalidation(pattern, excludeClientId = null) {
        const message = {
            type: 'cache_invalidation',
            pattern,
            timestamp: new Date().toISOString(),
        };

        let sentCount = 0;
        for (const [clientId, client] of this.clients) {
            if (clientId === excludeClientId) continue;

            // Check if client is subscribed to this pattern
            if (this._matchesSubscription(pattern, client.subscriptions)) {
                if (this._send(client.ws, message)) {
                    sentCount++;
                }
            }
        }

        // Also invalidate in Redis cache
        redisCache.invalidatePattern(pattern).catch(err => {
            logger.warn(`[WSCache] Redis invalidation failed: ${err.message}`);
        });

        this.stats.invalidationsBroadcast++;
        logger.info(`[WSCache] 📢 Broadcast invalidation: ${pattern} (${sentCount} clients)`);

        return sentCount;
    }

    /**
     * Check if pattern matches any subscription
     */
    _matchesSubscription(pattern, subscriptions) {
        if (subscriptions.has('default') || subscriptions.has('*')) {
            return true;
        }

        for (const sub of subscriptions) {
            if (pattern.startsWith(sub) || sub.startsWith(pattern.split('*')[0])) {
                return true;
            }
        }

        return false;
    }

    /**
     * Send message to client
     */
    _send(ws, data) {
        try {
            if (ws.readyState === WebSocket.OPEN) {
                ws.send(JSON.stringify(data));
                this.stats.messagesSent++;
                return true;
            }
        } catch (error) {
            logger.warn(`[WSCache] Send error: ${error.message}`);
        }
        return false;
    }

    /**
     * Start heartbeat checker
     */
    _startHeartbeat() {
        this.heartbeatInterval = setInterval(() => {
            const now = Date.now();
            const timeout = HEARTBEAT_INTERVAL * 2;

            for (const [clientId, client] of this.clients) {
                if (now - client.lastHeartbeat > timeout) {
                    // Client unresponsive, terminate
                    logger.warn(`[WSCache] Client ${clientId} unresponsive, terminating`);
                    client.ws.terminate();
                    this.clients.delete(clientId);
                } else {
                    // Send ping
                    if (client.ws.readyState === WebSocket.OPEN) {
                        client.ws.ping();
                    }
                }
            }

            this.stats.activeConnections = this.clients.size;
        }, HEARTBEAT_INTERVAL);
    }

    /**
     * Generate unique client ID
     */
    _generateClientId() {
        return `client_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    }

    /**
     * Get connection statistics
     */
    getStats() {
        return {
            ...this.stats,
            clients: Array.from(this.clients.entries()).map(([id, client]) => ({
                id,
                ip: client.ip,
                subscriptions: Array.from(client.subscriptions),
                connectedAt: client.connectedAt,
                lastHeartbeat: new Date(client.lastHeartbeat),
            })),
        };
    }

    /**
     * Notify all clients of data change
     * Use this when data is updated via API
     */
    notifyDataChange(entityType, entityId, action = 'updated') {
        const pattern = `${entityType}:*`;
        const message = {
            type: 'data_change',
            entityType,
            entityId,
            action, // 'created', 'updated', 'deleted'
            timestamp: new Date().toISOString(),
        };

        // Broadcast to all clients
        for (const [clientId, client] of this.clients) {
            this._send(client.ws, message);
        }

        // Invalidate cache
        this.broadcastInvalidation(pattern);
    }

    /**
     * Shutdown WebSocket server
     */
    shutdown() {
        if (this.heartbeatInterval) {
            clearInterval(this.heartbeatInterval);
            this.heartbeatInterval = null;
        }

        if (this.wss) {
            for (const [clientId, client] of this.clients) {
                client.ws.close(1000, 'Server shutting down');
            }

            this.wss.close(() => {
                logger.info('[WSCache] Server shutdown complete');
            });
        }
    }

    /**
     * Close WebSocket server (alias for shutdown)
     */
    close() {
        this.shutdown();
    }
}

// Singleton instance
const wsCacheManager = new WebSocketCacheManager();

module.exports = {
    wsCacheManager,
    initWSCache: (server) => wsCacheManager.init(server),
    broadcastInvalidation: (pattern) => wsCacheManager.broadcastInvalidation(pattern),
    notifyDataChange: (type, id, action) => wsCacheManager.notifyDataChange(type, id, action),
    getWSStats: () => wsCacheManager.getStats(),
};

/**
 * Free corporate WhatsApp gateway via Baileys (WhatsApp Web multi-device).
 *
 * NOT Meta WhatsApp Business API. Links a normal company phone (QR once) and
 * sends text + PDF from that number — same UX as a "bot" for the recipient.
 *
 * Trade-offs (senior notes):
 * - €0 / no WABA / no templates
 * - Violates WhatsApp ToS if abused; use a dedicated company SIM, low volume,
 *   human-like cadence. Ban risk exists.
 * - Session must stay on the server (auth files + reconnect).
 *
 * Env:
 *   WHATSAPP_BAILEYS_ENABLED=true
 *   WHATSAPP_BAILEYS_AUTH_DIR=/opt/gmp-api/data/whatsapp-baileys  (optional)
 *   WHATSAPP_BAILEYS_MIN_INTERVAL_MS=2500                         (optional)
 */

'use strict';

const fs = require('fs');
const path = require('path');
const logger = require('../middleware/logger');

const DEFAULT_AUTH_DIR = path.join(__dirname, '../data/whatsapp-baileys');
const MIN_INTERVAL_MS = Math.max(
  500,
  parseInt(process.env.WHATSAPP_BAILEYS_MIN_INTERVAL_MS || '2500', 10) || 2500,
);

let sock = null;
let starting = null;
let connectionStatus = 'idle'; // idle | connecting | qr | open | close
let lastQr = null;
let lastQrAt = 0;
let lastSendAt = 0;
let sendChain = Promise.resolve();

function isEnabled() {
  return String(process.env.WHATSAPP_BAILEYS_ENABLED || '').toLowerCase() === 'true';
}

function authDir() {
  const fromEnv = String(process.env.WHATSAPP_BAILEYS_AUTH_DIR || '').trim();
  return fromEnv || DEFAULT_AUTH_DIR;
}

function ensureAuthDir() {
  const dir = authDir();
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function normalizeE164Digits(phone) {
  const digits = String(phone || '').replace(/\D/g, '');
  if (!/^\d{7,15}$/.test(digits)) {
    const err = new Error('PHONE_INVALID');
    err.code = 'PHONE_INVALID';
    throw err;
  }
  if (digits.length === 9 && digits.startsWith('6')) {
    return `34${digits}`;
  }
  return digits;
}

function toJid(phone) {
  return `${normalizeE164Digits(phone)}@s.whatsapp.net`;
}

function getStatus() {
  return {
    provider: 'BAILEYS',
    enabled: isEnabled(),
    status: connectionStatus,
    ready: connectionStatus === 'open' && Boolean(sock),
    hasQr: Boolean(lastQr) && connectionStatus === 'qr',
    qrAgeMs: lastQr ? Date.now() - lastQrAt : null,
    authDir: authDir(),
  };
}

async function loadBaileys() {
  // CJS-friendly require of the published package.
  // eslint-disable-next-line import/no-extraneous-dependencies
  const baileys = require('@whiskeysockets/baileys');
  return baileys;
}

async function startSocket({ forceNewQr = false } = {}) {
  if (!isEnabled()) {
    const err = new Error('Baileys gateway disabled');
    err.code = 'WHATSAPP_BAILEYS_DISABLED';
    throw err;
  }
  if (starting) return starting;
  if (sock && connectionStatus === 'open' && !forceNewQr) {
    return sock;
  }

  starting = (async () => {
    const baileys = await loadBaileys();
    const makeWASocket = baileys.default || baileys.makeWASocket;
    const {
      useMultiFileAuthState,
      DisconnectReason,
      fetchLatestBaileysVersion,
      Browsers,
    } = baileys;

    const dir = ensureAuthDir();
    if (forceNewQr) {
      try {
        for (const name of fs.readdirSync(dir)) {
          fs.rmSync(path.join(dir, name), { recursive: true, force: true });
        }
      } catch (error) {
        logger.warn('[WhatsAppBaileys] could not clear auth dir', { message: error.message });
      }
      sock = null;
      connectionStatus = 'connecting';
      lastQr = null;
    }

    const { state, saveCreds } = await useMultiFileAuthState(dir);
    let version;
    try {
      ({ version } = await fetchLatestBaileysVersion());
    } catch {
      version = undefined;
    }

    connectionStatus = 'connecting';
    const socket = makeWASocket({
      version,
      auth: state,
      printQRInTerminal: false,
      browser: Browsers?.ubuntu?.('Chrome') || ['GMP', 'Chrome', '1.0.0'],
      syncFullHistory: false,
      markOnlineOnConnect: false,
    });

    socket.ev.on('creds.update', saveCreds);
    socket.ev.on('connection.update', (update) => {
      const { connection, lastDisconnect, qr } = update || {};
      if (qr) {
        lastQr = qr;
        lastQrAt = Date.now();
        connectionStatus = 'qr';
        logger.info('[WhatsAppBaileys] QR ready — scan with company phone (Dispositivos vinculados)');
      }
      if (connection === 'open') {
        connectionStatus = 'open';
        lastQr = null;
        logger.info('[WhatsAppBaileys] session open');
      }
      if (connection === 'close') {
        connectionStatus = 'close';
        const statusCode = lastDisconnect?.error?.output?.statusCode;
        const loggedOut = statusCode === DisconnectReason.loggedOut;
        sock = null;
        starting = null;
        logger.warn('[WhatsAppBaileys] connection closed', { statusCode, loggedOut });
        if (!loggedOut && isEnabled()) {
          setTimeout(() => {
            startSocket().catch((error) => {
              logger.error('[WhatsAppBaileys] reconnect failed', { message: error.message });
            });
          }, 3000);
        }
      }
    });

    sock = socket;
    return socket;
  })();

  try {
    return await starting;
  } finally {
    // keep starting until open/qr settles; clear only on failure
    if (connectionStatus === 'close') {
      starting = null;
    }
  }
}

async function ensureReady() {
  if (!isEnabled()) return false;
  if (connectionStatus === 'open' && sock) return true;
  await startSocket();
  // Wait briefly for open after restart with existing creds.
  const deadline = Date.now() + 15000;
  while (Date.now() < deadline) {
    if (connectionStatus === 'open' && sock) return true;
