                        quantity: parseFloat(line.CANTIDAD) || 0,
                        unitPrice: parseFloat(line.PRECIO) || 0,
                        amount: parseFloat(line.IMPORTE) || 0,
                    }));
                }
            }
        }

        return runPdfExtraction(conn, invoiceTools, { documentType, reference, albaranLines });
    },
};

