/**
 * DB2 Connection Pool Manager
 * Wraps the legacy db.js with a cleaner interface for DDD modules
 */
const { query, queryWithParams, getPool, initDb } = require('../../../../config/db');
const odbc = require('odbc');
const logger = require('../../../../middleware/logger');

class Db2ConnectionPool {
  constructor() {
    this._initialized = false;
  }

  async initialize() {
    if (!this._initialized) {
      await initDb();
      this._initialized = true;
    }
    return this;
  }

  async execute(sql) {
    return query(sql, true, true);
  }

  async executeParams(sql, params) {
    return queryWithParams(sql, params, true, true);
  }

  async executeSilent(sql) {
    return query(sql, false, false);
  }

  async executeParamsSilent(sql, params) {
    return queryWithParams(sql, params, false, false);
  }

  /**
   * Execute multiple SQL statements within a single transaction.
   * If any statement fails, all changes are rolled back.
   * @param {Function} callback - Async function receiving a transaction connection
   * @returns {Promise<any>} Result from the callback
   */
  async transaction(callback) {
    const pool = getPool();
    if (!pool) {
      await initDb();
      const newPool = getPool();
      if (!newPool) throw new Error('Database pool not initialized');
    }

    const conn = await (getPool() || await initDb() && getPool()).connect();
    try {
      await conn.query('BEGIN WORK');
      const result = await callback(conn);
      await conn.query('COMMIT');
      return result;
    } catch (err) {
      try {
        await conn.query('ROLLBACK');
      } catch (rollbackErr) {
        logger.error(`[TX] Rollback failed: ${rollbackErr.message}`);
      }
      throw err;
    } finally {
      try { await conn.close(); } catch (_) { }
    }
  }

  /**
   * Direct connection access for transactional operations.
   * Caller is responsible for closing the connection.
   */
  async getConnection() {
    const pool = getPool();
    if (!pool) {
      await initDb();
    }
    return getPool().connect();
  }

  getPool() {
    return getPool();
  }

  isInitialized() {
    return this._initialized;
  }
}

module.exports = { Db2ConnectionPool };

/**
 * Advanced Rate Limiter - Per-role, per-IP, per-user rate limiting
 * Prevents abuse while allowing legitimate heavy usage (JEFE ALL queries)
 */

const logger = require('../../../../middleware/logger');
const rateLimitStore = new Map();

const ROLE_LIMITS = {
  JEFE_VENTAS: {
    windowMs: 60000,       // 1 minute window
    maxRequests: 500,       // Increased from 200 to support multi-vendor queries
    maxAllQueries: 100,     // Increased from 30 for jefe with many vendors
    maxConcurrent: 10       // Increased from 5 for parallel loading
  },
  COMERCIAL: {
    windowMs: 60000,
    maxRequests: 300,       // Increased from 150
    maxAllQueries: 50,      // Increased from 10
    maxConcurrent: 5        // Increased from 3
  },
  REPARTIDOR: {
    windowMs: 60000,
    maxRequests: 200,       // Increased from 100
    maxAllQueries: 30,      // Increased from 5
    maxConcurrent: 5        // Increased from 2
  }
};

const IP_LIMITS = {
  windowMs: 900000,     // 15 minutes
  maxRequests: 1000
};

class AdvancedRateLimiter {
  constructor() {
    this._userStore = new Map();
    this._ipStore = new Map();
    this._endpointStore = new Map();
    this._concurrentStore = new Map();
    this._cleanupInterval = null;
  }

  /**
   * Start periodic cleanup
   */
  startCleanup() {
    if (this._cleanupInterval) return; // Already running
    this._cleanupInterval = setInterval(() => this.cleanup(), 300000);
    logger.info('[RateLimiter] Cleanup interval started');
  }

  /**
   * Stop periodic cleanup - call on shutdown
   */
  stopCleanup() {
    if (this._cleanupInterval) {
      clearInterval(this._cleanupInterval);
      this._cleanupInterval = null;
      logger.info('[RateLimiter] Cleanup interval stopped');
    }
  }

  /**
   * Clean expired entries periodically
   */
  cleanup() {
    const now = Date.now();
    for (const [key, store] of Object.entries({
      user: this._userStore,
      ip: this._ipStore,
      endpoint: this._endpointStore
    })) {
      for (const [k, entry] of store.entries()) {
        if (now > entry.windowEnd) {
          store.delete(k);
        }
      }
    }
  }

  /**
   * Check rate limit for a request
   */
  check(req, role = 'COMERCIAL') {
    const now = Date.now();
    const ip = req.ip || req.connection?.remoteAddress || 'unknown';
    const userId = req.user?.code || 'anonymous';
    const endpoint = req.path;
    const isAllQuery = req.query.vendedorCodes === 'ALL';

    const roleLimits = ROLE_LIMITS[role] || ROLE_LIMITS.COMERCIAL;

    // IP-based check
    const ipKey = ip;
    const ipEntry = this._getOrCreateEntry(this._ipStore, ipKey, IP_LIMITS.windowMs);
    if (ipEntry.count >= IP_LIMITS.maxRequests) {
      return {
        allowed: false,
        reason: 'IP_RATE_LIMIT_EXCEEDED',
        retryAfter: Math.ceil((ipEntry.windowEnd - now) / 1000)
      };
    }
    ipEntry.count++;

    // User-based check
    const userKey = `${userId}:${role}`;
    const userEntry = this._getOrCreateEntry(this._userStore, userKey, roleLimits.windowMs);
    if (userEntry.count >= roleLimits.maxRequests) {
      return {
        allowed: false,
        reason: 'USER_RATE_LIMIT_EXCEEDED',
        retryAfter: Math.ceil((userEntry.windowEnd - now) / 1000)
      };
    }
    userEntry.count++;

    // ALL query check (stricter limit)
    if (isAllQuery) {
      const allKey = `${userId}:ALL`;
      const allEntry = this._getOrCreateEntry(this._endpointStore, allKey, roleLimits.windowMs);
      if (allEntry.count >= roleLimits.maxAllQueries) {
        return {
