    const userPayload = {
      id: session.userId,
      user: session.userCode,
      role: session.role
    };

    const newTokens = await this.generateTokenPair({
      ...userPayload,
      ip: session.ip,
      userAgent: session.userAgent
    });

    // Update rotation count
    session.rotationCount++;
    session.createdAt = Date.now();
