class GrowthRate {
  constructor({ metric, currentPeriod, previousPeriod, rate, trend }) {
    this._metric = metric;
    this._currentPeriod = currentPeriod || 0;
    this._previousPeriod = previousPeriod || 0;
    this._rate = rate || 0;
    this._trend = trend || 'stable';
