/**
 * Auth Repository Implementation - DB2
 */
const { AuthRepository } = require('../domain/auth-repository');
const { User } = require('../domain/user');
const { Db2ConnectionPool } = require('../../../core/infrastructure/database/db2-connection-pool');
const { getVendorVisibilityScope } = require('../../../../utils/common');
const { createRepartidorFleetDirectory } = require('./repartidor-fleet-directory');

const ERP_MOBILITY_PROFILE_SELECT = `
        COALESCE((
          SELECT MAX(NULLIF(TRIM(X.PERMITEPREVENTASN), ''))
          FROM DSEDAC.VDDX X
          WHERE X.CODIGOVENDEDOR = P.CODIGOVENDEDOR
        ), '') AS PREVENTISTA_SN,
        COALESCE((
          SELECT MAX(NULLIF(TRIM(X.PERMITEREPARTOSN), ''))
          FROM DSEDAC.VDDX X
          WHERE X.CODIGOVENDEDOR = P.CODIGOVENDEDOR
        ), '') AS REPARTIDOR_SN,
        COALESCE((
          SELECT MAX(NULLIF(TRIM(X.JEFEVENTASSN), ''))
          FROM DSEDAC.VDDX X
          WHERE X.CODIGOVENDEDOR = P.CODIGOVENDEDOR
        ), '') AS JEFE_SN,
        COALESCE((
          SELECT TRIM(V.CODIGOVEHICULO)
          FROM DSEDAC.VEH V
          WHERE TRIM(V.CODIGOCONDUCTOR) = P.CODIGOVENDEDOR
          FETCH FIRST 1 ROW ONLY
        ), '') AS MATRICULA`;

const ERP_ROLE_SELECT = `
        CASE
          WHEN (
            SELECT MAX(NULLIF(TRIM(X.JEFEVENTASSN), ''))
            FROM DSEDAC.VDDX X
            WHERE X.CODIGOVENDEDOR = P.CODIGOVENDEDOR
          ) = 'S' THEN 'JEFE_VENTAS'
          WHEN (
            SELECT MAX(NULLIF(TRIM(X.PERMITEREPARTOSN), ''))
            FROM DSEDAC.VDDX X
            WHERE X.CODIGOVENDEDOR = P.CODIGOVENDEDOR
          ) = 'S'
          AND COALESCE((
            SELECT MAX(NULLIF(TRIM(X.PERMITEPREVENTASN), ''))
            FROM DSEDAC.VDDX X
            WHERE X.CODIGOVENDEDOR = P.CODIGOVENDEDOR
          ), '') <> 'S'
          THEN 'REPARTIDOR'
          ELSE 'COMERCIAL'
        END AS ROL`;

class Db2AuthRepository extends AuthRepository {
  constructor(dbPool, { repartidorFleetDirectory } = {}) {
    super();
    this._db = dbPool || new Db2ConnectionPool();
    this._repartidorFleetDirectory = repartidorFleetDirectory
      || createRepartidorFleetDirectory({ execute: (sql) => this._db.execute(sql) });
  }

  async findByCode(code) {
    const requested = String(code || '').trim();
    if (!requested || requested.length > 50) return null;

    const codeSql = `
      SELECT TRIM(P.CODIGOVENDEDOR) AS USUARIO,
        TRIM(D.NOMBREVENDEDOR) AS NOMBRE,
        ${ERP_ROLE_SELECT},
        ${ERP_MOBILITY_PROFILE_SELECT},
        COALESCE((
          SELECT MAX(NULLIF(TRIM(V2.TIPOVENDEDOR), ''))
          FROM DSEDAC.VDC V2
          WHERE V2.CODIGOVENDEDOR = P.CODIGOVENDEDOR
            AND V2.SUBEMPRESA = 'GMP'
        ), '-') AS TIPOVENDEDOR,
        COALESCE((
          SELECT MAX(NULLIF(TRIM(E.HIDE_COMMISSIONS), ''))
          FROM JAVIER.COMMISSION_EXCEPTIONS E
          WHERE E.CODIGOVENDEDOR = P.CODIGOVENDEDOR
        ), 'N') AS HIDE_COMMISSIONS,
        '' AS EMAIL, P.CODIGOPIN AS PASSWORD_HASH, 1 AS ACTIVO
      FROM DSEDAC.VDPL1 P
      JOIN DSEDAC.VDD D ON P.CODIGOVENDEDOR = D.CODIGOVENDEDOR
      WHERE EXISTS (
        SELECT 1 FROM DSEDAC.VDC V
        WHERE V.CODIGOVENDEDOR = P.CODIGOVENDEDOR
          AND V.SUBEMPRESA = 'GMP'
      )
      AND COALESCE(NULLIF(TRIM(P.ESTADO), ''), '') <> 'A'
        AND TRIM(P.CODIGOVENDEDOR) = CAST(? AS VARCHAR(50))
      ORDER BY TRIM(P.CODIGOVENDEDOR)
      FETCH FIRST 2 ROWS ONLY
    `;
    let result = await this._db.executeParams(codeSql, [requested]);
    if (Array.isArray(result) && result.length > 1) return null;

    if (!Array.isArray(result) || result.length === 0) {
      const nameSql = `
        SELECT TRIM(P.CODIGOVENDEDOR) AS USUARIO,
          TRIM(D.NOMBREVENDEDOR) AS NOMBRE,
          ${ERP_ROLE_SELECT},
          ${ERP_MOBILITY_PROFILE_SELECT},
          COALESCE((
            SELECT MAX(NULLIF(TRIM(V2.TIPOVENDEDOR), ''))
            FROM DSEDAC.VDC V2
            WHERE V2.CODIGOVENDEDOR = P.CODIGOVENDEDOR
              AND V2.SUBEMPRESA = 'GMP'
          ), '-') AS TIPOVENDEDOR,
          COALESCE((
            SELECT MAX(NULLIF(TRIM(E.HIDE_COMMISSIONS), ''))
            FROM JAVIER.COMMISSION_EXCEPTIONS E
            WHERE E.CODIGOVENDEDOR = P.CODIGOVENDEDOR
          ), 'N') AS HIDE_COMMISSIONS,
          '' AS EMAIL, P.CODIGOPIN AS PASSWORD_HASH, 1 AS ACTIVO
        FROM DSEDAC.VDD D
        JOIN DSEDAC.VDPL1 P ON D.CODIGOVENDEDOR = P.CODIGOVENDEDOR
        WHERE EXISTS (
          SELECT 1 FROM DSEDAC.VDC V
          WHERE V.CODIGOVENDEDOR = P.CODIGOVENDEDOR
            AND V.SUBEMPRESA = 'GMP'
        )
          AND REPLACE(UPPER(TRIM(D.NOMBREVENDEDOR)), ' ', '')
            LIKE '%' || CAST(? AS VARCHAR(100)) || '%'
        ORDER BY TRIM(P.CODIGOVENDEDOR)
        FETCH FIRST 2 ROWS ONLY
      `;
      const searchParam = requested.replace(/ /g, '').toUpperCase();
      result = await this._db.executeParams(nameSql, [searchParam]);
      if (!Array.isArray(result) || result.length !== 1) return null;
    }

    return User.fromDbRow(result[0]);
  }

  /**
   * Name login can match several vendors (e.g. "diego" → 22/25/86/98).
   * Caller must disambiguate with PIN; never invent a single row here.
   */
  async findNameLoginCandidates(name, { limit = 10 } = {}) {
    const requested = String(name || '').trim();
    if (!requested || requested.length > 50) return [];
    const max = Number.isInteger(limit) ? Math.min(Math.max(limit, 1), 20) : 10;
    const searchParam = requested.replace(/ /g, '').toUpperCase();
    const sql = `
      SELECT TRIM(P.CODIGOVENDEDOR) AS USUARIO,
        TRIM(D.NOMBREVENDEDOR) AS NOMBRE,
        ${ERP_ROLE_SELECT},
        ${ERP_MOBILITY_PROFILE_SELECT},
        COALESCE((
          SELECT MAX(NULLIF(TRIM(V2.TIPOVENDEDOR), ''))
          FROM DSEDAC.VDC V2
          WHERE V2.CODIGOVENDEDOR = P.CODIGOVENDEDOR
            AND V2.SUBEMPRESA = 'GMP'
        ), '-') AS TIPOVENDEDOR,
        COALESCE((
          SELECT MAX(NULLIF(TRIM(E.HIDE_COMMISSIONS), ''))
          FROM JAVIER.COMMISSION_EXCEPTIONS E
          WHERE E.CODIGOVENDEDOR = P.CODIGOVENDEDOR
        ), 'N') AS HIDE_COMMISSIONS,
        '' AS EMAIL, P.CODIGOPIN AS PASSWORD_HASH, 1 AS ACTIVO
      FROM DSEDAC.VDD D
      JOIN DSEDAC.VDPL1 P ON D.CODIGOVENDEDOR = P.CODIGOVENDEDOR
      WHERE EXISTS (
        SELECT 1 FROM DSEDAC.VDC V
        WHERE V.CODIGOVENDEDOR = P.CODIGOVENDEDOR
          AND V.SUBEMPRESA = 'GMP'
      )
      AND COALESCE(NULLIF(TRIM(P.ESTADO), ''), '') <> 'A'
        AND REPLACE(UPPER(TRIM(D.NOMBREVENDEDOR)), ' ', '')
          LIKE '%' || CAST(? AS VARCHAR(100)) || '%'
      ORDER BY TRIM(P.CODIGOVENDEDOR)
      FETCH FIRST ${max} ROWS ONLY
    `;
    // max is a clamped integer only; never accept raw user input into SQL text.
    const rows = await this._db.executeParams(sql, [searchParam]);
    if (!Array.isArray(rows) || rows.length === 0) return [];
    return rows.map((row) => User.fromDbRow(row));
  }

  async findByCredentials(username, password) {
    // CAST(? AS VARCHAR(50)) avoids ODBC 22001/CWB0111 when binding to IBM i CHAR columns
    const sql = `
      SELECT TRIM(V.CODIGOVENDEDOR) AS USUARIO, TRIM(V.NOMBREVENDEDOR) AS NOMBRE,
        CASE
          WHEN TRIM(VX.JEFEVENTASSN) = 'S' THEN 'JEFE_VENTAS'
          WHEN TRIM(VX.PERMITEREPARTOSN) = 'S' AND TRIM(VX.PERMITEPREVENTASN) <> 'S' THEN 'REPARTIDOR'
          ELSE 'COMERCIAL'
        END AS ROL,
        TRIM(VX.PERMITEPREVENTASN) AS PREVENTISTA_SN,
        TRIM(VX.PERMITEREPARTOSN) AS REPARTIDOR_SN,
        TRIM(VX.JEFEVENTASSN) AS JEFE_SN,
        '' AS EMAIL, TRIM(PL.CODIGOPIN) AS PASSWORD_HASH, 1 AS ACTIVO
      FROM DSEDAC.VDD V
      LEFT JOIN DSEDAC.VDDX VX ON V.CODIGOVENDEDOR = VX.CODIGOVENDEDOR
      LEFT JOIN DSEDAC.VDPL1 PL ON V.CODIGOVENDEDOR = PL.CODIGOVENDEDOR
      WHERE TRIM(V.CODIGOVENDEDOR) = CAST(? AS VARCHAR(50))
    `;
    const result = await this._db.executeParams(sql, [username.trim()]);
    if (!result || result.length === 0) return null;
    const user = User.fromDbRow(result[0]);
    // PIN-based auth: compare trimmed plain text PIN (CODIGOPIN is CHAR in DB2)
    if ((user._passwordHash || '').trim() === password.trim()) {
      return user;
    }
    return null;
  }

  async findRepartidorAssociation(code) {
    const normalizedCode = String(code || '').trim().toUpperCase();
    if (!normalizedCode || normalizedCode.length > 50 || !/^[A-Z0-9]+$/.test(normalizedCode)) return null;

    const sql = `
      SELECT TRIM(X.CODIGOVENDEDOR) AS CODIGO_CONDUCTOR,
        COALESCE((
          SELECT TRIM(V.CODIGOVEHICULO)
          FROM DSEDAC.VEH V
          WHERE TRIM(V.CODIGOCONDUCTOR) = TRIM(X.CODIGOVENDEDOR)
          FETCH FIRST 1 ROW ONLY
        ), '') AS MATRICULA
      FROM DSEDAC.VDDX X
      WHERE TRIM(X.CODIGOVENDEDOR) = CAST(? AS VARCHAR(50))
        AND TRIM(X.PERMITEREPARTOSN) = 'S'
      FETCH FIRST 2 ROWS ONLY
    `;
    const rows = await this._db.executeParams(sql, [normalizedCode]);
    if (!Array.isArray(rows) || rows.length !== 1) return null;

    const associationCode = String(
      rows[0].CODIGO_CONDUCTOR || rows[0].codigo_conductor || '',
    ).trim().toUpperCase();
    if (associationCode !== normalizedCode) return null;
    return {
      isRepartidor: true,
      codigoConductor: normalizedCode,
      matricula: String(rows[0].MATRICULA || rows[0].matricula || '').trim() || null,
    };
  }

  async listRepartidorFleet() {
    return this._repartidorFleetDirectory.list();
  }

  async getVendorVisibilityScope(code, { role } = {}) {
    const normalizedCode = String(code || '').trim().toUpperCase();
    if (!normalizedCode || normalizedCode.length > 50 || !/^[A-Z0-9]+$/.test(normalizedCode)) {
      return [];
    }
    if (role !== 'JEFE_VENTAS') {
      return getVendorVisibilityScope(normalizedCode);
    }

    const rows = await this._db.execute(`
      SELECT DISTINCT TRIM(CODIGOVENDEDOR) AS CODE
      FROM DSEDAC.VDC
      WHERE SUBEMPRESA = 'GMP'
      ORDER BY TRIM(CODIGOVENDEDOR)
    `);
    const codes = (Array.isArray(rows) ? rows : [])
      .map((row) => String(row.CODE || '').trim().toUpperCase())
      .filter(Boolean);
    return [...new Set([...codes, '82', '20', 'UNK'])];
  }
  async updatePassword(userId, newPasswordHash) {
    // NEVER write to DSEDAC/DSED (ERP tables are read-only)
    // Store password hash in JAVIER.APP_USUARIOS (our app's table)
    const sql = `
      MERGE INTO JAVIER.APP_USUARIOS U
      USING (VALUES (?)) AS V(USUARIO)
      ON U.USUARIO = V.USUARIO
      WHEN MATCHED THEN UPDATE SET U.PASSWORD_HASH = ?
      WHEN NOT MATCHED THEN INSERT (USUARIO, PASSWORD_HASH, ACTIVO) VALUES (?, ?, 1)
    `;
    await this._db.executeParams(sql, [userId, newPasswordHash, userId, newPasswordHash]);
    return true;
  }

  async logLoginAttempt(userId, success, ip) {
    // Pre-e7cfd8ee behavior (see 5e02bfc): APP_LOGIN_LOG is optional.
    // Missing table must never block login with AUTH_AUDIT_UNAVAILABLE / 503.
    try {
      const sql = `
        INSERT INTO JAVIER.APP_LOGIN_LOG (USUARIO, EXITO, IP, FECHA)
        VALUES (?, ?, ?, CURRENT_TIMESTAMP)
      `;
      await this._db.executeParamsSilent(sql, [userId || 'UNKNOWN', success ? 1 : 0, ip || 'unknown']);
      return Object.freeze({ ok: true });
    } catch (_error) {
      return Object.freeze({ ok: true, skipped: true, code: 'AUTH_AUDIT_SKIPPED' });
    }
  }
}

module.exports = { Db2AuthRepository };

'use strict';

const DEFAULT_TTL_MS = 5 * 60 * 1000;

const REPARTIDOR_FLEET_SQL = `
  WITH REPARTIDOR_CANDIDATES (CODE, NAME) AS (
    SELECT DISTINCT
      TRIM(V.CODIGOCONDUCTOR) AS CODE,
      COALESCE(NULLIF(TRIM(D.NOMBREVENDEDOR), ''), TRIM(V.CODIGOCONDUCTOR)) AS NAME
    FROM DSEDAC.VEH V
    LEFT JOIN DSEDAC.VDD D
      ON TRIM(D.CODIGOVENDEDOR) = TRIM(V.CODIGOCONDUCTOR)
    WHERE V.CODIGOCONDUCTOR IS NOT NULL
      AND TRIM(V.CODIGOCONDUCTOR) <> ''
      AND NOT EXISTS (
        SELECT 1 FROM DSEDAC.VDDX X
        WHERE TRIM(X.CODIGOVENDEDOR) = TRIM(V.CODIGOCONDUCTOR)
          AND TRIM(X.JEFEVENTASSN) = 'S'
      )
    UNION
    SELECT
      TRIM(OPP.CODIGOREPARTIDOR) AS CODE,
      COALESCE(NULLIF(TRIM(D.NOMBREVENDEDOR), ''), TRIM(OPP.CODIGOREPARTIDOR)) AS NAME
    FROM DSEDAC.OPP OPP
    LEFT JOIN DSEDAC.VDD D
      ON TRIM(D.CODIGOVENDEDOR) = TRIM(OPP.CODIGOREPARTIDOR)
    WHERE OPP.CODIGOREPARTIDOR IS NOT NULL
      AND TRIM(OPP.CODIGOREPARTIDOR) <> ''
      AND OPP.ANOREPARTO = YEAR(CURRENT_DATE)
      AND NOT EXISTS (
        SELECT 1 FROM DSEDAC.VDDX X
        WHERE TRIM(X.CODIGOVENDEDOR) = TRIM(OPP.CODIGOREPARTIDOR)
          AND TRIM(X.JEFEVENTASSN) = 'S'
      )
    GROUP BY
      TRIM(OPP.CODIGOREPARTIDOR),
      COALESCE(NULLIF(TRIM(D.NOMBREVENDEDOR), ''), TRIM(OPP.CODIGOREPARTIDOR))
    HAVING COUNT(*) >= 100
  )
  SELECT CODE, MAX(NAME) AS NAME
  FROM REPARTIDOR_CANDIDATES
  GROUP BY CODE
  ORDER BY CODE
`;

const EXCLUDED_PREFIXES = Object.freeze([
  'ZZ', 'ZD', 'ZB', 'ZE', 'Z7', 'ZA', 'ZC', 'ZF', 'ZG', 'ZH', 'ZI', 'ZJ',
  'ZK', 'ZL', 'ZM', 'ZN', 'ZO', 'ZP', 'ZQ', 'ZR', 'ZS', 'ZT', 'ZU', 'ZV',
  'ZW', 'ZX', 'ZY', 'Z0', 'Z1', 'Z2', 'Z3', 'Z4', 'Z5', 'Z6', 'Z8', 'Z9',
  'XX', 'TT', 'TEST',
]);
const EXCLUDED_CODES = new Set(['UNK', '00', '0', '', 'NULL', 'NONE', 'N/A', '97', '98']);

function canonicalRepartidorCode(value) {
  const raw = String(value || '').trim().toUpperCase();
  if (!/^[A-Z0-9]{1,2}$/.test(raw) || raw === 'ALL') return '';
  return /^\d{1,2}$/.test(raw) ? raw.padStart(2, '0') : raw;
}

function normalizeFleetRows(rows) {
  const byCode = new Map();
  for (const row of Array.isArray(rows) ? rows : []) {
    const code = canonicalRepartidorCode(row?.CODE ?? row?.code);
    const name = String(row?.NAME ?? row?.name ?? code).trim();
    if (!code || EXCLUDED_CODES.has(code)) continue;
    if (EXCLUDED_PREFIXES.some((prefix) => code.startsWith(prefix))) continue;
    if (name.toUpperCase().startsWith('ZZ')) continue;
    byCode.set(code, Object.freeze({ code, name: name || code }));
  }
  return Object.freeze([...byCode.values()].sort((left, right) =>
    left.code.localeCompare(right.code, undefined, { numeric: true })));
}

function createRepartidorFleetDirectory({ execute, ttlMs = DEFAULT_TTL_MS, now = Date.now } = {}) {
  if (typeof execute !== 'function') {
    throw new TypeError('repartidor fleet directory requires an execute function');
  }
  if (!Number.isFinite(ttlMs) || ttlMs < 0 || typeof now !== 'function') {
    throw new TypeError('invalid repartidor fleet cache configuration');
  }

  let cached = null;
  let expiresAt = 0;
  let inFlight = null;

  async function list() {
    const currentTime = Number(now());
    if (cached && currentTime < expiresAt) return cached;
    if (inFlight) return inFlight;

    inFlight = Promise.resolve()
      .then(() => execute(REPARTIDOR_FLEET_SQL))
      .then((rows) => {
        const normalized = normalizeFleetRows(rows);
        cached = normalized;
        expiresAt = Number(now()) + ttlMs;
        return normalized;
      })
      .finally(() => {
        inFlight = null;
      });
    return inFlight;
  }

  return Object.freeze({
    list,
    invalidate() {
      cached = null;
      expiresAt = 0;
    },
  });
}

module.exports = {
  DEFAULT_TTL_MS,
  REPARTIDOR_FLEET_SQL,
  canonicalRepartidorCode,
  createRepartidorFleetDirectory,
  normalizeFleetRows,
};

