  _tableName = _tableQualified.split('.')[1];

  try {
    const exists = await queryWithParams(`
      SELECT 1 AS OK FROM QSYS2.SYSTABLES
       WHERE TABLE_SCHEMA = 'JAVIER' AND TABLE_NAME = ?
       FETCH FIRST 1 ROW ONLY
    `, [_tableName], false, false);
    if (!exists?.length) {
      _isAvailable = false;
      _isNewSchema = false;
      logger.warn(`[DELIVERY_STATUS] ${_tableQualified} missing`);
      return;
    }

    const rows = await queryWithParams(`
      SELECT COLUMN_NAME
        FROM QSYS2.SYSCOLUMNS
       WHERE TABLE_SCHEMA = 'JAVIER'
         AND TABLE_NAME = ?
         AND COLUMN_NAME = 'EJERCICIOALBARAN'
       FETCH FIRST 1 ROW ONLY
    `, [_tableName], false, false);
    _isNewSchema = rows && rows.length > 0;
    _isAvailable = true;
    logger.info(`[DELIVERY_STATUS] ${_tableQualified} schema=${_isNewSchema ? 'NEW' : 'OLD'}`);
  } catch (e) {
    _isAvailable = false;
    _isNewSchema = false;
    logger.warn(`[DELIVERY_STATUS] check failed: ${e.message}`);
  }
}

module.exports = {
  async initSchemaCheck() {
    await checkSchema();
  },

  isDeliveryStatusAvailable() {
    return _isAvailable;
  },

  isDeliveryStatusNewSchema() {
    return _isNewSchema;
  },

  getDeliveryStatusTable() {
    return _tableQualified;
  },

  setDeliveryStatusAvailable(available) {
    _isAvailable = !!available;
  },

  getDeliveryStatusJoin(cpcAlias = 'CPC', dsAlias = 'DS') {
    if (!_isAvailable) return '';
    const table = _tableQualified;
    if (_isNewSchema) {
      return `
                LEFT JOIN ${table} ${dsAlias} ON
                    ${dsAlias}.EJERCICIOALBARAN = ${cpcAlias}.EJERCICIOALBARAN
                    AND ${dsAlias}.SERIEALBARAN = ${cpcAlias}.SERIEALBARAN
                    AND ${dsAlias}.TERMINALALBARAN = ${cpcAlias}.TERMINALALBARAN
                    AND ${dsAlias}.NUMEROALBARAN = ${cpcAlias}.NUMEROALBARAN
            `;
    }
    return `
            LEFT JOIN ${table} ${dsAlias} ON
                ${dsAlias}.ID = TRIM(CAST(${cpcAlias}.EJERCICIOALBARAN AS VARCHAR(10))) || '-' || TRIM(COALESCE(${cpcAlias}.SERIEALBARAN, '')) || '-' || TRIM(CAST(${cpcAlias}.TERMINALALBARAN AS VARCHAR(10))) || '-' || TRIM(CAST(${cpcAlias}.NUMEROALBARAN AS VARCHAR(10)))
        `;
  },

  getDeliveryStatusColumns(dsAlias = 'DS') {
    if (!_isAvailable) {
      return `
                CAST(NULL AS VARCHAR(20)) as DELIVERY_STATUS,
                CAST(NULL AS TIMESTAMP) as DELIVERY_UPDATED_AT,
                CAST(NULL AS VARCHAR(255)) as FIRMA_PATH,
                CAST(NULL AS VARCHAR(512)) as DS_OBS,
                CAST(NULL AS VARCHAR(255)) as DS_FIRMA,
                CAST(NULL AS VARCHAR(20)) as DELIVERY_REPARTIDOR
            `;
    }
    if (_isNewSchema) {
      return `
                ${dsAlias}.STATUS as DELIVERY_STATUS,
                ${dsAlias}.UPDATED_AT as DELIVERY_UPDATED_AT,
                CAST(NULL AS VARCHAR(255)) as FIRMA_PATH,
                CAST(NULL AS VARCHAR(512)) as OBSERVACIONES,
                CAST(NULL AS VARCHAR(255)) as DS_OBS,
                CAST(NULL AS VARCHAR(255)) as DS_FIRMA,
                CAST(NULL AS VARCHAR(20)) as DELIVERY_REPARTIDOR
            `;
    }
    return `
                ${dsAlias}.STATUS as DELIVERY_STATUS,
                ${dsAlias}.UPDATED_AT as DELIVERY_UPDATED_AT,
                ${dsAlias}.FIRMA_PATH,
                ${dsAlias}.OBSERVACIONES,
                ${dsAlias}.OBSERVACIONES as DS_OBS,
                ${dsAlias}.FIRMA_PATH as DS_FIRMA,
                ${dsAlias}.REPARTIDOR_ID as DELIVERY_REPARTIDOR
        `;
  },
};

'use strict';

const zlib = require('zlib');

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const MAX_DIMENSION = 4096;
const MAX_PIXELS = 4 * 1024 * 1024;
const CHANNELS_BY_COLOR_TYPE = Object.freeze({ 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 });
const BIT_DEPTHS_BY_COLOR_TYPE = Object.freeze({
  0: new Set([1, 2, 4, 8, 16]),
  2: new Set([8, 16]),
  3: new Set([1, 2, 4, 8]),
  4: new Set([8, 16]),
  6: new Set([8, 16]),
});

class PngValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PngValidationError';
    this.code = 'INVALID_PNG_IMAGE';
  }
}

function invalid(message) {
  throw new PngValidationError(message);
}

function crc32(buffer) {
  let crc = 0xffffffff;
  for (const byte of buffer) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit += 1) {
      crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
    }
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function assertDecodablePng(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 45 || !buffer.subarray(0, 8).equals(PNG_SIGNATURE)) {
    invalid('PNG signature or length is invalid');
  }
  let offset = 8;
  let header = null;
  let paletteEntries = null;
  let sawImageData = false;
  let endedImageData = false;
  let sawEnd = false;
  const compressedParts = [];
  while (offset < buffer.length) {
    if (offset + 12 > buffer.length) invalid('PNG chunk header is truncated');
    const length = buffer.readUInt32BE(offset);
    const end = offset + 12 + length;
    if (end > buffer.length) invalid('PNG chunk is truncated');
    const typeBytes = buffer.subarray(offset + 4, offset + 8);
    const type = typeBytes.toString('ascii');
    const data = buffer.subarray(offset + 8, offset + 8 + length);
    const storedCrc = buffer.readUInt32BE(offset + 8 + length);
    if (crc32(Buffer.concat([typeBytes, data])) !== storedCrc) invalid('PNG chunk checksum is invalid');
    if (!header && type !== 'IHDR') invalid('PNG IHDR must be first');
    if (type === 'IHDR') {
      if (header || length !== 13) invalid('PNG IHDR is invalid');
      const width = data.readUInt32BE(0);
      const height = data.readUInt32BE(4);
      const bitDepth = data[8];
      const colorType = data[9];
      if (!width || !height || width > MAX_DIMENSION || height > MAX_DIMENSION || width * height > MAX_PIXELS) {
        invalid('PNG dimensions are invalid');
      }
      if (!BIT_DEPTHS_BY_COLOR_TYPE[colorType]?.has(bitDepth)
          || data[10] !== 0 || data[11] !== 0 || data[12] !== 0) {
        invalid('PNG encoding is unsupported');
      }
      header = { width, height, bitDepth, colorType };
    } else if (type === 'IDAT') {
      if (!header || sawEnd || endedImageData || length === 0) invalid('PNG IDAT is invalid');
      if (header.colorType === 3 && paletteEntries == null) invalid('PNG palette is required');
      sawImageData = true;
      compressedParts.push(data);
    } else if (type === 'PLTE') {
      if (!header || sawImageData || paletteEntries != null
          || length < 3 || length > 768 || length % 3 !== 0
          || [0, 4].includes(header.colorType)) {
        invalid('PNG palette is invalid');
      }
      paletteEntries = length / 3;
      if (header.colorType === 3 && paletteEntries > (2 ** header.bitDepth)) {
        invalid('PNG palette has too many entries');
      }
    } else if (type === 'IEND') {
      if (!header || !sawImageData || length !== 0 || sawEnd) invalid('PNG IEND is invalid');
      sawEnd = true;
    } else if (typeBytes[0] >= 65 && typeBytes[0] <= 90 && type !== 'PLTE') {
      invalid('PNG contains an unsupported critical chunk');
    }
    if (sawImageData && type !== 'IDAT') endedImageData = true;
    offset = end;
    if (sawEnd) break;
  }
  if (!header || !sawImageData || !sawEnd || offset !== buffer.length) invalid('PNG structure is incomplete');
  const channels = CHANNELS_BY_COLOR_TYPE[header.colorType];
  const rowBytes = Math.ceil((header.width * channels * header.bitDepth) / 8);
  const expectedInflatedBytes = (rowBytes + 1) * header.height;
  let inflated;
  try {
    inflated = zlib.inflateSync(Buffer.concat(compressedParts), {
      maxOutputLength: expectedInflatedBytes + 1,
    });
  } catch (_) {
    invalid('PNG compressed data is invalid');
  }
  if (inflated.length !== expectedInflatedBytes) invalid('PNG decoded size is invalid');
  const inflatedStride = rowBytes + 1;
  for (let row = 0; row < header.height; row += 1) {
    if (inflated[row * inflatedStride] > 4) invalid('PNG scanline filter is invalid');
  }
  return Object.freeze({ ...header, decodedBytes: inflated.length });
}

module.exports = { PngValidationError, assertDecodablePng };

#!/usr/bin/env node
/**
 * Canary eval + auto-rollback for OpenCode governance (agent/prompt/model markers).
 * Staging/local orchestration — does NOT deploy to production hosts.
 *
 * Usage:
 *   node scripts/opencode-governance/canary-eval-rollback.mjs
 *   node scripts/opencode-governance/canary-eval-rollback.mjs --promote <label>
 *   node scripts/opencode-governance/canary-eval-rollback.mjs --candidate <label>
 *
 * On validate-governance FAIL while status=canary → restore last_known_good, exit 1.
 * On PASS with candidate → promote to last_known_good / active.
 */
import fs from "node:fs"
import path from "node:path"
import crypto from "node:crypto"
import { spawnSync } from "node:child_process"

const root = path.resolve(process.cwd())
const statePath = path.join(root, "docs/opencode-agent-governance/evals/canary-state.json")
const markerDir = path.join(root, "docs/opencode-agent-governance/evals/canary-markers")

function hashGovernance() {
  const files = [
    "docs/agent-classification.md",
    "docs/agent-inventory.yaml",
    "docs/opencode-agent-governance/canon/sandbox-policy.yaml",
    "docs/opencode-agent-governance/canon/otel-agentops.yaml",
    "docs/opencode-agent-governance/canon/cost-governance.yaml",
    "docs/opencode-agent-governance/canon/intent-validator.yaml",
    "docs/opencode-agent-governance/canon/tool-aci-registry.yaml",
    "docs/opencode-agent-governance/evals/baseline.json",
    "docs/opencode-agent-governance/evals/gold-cases.json",
  ]
  const h = crypto.createHash("sha256")
  for (const f of files) {
    const p = path.join(root, f)
    if (fs.existsSync(p)) h.update(fs.readFileSync(p))
    h.update("\n")
  }
  return h.digest("hex").slice(0, 16)
}

function loadState() {
  if (!fs.existsSync(statePath)) {
    return {
      version: 1,
      active_revision: "bootstrap",
      last_known_good: "bootstrap",
      candidate: null,
      status: "stable",
      updated_at: new Date().toISOString(),
      notes: "Auto-created canary state",
    }
  }
  return JSON.parse(fs.readFileSync(statePath, "utf8"))
}

function saveState(state) {
  fs.mkdirSync(path.dirname(statePath), { recursive: true })
  fs.mkdirSync(markerDir, { recursive: true })
  state.updated_at = new Date().toISOString()
  fs.writeFileSync(statePath, JSON.stringify(state, null, 2) + "\n", "utf8")
  fs.writeFileSync(
    path.join(markerDir, `${state.active_revision}.json`),
    JSON.stringify(
      {
        revision: state.active_revision,
        governance_hash: state.governance_hash,
        status: state.status,
        saved_at: state.updated_at,
      },
      null,
      2,
    ) + "\n",
    "utf8",
  )
}

function runValidator() {
  const r = spawnSync(process.execPath, ["scripts/opencode-governance/validate-governance.mjs"], {
    cwd: root,
    encoding: "utf8",
  })
  let report = null
  try {
    report = JSON.parse(r.stdout || "{}")
  } catch {
    report = { status: "FAIL", parse_error: true, stdout: r.stdout, stderr: r.stderr }
  }
  return { exit: r.status ?? 1, report }
}

const args = process.argv.slice(2)
const promoteIdx = args.indexOf("--promote")
const candidateIdx = args.indexOf("--candidate")
const state = loadState()
const governanceHash = hashGovernance()
state.governance_hash = governanceHash

if (candidateIdx >= 0) {
  const label = args[candidateIdx + 1] || `canary-${governanceHash}`
  state.candidate = label
  state.status = "canary"
  state.active_revision = label
  saveState(state)
  console.log(JSON.stringify({ action: "candidate_set", ...state }, null, 2))
}

if (promoteIdx >= 0) {
  const label = args[promoteIdx + 1] || state.candidate || state.active_revision
  state.active_revision = label
  state.last_known_good = label
  state.candidate = null
  state.status = "stable"
  saveState(state)
  console.log(JSON.stringify({ action: "promoted", ...state }, null, 2))
  process.exit(0)
}

const { exit, report } = runValidator()
const pass = exit === 0 && report?.status === "PASS" && (report?.fail ?? 1) === 0

if (pass) {
  if (state.status === "canary" && state.candidate) {
    state.last_known_good = state.candidate
    state.active_revision = state.candidate
    state.candidate = null
    state.status = "stable"
    state.last_result = "promoted_after_pass"
  } else {
    state.last_known_good = state.active_revision || governanceHash
    state.status = "stable"
    state.last_result = "pass"
  }
  saveState(state)
  console.log(
    JSON.stringify(
      {
        action: "pass",
        canary: state,
        validator: { status: report.status, pass: report.pass, fail: report.fail },
      },
      null,
      2,
    ),
  )
  process.exit(0)
}

// FAIL path: auto-rollback when in canary
if (state.status === "canary" || state.candidate) {
  const rolled = {
    ...state,
    active_revision: state.last_known_good,
    candidate: null,
    status: "rolled_back",
    last_result: "auto_rollback_on_eval_regression",
    regression_evidence: {
      validator_status: report?.status,
      fail: report?.fail,
      findings: (report?.findings || []).filter((f) => f.status === "FAIL").slice(0, 12),
    },
  }
  saveState(rolled)
  console.log(
    JSON.stringify(
      {
        action: "auto_rollback",
        canary: rolled,
        validator: report,
      },
      null,
      2,
    ),
  )
  process.exit(1)
}

saveState({
  ...state,
  last_result: "fail_stable_no_rollback",
})
console.log(
  JSON.stringify(
    {
      action: "fail",
      note: "Stable revision failed validation; no canary candidate to roll back",
      canary: state,
      validator: report,
    },
    null,
    2,
  ),
)
process.exit(1)

#!/usr/bin/env node
/**
 * Deterministic cost/latency threshold check for team runs.
 * Reads .opencode/state/metrics-latest.json and flow traces; exits non-zero on BLOCK.
 */
import fs from "node:fs"
import path from "node:path"

const root = process.cwd()
const args = new Set(process.argv.slice(2))
const failOnWarn = args.has("--fail-on-warn")

const THRESHOLDS = {
  session_cost_usd_warn: 5,
  session_cost_usd_block: 25,
  p95_latency_ms_warn: 120000,
  p95_latency_ms_block: 300000,
  token_budget_warn_ratio: 0.8,
}

const findings = []
const metricsPath = path.join(root, ".opencode", "state", "metrics-latest.json")
let metrics = null
if (fs.existsSync(metricsPath)) {
  try {
    metrics = JSON.parse(fs.readFileSync(metricsPath, "utf8"))
  } catch {
    findings.push({ severity: "WARN", rule: "metrics_parse", evidence: metricsPath, fix: "Repair metrics-latest.json" })
  }
} else {
  findings.push({
    severity: "WARN",
    rule: "metrics_missing",
    evidence: "No .opencode/state/metrics-latest.json",
    fix: "Run metrics-record after team sessions",
  })
}

if (metrics) {
  const cost = Number(metrics.session_cost_usd ?? metrics.cost_usd ?? 0)
  const p95 = Number(metrics.p95_latency_ms ?? metrics.latency_p95_ms ?? 0)
  const budget = Number(metrics.token_budget ?? metrics.budget_tokens ?? 0)
  const used = Number(metrics.tokens_used ?? metrics.total_tokens ?? 0)

  if (cost >= THRESHOLDS.session_cost_usd_block) {
    findings.push({
      severity: "BLOCK",
      rule: "cost_circuit_breaker",
      evidence: `session_cost_usd=${cost}`,
      fix: "Pause loops; require Javier approval to continue",
    })
  } else if (cost >= THRESHOLDS.session_cost_usd_warn) {
    findings.push({
      severity: "WARN",
      rule: "cost_high",
      evidence: `session_cost_usd=${cost}`,
      fix: "Reduce concurrent handoffs or switch to opencode-go models",
    })
  }

  if (p95 >= THRESHOLDS.p95_latency_ms_block) {
    findings.push({
      severity: "BLOCK",
      rule: "latency_block",
      evidence: `p95_latency_ms=${p95}`,
      fix: "Split workstreams or reduce tool-call depth",
    })
  } else if (p95 >= THRESHOLDS.p95_latency_ms_warn) {
    findings.push({
      severity: "WARN",
      rule: "latency_warn",
      evidence: `p95_latency_ms=${p95}`,
      fix: "Profile slow tools via flow-trace",
    })
  }

  if (budget > 0 && used / budget >= THRESHOLDS.token_budget_warn_ratio) {
    findings.push({
      severity: "WARN",
      rule: "token_budget_ratio",
      evidence: `used=${used} budget=${budget}`,
      fix: "Trigger context-compaction or close handoffs",
    })
  }
}

const blocks = findings.filter((f) => f.severity === "BLOCK")
const warns = findings.filter((f) => f.severity === "WARN")
const status = blocks.length ? "BLOCK" : warns.length ? "WARN" : "PASS"

const payload = {
  status,
  generated_at: new Date().toISOString(),
  thresholds: THRESHOLDS,
  block_count: blocks.length,
  warn_count: warns.length,
  findings,
}

const outDir = path.join(root, ".opencode", "state")
fs.mkdirSync(outDir, { recursive: true })
fs.writeFileSync(path.join(outDir, "cost-latency-threshold-latest.json"), JSON.stringify(payload, null, 2))

console.log(`cost-latency-threshold: ${status} blocks=${blocks.length} warns=${warns.length}`)
if (status === "BLOCK" || (failOnWarn && warns.length)) process.exit(1)
process.exit(0)

