const fs = require("fs");
const os = require("os");
const path = require("path");

function isPlaceholder(value) {
  const raw = String(value || "").trim();
  if (!raw) return true;
  if (raw.toLowerCase() === "undefined") return true;
  if (/^\$\{env\.[A-Z0-9_]+\}$/i.test(raw)) return true;
  if (/^\{env:[A-Z0-9_]+\}$/i.test(raw)) return true;
  return false;
}

function loadEnvFile(file) {
  try {
    if (!fs.existsSync(file)) return;
    const keyRe = /^(ODBC_(DSN|UID|PWD|SCHEMA)|SSH_GMP_(HOST|USER|PORT|PASSWORD|PLINK|OPENSSH|AUTH_MODE|PUTTY_SESSION|KEY_FILE|HOSTKEY|PAGEANT))$/;
    for (const line of fs.readFileSync(file, "utf8").split(/\r?\n/)) {
      if (!line || /^\s*#/.test(line) || !line.includes("=")) continue;
      const idx = line.indexOf("=");
      const name = line.slice(0, idx).trim();
      if (!keyRe.test(name)) continue;
      let value = line.slice(idx + 1).trim().replace(/^['"]|['"]$/g, "");
      if (!value || isPlaceholder(value)) continue;
      if (/^(ODBC_(UID|PWD)|SSH_GMP_PASSWORD)$/.test(name) || isPlaceholder(process.env[name])) {
        process.env[name] = value;
      }
    }
  } catch (_) {}
}

process.env.ODBC_UID = "undefined";
process.env.SSH_GMP_PASSWORD = "undefined";
loadEnvFile(path.join(os.homedir(), ".config", "opencode", ".env"));
loadEnvFile(path.join(os.homedir(), ".config", "opencode", ".env.recovered"));

console.log(
  JSON.stringify({
    ODBC_UID: !isPlaceholder(process.env.ODBC_UID),
    ODBC_PWD: !isPlaceholder(process.env.ODBC_PWD),
    SSH_GMP_PASSWORD: !isPlaceholder(process.env.SSH_GMP_PASSWORD),
    SSH_GMP_PUTTY_SESSION: !isPlaceholder(process.env.SSH_GMP_PUTTY_SESSION),
    SSH_GMP_KEY_FILE: !isPlaceholder(process.env.SSH_GMP_KEY_FILE),
    SSH_GMP_HOSTKEY: !isPlaceholder(process.env.SSH_GMP_HOSTKEY),
    SSH_GMP_AUTH_MODE: process.env.SSH_GMP_AUTH_MODE || "auto",
    SSH_AUTH: !isPlaceholder(process.env.SSH_GMP_PUTTY_SESSION)
      ? "putty-session"
      : !isPlaceholder(process.env.SSH_GMP_KEY_FILE)
        ? "key-file"
        : !isPlaceholder(process.env.SSH_GMP_PASSWORD)
          ? "password-env"
          : "pageant-or-client-cache",
    SSH_GMP_HOST: process.env.SSH_GMP_HOST || null,
  }),
);

