function resolveOpenSsh() {
  const configured = process.env.SSH_GMP_OPENSSH || "";
  if (configured) return configured;
  const candidates = [
    "C:\\Windows\\System32\\OpenSSH\\ssh.exe",
    "C:\\Program Files\\Git\\usr\\bin\\ssh.exe",
  ];
  return candidates.find((candidate) => fs.existsSync(candidate)) || "ssh";
}

function appendPlinkAuthArgs(args) {
  const hostKey = process.env.SSH_GMP_HOSTKEY || "";
  const keyFile = process.env.SSH_GMP_KEY_FILE || "";
  if (hostKey) args.push("-hostkey", hostKey);
  if (keyFile) args.push("-i", keyFile);
  if (process.env.SSH_GMP_PAGEANT !== "false") args.push("-agent");
}

function buildSshInvocation(command) {
  const host = process.env.SSH_GMP_HOST || "192.168.1.230";
  const user = process.env.SSH_GMP_USER || "gmp";
  const port = process.env.SSH_GMP_PORT || "22";
  const password = process.env.SSH_GMP_PASSWORD || "";
  const plink = process.env.SSH_GMP_PLINK || "C:\\Program Files (x86)\\PuTTY\\plink.exe";
  const puttySession = process.env.SSH_GMP_PUTTY_SESSION || "";
  const authMode = (process.env.SSH_GMP_AUTH_MODE || "auto").toLowerCase();
  const target = `${user}@${host}`;

  if (authMode === "openssh") {
    const args = ["-o", "BatchMode=yes", "-o", "ConnectTimeout=5", "-p", port];
    const keyFile = process.env.SSH_GMP_KEY_FILE || "";
    if (keyFile) args.push("-i", keyFile);
    args.push(target, command);
    return { executable: resolveOpenSsh(), args };
  }

  if (authMode === "putty-session" || (authMode === "auto" && puttySession)) {
    if (!puttySession) throw new Error("SSH_GMP_PUTTY_SESSION is required for putty-session auth mode.");
    const args = ["-batch", "-load", puttySession];
    appendPlinkAuthArgs(args);
    args.push(command);
    return { executable: plink, args };
  }

  const args = ["-ssh", "-batch", "-P", port];
  appendPlinkAuthArgs(args);

  if (authMode === "password" || (authMode === "auto" && password)) {
    if (!password) throw new Error("SSH_GMP_PASSWORD is required for password auth mode.");
    args.push("-pw", password);
  }

  args.push(target, command);
  return { executable: plink, args };
}

function sshErrorMessage(stderr, code) {
  const raw = (stderr || "").trim();
  if (/Cannot answer interactive prompts in batch mode/i.test(raw) || /host key/i.test(raw) || /password/i.test(raw)) {
    return [
      raw || `SSH client exited ${code}`,
      "Non-interactive SSH could not authenticate or confirm the host key.",
      "Configure one of: SSH_GMP_PUTTY_SESSION for a saved PuTTY session, Pageant/SSH_GMP_KEY_FILE for key auth, SSH_GMP_HOSTKEY for pinned PuTTY host key, or SSH_GMP_AUTH_MODE=openssh when OpenSSH is installed.",
      "Do not store plaintext credentials in this repository.",
    ].join(" ");
  }
  return raw || `SSH client exited ${code}`;
}

function runSsh(command) {
  const certCommand = finalCertReadonlyCommand(command) || finalCertAc3Ac4Command(command);
  if (certCommand) command = certCommand;
  else if (!allowed.some((re) => re.test(command))) {
    throw new Error("Command is not in the read-only GMP SSH allowlist. Aceptados: whoami, hostname, pwd, uptime, date, uname, node --version, pm2 list/status/jlist gmp-api, pm2 logs gmp-api --lines N --nostream, curl -A GMP-SRE-HealthCheck/1.0 http://localhost:3335/api/health|ready, tail/head/cat/ls/stat/file/wc/du en /opt/gmp-api|/var/log|/var/www/mari-pepa con extension .log/.txt/.json/.out/.err, df -h, free -m, systemctl status, ss -tlnp.");
  }
  const invocation = buildSshInvocation(command);

  return new Promise((resolve, reject) => {
    const child = spawn(invocation.executable, invocation.args, {
      windowsHide: true,
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (data) => { stdout += data.toString(); });
    child.stderr.on("data", (data) => { stderr += data.toString(); });
    child.on("error", reject);
    child.on("close", (code) => {
      if (code !== 0) reject(new Error(sshErrorMessage(stderr, code)));
      else resolve({ code, stdout: stdout.trim(), stderr: stderr.trim() });
    });
  });
}

const tools = [
  {
    name: "gmp_ssh_readonly",
    description: "Run an allowlisted read-only SSH command on the GMP backend server.",
    inputSchema: {
      type: "object",
      properties: {
        command: { type: "string", description: "Allowlisted command, e.g. whoami or curl health." },
      },
      required: ["command"],
      additionalProperties: false,
    },
  },
];

async function handle(request) {
  const { id, method, params } = request;
  if (method === "initialize") {
    return result(id, {
      protocolVersion: "2025-06-18",
      capabilities: { tools: {} },
      serverInfo: { name: "gmp-deploy-ssh-readonly", version: "1.1.0" },
    });
  }
  if (method === "tools/list") return result(id, { tools });
  if (method === "tools/call") {
    const name = params && params.name;
    if (name !== "gmp_ssh_readonly") return error(id, -32602, `Unknown tool: ${name}`);
    return result(id, text(await runSsh(String(params.arguments && params.arguments.command || ""))));
  }
  if (id === undefined || id === null) return null;
  return error(id, -32601, `Method not found: ${method}`);
}

let buffer = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => {
  buffer += chunk;
  for (;;) {
    const idx = buffer.indexOf("\n");
    if (idx < 0) break;
    const line = buffer.slice(0, idx).trim();
    buffer = buffer.slice(idx + 1);
    if (!line) continue;
    Promise.resolve()
      .then(() => handle(JSON.parse(line)))
      .then((response) => { if (response) process.stdout.write(`${JSON.stringify(response)}\n`); })
      .catch((err) => {
        let id = null;
        try { id = JSON.parse(line).id ?? null; } catch (_) {}
        process.stdout.write(`${JSON.stringify(error(id, -32000, err.message || String(err)))}\n`);
      });
  }
});

#!/usr/bin/env node
"use strict";

const path = require("path");

function loadOdbc() {
  const candidates = [
    path.resolve(__dirname, "../../../backend/node_modules/odbc"),
    "odbc",
  ];
  for (const candidate of candidates) {
    try {
      return require(candidate);
    } catch (_) {}
  }
  throw new Error("Node package 'odbc' not found. Run npm install in backend.");
}

function text(content) {
  return { content: [{ type: "text", text: typeof content === "string" ? content : JSON.stringify(content, null, 2) }] };
}

function error(id, code, message) {
  return { jsonrpc: "2.0", id, error: { code, message } };
}

function result(id, value) {
  return { jsonrpc: "2.0", id, result: value };
}

function isReadOnlySql(sql) {
  const cleaned = String(sql || "").trim().replace(/;+\s*$/, "");
  if (!cleaned) return false;
  if (!/^(select|with|values)\b/i.test(cleaned)) return false;
  return !/\b(insert|update|delete|merge|alter|drop|create|truncate|grant|revoke|call)\b/i.test(cleaned);
}

async function connect() {
  const odbc = loadOdbc();
  const dsn = process.env.ODBC_DSN || "GMP";
  const uid = process.env.ODBC_UID || "";
  const pwd = process.env.ODBC_PWD || process.env.ODBC_PASSWORD || "";
  const parts = [`DSN=${dsn}`];
  if (uid) parts.push(`UID=${uid}`);
  if (pwd) parts.push(`PWD=${pwd}`);
  parts.push("ConnectionTimeout=8", "LoginTimeout=8");
  return odbc.connect(parts.join(";"));
}

async function db2Health() {
  const conn = await connect();
  try {
    const rows = await conn.query("SELECT 1 AS OK FROM SYSIBM.SYSDUMMY1");
    return { ok: true, dsn: process.env.ODBC_DSN || "GMP", rows };
  } finally {
    try { await conn.close(); } catch (_) {}
  }
}

async function db2Query(args) {
  const sql = String(args && args.sql || "");
  const limit = Math.max(1, Math.min(Number(args && args.limit) || 50, 500));
  if (!isReadOnlySql(sql)) {
    throw new Error("Only read-only SELECT/WITH/VALUES statements are allowed.");
  }
  const conn = await connect();
  try {
    const wrapped = `SELECT * FROM (${sql.replace(/;+\s*$/, "")}) AS Q FETCH FIRST ${limit} ROWS ONLY`;
    return await conn.query(wrapped);
  } finally {
    try { await conn.close(); } catch (_) {}
  }
}

const tools = [
  {
    name: "db2_health",
    description: "Check GMP DB2 ODBC connectivity with a read-only SELECT 1.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  {
    name: "db2_query_readonly",
    description: "Run a read-only DB2 SELECT/WITH/VALUES query against DSN GMP. Mutations are rejected.",
    inputSchema: {
      type: "object",
      properties: {
        sql: { type: "string", description: "Read-only SQL statement." },
        limit: { type: "integer", minimum: 1, maximum: 500, description: "Maximum returned rows." },
      },
      required: ["sql"],
      additionalProperties: false,
    },
  },
];

async function handle(request) {
  const { id, method, params } = request;
  if (method === "initialize") {
    return result(id, {
      protocolVersion: "2025-06-18",
      capabilities: { tools: {} },
      serverInfo: { name: "gmp-db2-odbc", version: "1.0.0" },
    });
  }
  if (method === "tools/list") return result(id, { tools });
  if (method === "tools/call") {
    const name = params && params.name;
    const args = params && params.arguments || {};
    if (name === "db2_health") return result(id, text(await db2Health()));
    if (name === "db2_query_readonly") return result(id, text(await db2Query(args)));
    return error(id, -32602, `Unknown tool: ${name}`);
  }
  if (id === undefined || id === null) return null;
  return error(id, -32601, `Method not found: ${method}`);
}

let buffer = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => {
  buffer += chunk;
  for (;;) {
    const idx = buffer.indexOf("\n");
    if (idx < 0) break;
    const line = buffer.slice(0, idx).trim();
    buffer = buffer.slice(idx + 1);
    if (!line) continue;
    Promise.resolve()
      .then(() => handle(JSON.parse(line)))
      .then((response) => { if (response) process.stdout.write(`${JSON.stringify(response)}\n`); })
      .catch((err) => {
        let id = null;
        try { id = JSON.parse(line).id ?? null; } catch (_) {}
        process.stdout.write(`${JSON.stringify(error(id, -32000, err.message || String(err)))}\n`);
      });
  }
});

#!/usr/bin/env node
const fs = require("fs");
const os = require("os");
const path = require("path");

const configDir = path.join(os.homedir(), ".config", "opencode");
const primaryEnv = path.join(configDir, ".env");
const recoveredEnv = path.join(configDir, ".env.recovered");
const maxEnvBytes = 1024 * 1024;
const envKeyRe = /^(ODBC_(DSN|UID|PWD|SCHEMA)|SSH_GMP_(HOST|USER|PORT|PASSWORD|PLINK|OPENSSH|AUTH_MODE|PUTTY_SESSION|KEY_FILE|HOSTKEY|PAGEANT))$/;

function isPlaceholder(value) {
  const raw = String(value || "").trim();
  if (!raw) return true;
  if (raw.toLowerCase() === "undefined") return true;
  if (/^\$\{env\.[A-Z0-9_]+\}$/i.test(raw)) return true;
  if (/^\{env:[A-Z0-9_]+\}$/i.test(raw)) return true;
  return false;
}

function loadEnvFile(file) {
  try {
    if (!fs.existsSync(file)) return;
    if (fs.statSync(file).size > maxEnvBytes) return;
    for (const line of fs.readFileSync(file, "utf8").split(/\r?\n/)) {
      if (!line || /^\s*#/.test(line) || !line.includes("=")) continue;
      const idx = line.indexOf("=");
      const name = line.slice(0, idx).trim();
      if (!envKeyRe.test(name)) continue;
      let value = line.slice(idx + 1).trim().replace(/^['"]|['"]$/g, "");
      if (!value || isPlaceholder(value)) continue;
      const secret = /^(ODBC_(UID|PWD)|SSH_GMP_PASSWORD)$/.test(name);
      if (secret || isPlaceholder(process.env[name])) process.env[name] = value;
    }
  } catch (_) {}
}

function loadAllEnvFiles() {
  for (const name of [".env", ".env.recovered"]) {
    loadEnvFile(path.join(configDir, name));
  }
}

function scoped(name) {
  return process.env[name] || "";
}

function defaults(name, fallback) {
  return scoped(name) || fallback;
}

function rebuildEnv(target) {
  const lines = [
    `# OpenCode secrets - rebuilt ${new Date().toISOString()}`,
    "# Do not commit",
    `ODBC_DSN=${defaults("ODBC_DSN", "GMP")}`,
    `ODBC_UID=${defaults("ODBC_UID", "")}`,
    `ODBC_PWD=${defaults("ODBC_PWD", "")}`,
    `ODBC_SCHEMA=${defaults("ODBC_SCHEMA", "JAVIER")}`,
    `SSH_GMP_HOST=${defaults("SSH_GMP_HOST", "192.168.1.230")}`,
    `SSH_GMP_USER=${defaults("SSH_GMP_USER", "gmp")}`,
    `SSH_GMP_PORT=${defaults("SSH_GMP_PORT", "22")}`,
    `SSH_GMP_AUTH_MODE=${defaults("SSH_GMP_AUTH_MODE", "auto")}`,
  ];
  if (scoped("SSH_GMP_PASSWORD")) lines.push(`SSH_GMP_PASSWORD=${scoped("SSH_GMP_PASSWORD")}`);
  if (scoped("SSH_GMP_PLINK")) lines.push(`SSH_GMP_PLINK=${scoped("SSH_GMP_PLINK")}`);
  if (scoped("SSH_GMP_OPENSSH")) lines.push(`SSH_GMP_OPENSSH=${scoped("SSH_GMP_OPENSSH")}`);
  if (scoped("SSH_GMP_PUTTY_SESSION")) lines.push(`SSH_GMP_PUTTY_SESSION=${scoped("SSH_GMP_PUTTY_SESSION")}`);
  if (scoped("SSH_GMP_KEY_FILE")) lines.push(`SSH_GMP_KEY_FILE=${scoped("SSH_GMP_KEY_FILE")}`);
  if (scoped("SSH_GMP_HOSTKEY")) lines.push(`SSH_GMP_HOSTKEY=${scoped("SSH_GMP_HOSTKEY")}`);
  if (scoped("SSH_GMP_PAGEANT")) lines.push(`SSH_GMP_PAGEANT=${scoped("SSH_GMP_PAGEANT")}`);
  if (scoped("OPENCODE_SERVER_USERNAME")) lines.push(`OPENCODE_SERVER_USERNAME=${scoped("OPENCODE_SERVER_USERNAME")}`);
  if (scoped("OPENCODE_SERVER_PASSWORD")) lines.push(`OPENCODE_SERVER_PASSWORD=${scoped("OPENCODE_SERVER_PASSWORD")}`);
  fs.writeFileSync(target, lines.join("\n") + "\n", "utf8");
  return target;
}

function quarantineIfBloated() {
  if (!fs.existsSync(primaryEnv)) return "missing";
  const size = fs.statSync(primaryEnv).size;
  if (size <= maxEnvBytes) return "ok";
  const stamp = new Date().toISOString().replace(/[:.]/g, "").slice(0, 15);
  const quarantine = `${primaryEnv}.corrupt-${stamp}`;
  try {
    fs.renameSync(primaryEnv, quarantine);
    return `quarantined:${quarantine}`;
  } catch (err) {
    rebuildEnv(recoveredEnv);
    return `locked:${size}`;
  }
}

function patchMcpConfig(file) {
  if (!fs.existsSync(file)) return `skip:${file}`;
  const cfg = JSON.parse(fs.readFileSync(file, "utf8"));
  if (!cfg.mcp) return `no_mcp:${file}`;
  const node = "C:/Program Files/nodejs/node.exe";
  if (cfg.mcp["ibm-db2-mcp"]) {
    cfg.mcp["ibm-db2-mcp"].type = "local";
    cfg.mcp["ibm-db2-mcp"].command = [node, path.join(configDir, "mcp/ibm-odbc-mcp.cjs").replace(/\\/g, "/")];
    cfg.mcp["ibm-db2-mcp"].environment = {
      ODBC_DSN: defaults("ODBC_DSN", "GMP"),
      ODBC_SCHEMA: defaults("ODBC_SCHEMA", "JAVIER"),
    };
    delete cfg.mcp["ibm-db2-mcp"].environment.ODBC_UID;
    delete cfg.mcp["ibm-db2-mcp"].environment.ODBC_PWD;
    cfg.mcp["ibm-db2-mcp"].enabled = true;
    cfg.mcp["ibm-db2-mcp"].timeout = 30000;
  }
  if (cfg.mcp["gmp-deploy-ssh"]) {
    cfg.mcp["gmp-deploy-ssh"].type = "local";
    cfg.mcp["gmp-deploy-ssh"].command = [node, path.join(configDir, "mcp/gmp-deploy-ssh-mcp.cjs").replace(/\\/g, "/")];
    cfg.mcp["gmp-deploy-ssh"].environment = {
      SSH_GMP_HOST: defaults("SSH_GMP_HOST", "192.168.1.230"),
      SSH_GMP_USER: defaults("SSH_GMP_USER", "gmp"),
      SSH_GMP_PORT: defaults("SSH_GMP_PORT", "22"),
      SSH_GMP_AUTH_MODE: defaults("SSH_GMP_AUTH_MODE", "auto"),
    };
    for (const key of [
      "SSH_GMP_PLINK",
      "SSH_GMP_OPENSSH",
      "SSH_GMP_PUTTY_SESSION",
      "SSH_GMP_KEY_FILE",
      "SSH_GMP_HOSTKEY",
      "SSH_GMP_PAGEANT",
    ]) {
      if (scoped(key)) cfg.mcp["gmp-deploy-ssh"].environment[key] = scoped(key);
    }
    delete cfg.mcp["gmp-deploy-ssh"].environment.SSH_GMP_PASSWORD;
    cfg.mcp["gmp-deploy-ssh"].enabled = true;
    cfg.mcp["gmp-deploy-ssh"].timeout = 30000;
  }
  fs.writeFileSync(file, JSON.stringify(cfg, null, 4) + "\n", "utf8");
  return `ok:${file}`;
}

function syncMcpScripts(projectDir) {
  const sourceDir = path.join(projectDir, "scripts", "opencode", "mcp");
  const targetDir = path.join(configDir, "mcp");
  fs.mkdirSync(targetDir, { recursive: true });
  const copied = [];
  for (const name of ["gmp-deploy-ssh-mcp.cjs", "ibm-odbc-mcp.cjs"]) {
    const source = path.join(sourceDir, name);
    if (!fs.existsSync(source)) continue;
    const target = path.join(targetDir, name);
    fs.copyFileSync(source, target);
    copied.push(name);
  }
  return copied;
}

const envState = quarantineIfBloated();
if (envState.startsWith("locked:")) {
  loadEnvFile(recoveredEnv);
  rebuildEnv(recoveredEnv);
} else if (envState === "missing" || envState.startsWith("quarantined:")) {
  loadEnvFile(recoveredEnv);
  rebuildEnv(primaryEnv);
} else if (!fs.existsSync(recoveredEnv) && fs.existsSync(primaryEnv) && fs.statSync(primaryEnv).size > maxEnvBytes) {
  loadEnvFile(primaryEnv);
  rebuildEnv(recoveredEnv);
} else {
  loadAllEnvFiles();
}

if (envState !== "ok") {
  loadAllEnvFiles();
}

const required = ["ODBC_UID", "ODBC_PWD"];
const missing = required.filter((k) => !scoped(k));
if (missing.length) {
  console.error("MISSING:", missing.join(", "));
  process.exit(2);
}
if (!scoped("SSH_GMP_PASSWORD") && !scoped("SSH_GMP_PUTTY_SESSION") && !scoped("SSH_GMP_KEY_FILE")) {
  console.error("WARN: SSH auth will rely on Pageant or an already configured SSH client.");
}

const projectDir = path.resolve(__dirname, "..", "..");
const copiedMcpScripts = syncMcpScripts(projectDir);
const targets = [
  path.join(configDir, "opencode.json"),
  path.join(os.homedir(), ".opencode-runtime/opencode/opencode.json"),
  path.join(projectDir, ".opencode/opencode.json"),
  path.join(projectDir, "opencode.json"),
];
const results = targets.map(patchMcpConfig);
console.log("OK repair-mcp-env-node");
console.log(" env:", envState);
console.log(" mcp:", copiedMcpScripts.length ? copiedMcpScripts.join(", ") : "none");
console.log(" configs:", results.join(" | "));

